#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_SPEED 1000000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_moisture_level(int adc_value) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    printf("%04d-%02d-%02d %02d:%02d:%02d - Moisture Level: %d\n",
           tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
           tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
           adc_value);
}

int read_adc(int spi_handle, int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int count = spi_xfer(spi_handle, tx, rx, 3);
    if (count < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", count);
        return -1;
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int adc_value = read_adc(spi_handle, 0);
        if (adc_value >= 0) {
            log_moisture_level(adc_value);
        }
        time_sleep(1);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

