#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define ADS1115_I2C_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00

#define PGA_4_096V 0x0200
#define MUX_AIN0 0x4000
#define DATA_RATE_128SPS 0x00E0
#define MODE_SINGLE_SHOT 0x0100

#define MLX91219_SENSITIVITY 0.040 // 40 mV/A
#define MLX91219_OFFSET 2.048 // Mid-supply voltage in volts

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, ADS1115_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t config = PGA_4_096V | MUX_AIN0 | DATA_RATE_128SPS | MODE_SINGLE_SHOT;
    uint8_t config_bytes[3] = {ADS1115_REG_CONFIG, config >> 8, config & 0xFF};

    if (i2cWriteI2CBlockData(i2c_handle, config_bytes[0], 3, config_bytes) < 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        uint8_t conversion_bytes[2];
        if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERSION, 2, conversion_bytes) < 0) {
            fprintf(stderr, "Failed to read from ADS1115 conversion register\n");
            continue;
        }

        uint16_t conversion = (conversion_bytes[0] << 8) | conversion_bytes[1];
        int16_t voltage = (int16_t)conversion;
        double current = (voltage * MLX91219_SENSITIVITY - MLX91219_OFFSET) / MLX91219_SENSITIVITY;

        printf("Current: %.3f A\n", current);

        usleep(500000); // 500ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

