#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define KY026_GPIO 4
#define MCP3008_SPI_CHANNEL 0
#define MCP3008_SPI_SPEED 1000000
#define ADC_MIN_VALUE 0
#define ADC_MAX_VALUE 1023
#define TEMP_MIN_VALUE 10
#define TEMP_MAX_VALUE 40

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_data(FILE *file, int flame_detected, int temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s,%d,%d\n", timestamp, flame_detected, temperature);
}

int read_adc(int channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];

    if (spiXfer(0, tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    atexit(gpioTerminate);

    if (gpioSetMode(KY026_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for KY-026\n");
        return EXIT_FAILURE;
    }

    if (spiOpen(0, MCP3008_SPI_SPEED, 0) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return EXIT_FAILURE;
    }

    FILE *file = fopen("flame_data.csv", "a");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return EXIT_FAILURE;
    }

    atexit(() -> { fclose(file); });

    signal(SIGINT, signal_handler);

    while (running) {
        int flame_detected = gpioRead(KY026_GPIO);
        int adc_value = read_adc(MCP3008_SPI_CHANNEL);
        if (adc_value < 0) {
            continue;
        }

        int temperature = TEMP_MIN_VALUE + (adc_value * (TEMP_MAX_VALUE - TEMP_MIN_VALUE)) / ADC_MAX_VALUE;
        log_data(file, flame_detected, temperature);

        sleep(1);
    }

    return EXIT_SUCCESS;
}

