#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define ADC_ADDRESS 0x48
#define ADC_CHANNEL 0
#define ADC_CONFIG_REG 0x01
#define ADC_CONVERSION_REG 0x00
#define ADC_CONFIG_VALUE 0b1000010110000000 // Single-shot, 128 SPS, gain ±4.096V
#define TEMP_THRESHOLD 60.0
#define DEBOUNCE_TIME 50
#define LOG_FILE "fire_log.txt"

volatile int running = 1;
volatile int flame_detected = 0;
volatile time_t last_flame_time = 0;

void flame_isr(int gpio, int level, uint32_t tick) {
    if (level == PI_LOW) {
        time_t current_time = time(NULL);
        if (current_time - last_flame_time >= DEBOUNCE_TIME / 1000) {
            flame_detected = 1;
            last_flame_time = current_time;
        }
    }
}

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetISRFunc(FLAME_SENSOR_PIN, RISING_EDGE, 0, flame_isr) < 0) {
        fprintf(stderr, "Failed to set ISR function for flame sensor\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, PI_LOW);

    int i2c_handle = i2cOpen(I2C_BUS, ADC_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioSetISRFunc(FLAME_SENSOR_PIN, RISING_EDGE, 0, NULL);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteReg16(i2c_handle, ADC_CONFIG_REG, ADC_CONFIG_VALUE) < 0) {
        fprintf(stderr, "Failed to write ADC configuration\n");
        i2cClose(i2c_handle);
        gpioSetISRFunc(FLAME_SENSOR_PIN, RISING_EDGE, 0, NULL);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioSetISRFunc(FLAME_SENSOR_PIN, RISING_EDGE, 0, NULL);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        gpioDelay(100000); // 100ms delay

        if (gpioRead(FLAME_SENSOR_PIN) == PI_LOW) {
            time_t current_time = time(NULL);
            if (current_time - last_flame_time >= DEBOUNCE_TIME / 1000) {
                flame_detected = 1;
                last_flame_time = current_time;
            }
        }

        int adc_value = i2cReadReg16(i2c_handle, ADC_CONVERSION_REG);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        // Convert ADC value to voltage (0-3.3V)
        double voltage = (adc_value >> 4) * 3.3 / 4096.0;
        // Map voltage to temperature (20°C-80°C)
        double temperature = 20.0 + (voltage / 3.3) * 60.0;

        if (flame_detected && temperature > TEMP_THRESHOLD) {
            time_t current_time = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));
            fprintf(log_file, "%s: Fire detected!\n", timestamp);
            fflush(log_file);
            gpioWrite(BUZZER_PIN, PI_HIGH);
            gpioDelay(2000000); // 2 seconds
            gpioWrite(BUZZER_PIN, PI_LOW);
            flame_detected = 0;
        } else if (flame_detected) {
            fprintf(log_file, "Flame detected!\n");
            fflush(log_file);
            flame_detected = 0;
        } else if (temperature > TEMP_THRESHOLD) {
            fprintf(log_file, "Temperature: %.2f°C\n", temperature);
            fflush(log_file);
        }
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioSetISRFunc(FLAME_SENSOR_PIN, RISING_EDGE, 0, NULL);
    gpioTerminate();

    return 0;
}

