#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip4"
#define GPIO_PIN 18
#define ADC_CHANNEL 0
#define ADC_COMMAND 0x01
#define ADC_MASK 0x03
#define ADC_SHIFT 8
#define ADC_BITS 10
#define ADC_VREF 3.3
#define DEFAULT_SENSITIVITY 0.1
#define DEFAULT_THRESHOLD 5.0
#define SAMPLE_INTERVAL 1

static volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

int main(int argc, char *argv[]) {
    int spi_fd = -1;
    struct gpiod_chip *gpio_chip = NULL;
    struct gpiod_line *gpio_line = NULL;
    float sensitivity = DEFAULT_SENSITIVITY;
    float threshold = DEFAULT_THRESHOLD;
    char *log_file = "current_log.txt";

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            sensitivity = atof(argv[++i]);
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = atof(argv[++i]);
        } else if (strcmp(argv[i], "-l") == 0 && i + 1 < argc) {
            log_file = argv[++i];
        } else {
