    log_file = fopen(CO_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure ADC
    uint16_t config = ADC_CONFIG_OS_SINGLE | ADC_CONFIG_MUX_SINGLE_0 | ADC_CONFIG_PGA_1 |
