        if (adc_value < 0) {
            fprintf(stderr, "I2C read failed\n");
            break;
        }

        // Calculate CO PPM
        co_ppm = calculate_co_ppm(adc_value);

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Log the timestamped PPM value
        fprintf(log_file, "%ld.%09ld, %.2f PPM\n", ts.tv_sec, ts.tv_nsec, co_ppm);
        fflush(log_file);

        // Wait for 5 seconds
        sleep(5);
    }

    // Close resources
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
