#define MCP3008_SPI_SPEED 1000000
#define ADC_MIN_VALUE 0
#define ADC_MAX_VALUE 1023
#define TEMP_MIN_VALUE 10.0
#define TEMP_MAX_VALUE 40.0

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    FILE *file = fopen("flame_data.csv", "a");
    if (!file) {
        fprintf(stderr, "Failed to open flame_data.csv for writing: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        fclose(file);
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(0, MCP3008_SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        fclose(file);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int flame_detected = gpioRead(KY026_DIGITAL_PIN);
        if (flame_detected < 0) {
            fprintf(stderr, "Failed to read KY-026 digital pin: %s\n", pigpio_error(flame_detected));
            continue;
        }

        unsigned char spi_tx[3] = {1, (8 + MCP3008_SPI_CHANNEL) << 4, 0};
        unsigned char spi_rx[3];
        int spi_status = spiXfer(spi_handle, spi_tx, spi_rx, 3);
        if (spi_status < 0) {
            fprintf(stderr, "Failed to transfer data over SPI: %s\n", pigpio_error(spi_status));
            continue;
