        int adc_value = ((spi_rx[1] & 3) << 8) | spi_rx[2];
        double temperature = TEMP_MIN_VALUE + ((double)(adc_value - ADC_MIN_VALUE) / (ADC_MAX_VALUE - ADC_MIN_VALUE)) * (TEMP_MAX_VALUE - TEMP_MIN_VALUE);

