#define I2C_ADDR2 0x49
#define REGISTER 0x00
#define SAMPLE_INTERVAL_US 100000
#define MIC_SENSITIVITY_DBV_PA -38.0
#define REFERENCE_PRESSURE_PA 20e-6

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

double convert_to_dB(int16_t raw_data) {
    double voltage = raw_data * (3.3 / 32768.0); // Assuming 3.3V reference
    double pressure = voltage / (pow(10, MIC_SENSITIVITY_DBV_PA / 20.0));
    double SPL = 20 * log10(pressure / REFERENCE_PRESSURE_PA);
    return SPL;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle1 = i2cOpen(I2C_BUS, I2C_ADDR1, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X\n", I2C_ADDR1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle2 = i2cOpen(I2C_BUS, I2C_ADDR2, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X\n", I2C_ADDR2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen("audio_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t buffer1[2];
        uint8_t buffer2[2];
        int status1 = i2cReadI2CBlockData(i2c_handle1, REGISTER, buffer1, 2);
        int status2 = i2cReadI2CBlockData(i2c_handle2, REGISTER, buffer2, 2);

        int16_t raw_data1 = (buffer1[0] << 8) | buffer1[1];
        int16_t raw_data2 = (buffer2[0] << 8) | buffer2[1];

        double SPL1 = (status1 == 2) ? convert_to_dB(raw_data1) : -999.0;
        double SPL2 = (status2 == 2) ? convert_to_dB(raw_data2) : -999.0;

        double average_SPL = (SPL1 + SPL2) / 2.0;
        time_t now = time(NULL);
        fprintf(log_file, "%s: Average SPL = %.2f dB\n", ctime(&now), average_SPL);

        fflush(log_file);
        usleep(SAMPLE_INTERVAL_US);
    }

    fclose(log_file);
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return EXIT_SUCCESS;
}

