#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SAMPLE_INTERVAL_US 1000
#define SAMPLE_WINDOW_US 100000
#define SAMPLE_COUNT (SAMPLE_WINDOW_US / SAMPLE_INTERVAL_US)
#define RMS_THRESHOLD 0.7
#define LED_PIN 27

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

double calculate_rms(uint16_t *samples, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += samples[i] * samples[i];
    }
    return sqrt(sum / count);
}

void log_to_csv(const char *filename, double timestamp, double mic1_rms, double mic2_rms) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open CSV file");
        return;
    }
    fprintf(file, "%.6f,%.6f,%.6f\n", timestamp, mic1_rms, mic2_rms);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetSignalFunc(SIGINT, signal_handler) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t mic1_samples[SAMPLE_COUNT];
    uint16_t mic2_samples[SAMPLE_COUNT];

    while (running) {
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        for (int i = 0; i < SAMPLE_COUNT; i++) {
            uint8_t tx[3] = {0x01, 0x80, 0x00}; // Read from channel 0
            uint8_t rx[3];
            spiXfer(spi_handle, tx, rx, 3);
            mic1_samples[i] = ((rx[1] & 0x03) << 8) | rx[2];

            tx[1] = 0xC0; // Read from channel 1
            spiXfer(spi_handle, tx, rx, 3);
            mic2_samples[i] = ((rx[1] & 0x03) << 8) | rx[2];

            usleep(SAMPLE_INTERVAL_US);
        }

        clock_gettime(CLOCK_MONOTONIC, &end);
        double elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;

        double mic1_rms = calculate_rms(mic1_samples, SAMPLE_COUNT);
        double mic2_rms = calculate_rms(mic2_samples, SAMPLE_COUNT);

        double timestamp = start.tv_sec + start.tv_nsec / 1e9;
        log_to_csv("audio_events.csv", timestamp, mic1_rms, mic2_rms);

        if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
            gpioWrite(LED_PIN, PI_HIGH);
            usleep(500000);
            gpioWrite(LED_PIN, PI_LOW);
        }

        if (elapsed_time < SAMPLE_WINDOW_US / 1e6) {
            usleep((SAMPLE_WINDOW_US / 1e6 - elapsed_time) * 1e6);
        }
    }

    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

