#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define ADC_CONFIG_REG 0x01
#define ADC_CONVERSION_REG 0x00
#define ADC_CONFIG_OS_SINGLE 0x8000
#define ADC_CONFIG_PGA_1 0x0000
#define ADC_CONFIG_MODE_CONTINUOUS 0x0000
#define ADC_CONFIG_DR_128SPS 0x0080
#define ADC_CONFIG_CMODE_TRAD 0x0000
#define ADC_CONFIG_CQUE_1CONV 0x0000
#define ADC_CONFIG_DEFAULT (ADC_CONFIG_OS_SINGLE | ADC_CONFIG_PGA_1 | ADC_CONFIG_MODE_CONTINUOUS | ADC_CONFIG_DR_128SPS | ADC_CONFIG_CMODE_TRAD | ADC_CONFIG_CQUE_1CONV)
#define ADC_RESOLUTION 32768.0
#define ADC_REF_VOLTAGE 4.5
#define CURRENT_SCALE (100.0 / (ADC_REF_VOLTAGE - 0.5))
#define BUFFER_SIZE 100
#define OVERCURRENT_THRESHOLD 50.0
#define LED_PIN 17
#define SAMPLE_RATE 1000000 / 100 // 10Hz

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for LED\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t config = ADC_CONFIG_DEFAULT;
    if (i2cWriteDevice(i2c_handle, (char*)&config, 2) < 0) {
        fprintf(stderr, "Failed to write to ADC config register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double buffer[BUFFER_SIZE];
    int buffer_index = 0;
    double sum = 0.0;

    signal(SIGINT, signal_handler);

    while (running) {
        uint16_t adc_value;
        if (i2cReadDevice(i2c_handle, (char*)&adc_value, 2) < 0) {
            fprintf(stderr, "Failed to read from ADC\n");
            continue;
        }

        adc_value = (adc_value >> 4) & 0xFFF; // 12-bit result
        double voltage = (adc_value / ADC_RESOLUTION) * ADC_REF_VOLTAGE;
        double current = (voltage - 0.5) * CURRENT_SCALE;

        sum -= buffer[buffer_index];
        buffer[buffer_index] = current;
        sum += current;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        double average_current = sum / BUFFER_SIZE;
        if (average_current > OVERCURRENT_THRESHOLD) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }

        usleep(SAMPLE_RATE);
    }

    gpioWrite(LED_PIN, PI_LOW);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

