#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CE0_LINE 8
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000

#define ADC_CHANNEL_0 0
#define ADC_CHANNEL_1 1

#define MOISTURE_SCALE 1024.0

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_moisture_data(int moisture1, int moisture2) {
    FILE *file = fopen("moisture_log.csv", "a");
    if (!file) {
        perror("Failed to open moisture_log.csv");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strcspn(timestamp, "\n")] = 0; // Remove newline

    fprintf(file, "%s,%d,%d\n", timestamp, moisture1, moisture2);
    fclose(file);
}

int read_adc_channel(int fd, int channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *ce0_line = gpiod_chip_get_line(chip, CE0_LINE);
    if (!ce0_line) {
        perror("Failed to get CE0 line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_output(ce0_line, "mcp3008_ce0", 1);
    if (ret < 0) {
        perror("Failed to request CE0 line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("moisture_log.csv", "a");
    if (!log_file) {
        perror("Failed to open moisture_log.csv");
        gpiod_line_release(ce0_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");
    fclose(log_file);

    while (running) {
        gpiod_line_set_value(ce0_line, 0);
        int moisture1 = read_adc_channel(spi_fd, ADC_CHANNEL_0);
        gpiod_line_set_value(ce0_line, 1);
        gpiod_line_set_value(ce0_line, 0);
        int moisture2 = read_adc_channel(spi_fd, ADC_CHANNEL_1);
        gpiod_line_set_value(ce0_line, 1);

        if (moisture1 >= 0 && moisture2 >= 0) {
            int moisture_percent1 = (moisture1 * 100) / MOISTURE_SCALE;
            int moisture_percent2 = (moisture2 * 100) / MOISTURE_SCALE;
            log_moisture_data(moisture_percent1, moisture_percent2);
        }

        sleep(5);
    }

    gpiod_line_release(ce0_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

