#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define MOTOR_SHUTDOWN_PIN 17
#define OVERCURRENT_THRESHOLD 10.0
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define ADC_REF_VOLTAGE 3.3
#define ADC_RESOLUTION 1024
#define SENSITIVITY 0.1
#define OFFSET 0.05
#define LOG_FILE "current_log.csv"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_current(FILE *log_file, double current) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.2f\n", timestamp, current);
}

double read_adc(int spi_fd, int channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
    };

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) == -1) {
            perror("SPI_IOC_MESSAGE");
            retries++;
            continue;
        }
        break;
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read from ADC after %d retries\n", MAX_RETRIES);
        exit(EXIT_FAILURE);
    }

    int adc_value = ((rx[1] & 3) << 8) | rx[2];
    return adc_value;
}

double convert_adc_to_current(int adc_value) {
    double voltage = (adc_value * ADC_REF_VOLTAGE) / ADC_RESOLUTION;
    return (voltage - OFFSET) / SENSITIVITY;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) == -1) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) == -1) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) == -1) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *shutdown_line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!shutdown_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_output(shutdown_line, "motor_shutdown", 1);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(shutdown_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,current_in_Amperes\n");
    }

    while (running) {
        int adc_value = read_adc(spi_fd, ADC_CHANNEL);
        double current = convert_adc_to_current(adc_value);
        log_current(log_file, current);

        if (current > OVERCURRENT_THRESHOLD) {
            gpiod_line_set_value(shutdown_line, 0);
            fprintf(log_file, "Overcurrent detected, shutting down motor\n");
            log_current(log_file, current);
            sleep(1);
            gpiod_line_set_value(shutdown_line, 1);
        }

        sleep(1);
    }

    fclose(log_file);
    gpiod_line_release(shutdown_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

