volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_pressure(FILE *file, double pressure_kPa) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(file, "%s,%.2f\n", timestamp, pressure_kPa);
    fflush(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(FILENAME, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", FILENAME);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
        fflush(log_file);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint16_t raw_value;
        int result = i2cReadWordData(i2c_handle, PRESSURE_REG, (char *)&raw_value);
        if (result < 0) {
            fprintf(stderr, "I2C read failed for register 0x%02X: %d\n", PRESSURE_REG, result);
            continue;
        }

        double pressure_kPa = (raw_value / 65535.0) * 500.0;
        log_pressure(log_file, pressure_kPa);

        gpioDelay(1000000); // 1 second delay
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

