#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define ADS1115_I2C_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONV 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_MUX_SINGLE_1 0x5000
#define ADS1115_CONFIG_PGA_2_3 0x0200
#define ADS1115_CONFIG_DR_128 0x00E0
#define ADS1115_CONFIG_MODE_CONTINUOUS 0x0000
#define ADS1115_CONFIG_CMODE_TRAD 0x0000
#define ADS1115_CONFIG_CLAT_NONLAT 0x0000
#define ADS1115_CONFIG_CPOL_ACTVLOW 0x0000
#define ADS1115_CONFIG_CQUE_1CONV 0x0003

#define GPIO_WARNING_LED 17

#define VOLTAGE_TO_PRESSURE(v) ((v) * 400.0 / 5.0)
#define VOLTAGE_TO_TEMPERATURE(v) ((v) * 100.0 / 1.0)

#define I2C_RETRIES 3

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int read_adc_channel(int channel) {
    uint16_t config;
    uint16_t data;
    int retries = I2C_RETRIES;

    if (channel == 0) {
        config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_2_3 | ADS1115_CONFIG_DR_128 | ADS1115_CONFIG_MODE_CONTINUOUS | ADS1115_CONFIG_CMODE_TRAD | ADS1115_CONFIG_CLAT_NONLAT | ADS1115_CONFIG_CPOL_ACTVLOW | ADS1115_CONFIG_CQUE_1CONV;
    } else if (channel == 1) {
        config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_1 | ADS1115_CONFIG_PGA_2_3 | ADS1115_CONFIG_DR_128 | ADS1115_CONFIG_MODE_CONTINUOUS | ADS1115_CONFIG_CMODE_TRAD | ADS1115_CONFIG_CLAT_NONLAT | ADS1115_CONFIG_CPOL_ACTVLOW | ADS1115_CONFIG_CQUE_1CONV;
    } else {
        fprintf(stderr, "Invalid channel\n");
        return -1;
    }

    while (retries--) {
        if (i2cWriteWordData(ADS1115_I2C_ADDR, ADS1115_REG_CONFIG, config) < 0) {
            fprintf(stderr, "Failed to write to ADS1115 config register\n");
            continue;
        }

        usleep(13000); // Wait for conversion (128 SPS)

        if (i2cReadWordData(ADS1115_I2C_ADDR, ADS1115_REG_CONV, &data) < 0) {
            fprintf(stderr, "Failed to read from ADS1115 conversion register\n");
            continue;
        }

        return (int16_t)data >> 4; // 12-bit result
    }

    fprintf(stderr, "Failed to read ADC channel after %d retries\n", I2C_RETRIES);
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (i2cOpen(1, ADS1115_I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_WARNING_LED, PI_OUTPUT);
    gpioWrite(GPIO_WARNING_LED, PI_LOW);

    signal(SIGINT, sigint_handler);

    while (running) {
        int pressure_raw = read_adc_channel(0);
        int temperature_raw = read_adc_channel(1);

        if (pressure_raw < 0 || temperature_raw < 0) {
            fprintf(stderr, "Failed to read ADC channels\n");
            continue;
        }

        double pressure_voltage = (double)pressure_raw * 4.096 / 32768.0;
        double temperature_voltage = (double)temperature_raw * 4.096 / 32768.0;

        double pressure_kpa = VOLTAGE_TO_PRESSURE(pressure_voltage);
        double temperature_c = VOLTAGE_TO_TEMPERATURE(temperature_voltage);

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure_kpa, temperature_c);

        if (pressure_kpa > 105.0) {
            gpioWrite(GPIO_WARNING_LED, PI_HIGH);
        } else {
            gpioWrite(GPIO_WARNING_LED, PI_LOW);
        }

        sleep(1);
    }

    i2cClose(1);
    gpioTerminate();

    return EXIT_SUCCESS;
}

