#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define GPIO_SHUTDOWN 27
#define OVERCURRENT_THRESHOLD 10.0
#define VCC 3.3
#define SENSITIVITY 0.066

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s %s\n", ctime(&now), message);
    fflush(log_file);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for shutdown\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        char tx[3] = {0x01, (1 << 6) | (ADC_CHANNEL << 4), 0x00};
        char rx[3];
        int bytes_read = spiXfer(spi_handle, tx, rx, 3);
        if (bytes_read != 3) {
            fprintf(stderr, "SPI transfer failed\n");
            break;
        }

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        if (adc_value < 0 || adc_value >= 1024) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            break;
        }

        double voltage = (adc_value * VCC) / 1024.0;
        double current = (voltage - VCC / 2) / SENSITIVITY;

        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Current: %.2f A", current);
        log_message(log_message);

        if (current > OVERCURRENT_THRESHOLD) {
            gpioWrite(GPIO_SHUTDOWN, PI_HIGH);
            log_message("OVERCURRENT event");
            break;
        }

        usleep(100000);
    }

    spiClose(spi_handle);
    gpioWrite(GPIO_SHUTDOWN, PI_LOW);
    gpioTerminate();
    return EXIT_SUCCESS;
}

