#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define ADC_COMMAND_START 0x01
#define ADC_COMMAND_CONFIG 0x80
#define ADC_COMMAND_DUMMY 0x00
#define ADC_MIN_VALUE 0
#define ADC_MAX_VALUE 1023
#define PPM_MIN 0
#define PPM_MAX 5000
#define LEAK_THRESHOLD 1000
#define LOG_FILE "methane_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void log_reading(int ppm) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(log_file, "%s, %d PPM\n", timestamp, ppm);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        log_error("Failed to open SPI");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t tx[3] = {ADC_COMMAND_START, ADC_COMMAND_CONFIG, ADC_COMMAND_DUMMY};
        uint8_t rx[3] = {0};

        int result = spiXfer(spi_handle, tx, rx, 3);
        if (result < 0) {
            log_error("SPI transfer failed");
            continue;
        }

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        int ppm = (adc_value - ADC_MIN_VALUE) * (PPM_MAX - PPM_MIN) / (ADC_MAX_VALUE - ADC_MIN_VALUE);

        log_reading(ppm);

        if (ppm > LEAK_THRESHOLD) {
            fprintf(stderr, "ALERT: Methane concentration exceeds 1000 PPM!\n");
        }

        gpioDelay(1000000); // Delay for 1 second
    }

    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

