#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define ADS1115_I2C_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_2_048V 0x0200
#define ADS1115_CONFIG_MODE_CONTINUOUS 0x0000
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CMODE_TRAD 0x0000
#define ADS1115_CONFIG_CLAT_NONLAT 0x0000
#define ADS1115_CONFIG_CQUE_NONE 0x0000

#define VREF 3.3
#define OFFSET 0.5
#define SENSITIVITY 0.1

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, ADS1115_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 |
                      ADS1115_CONFIG_PGA_2_048V | ADS1115_CONFIG_MODE_CONTINUOUS |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CMODE_TRAD |
                      ADS1115_CONFIG_CLAT_NONLAT | ADS1115_CONFIG_CQUE_NONE;

    if (i2cWriteWordData(i2c_handle, ADS1115_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Failed to write configuration to ADS1115\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        uint16_t raw_value;
        if (i2cReadWordData(i2c_handle, ADS1115_REG_CONVERSION, &raw_value) < 0) {
            fprintf(stderr, "Failed to read conversion data from ADS1115\n");
            break;
        }

        raw_value = (raw_value >> 4) & 0xFFF; // 12-bit result
        double voltage = (raw_value * VREF) / 4096.0;
        double pressure = (voltage - OFFSET) / SENSITIVITY;

        if (pressure >= 0 && pressure <= 100) {
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
            fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure);
            fflush(log_file);
        }

        time_sleep(1.0);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

