#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL_HUMIDITY 0
#define ADC_CHANNEL_THERMISTOR 1
#define VREF 5.0
#define HUMIDITY_TRANSFER_A 0.824
#define HUMIDITY_TRANSFER_B 0.0315
#define BETA 3950.0
#define R0 10000.0
#define TEMP_NOMINAL 25.0
#define EMAIL_THRESHOLD 80.0

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

double read_adc(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    if (spi_xfer(SPI_CHANNEL, tx, rx, 3) < 0) {
        perror("spi_xfer");
        exit(EXIT_FAILURE);
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

double calculate_humidity(double adc_value) {
    double voltage = adc_value * VREF / 4095.0;
    return (voltage - HUMIDITY_TRANSFER_A) / HUMIDITY_TRANSFER_B;
}

double calculate_temperature(double adc_value) {
    double voltage = adc_value * VREF / 4095.0;
    double resistance = (VREF / voltage - 1) * R0;
    return BETA / (log(resistance / R0) + BETA / (TEMP_NOMINAL + 273.15)) - 273.15;
}

void log_data(double humidity, double temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *log_file = fopen("humidity_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        return;
    }
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(log_file);
}

void send_email_alert(double humidity) {
    char command[256];
    snprintf(command, sizeof(command), "echo 'Humidity is %.2f%%' | ssmtp your_email@example.com", humidity);
    system(command);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioHardwareClock(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "gpioHardwareClock failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_CE, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(SPI_CE, 1);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        double humidity_adc = read_adc(ADC_CHANNEL_HUMIDITY);
        double temperature_adc = read_adc(ADC_CHANNEL_THERMISTOR);
        double humidity = calculate_humidity(humidity_adc);
        double temperature = calculate_temperature(temperature_adc);

        log_data(humidity, temperature);

        if (humidity > EMAIL_THRESHOLD) {
            send_email_alert(humidity);
        }

        sleep(60); // Log every minute
    }

    gpioWrite(SPI_CE, 1);
    gpioTerminate();
    return EXIT_SUCCESS;
}

