#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 8
#define VREF 3.3
#define TMP36_MIN_TEMP -40.0
#define TMP36_MAX_TEMP 125.0
#define SAMPLE_RATE 1

static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;

void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int setup_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return -1;
    }

    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int setup_gpio() {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "mcp3208_cs", 1) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

int read_adc() {
    uint8_t tx[] = {0x01, 0x80, 0x00}; // Start bit, single-ended, channel 0
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to transfer SPI message");
        return -1;
    }

    uint16_t adc_value = ((rx[1] & 0x0F) << 8) | rx[2];
    return adc_value;
}

double adc_to_voltage(int adc_value) {
    return (adc_value * VREF) / 4096.0;
}

double voltage_to_temperature(double voltage) {
    return (voltage - 0.5) / 0.01;
}

void log_temperature(double temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (setup_spi() < 0) {
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("temperature_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    while (1) {
        gpiod_line_set_value(gpio_line, 0);
        int adc_value = read_adc();
        gpiod_line_set_value(gpio_line, 1);

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        double voltage = adc_to_voltage(adc_value);
        double temperature = voltage_to_temperature(voltage);

        if (temperature < TMP36_MIN_TEMP || temperature > TMP36_MAX_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f C\n", temperature);
            continue;
        }

        log_temperature(temperature);
        fflush(log_file);

        sleep(SAMPLE_RATE);
    }

    cleanup();
    return EXIT_SUCCESS;
}

