#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CS_PIN 8
#define ADC_CHANNEL_X 0
#define ADC_CHANNEL_Y 1
#define ADC_CHANNEL_Z 2
#define ADC_REF_VOLTAGE 3.3
#define ADXL335_ZERO_VOLTAGE 1.65
#define ADXL335_SENSITIVITY 0.300
#define IMPACT_THRESHOLD 2.0
#define LOG_FILE "impact_log.txt"
#define SAMPLE_RATE 100

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int spi_transfer(int handle, uint8_t channel, uint16_t *result) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int ret = spiXfer(handle, tx, rx, 3);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", ret);
        return ret;
    }
    *result = ((rx[1] & 3) << 8) | rx[2];
    return 0;
}

double calculate_acceleration(uint16_t adc_value) {
    double voltage = (adc_value / 1023.0) * ADC_REF_VOLTAGE;
    double acceleration = (voltage - ADXL335_ZERO_VOLTAGE) / ADXL335_SENSITIVITY;
    return acceleration;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        uint16_t adc_x, adc_y, adc_z;
        if (spi_transfer(spi_handle, ADC_CHANNEL_X, &adc_x) < 0 ||
            spi_transfer(spi_handle, ADC_CHANNEL_Y, &adc_y) < 0 ||
            spi_transfer(spi_handle, ADC_CHANNEL_Z, &adc_z) < 0) {
            break;
        }

        double acc_x = calculate_acceleration(adc_x);
        double acc_y = calculate_acceleration(adc_y);
        double acc_z = calculate_acceleration(adc_z);
        double acc_magnitude = sqrt(acc_x * acc_x + acc_y * acc_y + acc_z * acc_z);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s, %d, %d, %d, %.2f\n", timestamp, adc_x, adc_y, adc_z, acc_magnitude);
        fflush(log_file);

        if (acc_magnitude > IMPACT_THRESHOLD) {
            fprintf(log_file, "IMPACT DETECTED\n");
            fflush(log_file);
        }

        gpioDelay(1000000 / SAMPLE_RATE);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

