#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1172_I2C_ADDR 0x49
#define SI1172_CMD_REG 0xC0
#define SI1172_FIFO_REG 0xC1
#define SI1172_FIFO_SIZE 4
#define SI1172_MEASUREMENT_CMD 0x10

#define LOG_FILE "biometric_log.csv"

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_handle;
    FILE *log_file;
    struct sigaction sa;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1172_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Write header to log file if it's empty
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,HR,SpO2,Error\n");
        fflush(log_file);
    }

    // Set up signal handler for graceful shutdown
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        uint8_t cmd = SI1172_MEASUREMENT_CMD;
        uint8_t data[SI1172_FIFO_SIZE];
        int error_flag = 0;
        time_t timestamp = time(NULL);

        // Trigger a measurement
        if (i2cWriteByteData(i2c_handle, SI1172_CMD_REG, cmd) < 0) {
            error_flag = 1;
            fprintf(log_file, "%ld,0,0,%d\n", (long)timestamp, error_flag);
            fflush(log_file);
            sleep(1);
            continue;
        }

        // Wait for the measurement to complete
        usleep(100000); // 100ms

        // Read the FIFO data
        if (i2cReadI2CBlockData(i2c_handle, SI1172_FIFO_REG, data, SI1172_FIFO_SIZE) < 0) {
            error_flag = 1;
            fprintf(log_file, "%ld,0,0,%d\n", (long)timestamp, error_flag);
            fflush(log_file);
            sleep(1);
            continue;
        }

        // Extract IR and RED ADC values (proxy for HR and SpO2)
        uint16_t ir_adc = (data[0] << 8) | data[1];
        uint16_t red_adc = (data[2] << 8) | data[3];

        // Log the data
        fprintf(log_file, "%ld,%u,%u,%d\n", (long)timestamp, ir_adc, red_adc, error_flag);
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Close resources
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

