    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", gmtime(&ts));
    fprintf(file, "%s.%06ld,%f\n", timestamp, ts.tv_nsec / 1000, flow_rate);
    fflush(file);
}

int read_adc(int spi_handle, int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int result = spi_xfer(spi_handle, tx, rx, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

double convert_adc_to_flow(int adc_value) {
    double voltage = (adc_value * ADC_REF_VOLTAGE) / ADC_MAX_VALUE;
    return voltage * FLOW_SCALE;
}

