    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int adc_value = read_adc(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            log_flow_rate(log_file, -1.0); // Log error value
            continue;
        }

        double flow_rate = convert_adc_to_flow(adc_value);
        if (flow_rate < 0.0 || flow_rate > 5.0) {
            fprintf(stderr, "Invalid flow rate: %f\n", flow_rate);
            flow_rate = -1.0; // Log error value
        }

        log_flow_rate(log_file, flow_rate);
        gpioDelay(1000000); // Sleep for 1 second
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

