#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x67
#define MEASUREMENT_CMD 0x6845
#define READ_CMD 0x00
#define READ_LEN 6
#define SAMPLE_INTERVAL 5

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    running = 0;
}

void log_error(const char *msg) {
    fprintf(stderr, "%s: %s\n", msg, strerror(errno));
}

int i2c_write(uint8_t reg) {
    uint8_t buf[2] = {reg >> 8, reg & 0xFF};
    if (write(i2c_fd, buf, 2) != 2) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(uint8_t *buf, size_t len) {
    if (read(i2c_fd, buf, len) != len) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

int trigger_measurement() {
    if (i2c_write(MEASUREMENT_CMD) == -1) {
        return -1;
    }
    sleep(1); // Wait for conversion to finish
    return 0;
}

int read_sensor_data(uint8_t *data) {
    if (i2c_write(READ_CMD) == -1) {
        return -1;
    }
    if (i2c_read(data, READ_LEN) == -1) {
        return -1;
    }
    return 0;
}

double convert_pressure(uint16_t pressure_raw) {
    // Apply ICP-10125 calibration formula for pressure
    return pressure_raw * 0.1; // Placeholder formula
}

double convert_temperature(uint16_t temp_raw) {
    // Apply ICP-10125 calibration formula for temperature
    return temp_raw * 0.01; // Placeholder formula
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        log_error("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t data[READ_LEN];
        if (trigger_measurement() == -1 || read_sensor_data(data) == -1) {
            sleep(5);
            continue;
        }

        uint16_t pressure_raw = (data[0] << 8) | data[1];
        uint16_t temp_raw = (data[2] << 8) | data[3];
        double pressure = convert_pressure(pressure_raw);
        double temperature = convert_temperature(temp_raw);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
        fflush(log_file);

        printf("Timestamp: %s, Pressure: %.2f Pa, Temperature: %.2f °C\n", timestamp, pressure, temperature);

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

