void signal_handler(int sig) {
    running = 0;
}

int main(int argc, char *argv[]) {
    double gain = GAIN_DEFAULT;
    if (argc > 1) {
        gain = atof(argv[1]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioHardwareSPIOpen(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    printf("time,channel1,channel2,cancelled\n");

    while (running) {
        uint32_t start_time = gpioTick();
        uint32_t adc_data[2];

        // Read from channel 0
        gpioHardwareSPISendReceive(SPI_CHANNEL, 0x80 | 0x00, (char *)adc_data, 3);
        int channel1 = ((adc_data[1] & 3) << 8) | adc_data[2];

        // Read from channel 1
        gpioHardwareSPISendReceive(SPI_CHANNEL, 0x80 | 0x01, (char *)(adc_data + 1), 3);
        int channel2 = ((adc_data[1] & 3) << 8) | adc_data[2];

        int cancelled = channel1 - channel2;

        printf("%f,%d,%d,%d\n", (gpioTick() - start_time) / 1e6, channel1, channel2, cancelled);

        usleep(1000000 / SAMPLE_RATE);
    }

    gpioHardwareSPIClose(SPI_CHANNEL);
    gpioTerminate();

    return EXIT_SUCCESS;
}

