        double voltage = (double)adc_value / ADC_MAX_VALUE * 3.3;
        double compensated_voltage = voltage + (temperature - 25.0) * 0.001;
        int flame_detected = compensated_voltage > FLAME_THRESHOLD;

        gpiod_line_set_value(buzzer_line, flame_detected);

        log_reading(log_file, voltage, compensated_voltage, temperature, flame_detected);

        usleep(SAMPLE_INTERVAL_US);
    }

    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(spi_fd);

    return EXIT_SUCCESS;
}

