#define WATER_LEVEL_THRESHOLD_HIGH 75
#define WATER_LEVEL_THRESHOLD_LOW 70
#define JSON_FILE "water_levels.json"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_to_json(int water_level) {
    static FILE *json_file = NULL;
    static int first_entry = 1;

    if (!json_file) {
        json_file = fopen(JSON_FILE, "a");
        if (!json_file) {
            perror("Failed to open JSON file");
            return;
        }
        if (first_entry) {
            fprintf(json_file, "[\n");
            first_entry = 0;
        } else {
            fprintf(json_file, ",\n");
        }
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%3NZ", tm_info);

    fprintf(json_file, "  {\n");
    fprintf(json_file, "    \"timestamp\": \"%s\",\n", timestamp);
    fprintf(json_file, "    \"water_level\": %d\n", water_level);
    fprintf(json_file, "  }");

    fflush(json_file);
}

void close_json_file() {
    static FILE *json_file = NULL;
    if (json_file) {
        fprintf(json_file, "\n]\n");
        fclose(json_file);
        json_file = NULL;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        unsigned char tx[3] = {0x01, 0x80 | (ADC_CHANNEL << 4), 0x00};
        unsigned char rx[3] = {0};

        int result = spiXfer(spi_handle, tx, rx, 3);
        if (result < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", pigpio_error(result));
            gpioDelay(500000); // 500ms delay before retrying
            continue;
        }

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        int water_level = (adc_value * 100) / 1023;

        printf("Water Level: %d%%\n", water_level);
        log_to_json(water_level);

        if (water_level > WATER_LEVEL_THRESHOLD_HIGH) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else if (water_level < WATER_LEVEL_THRESHOLD_LOW) {
            gpioWrite(LED_PIN, PI_LOW);
        }

        gpioDelay(5000000); // 5s delay between readings
    }

    close_json_file();
    spiClose(spi_handle);
    gpioWrite(LED_PIN, PI_LOW);
    gpioTerminate();

    return 0;
}

