#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define LOG_FILE "soil_moisture.log"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_entry(FILE *log, int adc_value) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    double moisture_percentage = (double)adc_value / 1023 * 100;
    if (moisture_percentage < 0) moisture_percentage = 0;
    if (moisture_percentage > 100) moisture_percentage = 100;

    fprintf(log, "%s, %d, %.2f%%\n", timestamp, adc_value, moisture_percentage);
    fflush(log);
}

int main(int argc, char *argv[]) {
    int sample_interval = 1000; // default 1 second
    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval <= 0) {
            fprintf(stderr, "Invalid sample interval. Using default 1 second.\n");
            sample_interval = 1000;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Failed to open log file.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        unsigned char tx[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
        unsigned char rx[3];
        int status = spiXfer(spi_handle, tx, rx, 3);
        if (status < 0) {
            fprintf(stderr, "SPI transfer failed.\n");
        } else {
            int adc_value = ((rx[1] & 3) << 8) | rx[2];
            log_entry(log, adc_value);
        }
        gpioDelay(sample_interval * 1000);
    }

    fclose(log);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

