#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define DRY_ADC_VALUE 700
#define WET_ADC_VALUE 300

static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int setup_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        return -1;
    }

    return 0;
}

int setup_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, 8); // CE0 on GPIO8
    if (!cs_line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "spi_cs", 1) < 0) {
        perror("Failed to request GPIO line as output");
        return -1;
    }

    return 0;
}

uint16_t read_adc(uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    gpiod_line_set_value(cs_line, 0); // Select the device

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to transfer data via SPI");
        gpiod_line_set_value(cs_line, 1); // Deselect the device
        return 0;
    }

    gpiod_line_set_value(cs_line, 1); // Deselect the device

    return ((rx[1] & 3) << 8) | rx[2];
}

double calculate_moisture(uint16_t adc_value) {
    double moisture = 100.0 * (double)(DRY_ADC_VALUE - adc_value) / (DRY_ADC_VALUE - WET_ADC_VALUE);
    return moisture < 0 ? 0 : (moisture > 100 ? 100 : moisture);
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (setup_spi() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t adc_value = read_adc(ADC_CHANNEL);
        double moisture = calculate_moisture(adc_value);
        printf("ADC Value: %d, Moisture: %.2f%%\n", adc_value, moisture);
        sleep(5);
    }

    cleanup();
    return EXIT_SUCCESS;
}

