This code sets up the SPI and GPIO for the Raspberry Pi Zero W to read from the DFRobot Soil Moisture Sensor v2.0 connected to an MCP3008 ADC. It reads the ADC value every 5 seconds, calculates the moisture percentage, and logs the results to the console. The program handles signals to clean up resources gracefully.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define ADC_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define VOLTAGE_REF 3.3
#define ADC_MAX 1023
#define MIN_VOLTAGE 0.5
#define MAX_VOLTAGE 4.5
#define MIN_PRESSURE 100
#define MAX_PRESSURE 150

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void log_reading(double pressure, const char *timestamp) {
    printf("%s: Pressure = %.2f kPa\n", timestamp, pressure);
}

double adc_to_voltage(uint16_t adc_value) {
    return (adc_value * VOLTAGE_REF) / ADC_MAX;
}

double voltage_to_pressure(double voltage) {
    if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
        return -1; // Out of range
    }
    return MIN_PRESSURE + ((voltage - MIN_VOLTAGE) * (MAX_PRESSURE - MIN_PRESSURE) / (MAX_VOLTAGE - MIN_VOLTAGE));
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialization failed");
        return EXIT_FAILURE;
    }

    atexit(gpioTerminate);

    if (gpioHardwareClock(SPI_CHANNEL, SPI_SPEED) < 0) {
        log_error("Failed to set hardware clock");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(8, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO8 as output");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint16_t adc_value = 0;
        if (gpioSpiXfer(SPI_CHANNEL, &adc_value, &adc_value, 2) < 0) {
            log_error("SPI transfer failed");
            continue;
        }

        double voltage = adc_to_voltage(adc_value);
        double pressure = voltage_to_pressure(voltage);

        if (pressure == -1) {
            log_error("Voltage out of range");
        } else if (voltage == 0 || voltage == VOLTAGE_REF) {
            log_error("Sensor absent or stuck");
        } else {
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
            log_reading(pressure, timestamp);
        }

        time_sleep(1);
    }

    return EXIT_SUCCESS;
}

