    if (gpioSetMode(8, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO8 as output");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint16_t adc_value = 0;
        if (gpioSpiXfer(SPI_CHANNEL, &adc_value, &adc_value, 2) < 0) {
            log_error("SPI transfer failed");
            continue;
        }

        double voltage = adc_to_voltage(adc_value);
        double pressure = voltage_to_pressure(voltage);

        if (pressure == -1) {
            log_error("Voltage out of range");
        } else if (voltage == 0 || voltage == VOLTAGE_REF) {
            log_error("Sensor absent or stuck");
        } else {
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
            log_reading(pressure, timestamp);
        }

        time_sleep(1);
    }

    return EXIT_SUCCESS;
}
```

This code initializes the pigpio library, sets up the SPI bus, and reads from the MCP3008 ADC connected to the Melexis MLX90823 pressure sensor. It converts the ADC value to a voltage and then maps the voltage to a pressure value. The readings are logged with ISO-8601 timestamps. The program handles errors and exits cleanly on signals.

