#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define ADC_CHANNEL 0
#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700
#define READ_INTERVAL 5

static struct gpiod_chip *chip;
static struct gpiod_line *cs_line;
static int spi_fd;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void signal_handler(int signum) {
    running = 0;
}

int spi_transfer(uint8_t tx, uint8_t *rx) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long) &tx,
        .rx_buf = (unsigned long) rx,
        .len = 1,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }
    return 0;
}

uint16_t read_adc(uint8_t channel) {
    uint8_t tx = 0x01 | ((channel & 0x07) << 3);
    uint8_t rx[2] = {0};
    uint16_t result;

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }

    if (spi_transfer(tx, rx) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (spi_transfer(0x00, rx + 1) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }

    result = ((rx[0] & 0x03) << 8) | rx[1];
    return result;
}

double adc_to_moisture(uint16_t adc_value) {
    if (adc_value <= MIN_ADC_VALUE) return 100.0;
    if (adc_value >= MAX_ADC_VALUE) return 0.0;
    return 100.0 - ((double)(adc_value - MIN_ADC_VALUE) / (MAX_ADC_VALUE - MIN_ADC_VALUE)) * 100.0;
}

int main() {
    struct sigaction sa;
    struct timespec ts;
    uint16_t adc_value;
    double moisture;

    atexit(cleanup);

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_label");
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_get_line(chip, 8);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008_cs", 1) < 0) {
        perror("gpiod_line_request_output");
        return EXIT_FAILURE;
    }

    while (running) {
        adc_value = read_adc(ADC_CHANNEL);
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Error: ADC value out of range, possible wiring fault.\n");
            break;
        }

        moisture = adc_to_moisture(adc_value);
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%09ld: ADC Value: %d, Moisture: %.2f%%\n", ts.tv_sec, ts.tv_nsec, adc_value, moisture);

        sleep(READ_INTERVAL);
    }

    return EXIT_SUCCESS;
}

