#define ADC_START_BIT 0x01
#define ADC_SINGLE_ENDED 0x80
#define ADC_CHANNEL_MASK 0x07

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    int spi_fd;
    struct sigaction sa;
    struct spi_ioc_transfer xfer;
    uint8_t tx[3] = {0};
    uint8_t rx[3] = {0};
    int ret;

    // Set up signal handler for graceful exit
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set max speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set max speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Configure the SPI transfer
    tx[0] = (ADC_START_BIT | ADC_SINGLE_ENDED | (CHANNEL & ADC_CHANNEL_MASK));
    xfer.tx_buf = (unsigned long)tx;
    xfer.rx_buf = (unsigned long)rx;
    xfer.len = 3;
    xfer.delay_usecs = 0;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = SPI_BITS_PER_WORD;

    while (running) {
        // Perform SPI transfer
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret < 0) {
            perror("Failed to perform SPI transfer");
            close(spi_fd);
            exit(EXIT_FAILURE);
        }

        // Extract 10-bit result
        uint16_t adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        // Convert ADC value to moisture percentage (assuming linear mapping)
        int moisture_percentage = (adc_value * 100) / 1023;
        // Clamp to 0-100 range
        moisture_percentage = (moisture_percentage < 0) ? 0 : ((moisture_percentage > 100) ? 100 : moisture_percentage);

        printf("Moisture Percentage: %d%%\n", moisture_percentage);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close SPI device
    close(spi_fd);

    return 0;
}

