    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure GPIO line as output
    if (gpiod_line_request_output(gpio_line, "spi_cs", 1) < 0) {
        perror("Failed to request GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Write header to log file
    if (fprintf(log_file, "Timestamp,Channel0,Channel1,Channel2,Channel3\n") < 0) {
        perror("Failed to write to log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        unsigned short adc_values[CHANNELS];
        for (int i = 0; i < CHANNELS; i++) {
            gpiod_line_set_value(gpio_line, 0); // Select ADC
            adc_values[i] = read_adc_channel(i);
            gpiod_line_set_value(gpio_line, 1); // Deselect ADC
        }

        if (fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f\n",
                   timestamp,
                   convert_to_voltage(adc_values[0]),
                   convert_to_voltage(adc_values[1]),
