#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define PUMP_GPIO 17
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define LOG_CAPACITY 20

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

LogEntry log_buffer[LOG_CAPACITY];
int log_index = 0;

void log_entry(int moisture_level, int pump_state) {
    log_buffer[log_index].timestamp = time(NULL);
    log_buffer[log_index].moisture_level = moisture_level;
    log_buffer[log_index].pump_state = pump_state;
    log_index = (log_index + 1) % LOG_CAPACITY;
}

void print_log() {
    for (int i = 0; i < LOG_CAPACITY; i++) {
        if (log_buffer[i].timestamp != 0) {
            printf("Timestamp: %s", ctime(&log_buffer[i].timestamp));
            printf("Moisture Level: %d\n", log_buffer[i].moisture_level);
            printf("Pump State: %s\n", log_buffer[i].pump_state ? "ON" : "OFF");
        }
    }
}

void handle_sigint(int sig) {
    gpioSetTimerFunc(0, 0, NULL);
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
    exit(0);
}

int read_moisture(int spi_handle) {
    unsigned char tx[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
    unsigned char rx[3];
    int result = gpioSpiXfer(spi_handle, tx, rx, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int spi_handle = gpioOpenSPI(SPI_CHANNEL, SPI_SPEED | SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0);

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    int pump_state = 0;
    gpioSetTimerFunc(0, 5000, []() {
        int moisture_level = read_moisture(spi_handle);
        if (moisture_level < 0) {
            return;
        }

        if (moisture_level < LOW_THRESHOLD && !pump_state) {
            gpioWrite(PUMP_GPIO, 1);
            pump_state = 1;
        } else if (moisture_level > HIGH_THRESHOLD && pump_state) {
            gpioWrite(PUMP_GPIO, 0);
            pump_state = 0;
        }

        log_entry(moisture_level, pump_state);
        print_log();
    });

    while (1) {
        time_t now = time(NULL);
        printf("Current Time: %s", ctime(&now));
        sleep(1);
    }

    gpioSetTimerFunc(0, 0, NULL);
    gpioWrite(PUMP_GPIO, 0);
    gpioCloseSPI(spi_handle);
    gpioTerminate();

    return 0;
}

