            snprintf(message, sizeof(message), "High heart rate detected: %d BPM", heart_rate);
            log_message(message);
        }

        usleep(SAMPLE_INTERVAL);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

