#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define VREF 3.3
#define NUM_CHANNELS 3
#define CSV_FILE "analog_log.csv"

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void log_voltage(FILE *csv, int channel, double voltage) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);
    fprintf(csv, "%s,%d,%.2f\n", timestamp, channel, voltage);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    FILE *csv = fopen(CSV_FILE, "a");
    if (!csv) {
        fprintf(stderr, "Failed to open CSV file %s\n", CSV_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (ftell(csv) == 0) {
        fprintf(csv, "Timestamp,Channel,Voltage\n");
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        for (int channel = 0; channel < NUM_CHANNELS; channel++) {
            char tx_buf[3] = {0x01, (0x80 | (channel << 4)), 0x00};
            char rx_buf[3];
            int status = spiXfer(spi_handle, tx_buf, rx_buf, 3);
            if (status < 0) {
                fprintf(stderr, "SPI transfer failed for channel %d\n", channel);
                continue;
            }

            int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
            double voltage = (adc_value * VREF) / 1023.0;
            log_voltage(csv, channel, voltage);
        }

        gpioDelay(500000); // 500 ms
    }

    fclose(csv);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

