#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_1 0x0000
#define ADS1115_CONFIG_MODE_CONTINUOUS 0x0000
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CMODE_TRAD 0x0000
#define ADS1115_CONFIG_CPOL_ACTVLOW 0x0000
#define ADS1115_CONFIG_CLAT_NONLAT 0x0000
#define ADS1115_CONFIG_CQUE_1CONV 0x0003

#define RELAY_PIN 17
#define REED_PIN 27
#define LOG_FILE "/var/log/door_events.log"

#define SAMPLE_COUNT 10
#define SAMPLE_INTERVAL_US 50000
#define POLL_INTERVAL_US 200000
#define RELAY_DURATION_US 3000000
#define THRESHOLD_MULTIPLIER 0.8

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_line = NULL;
static FILE *log_file = NULL;

static void cleanup() {
    if (relay_line) {
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (reed_line) {
        gpiod_line_release(reed_line);
        reed_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

static void log_event(const char *event) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%03ld: %s\n", ts.tv_sec, ts.tv_nsec / 1000000, event);
    fflush(log_file);
}

static int read_adc() {
    uint8_t config[3] = {
        ADS1115_REG_CONFIG,
        (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_1 |
         ADS1115_CONFIG_MODE_CONTINUOUS | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CMODE_TRAD |
         ADS1115_CONFIG_CPOL_ACTVLOW | ADS1115_CONFIG_CLAT_NONLAT | ADS1115_CONFIG_CQUE_1CONV) >> 8,
        (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_1 |
         ADS1115_CONFIG_MODE_CONTINUOUS | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CMODE_TRAD |
         ADS1115_CONFIG_CPOL_ACTVLOW | ADS1115_CONFIG_CLAT_NONLAT | ADS1115_CONFIG_CQUE_1CONV) & 0xFF
    };

    if (write(i2c_fd, config, 3) != 3) {
        perror("Failed to write to ADS1115");
        return -1;
    }

    usleep(10000); // Wait for conversion

    uint8_t buffer[2];
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read from ADS1115");
        return -1;
    }

    int16_t value = (buffer[0] << 8) | buffer[1];
    return value;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        cleanup();
        return EXIT_FAILURE;
    }

    reed_line = gpiod_chip_get_line(chip, REED_PIN);
    if (!reed_line) {
        perror("Failed to get reed line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        perror("Failed to request relay line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(reed_line, "reed") < 0) {
        perror("Failed to request reed line");
        cleanup();
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    int baseline_sum = 0;
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        int value = read_adc();
        if (value < 0) {
            log_event("Failed to read ADC");
            continue;
        }
        baseline_sum += value;
        usleep(SAMPLE_INTERVAL_US);
    }

    int threshold = (baseline_sum / SAMPLE_COUNT) * THRESHOLD_MULTIPLIER;
    log_event("Calibrated threshold set");

    while (1) {
        int value = read_adc();
        if (value < 0) {
            log_event("Failed to read ADC");
            continue;
        }

        if (value < threshold) {
            gpiod_line_set_value(relay_line, 1);
            log_event("Relay activated");
            usleep(RELAY_DURATION_US);
            gpiod_line_set_value(relay_line, 0);
            log_event("Relay deactivated");

            int reed_state = gpiod_line_get_value(reed_line);
            if (reed_state == 0) {
                log_event("Door opened");
            } else {
                log_event("Door not opened");
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

