#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0

#define CS0 8
#define CS1 7
#define CS2 25

#define CHANNEL 0

#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int read_mcp3008(int spi_fd, struct gpiod_line *cs_line) {
    uint8_t tx[] = {0x01, (0x08 | CHANNEL) << 4, 0x00};
    uint8_t rx[3] = {0};

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Failed to set CS line low");
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE failed");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Failed to set CS line high");
        return -1;
    }

    int result = ((rx[1] & 0x03) << 8) | rx[2];
    return result;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *cs0_line = gpiod_chip_get_line(chip, CS0);
    struct gpiod_line *cs1_line = gpiod_chip_get_line(chip, CS1);
    struct gpiod_line *cs2_line = gpiod_chip_get_line(chip, CS2);

    if (!cs0_line || !cs1_line || !cs2_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(cs0_line, "mcp3008_cs0", 1) < 0 ||
        gpiod_line_request_output(cs1_line, "mcp3008_cs1", 1) < 0 ||
        gpiod_line_request_output(cs2_line, "mcp3008_cs2", 1) < 0) {
        perror("Failed to request GPIO lines as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
    }

    while (running) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        int sensor1 = read_mcp3008(spi_fd, cs0_line);
        int sensor2 = read_mcp3008(spi_fd, cs1_line);
        int sensor3 = read_mcp3008(spi_fd, cs2_line);

        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);
        fflush(log_file);

        sleep(5);
    }

    fclose(log_file);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

