#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <wiringPiSPI.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define DRY_THRESHOLD 200
#define WET_THRESHOLD 800
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_INTERVAL 60
#define LOG_FILE "irrigation.log"
#define MAX_RETRIES 3

int threshold = DEFAULT_THRESHOLD;
int duration = DEFAULT_DURATION;
int interval = DEFAULT_INTERVAL;
int spi_fd = -1;
int pump_state = 0;

void log_message(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        time_t now = time(NULL);
        fprintf(log, "%s %s\n", ctime(&now), message);
        fclose(log);
    }
}

void activate_pump() {
    gpioWrite(PUMP_GPIO, 1);
    pump_state = 1;
    log_message("Pump activated");
}

void deactivate_pump() {
    gpioWrite(PUMP_GPIO, 0);
    pump_state = 0;
    log_message("Pump deactivated");
}

int read_adc(int channel) {
    unsigned char buffer[3];
    buffer[0] = 1; // start bit
    buffer[1] = (8 + channel) << 4; // single-ended mode
    buffer[2] = 0;

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == 3) {
            return ((buffer[1] & 3) << 8) + buffer[2];
        }
        retries++;
        usleep(100000); // 100 ms delay before retry
    }
    log_message("SPI read failed after multiple retries");
    return -1;
}

void handle_sigint(int sig) {
    deactivate_pump();
    if (spi_fd != -1) {
        close(spi_fd);
    }
    gpioTerminate();
    exit(0);
}

void parse_options(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration_seconds] [-s sleep_interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    parse_options(argc, argv);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    deactivate_pump();

    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI setup failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value == -1) {
            // Skip this cycle if SPI read fails
            sleep(interval);
            continue;
        }

        int moisture_percent = (adc_value - DRY_THRESHOLD) * 100 / (WET_THRESHOLD - DRY_THRESHOLD);
        moisture_percent = moisture_percent < 0 ? 0 : (moisture_percent > 100 ? 100 : moisture_percent);

        char log_entry[100];
        snprintf(log_entry, sizeof(log_entry), "Moisture: %d%%", moisture_percent);
        log_message(log_entry);

        if (moisture_percent < threshold) {
            activate_pump();
            sleep(duration);
            deactivate_pump();
        }

        sleep(interval);
    }

    return 0;
}

