#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <syslog.h>

#define ADC_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SAMPLE_INTERVAL_US 10000
#define EMA_ALPHA 0.1
#define PEAK_THRESHOLD 0.2

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_peak(int value) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    FILE *log_file = fopen("/var/log/sound_events.log", "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %m");
        return;
    }

    fprintf(log_file, "%s, %d\n", timestamp, value);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetSignalFunc(SIGINT, signal_handler) < 0 ||
        gpioSetSignalFunc(SIGTERM, signal_handler) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double ema = 0.0;
    int last_value = 0;

    while (running) {
        uint8_t tx[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
        uint8_t rx[3];
        spiXfer(spi_handle, tx, rx, 3);

        int value = ((rx[1] & 3) << 8) | rx[2];

        if (ema == 0.0) {
            ema = value;
        } else {
            ema = EMA_ALPHA * value + (1 - EMA_ALPHA) * ema;
        }

        if (value > ema * (1 + PEAK_THRESHOLD) && value != last_value) {
            log_peak(value);
        }

        last_value = value;
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

