#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define PCF8591_ADDRESS 0x48
#define CONTROL_BYTE 0x40 // Single-ended mode on channel 0, analog output disabled

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct sigaction sa;

    // Set up signal handler for SIGINT
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open the I2C bus
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Perform a dummy read to discard the previous conversion result
    uint8_t dummy;
    if (read(i2c_fd, &dummy, 1) != 1) {
        perror("Failed to perform dummy read");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Write the control byte to select the channel and mode
        if (write(i2c_fd, &CONTROL_BYTE, 1) != 1) {
            perror("Failed to write control byte");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Read the analog value from AIN0
        uint8_t sample;
        if (read(i2c_fd, &sample, 1) != 1) {
            perror("Failed to read analog value");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Print the sample value
        printf("Sample value: %d\n", sample);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close the I2C file descriptor
    close(i2c_fd);

    return 0;
}

