#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

#define ADC_ADDRESS 0x48
#define ADC_CHANNEL 0x80 // Single-ended AIN0
#define ADC_CONFIG_REG 0x01
#define ADC_CONVERSION_REG 0x00
#define ADC_CONFIG_DEFAULT 0x4093 // 128 SPS, AIN0, GND, 1.024V, unipolar
#define ADC_VREF 3.3
#define SS49E_ZERO_FIELD 2.5
#define SS49E_SENSITIVITY 0.0014 // 1.4 mV/Gauss
#define BUFFER_SIZE 10
#define THRESHOLD_GAUSS 500

static int i2c_handle = -1;
static int gpio_shutdown = 27;
static double buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int threshold_exceeded = 0;

void log_message(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

void handle_signal(int signum) {
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    gpioWrite(gpio_shutdown, PI_LOW);
    gpioTerminate();
    closelog();
    exit(EXIT_SUCCESS);
}

double read_adc_voltage() {
    int adc_value = i2cReadWordData(i2c_handle, ADC_CONVERSION_REG);
    if (adc_value == -1) {
        log_message("I2C read failed");
        return -1;
    }
    adc_value = ((adc_value >> 4) & 0xFFF);
    return (adc_value * ADC_VREF) / 4096.0;
}

double convert_voltage_to_gauss(double voltage) {
    if (voltage < 0 || voltage > ADC_VREF) {
        log_message("Invalid voltage reading");
        return -1;
    }
    return ((voltage - SS49E_ZERO_FIELD) / SS49E_SENSITIVITY);
}

void update_buffer(double gauss) {
    buffer[buffer_index] = gauss;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

double calculate_rolling_average() {
    double sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += buffer[i];
    }
    return sum / buffer_count;
}

int main() {
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        log_message("pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(gpio_shutdown, PI_OUTPUT);
    gpioWrite(gpio_shutdown, PI_LOW);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_handle = i2cOpen(1, ADC_ADDRESS, 0);
    if (i2c_handle == -1) {
        log_message("I2C open failed");
        gpioTerminate();
        closelog();
