        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int result = spiXfer(SPI_DEVICE, tx, rx, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((rx[1] & 3) << 8) | rx[2];
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

void activate_pump(int duration) {
    gpioWrite(PUMP_GPIO, PI_HIGH);
    sleep(duration);
    gpioWrite(PUMP_GPIO, PI_LOW);
}

