        fprintf(stderr, "Failed to set GPIO mode for pump\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(PUMP_GPIO, PI_LOW) < 0) {
        fprintf(stderr, "Failed to set initial state for pump\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (spiOpen(SPI_DEVICE, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int moisture_level = read_adc(ADC_CHANNEL);
        if (moisture_level < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            break;
        }

        log_event("Moisture level read", moisture_level);

        if (moisture_level < ADC_THRESHOLD) {
            log_event("Watering cycle started", moisture_level);
            activate_pump(PUMP_DURATION);
            log_event("Watering cycle ended", moisture_level);
        }

        sleep(60);
    }

    gpioWrite(PUMP_GPIO, PI_LOW);
    spiClose(SPI_DEVICE);
    gpioTerminate();

    return EXIT_SUCCESS;
}

