    while (running) {
        unsigned char tx[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
        unsigned char rx[3];

        int result = spiXfer(spi_handle, tx, rx, 3);
        if (result < 0) {
            fprintf(stderr, "SPI transfer failed, retrying...\n");
            continue;
        }

        int adc_value = ((rx[1] & 3) << 8) | rx[2];
        int rain_intensity = (adc_value * RAIN_INTENSITY_SCALE) / ADC_FULL_SCALE;

        time_t now = time(NULL);
        printf("%s ADC Value: %d, Rain Intensity: %d\n", ctime(&now), adc_value, rain_intensity);
        fflush(stdout);

        gpioDelay(1000000); // Sleep for 1 second
    }

    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

