#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define PWM_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 1023
#define READ_INTERVAL 100000 // 100 ms in microseconds

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(EXIT_FAILURE);
    }

    // Open SPI device
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up PWM
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    while (running) {
        // Read from ADC
        uint8_t tx[] = {1, (8 + ADC_CHANNEL) << 4, 0};
        uint8_t rx[3];
        int result = spiXfer(spi_handle, tx, rx, 3);
        if (result < 0) {
            fprintf(stderr, "SPI transfer failed: %d\n", result);
            continue;
        }

        // Combine bytes to get 10-bit ADC value
        uint16_t adc_value = ((rx[1] & 3) << 8) | rx[2];

        // Set PWM duty cycle
        gpioPWM(PWM_GPIO, adc_value);

        // Print values
        printf("ADC Value: %d, PWM Duty Cycle: %d\n", adc_value, adc_value);

        // Wait for next read
        gpioDelay(READ_INTERVAL);
    }

    // Clean up
    gpioPWM(PWM_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

