#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <paho-mqtt/MQTTClient.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define RELAY_PIN 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_CLIENT_ID "soil_moisture_client"
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_adc(int channel) {
    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (handle < 0) {
        syslog(LOG_ERR, "Failed to open SPI: %s", spiErrStr(handle));
        return -1;
    }

    unsigned char tx[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx[3];
    int result = spiXfer(handle, tx, rx, 3);
    spiClose(handle);

    if (result < 0) {
        syslog(LOG_ERR, "SPI transfer failed: %s", spiErrStr(result));
        return -1;
    }

    return ((rx[1] & 3) << 8) + rx[2];
}

void publish_mqtt(MQTTClient client, const char* topic, const char* payload) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = (void*)payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;
    MQTTClient_deliveryToken token;
    MQTTClient_publishMessage(client, topic, &pubmsg, &token);
    MQTTClient_waitForCompletion(client, token, 1000);
}

void on_message(void* context, char* topicName, int topicLen, MQTTClient_message* message) {
    char* payload = (char*)message->payload;
    if (strcmp(topicName, MQTT_TOPIC_PUMP_CONTROL) == 0) {
        if (strcmp(payload, "pump_on") == 0) {
            gpioWrite(RELAY_PIN, PI_HIGH);
            syslog(LOG_INFO, "Pump turned on via MQTT");
        } else if (strcmp(payload, "pump_off") == 0) {
            gpioWrite(RELAY_PIN, PI_LOW);
            syslog(LOG_INFO, "Pump turned off via MQTT");
        }
    }
    MQTTClient_freeMessage(&message);
    MQTTClient_free(topicName);
}

int main() {
    openlog("soil_moisture", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, PI_LOW);

    MQTTClient client;
    MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    MQTTClient_setCallbacks(client, NULL, NULL, on_message, NULL);
    MQTTClient_subscribe(client, MQTT_TOPIC_PUMP_CONTROL, 1);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int moisture = read_adc(ADC_CHANNEL);
        if (moisture < 0) {
            syslog(LOG_ERR, "Failed to read moisture sensor");
        } else {
            char payload[10];
            snprintf(payload, sizeof(payload), "%d", moisture);
            publish_mqtt(client, MQTT_TOPIC_SOIL_MOISTURE, payload);
            syslog(LOG_INFO, "Moisture level: %d%%", moisture);

            if (moisture < MOISTURE_THRESHOLD_LOW) {
                gpioWrite(RELAY_PIN, PI_HIGH);
                syslog(LOG_INFO, "Pump activated due to low moisture");
            } else if (moisture > MOISTURE_THRESHOLD_HIGH) {
                gpioWrite(RELAY_PIN, PI_LOW);
                syslog(LOG_INFO, "Pump deactivated due to high moisture");
            }
        }
        sleep(60);
    }

    gpioWrite(RELAY_PIN, PI_LOW);
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

