#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

#define MCP3008_CHANNEL 0
#define MCP3008_VREF 3.3

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int spi_fd;
    struct sigaction sa;
    struct spi_ioc_transfer xfer;
    uint8_t tx[3] = {0x01, (MCP3008_CHANNEL << 6) | 0x80, 0x00};
    uint8_t rx[3];
    int ret;

    // Set up signal handler for SIGINT
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret == -1) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret == -1) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set max speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret == -1) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // SPI transfer setup
    xfer.tx_buf = (unsigned long)tx;
    xfer.rx_buf = (unsigned long)rx;
    xfer.len = 3;
    xfer.delay_usecs = 0;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = SPI_BITS_PER_WORD;

    while (running) {
        // Perform SPI transfer
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret == -1) {
            perror("ioctl(SPI_IOC_MESSAGE)");
            close(spi_fd);
            exit(EXIT_FAILURE);
        }

        // Extract 10-bit result
        uint16_t raw_value = ((rx[1] & 0x03) << 8) | rx[2];
        double voltage = raw_value * MCP3008_VREF / 1024.0;

        // Print results
        printf("Raw Value: %d, Voltage: %.3f V\n", raw_value, voltage);

        // Sleep for 500 ms
        usleep(500000);
    }

    // Close SPI device
    close(spi_fd);

    return 0;
}

