#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define CE_PIN 8
#define VREF 3.3
#define RESOLUTION 1024
#define SAMPLE_INTERVAL 5

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    FILE *file = fopen("sensor_data.csv", "w");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        fclose(file);
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0);
    if (spi_handle < 0) {
        perror("Failed to open SPI");
        gpioTerminate();
        fclose(file);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(file, "Timestamp,Channel0,Channel1,Channel2\n");

    while (running) {
        uint8_t tx[3] = {0x01, 0x80, 0x00};
        uint8_t rx[3];

        for (int channel = 0; channel < 3; channel++) {
            tx[1] = 0x80 | (channel << 4);
            if (spiXfer(spi_handle, tx, rx, 3) < 0) {
                perror("SPI transfer failed");
                break;
            }

