#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define SAMPLE_INTERVAL_US 10000
#define NOISE_THRESHOLD 500
#define PWM_FREQUENCY 100

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int setup_spi(int *fd) {
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(*fd);
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(*fd);
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(*fd);
        return -1;
    }

    return 0;
}

int read_adc(int fd, uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Failed to read from ADC");
        return -1;
    }

    return ((rx[1] & 3) << 8) + rx[2];
}

void log_event(const char *message) {
    FILE *log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&now), message);
    fclose(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY);

    int spi_fd;
    if (setup_spi(&spi_fd) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            continue;
        }

        if (adc_value > NOISE_THRESHOLD) {
            int duty_cycle = (adc_value - NOISE_THRESHOLD) * 100 / (1023 - NOISE_THRESHOLD);
            gpioPWM(MOTOR1_GPIO, duty_cycle);
            gpioPWM(MOTOR2_GPIO, duty_cycle);

            char message[100];
            snprintf(message, sizeof(message), "Noise level: %d, Duty cycle: %d%%", adc_value, duty_cycle);
            log_event(message);
        } else {
            gpioPWM(MOTOR1_GPIO, 0);
            gpioPWM(MOTOR2_GPIO, 0);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    gpioPWM(MOTOR1_GPIO, 0);
    gpioPWM(MOTOR2_GPIO, 0);
    close(spi_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

