#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES_MODE2 0x11
#define BH1750_DELAY_MS 180
#define MCP3008_CHANNEL 0
#define CSV_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL 5

static int spi_fd = -1;
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void cleanup() {
    if (csv_file) {
        fclose(csv_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int read_adc(int channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int read_bh1750() {
    uint8_t cmd = BH1750_CONT_HIGH_RES_MODE2;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }

    usleep(BH1750_DELAY_MS * 1000);

    uint16_t lux;
    if (read(i2c_fd, &lux, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }

    lux = (lux >> 8) | (lux << 8);
    return lux / 1.2;
}

void log_data() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    int sound_level = read_adc(MCP3008_CHANNEL);
    int light_level = read_bh1750();
    int error_code = (sound_level < 0) || (light_level < 0);

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, sound_level, light_level, error_code);
    fflush(csv_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        cleanup();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 0); // Assuming GPIO0 for CE0
    if (!line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "spi-ce0", 0) < 0) {
        perror("Failed to request GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    while (1) {
        log_data();
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

