    while (retries < MAX_RETRIES) {
        if (spiXfer(handle, tx, rx, 3) == 0) {
            spiClose(handle);
            int result = ((rx[1] & 3) << 8) + rx[2];
            return result;
        }
        retries++;
        spiClose(handle);
        handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
        if (handle < 0) {
            fprintf(stderr, "Failed to reopen SPI channel %d\n", SPI_CHANNEL);
            return -1;
        }
    }

    spiClose(handle);
    fprintf(stderr, "Failed to read from ADC after %d retries\n", MAX_RETRIES);
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, PI_LOW);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int adc_value = read_adc_channel(ADC_CHANNEL);
        if (adc_value < 0) {
            continue;
        }

        // Convert ADC value to percentage (assuming 1023 is 100%)
        float moisture_percentage = (adc_value * 100.0) / 1023.0;
        printf("Moisture: %.2f%%\n", moisture_percentage);

        if (moisture_percentage < MOISTURE_THRESHOLD) {
            gpioWrite(PUMP_GPIO, PI_HIGH);
            printf("Pump activated\n");
        } else {
            gpioWrite(PUMP_GPIO, PI_LOW);
            printf("Pump deactivated\n");
        }

        time_t now = time(NULL);
        printf("Timestamp: %s", ctime(&now));

        sleep(LOG_INTERVAL);
    }

    gpioWrite(PUMP_GPIO, PI_LOW);
    gpioTerminate();
    printf("Program terminated gracefully\n");

    return EXIT_SUCCESS;
}
