#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define RELAY_GPIO 17
#define PROXIMITY_THRESHOLD 200  // 20 cm in ADC units
#define POLL_INTERVAL 100000  // 100 ms
#define DEBOUNCE_DELAY 1000000  // 1 s

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static int spi_fd;
static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void log_event(const char *event) {
    FILE *log_file = fopen("door_events.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "[%s] %s\n", timestamp, event);
    fclose(log_file);
}

int read_adc(int channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    return ((rx[1] & 3) << 8) + rx[2];
}

int main() {
    signal(SIGINT, sigint_handler);

    // Initialize GPIO
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int last_state = 0;
    time_t last_trigger = 0;

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            log_event("ADC read error");
            continue;
        }

        int proximity_detected = (adc_value < PROXIMITY_THRESHOLD);

        if (proximity_detected && !last_state) {
            time_t now = time(NULL);
            if (now - last_trigger > DEBOUNCE_DELAY / 1000000) {
                gpiod_line_set_value(relay_line, 1);
                log_event("Door opened");
                last_trigger = now;
            }
        } else if (!proximity_detected && last_state) {
            gpiod_line_set_value(relay_line, 0);
            log_event("Door closed");
        }

        last_state = proximity_detected;
        usleep(POLL_INTERVAL);
    }

    // Cleanup
    gpiod_line_set_value(relay_line, 0);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

