#define ADC_SPI_CHANNEL 0
#define ADC_SPI_SPEED 1000000
#define ADC_SPI_MODE 0
#define PWM_GPIO 17
#define PWM_FREQ 100
#define PWM_RANGE 100
#define LOG_FILE "irrigation.log"
#define LOG_INTERVAL 5

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_adc_channel(int channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int result = spiXfer(ADC_SPI_CHANNEL, tx, rx, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed for channel %d\n", channel);
        return -1;
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

void log_data(int adc0, int adc1, int adc2, int avg, int valve_pos) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log, "%04d-%02d-%02d %02d:%02d:%02d, ADC0: %d, ADC1: %d, ADC2: %d, Avg: %d, Valve: %d%%\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            adc0, adc1, adc2, avg, valve_pos);
    fclose(log);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int spi_handle = spiOpen(ADC_SPI_CHANNEL, ADC_SPI_SPEED, ADC_SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", ADC_SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int adc0 = read_adc_channel(ADC_CHANNEL_0);
        int adc1 = read_adc_channel(ADC_CHANNEL_1);
        int adc2 = read_adc_channel(ADC_CHANNEL_2);

        int valid_count = 0;
        int sum = 0;
        if (adc0 >= 0) {
            sum += adc0;
            valid_count++;
        }
        if (adc1 >= 0) {
            sum += adc1;
            valid_count++;
        }
        if (adc2 >= 0) {
            sum += adc2;
            valid_count++;
        }

        int avg = valid_count > 0 ? sum / valid_count : 0;
        int valve_pos = 100 - (avg * 100 / 1023);

        gpioPWM(PWM_GPIO, valve_pos);

        log_data(adc0, adc1, adc2, avg, valve_pos);

        sleep(LOG_INTERVAL);
    }

    gpioPWM(PWM_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

