#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define LOG_FILE "soil_data.txt"
#define MAX_RETRIES 5
#define RETRY_BACKOFF 100000 // 100ms

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_adc(int spi_handle, int channel) {
    char tx[3] = {1, (8 + channel) << 4, 0};
    char rx[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (spi_xfer(spi_handle, tx, rx, 3) == 0) {
            int adc_value = ((rx[1] & 3) << 8) | rx[2];
            if (adc_value >= 0 && adc_value <= 1023) {
                return adc_value;
            }
        }
        retries++;
        usleep(RETRY_BACKOFF * (1 << retries));
    }

    fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
    return -1;
