#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>
#include <math.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define ADC_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define PWM_CHIP "pwmchip0"
#define PWM_CHANNEL 0
#define PWM_PERIOD 10000000 // 10ms period for 100Hz max frequency
#define MIN_FREQ 220
#define MAX_FREQ 880
#define ADC_MAX_VALUE 1023
#define CALIBRATION_FILE "theremin_config.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *trig_line, *echo_line;
static int pwm_fd;
static int adc_fd;
static int calibration_loaded = 0;
static int min_freq = MIN_FREQ, max_freq = MAX_FREQ;

void cleanup() {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (pwm_fd >= 0) {
        close(pwm_fd);
    }
    if (adc_fd >= 0) {
        close(adc_fd);
    }
}

void load_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp) {
        if (fscanf(fp, "%d %d", &min_freq, &max_freq) == 2) {
            calibration_loaded = 1;
        }
        fclose(fp);
    }
}

void save_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp) {
        fprintf(fp, "%d %d\n", min_freq, max_freq);
        fclose(fp);
    }
}

void set_pwm_frequency(int frequency) {
    if (frequency < min_freq || frequency > max_freq) {
        return;
    }
    int duty_cycle = (int)(PWM_PERIOD * (frequency - min_freq) / (double)(max_freq - min_freq));
    char buf[64];
    snprintf(buf, sizeof(buf), "echo %d > /sys/class/pwm/%s/pwm%d/duty_cycle", duty_cycle, PWM_CHIP, PWM_CHANNEL);
    system(buf);
}

int read_distance() {
    gpiod_line_set_value(trig_line, 1);
    usleep(10);
    gpiod_line_set_value(trig_line, 0);

    struct timespec start, end;
    if (gpiod_line_event_wait(echo_line, NULL) < 0) {
        perror("gpiod_line_event_wait");
        return -1;
    }
    if (gpiod_line_get_value(echo_line) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
            perror("clock_gettime");
            return -1;
        }
        while (gpiod_line_get_value(echo_line) == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
                perror("clock_gettime");
                return -1;
            }
            if (end.tv_sec - start.tv_sec > 1) {
                return -1; // Timeout
            }
        }
    } else {
        return -1; // No echo
    }

    long diff = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);
    return (int)(diff / 58.0); // Distance in cm
}

int read_adc() {
    uint8_t tx[] = {1, (8 + ADC_CHANNEL) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    if (ioctl(adc_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl");
        return -1;
    }
    return ((rx[1] & 3) << 8) + rx[2];
}

