    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(trig_line, "theremin_trig", 0) < 0 ||
        gpiod_line_request_input(echo_line, "theremin_echo") < 0) {
        perror("gpiod_line_request");
        cleanup();
        return 1;
    }

    pwm_fd = open("/sys/class/pwm/pwmchip0/export", O_WRONLY);
    if (pwm_fd < 0) {
        perror("open pwm export");
        cleanup();
        return 1;
    }
    write(pwm_fd, "0", 1);
    close(pwm_fd);

    pwm_fd = open("/sys/class/pwm/pwmchip0/pwm0/period", O_WRONLY);
    if (pwm_fd < 0) {
        perror("open pwm period");
        cleanup();
        return 1;
    }
    dprintf(pwm_fd, "%d", PWM_PERIOD);
    close(pwm_fd);

    pwm_fd = open("/sys/class/pwm/pwmchip0/pwm0/duty_cycle", O_WRONLY);
    if (pwm_fd < 0) {
        perror("open pwm duty_cycle");
        cleanup();
        return 1;
    }

    adc_fd = open(SPI_DEVICE, O_RDWR);
    if (adc_fd < 0) {
        perror("open spi device");
        cleanup();
        return 1;
    }

    if (ioctl(adc_fd, SPI_IOC_WR_MODE, SPI_MODE_0) < 0 ||
        ioctl(adc_fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0 ||
        ioctl(adc_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000) < 0) {
        perror("ioctl spi");
        cleanup();
        return 1;
    }

    load_calibration();

    while (1) {
        int distance = read_distance();
        if (distance < 0) {
            distance = 50; // Hold last valid state
        }
        int frequency = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (distance / 100.0);
        set_pwm_frequency(frequency);

        int adc_value = read_adc();
        if (adc_value < 0) {
            adc_value = ADC_MAX_VALUE / 2; // Hold last valid state
        }
        int volume = (int)(100.0 * adc_value / ADC_MAX_VALUE);
        // Set PWM duty cycle based on volume (not implemented here)

        usleep(100000); // 100ms loop
    }

    cleanup();
    return 0;
}

