#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define FAN_GPIO 18
#define AQI_MIN 0
#define AQI_MAX 500
#define ADC_MIN 0
#define ADC_MAX 1023
#define RETRY_COUNT 3
#define RETRY_DELAY 1000000 // 1 second

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_aqi(FILE *log_file, int aqi) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
    fprintf(log_file, "%s, AQI: %d\n", timestamp, aqi);
    fflush(log_file);
}

int read_adc(int spi_handle, int channel) {
    char tx[3] = {0x01, (0x08 | (channel & 0x07)), 0x00};
    char rx[3];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (spi_xfer(spi_handle, tx, rx, 3) == 0) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            return adc_value;
        }
        retries++;
        usleep(RETRY_DELAY);
    }

    // Re-initialize SPI on failure
    spi_close(spi_handle);
    spi_handle = spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to re-initialize SPI\n");
        exit(EXIT_FAILURE);
    }
    return read_adc(spi_handle, channel);
}

int adc_to_aqi(int adc_value) {
    return (AQI_MAX * adc_value) / ADC_MAX;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int spi_handle = spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("air_quality.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spi_close(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int adc_value = read_adc(spi_handle, ADC_CHANNEL);
        int aqi = adc_to_aqi(adc_value);
        log_aqi(log_file, aqi);

        if (aqi > 100) {
            gpioWrite(FAN_GPIO, PI_HIGH);
        } else {
            gpioWrite(FAN_GPIO, PI_LOW);
        }

        sleep(5);
    }

    fclose(log_file);
    spi_close(spi_handle);
    gpioWrite(FAN_GPIO, PI_LOW);
    gpioTerminate();

    return EXIT_SUCCESS;
}

