#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8
#define ADC_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define RETRY_COUNT 3
#define RETRY_DELAY 100000 // 100 ms

static volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

int main() {
    int spi_fd;
    struct spi_ioc_transfer xfer;
    uint8_t tx[3] = {0x01, (ADC_CHANNEL << 4) | 0x80, 0x00};
    uint8_t rx[3];
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    FILE *log_file;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];
    int adc_value;
    float ppm;
    int retries;
    int error_count = 0;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set SPI bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as output
    if (gpiod_line_request_output(line, "spi_cs", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("alcohol_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        memset(rx, 0, sizeof(rx));
        xfer.tx_buf = (unsigned long)tx;
        xfer.rx_buf = (unsigned long)rx;
        xfer.len = sizeof(tx);
        xfer.speed_hz = SPI_SPEED;
        xfer.bits_per_word = SPI_BITS_PER_WORD;
        xfer.delay_usecs = 0;
        xfer.cs_change = 0;

        retries = 0;
        while (retries < RETRY_COUNT) {
            if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
                perror("Failed to perform SPI transfer");
                retries++;
                usleep(RETRY_DELAY);
            } else {
                break;
            }
        }

        if (retries == RETRY_COUNT) {
            fprintf(log_file, "Error: SPI transfer failed after %d retries\n", RETRY_COUNT);
            error_count++;
            if (error_count >= 3) {
                fprintf(log_file, "Error: Too many consecutive SPI transfer failures. Exiting.\n");
                break;
            }
            continue;
        }

        adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        ppm = (adc_value * 0.5) - 10.0;

        time(&now);
        tm_info = gmtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

        fprintf(log_file, "%s ADC Value: %d, PPM: %.2f - ", timestamp, adc_value, ppm);

        if (adc_value == 0 || adc_value == 1023) {
            fprintf(log_file, "Sensor absent or error condition.\n");
        } else if (ppm > 50) {
            fprintf(log_file, "Alcohol detected! Limit exceeded.\n");
        } else if (ppm < 20) {
            fprintf(log_file, "Sobriety confirmed.\n");
        } else {
            fprintf(log_file, "Alcohol level within acceptable range.\n");
        }

        fflush(log_file);
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

