#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define THRESHOLD 300
#define PUMP_PIN 18
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 60

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_adc(int spi_handle, int channel) {
    unsigned char tx[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx[3];
    int result;

    if (spi_xfer(spi_handle, tx, rx, 3) < 0) {
        perror("spi_xfer");
        return -1;
    }

    result = ((rx[1] & 3) << 8) | rx[2];
    return result;
}

void log_entry(FILE *log_file, int moisture, int pump_status) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s - Moisture: %d, Pump: %s\n", timestamp, moisture, pump_status ? "ON" : "OFF");
    fflush(log_file);
}

int main() {
    int spi_handle;
    FILE *log_file;
    int moisture;
    int pump_status = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(PUMP_PIN, PI_OUTPUT);
    gpioWrite(PUMP_PIN, PI_LOW);

    while (running) {
        moisture = read_adc(spi_handle, ADC_CHANNEL);
        if (moisture < 0) {
            log_entry(log_file, -1, pump_status);
        } else {
            if (moisture < THRESHOLD && !pump_status) {
                gpioWrite(PUMP_PIN, PI_HIGH);
                pump_status = 1;
            } else if (moisture >= THRESHOLD && pump_status) {
                gpioWrite(PUMP_PIN, PI_LOW);
                pump_status = 0;
            }
            log_entry(log_file, moisture, pump_status);
        }
        sleep(SAMPLE_INTERVAL);
    }

    gpioWrite(PUMP_PIN, PI_LOW);
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

