#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

#define POT1_ADC_CHANNEL 0
#define POT2_ADC_CHANNEL 1

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0

#define MIN_SPEED 50
#define MAX_SPEED 255
#define ACCELERATION_STEP 1
#define ACCELERATION_DELAY 10000  // 10 ms
#define CONSTANT_SPEED_DELAY 2000000  // 2 seconds
#define PAUSE_DELAY 5000000  // 5 seconds

#define LOGARITHMIC_SCALE_FACTOR 0.01

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }

    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);

    return 0;
}

int setup_spi() {
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return -1;
    }
    return spi_handle;
}

int read_adc(int spi_handle, int channel) {
    unsigned char tx[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx[3];
    spiXfer(spi_handle, tx, rx, 3);
    return ((rx[1] & 3) << 8) | rx[2];
}

int map_speed(int adc_value) {
    double log_value = log(1 + adc_value * LOGARITHMIC_SCALE_FACTOR);
    return (int)(MIN_SPEED + (MAX_SPEED - MIN_SPEED) * (log_value / log(1 + 1024 * LOGARITHMIC_SCALE_FACTOR)));
}

void run_motion_profile(int spi_handle) {
    while (running) {
        int pot1_value = read_adc(spi_handle, POT1_ADC_CHANNEL);
        int pot2_value = read_adc(spi_handle, POT2_ADC_CHANNEL);
        int speed1 = map_speed(pot1_value);
        int speed2 = map_speed(pot2_value);

        gpioWrite(MOTOR1_DIRECTION, 1);
        gpioWrite(MOTOR2_DIRECTION, 0);

        for (int speed = MIN_SPEED; speed <= MAX_SPEED; speed += ACCELERATION_STEP) {
            if (!running) break;
            gpioPWM(MOTOR1_ENABLE, speed * speed1 / 1023);
            gpioPWM(MOTOR2_ENABLE, speed * speed2 / 1023);
            gpioDelay(ACCELERATION_DELAY);
        }

        gpioDelay(CONSTANT_SPEED_DELAY);

        for (int speed = MAX_SPEED; speed >= MIN_SPEED; speed -= ACCELERATION_STEP) {
            if (!running) break;
            gpioPWM(MOTOR1_ENABLE, speed * speed1 / 1023);
            gpioPWM(MOTOR2_ENABLE, speed * speed2 / 1023);
            gpioDelay(ACCELERATION_DELAY);
        }

        gpioDelay(PAUSE_DELAY);

        gpioWrite(MOTOR1_DIRECTION, 0);
        gpioWrite(MOTOR2_DIRECTION, 1);

        for (int speed = MIN_SPEED; speed <= MAX_SPEED; speed += ACCELERATION_STEP) {
            if (!running) break;
            gpioPWM(MOTOR1_ENABLE, speed * speed1 / 1023);
            gpioPWM(MOTOR2_ENABLE, speed * speed2 / 1023);
            gpioDelay(ACCELERATION_DELAY);
        }

        gpioDelay(CONSTANT_SPEED_DELAY);

        for (int speed = MAX_SPEED; speed >= MIN_SPEED; speed -= ACCELERATION_STEP) {
            if (!running) break;
            gpioPWM(MOTOR1_ENABLE, speed * speed1 / 1023);
            gpioPWM(MOTOR2_ENABLE, speed * speed2 / 1023);
            gpioDelay(ACCELERATION_DELAY);
        }

        gpioDelay(PAUSE_DELAY);
    }
}

void cleanup(int spi_handle) {
    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() < 0) return EXIT_FAILURE;

    int spi_handle = setup_spi();
    if (spi_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    run_motion_profile(spi_handle);

    cleanup(spi_handle);
    return EXIT_SUCCESS;
}

