#define ADC_MISO 9
#define ADC_SCLK 11
#define LED_PIN 17
#define CALIBRATION_TIME 5
#define DEBOUNCE_TIME 10
#define THRESHOLD_MULTIPLIER 1.1

volatile sig_atomic_t running = 1;

