        return -1;
    }

    result = ((rx[1] & 3) << 8) | rx[2];
    return result;
}

int main() {
    int spi_handle;
    int sum = 0;
    int samples = 0;
    int average = 0;
    int threshold = 0;
    int current_level = 0;
    struct timespec debounce_start;
    struct timespec current_time;

