        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ADC_CS, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for CS\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for LED\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(LED_PIN, PI_LOW);

    printf("Calibrating for %d seconds...\n", CALIBRATION_TIME);
    for (int i = 0; i < CALIBRATION_TIME * 100; i++) {
        current_level = read_adc(0);
        if (current_level < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            spiClose(spi_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        sum += current_level;
        samples++;
        usleep(10000); // 10 ms
    }

    average = sum / samples;
    threshold = average * THRESHOLD_MULTIPLIER;
    printf("Calibrated average: %d, Threshold: %d\n", average, threshold);

    while (running) {
        current_level = read_adc(0);
        if (current_level < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            break;
        }

        if (current_level > threshold) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            if (timespec_diff(&current_time, &debounce_start) > DEBOUNCE_TIME * 1000000) {
                gpioWrite(LED_PIN, PI_HIGH);
                clock_gettime(CLOCK_MONOTONIC, &debounce_start);
            }
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }

        usleep(10000); // 10 ms
    }

    gpioWrite(LED_PIN, PI_LOW);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

long timespec_diff(struct timespec *a, struct timespec *b) {
    return (a->tv_sec - b->tv_sec) * 1000000 + (a->tv_nsec - b->tv_nsec) / 1000;
}

