#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CS 8
#define ADC_BITS 10
#define ADC_REF_VOLTAGE 3.3
#define ADC_MAX_VALUE (1 << ADC_BITS)
#define SAMPLE_INTERVAL_US 100000

#define LOG_FILE "airflow_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "ERROR: Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fclose(log_file);
}

int read_adc(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3] = {0};

    if (spiXfer(SPI_CHANNEL, tx, rx, 3) < 0) {
        log_message("ERROR: ADC read failed");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

double convert_to_slpm(int adc_value) {
    double voltage = (adc_value * ADC_REF_VOLTAGE) / ADC_MAX_VALUE;
    return (voltage - 0.5) / (4.5 - 0.5) * 200;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "ERROR: Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ADC_CS, PI_OUTPUT) < 0) {
        fprintf(stderr, "ERROR: Failed to set GPIO mode for ADC CS\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ADC_CS, 1) < 0) {
        fprintf(stderr, "ERROR: Failed to set initial state for ADC CS\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        fprintf(stderr, "ERROR: Failed to open SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        gpioWrite(ADC_CS, 0);
        int adc_value = read_adc(0);
        gpioWrite(ADC_CS, 1);

        if (adc_value >= 0) {
            double slpm = convert_to_slpm(adc_value);
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Airflow: %.2f SLPM", slpm);
            log_message(log_message);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    spiClose(SPI_CHANNEL);
    gpioTerminate();
    return EXIT_SUCCESS;
}

