#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define SAMPLE_RATE 1000
#define SAMPLE_PERIOD 1000000 // 1 ms in nanoseconds

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int spi_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *cs_line;
    struct spi_ioc_transfer xfer;
    uint8_t tx_buf[3] = {0x01, 0x08, 0x00};
    uint8_t rx_buf[3];
    FILE *log_file;
    struct timespec start_time, current_time, sleep_time;
    uint64_t timestamp_ns;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8);
    if (ret < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set max speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000);
    if (ret < 0) {
        perror("Failed to set max speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    cs_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as output
    ret = gpiod_line_request_output(cs_line, "mcp3008_cs", 1);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("audio_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Get start time
    clock_gettime(CLOCK_MONOTONIC_RAW, &start_time);

    while (running) {
        // Set CS low
        gpiod_line_set_value(cs_line, 0);

        // Configure SPI transfer
        xfer.tx_buf = (unsigned long)tx_buf;
        xfer.rx_buf = (unsigned long)rx_buf;
        xfer.len = 3;
        xfer.speed_hz = 1000000;
        xfer.bits_per_word = 8;
        xfer.delay_usecs = 0;
        xfer.cs_change = 0;

        // Perform SPI transfer
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret < 0) {
            perror("Failed to perform SPI transfer");
            break;
        }

        // Set CS high
        gpiod_line_set_value(cs_line, 1);

        // Parse 10-bit result
        uint16_t raw_adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        // Get current time
        clock_gettime(CLOCK_MONOTONIC_RAW, &current_time);

        // Calculate timestamp in nanoseconds
        timestamp_ns = (current_time.tv_sec - start_time.tv_sec) * 1000000000ULL +
                        (current_time.tv_nsec - start_time.tv_nsec);

        // Log the reading
        fprintf(log_file, "%llu|%u\n", timestamp_ns, raw_adc_value);
        fflush(log_file);

        // Calculate sleep time for next sample
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = SAMPLE_PERIOD;

        // Sleep until the next sample deadline
        nanosleep(&sleep_time, NULL);
    }

    // Close log file
    fclose(log_file);

    // Release GPIO line request
    gpiod_line_release(cs_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    // Close SPI device
    close(spi_fd);

    return EXIT_SUCCESS;
}

