#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

#define MCP3008_CS 8
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_SCLK 11

#define ADXL335_SENSITIVITY 0.300 // mV/g
#define ADXL335_ZERO_G_BIAS 1.500 // V

#define REFERENCE_VOLTAGE 3.3 // V
#define ADC_RESOLUTION 1024.0

#define SAMPLE_RATE 10 // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE)

#define KALMAN_Q 0.01
#define KALMAN_R 0.1

typedef struct {
    double x, y, z;
} Vector3;

typedef struct {
    double x, y, z;
    double p_x, p_y, p_z;
} KalmanState;

KalmanState kalman_state = {0, 0, 0, 1, 1, 1};

double kalman_filter(double measurement, double *state, double *p) {
    double prediction = *state;
    double prediction_error_covariance = *p + KALMAN_Q;

    double kalman_gain = prediction_error_covariance / (prediction_error_covariance + KALMAN_R);

    double state_update = prediction + kalman_gain * (measurement - prediction);
    double p_update = (1 - kalman_gain) * prediction_error_covariance;

    *state = state_update;
    *p = p_update;

    return state_update;
}

int read_adc_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    int data = 0x01 | (channel << 1); // Start bit + single-ended mode + channel
    gpioWrite(MCP3008_CS, 0);

    for (int i = 7; i >= 0; i--) {
        gpioWrite(MCP3008_SCLK, 0);
        gpioWrite(MCP3008_MOSI, (data & (1 << i)) ? 1 : 0);
        gpioWrite(MCP3008_SCLK, 1);
    }

    gpioWrite(MCP3008_SCLK, 0);
    gpioWrite(MCP3008_MOSI, 0);
    gpioWrite(MCP3008_SCLK, 1);

    int adc_value = 0;
    for (int i = 0; i < 10; i++) {
        gpioWrite(MCP3008_SCLK, 0);
        adc_value <<= 1;
        adc_value |= gpioRead(MCP3008_MISO);
        gpioWrite(MCP3008_SCLK, 1);
    }

    gpioWrite(MCP3008_CS, 1);
    return adc_value;
}

double convert_adc_to_voltage(int adc_value) {
    return (adc_value * REFERENCE_VOLTAGE) / ADC_RESOLUTION;
}

double convert_voltage_to_g(double voltage) {
    return (voltage - ADXL335_ZERO_G_BIAS) / ADXL335_SENSITIVITY;
}

void handle_signal(int signum) {
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioSetMode(MCP3008_MOSI, PI_OUTPUT);
    gpioSetMode(MCP3008_MISO, PI_INPUT);
    gpioSetMode(MCP3008_SCLK, PI_OUTPUT);

    gpioWrite(MCP3008_CS, 1);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int adc_x = read_adc_channel(0);
        int adc_y = read_adc_channel(1);
        int adc_z = read_adc_channel(2);

        if (adc_x < 0 || adc_y < 0 || adc_z < 0) {
            fprintf(stderr, "Failed to read ADC values\n");
            continue;
        }

        double voltage_x = convert_adc_to_voltage(adc_x);
        double voltage_y = convert_adc_to_voltage(adc_y);
        double voltage_z = convert_adc_to_voltage(adc_z);

        double g_x = convert_voltage_to_g(voltage_x);
        double g_y = convert_voltage_to_g(voltage_y);
        double g_z = convert_voltage_to_g(voltage_z);

        double filtered_g_x = kalman_filter(g_x, &kalman_state.x, &kalman_state.p_x);
        double filtered_g_y = kalman_filter(g_y, &kalman_state.y, &kalman_state.p_y);
        double filtered_g_z = kalman_filter(g_z, &kalman_state.z, &kalman_state.p_z);

        printf("Filtered Acceleration: X = %.3f g, Y = %.3f g, Z = %.3f g\n", filtered_g_x, filtered_g_y, filtered_g_z);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioTerminate();
    return 0;
}

