#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define VCC 3.3
#define V_QUIESCENT 1.65
#define SENSITIVITY 0.025
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2, *line3;
    FILE *log_file;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    line1 = gpiod_chip_get_line(chip, 4);
    line2 = gpiod_chip_get_line(chip, 17);
    line3 = gpiod_chip_get_line(chip, 27);

    if (!line1 || !line2 || !line3) {
        perror("Failed to get GPIO line");
        ret = EXIT_FAILURE;
        goto close_chip;
    }

    ret = gpiod_line_request_input(line1, "hall_sensor1");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        ret = EXIT_FAILURE;
        goto release_lines;
    }

    ret = gpiod_line_request_input(line2, "hall_sensor2");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        ret = EXIT_FAILURE;
        goto release_lines;
    }

    ret = gpiod_line_request_input(line3, "hall_sensor3");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        ret = EXIT_FAILURE;
        goto release_lines;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        ret = EXIT_FAILURE;
        goto release_lines;
    }

    // Set up signal handler for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        ret = EXIT_FAILURE;
        goto close_log;
    }

    while (running) {
        int val1, val2, val3;
        double B1, B2, B3;

        // Read GPIO lines
        val1 = gpiod_line_get_value(line1);
        val2 = gpiod_line_get_value(line2);
        val3 = gpiod_line_get_value(line3);

        if (val1 < 0 || val2 < 0 || val3 < 0) {
            perror("Failed to read GPIO line");
            continue;
        }

        // Calculate magnetic field strength
        B1 = (val1 * VCC - V_QUIESCENT) / SENSITIVITY;
        B2 = (val2 * VCC - V_QUIESCENT) / SENSITIVITY;
        B3 = (val3 * VCC - V_QUIESCENT) / SENSITIVITY;

        // Log readings
        fprintf(log_file, "%.2f,%.2f,%.2f\n", B1, B2, B3);
        fflush(log_file);

        // Check for out-of-range values
        if (B1 < -100 || B1 > 100 || B2 < -100 || B2 > 100 || B3 < -100 || B3 > 100) {
            fprintf(stderr, "Warning: Magnetic field value out of range\n");
        }

        // Sleep for 100 milliseconds
        usleep(SAMPLE_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

close_log:
    fclose(log_file);
release_lines:
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_line_release(line3);
close_chip:
    gpiod_chip_close(chip);

    return ret;
}

