#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 300  // 30% of 1023

volatile sig_atomic_t running = 1;

void log_event(const char *message) {
    FILE *log_file = fopen("watering.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&now), message);
    fclose(log_file);
}

void signal_handler(int signum) {
    running = 0;
}

int read_adc(int channel) {
    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (handle < 0) {
        log_event("Failed to open SPI device");
        return -1;
    }

    unsigned char tx[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx[3];
    int count = spiXfer(handle, tx, rx, 3);
    spiClose(handle);

    if (count < 0) {
        log_event("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 3) << 8) + rx[2];
}

void control_pump(int moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, PI_HIGH);
        log_event("Pump turned ON");
    } else {
        gpioWrite(PUMP_GPIO, PI_LOW);
        log_event("Pump turned OFF");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, PI_LOW);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started");

    while (running) {
        int moisture_level = read_adc(ADC_CHANNEL);
        if (moisture_level >= 0) {
            control_pump(moisture_level);
        }
        sleep(60);
    }

    gpioWrite(PUMP_GPIO, PI_LOW);
    log_event("Program terminated");

    gpioTerminate();
    return 0;
}

