        perror("Failed to request CE0 line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        cleanup();
        exit(EXIT_FAILURE);
    }

    fprintf(csv_file, "Time,Channel0,Channel1,Channel2\n");

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        unsigned int adc_values[NUM_CHANNELS];
        for (int i = 0; i < NUM_CHANNELS; i++) {
            adc_values[i] = read_adc_channel(i);
        }

        fprintf(csv_file, "%s,%u,%u,%u\n", time_str, adc_values[0], adc_values[1], adc_values[2]);
        fflush(csv_file);

        sleep(1);
    }

    cleanup();
    return 0;
}

