#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cJSON.h>

#define LED_PIN 17
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MAX_RECONNECT_DELAY 60

volatile sig_atomic_t running = 1;

void log_error(const char *message) {
    time_t now = time(NULL);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(stderr, "[%s] ERROR: %s\n", time_str, message);
}

void signal_handler(int signum) {
    running = 0;
}

void on_connect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc == 0) {
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_error("MQTT connection failed");
    }
}

void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *msg) {
    if (strcmp(msg->topic, MQTT_TOPIC) == 0) {
        cJSON *root = cJSON_Parse((char *)msg->payload);
        if (root) {
            cJSON *led_state = cJSON_GetObjectItemCaseSensitive(root, "led_state");
            if (cJSON_IsBool(led_state)) {
                gpioWrite(LED_PIN, cJSON_IsTrue(led_state) ? PI_ON : PI_OFF);
            } else {
                log_error("Invalid JSON payload: led_state must be a boolean");
            }
            cJSON_Delete(root);
        } else {
            log_error("Failed to parse JSON payload");
        }
    }
}

void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_error("MQTT disconnected unexpectedly");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_OFF);

    struct mosquitto *mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create MQTT client");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mosquitto_loop_start(mosq) != MOSQ_ERR_SUCCESS) {
        log_error("Failed to start MQTT loop");
        mosquitto_destroy(mosq);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int reconnect_delay = 1;
    while (running) {
        mosquitto_loop(mosq, -1, 1);
        if (!mosquitto_connected(mosq) && reconnect_delay <= MAX_RECONNECT_DELAY) {
            sleep(reconnect_delay);
            if (mosquitto_reconnect(mosq) == MOSQ_ERR_SUCCESS) {
                reconnect_delay = 1;
            } else {
                reconnect_delay = reconnect_delay * 2 > MAX_RECONNECT_DELAY ? MAX_RECONNECT_DELAY : reconnect_delay * 2;
            }
        }
    }

    mosquitto_loop_stop(mosq, true, 1000);
    mosquitto_destroy(mosq);
    gpioWrite(LED_PIN, PI_OFF);
    gpioTerminate();

    return EXIT_SUCCESS;
}

