#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR_PIN 17
#define LED_PIN 18
#define CHIP_LABEL "gpiochip0"
#define POLL_TIMEOUT_US 100000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret;

    // Set up signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_label(CHIP_LABEL);
    if (!chip) {
        perror("gpiod_chip_open_by_label");
        exit(EXIT_FAILURE);
    }

    // Request the sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("gpiod_chip_get_line (sensor)");
        goto cleanup;
    }
    ret = gpiod_line_request_input(sensor_line, "sound_sensor");
    if (ret < 0) {
        perror("gpiod_line_request_input (sensor)");
        goto cleanup;
    }

    // Request the LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (led)");
        goto cleanup;
    }
    ret = gpiod_line_request_output(led_line, "alarm_led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (led)");
        goto cleanup;
    }

    // Main loop
    while (running) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }
        printf("Sound level: %d\n", sensor_value);

        if (sensor_value == 0) {
            // Sound detected, blink LED for 1 second
            gpiod_line_set_value(led_line, 1);
            usleep(1000000);
            gpiod_line_set_value(led_line, 0);
        }

        usleep(POLL_TIMEOUT_US);
    }

cleanup:
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

