#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define BUFFER_SIZE 120
#define FILENAME "temp_log.dat"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void setup_signals() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

float read_temperature(int spi_handle) {
    uint8_t tx[] = {0x01, 0x80, 0x00};
    uint8_t rx[3];
    int result = spi_xfer(spi_handle, tx, rx, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1.0;
    }
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return (adc_value * 3.3 / 1024.0) * 100.0; // Convert to °C
}

void log_to_file(float *buffer) {
    FILE *file = fopen(FILENAME, "wb+");
    if (!file) {
        fprintf(stderr, "Failed to open file %s for writing\n", FILENAME);
        return;
    }
    fwrite(buffer, sizeof(float), BUFFER_SIZE, file);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    setup_signals();

    float buffer[BUFFER_SIZE];
    int index = 0;

    while (running) {
        float temperature = read_temperature(spi_handle);
        if (temperature >= 0.0) {
            buffer[index] = temperature;
            index = (index + 1) % BUFFER_SIZE;
            printf("Temperature: %.2f °C\n", temperature);
        }
        log_to_file(buffer);
        sleep(5);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

