#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "flame_events.log"

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_event(FILE *log_file, int pin, int state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%d,%d\n", timestamp, pin, state);
    fflush(log_file);
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    // Request the line for input with pull-down
    ret = gpiod_line_request_input(line, "flame_sensor");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    ret = gpiod_line_set_bias(line, GPIOD_LINE_BIAS_PULL_DOWN);
    if (ret < 0) {
        perror("Failed to set GPIO line bias to pull-down");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to stop.\n");

    // Main loop
    while (running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Failed to read GPIO line value");
            ret = EXIT_FAILURE;
            break;
        }

        log_event(log_file, GPIO_LINE, value);

        if (value == 1) {
            printf("ALARM: Flame detected!\n");
        }

        sleep(1);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

