#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TMP36_ADC_CHANNEL 0
#define MCP3008_SPI_CHANNEL 0
#define MCP4725_I2C_ADDRESS 0x62
#define MCP4725_I2C_BUS 1
#define ADC_MAX_VALUE 1023
#define DAC_MAX_VALUE 4095
#define TEMP_MIN_C 0
#define TEMP_MAX_C 50
#define VOLTAGE_MIN_V 0.0
#define VOLTAGE_MAX_V 3.3
#define SAMPLE_INTERVAL_US 500000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    fprintf(log_file, "%s", message);
    fclose(log_file);
}

int read_adc(int spi_handle, int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int result = spi_xfer(spi_handle, tx, rx, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", pigpio_error(result));
        return -1;
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

int write_dac(int i2c_handle, uint16_t value) {
    uint8_t tx[3] = {0x40, (value >> 4) & 0xFF, (value << 4) & 0xF0};
    int result = i2c_write_device(i2c_handle, tx, 3);
    if (result < 0) {
        fprintf(stderr, "I2C write failed: %s\n", pigpio_error(result));
        return -1;
    }
    return 0;
}

double adc_to_voltage(int adc_value) {
    return (double)adc_value * VOLTAGE_MAX_V / ADC_MAX_VALUE;
}

double voltage_to_temperature(double voltage) {
    return (voltage - 0.5) * 100.0;
}

double map_temperature_to_voltage(double temperature) {
    return (temperature - TEMP_MIN_C) * (VOLTAGE_MAX_V - VOLTAGE_MIN_V) / (TEMP_MAX_C - TEMP_MIN_C) + VOLTAGE_MIN_V;
}

uint16_t voltage_to_dac_value(double voltage) {
    return (uint16_t)(voltage * DAC_MAX_VALUE / VOLTAGE_MAX_V);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(MCP3008_SPI_CHANNEL, 500000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(MCP4725_I2C_BUS, MCP4725_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C: %s\n", pigpio_error(i2c_handle));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int adc_value = read_adc(spi_handle, TMP36_ADC_CHANNEL);
        if (adc_value < 0) {
            sleep(1);
            continue;
        }

        double voltage = adc_to_voltage(adc_value);
        double temperature = voltage_to_temperature(voltage);
        double dac_voltage = map_temperature_to_voltage(temperature);
        uint16_t dac_value = voltage_to_dac_value(dac_voltage);

        if (write_dac(i2c_handle, dac_value) < 0) {
            sleep(1);
            continue;
        }

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        char log_message[100];
        snprintf(log_message, sizeof(log_message), "%s, ADC: %d, Temp: %.2fC, DAC Voltage: %.2fV\n",
                 timestamp, adc_value, temperature, dac_voltage);
        printf("%s", log_message);
        log_message(log_message);

        usleep(SAMPLE_INTERVAL_US);
    }

    spiClose(spi_handle);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

