#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL_0 0
#define ADC_CHANNEL_1 1
#define ADC_CHANNEL_2 2
#define LOG_FILE "soil_data.txt"
#define SLEEP_INTERVAL 60000000  // 60 seconds in microseconds

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void log_message(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        log_error("Failed to open log file");
        return;
    }
    fprintf(log, "%s\n", message);
    fclose(log);
}

void timestamp(char *buffer, size_t size) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(buffer, size, "%Y-%m-%d %H:%M:%S", tm_info);
}

int read_adc(int spi_handle, int channel) {
    unsigned char tx[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx[3];
    if (spiXfer(spi_handle, tx, rx, 3) < 0) {
        log_error("spiXfer failed");
        return -1;
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

void handle_sigint(int signal) {
    log_message("Received SIGINT, exiting...");
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialization failed");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        log_error("spiOpen failed");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        char time_str[20];
        timestamp(time_str, sizeof(time_str));

        for (int channel = ADC_CHANNEL_0; channel <= ADC_CHANNEL_2; channel++) {
            int adc_value = read_adc(spi_handle, channel);
            if (adc_value < 0 || adc_value > 1023) {
                log_error("Invalid ADC value");
                continue;
            }
            double moisture = (1.0 - (adc_value / 1023.0)) * 100.0;
            char log_entry[100];
            snprintf(log_entry, sizeof(log_entry), "%s, Channel %d, Moisture: %.2f%%", time_str, channel, moisture);
            log_message(log_entry);
        }

        gpioDelay(SLEEP_INTERVAL);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

