#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define CONSUMER "relay_sequencer"
#define RELAY_PINS {17, 22, 23, 24}
#define NUM_RELAYS 4
#define DELAY 1

struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_RELAYS];
volatile sig_atomic_t running = 1;

void cleanup_and_exit(int signum) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0); // Deactivate relay
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Exiting on signal %d\n", signum);
    exit(EXIT_SUCCESS);
}

int main() {
    int pin_numbers[NUM_RELAYS] = RELAY_PINS;
    struct sigaction sa;

    // Set up signal handler for SIGINT and SIGTERM
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_label");
        exit(EXIT_FAILURE);
    }

    // Request GPIO lines for relays
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_numbers[i]);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            cleanup_and_exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            perror("gpiod_line_request_output");
            cleanup_and_exit(EXIT_FAILURE);
        }
    }

    // Main loop to sequence relays
    while (running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpiod_line_set_value(lines[i], 1); // Activate relay
            sleep(DELAY);
            gpiod_line_set_value(lines[i], 0); // Deactivate relay
            sleep(DELAY);
        }
    }

    // Cleanup and exit
    cleanup_and_exit(EXIT_SUCCESS);
    return 0;
}

