#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define LED_PIN 16
#define THRESHOLD 500
#define DEBOUNCE_DELAY 100
#define LOG_FILE "sound_events.log"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for LED\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    time_t last_trigger_time = 0;
    while (running) {
        uint8_t spi_tx[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
        uint8_t spi_rx[3];
        int status = spiXfer(spi_handle, spi_tx, spi_rx, 3);
        if (status < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        uint16_t adc_value = ((spi_rx[1] & 3) << 8) | spi_rx[2];
        if (adc_value > THRESHOLD) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_trigger_time) > 0.5) {
                gpioWrite(LED_PIN, PI_HIGH);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time));
                fprintf(log_file, "%s - Sound level exceeded threshold: %d\n", timestamp, adc_value);
                fflush(log_file);
                gpioDelay(500000); // 500 ms
                gpioWrite(LED_PIN, PI_LOW);
                last_trigger_time = current_time;
            }
        }

        gpioDelay(10000); // 10 ms
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

