This code sets up a Raspberry Pi to read from a sound sensor using an MCP3008 ADC over SPI, and controls an LED based on the sensor's output. It includes error handling for SPI operations, GPIO setup, and file operations, and it uses a signal handler to ensure resources are released cleanly on program termination.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27
#define PWM_RANGE 255
#define PWM_DUTY 150
#define RAIN_THRESHOLD 5
#define LOG_FILE "rain_log.txt"

volatile sig_atomic_t shutdown_flag = 0;

void signal_handler(int signum) {
    shutdown_flag = 1;
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);
    gpioSetPWMrange(MOTOR_ENA, PWM_RANGE);
    gpioSetPWMfrequency(MOTOR_ENA, 1000);
}

void init_spi() {
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    return spi_handle;
}

void init_log() {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Log file open failed\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    return log_file;
}

void close_motor() {
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);
}

void drive_motor_forward() {
    gpioWrite(MOTOR_IN1, 1);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, PWM_DUTY);
}

void drive_motor_backward() {
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 1);
    gpioPWM(MOTOR_ENA, PWM_DUTY);
}

int read_adc(int spi_handle) {
    char tx[3] = {0x01, (0x08 | ADC_CHANNEL) << 4, 0x00};
    char rx[3];
    if (spiXfer(spi_handle, tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

int convert_adc_to_rain_level(int adc_value) {
    return 10 - (adc_value * 10) / 1023;
}

void log_rain_level(FILE *log_file, int rain_level) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s Rain Level: %d\n", timestamp, rain_level);
    fflush(log_file);
}

void cleanup(int spi_handle, FILE *log_file) {
    close_motor();
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();
    int spi_handle = init_spi();
    FILE *log_file = init_log();

    int previous_rain_level = -1;
    while (!shutdown_flag) {
        int adc_value = read_adc(spi_handle);
        if (adc_value < 0) {
            continue;
        }
        int rain_level = convert_adc_to_rain_level(adc_value);
        log_rain_level(log_file, rain_level);

        if (rain_level >= RAIN_THRESHOLD) {
            if (previous_rain_level < RAIN_THRESHOLD) {
                drive_motor_forward();
                sleep(3);
                close_motor();
            }
        } else {
            if (previous_rain_level >= RAIN_THRESHOLD) {
                drive_motor_backward();
                sleep(3);
                close_motor();
            }
        }
        previous_rain_level = rain_level;
        sleep(1);
    }

    cleanup(spi_handle, log_file);
    return 0;
}

