    int spi_handle = init_spi();
    FILE *log_file = init_log();

    int previous_rain_level = -1;
    while (!shutdown_flag) {
        int adc_value = read_adc(spi_handle);
        if (adc_value < 0) {
            continue;
        }
        int rain_level = convert_adc_to_rain_level(adc_value);
        log_rain_level(log_file, rain_level);

        if (rain_level >= RAIN_THRESHOLD) {
            if (previous_rain_level < RAIN_THRESHOLD) {
                drive_motor_forward();
                sleep(3);
                close_motor();
            }
        } else {
            if (previous_rain_level >= RAIN_THRESHOLD) {
                drive_motor_backward();
                sleep(3);
                close_motor();
            }
        }
        previous_rain_level = rain_level;
        sleep(1);
    }

    cleanup(spi_handle, log_file);
    return 0;
}
