#define GPIO_PIN 17
#define A 26.0
#define B -6.0
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_distance(double distance) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, Distance: %.2f mm\n", timestamp, distance);
    fclose(log_file);
}

double read_distance() {
    int gpio_fd = open("/sys/class/gpio/gpio17/value", O_RDONLY);
    if (gpio_fd == -1) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    char value_str[4];
    ssize_t bytes_read = read(gpio_fd, value_str, sizeof(value_str) - 1);
    close(gpio_fd);

    if (bytes_read == -1) {
        perror("Failed to read GPIO value");
        return -1;
    }

    value_str[bytes_read] = '\0';
    int gpio_value = atoi(value_str);
    double voltage = gpio_value ? 3.3 : 0.0;
    double distance = A / voltage + B;

    return distance;
}

void setup_gpio() {
    int gpio_export_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (gpio_export_fd == -1) {
        perror("Failed to open GPIO export file");
        exit(EXIT_FAILURE);
    }

    char gpio_str[4];
    snprintf(gpio_str, sizeof(gpio_str), "%d", GPIO_PIN);
    if (write(gpio_export_fd, gpio_str, strlen(gpio_str)) == -1) {
        perror("Failed to export GPIO");
        close(gpio_export_fd);
        exit(EXIT_FAILURE);
    }

    close(gpio_export_fd);

    int gpio_direction_fd = open("/sys/class/gpio/gpio17/direction", O_WRONLY);
    if (gpio_direction_fd == -1) {
        perror("Failed to open GPIO direction file");
        exit(EXIT_FAILURE);
    }

    if (write(gpio_direction_fd, "in", 2) == -1) {
        perror("Failed to set GPIO direction");
        close(gpio_direction_fd);
        exit(EXIT_FAILURE);
    }

    close(gpio_direction_fd);
}

void cleanup_gpio() {
    int gpio_unexport_fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (gpio_unexport_fd == -1) {
        perror("Failed to open GPIO unexport file");
        return;
    }

    char gpio_str[4];
    snprintf(gpio_str, sizeof(gpio_str), "%d", GPIO_PIN);
    if (write(gpio_unexport_fd, gpio_str, strlen(gpio_str)) == -1) {
        perror("Failed to unexport GPIO");
    }

    close(gpio_unexport_fd);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();

    while (running) {
        double distance = read_distance();
        if (distance == -1) {
            sleep(1);
            continue;
        }

        log_distance(distance);

        if (distance < 200) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    cleanup_gpio();
    return 0;
}

