#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CE0_CHIP "gpiochip0"
#define CE0_LINE 8
#define PUMP_LINE 17
#define ADC_CHANNEL 0
#define ADC_DRY 800
#define ADC_WET 300
#define LOG_FILE "soil_moisture.log"
#define SAMPLE_INTERVAL 60

static struct gpiod_chip *chip;
static struct gpiod_line *ce0_line;
static struct gpiod_line *pump_line;
static int spi_fd;
static FILE *log_file;

void cleanup() {
    if (pump_line) {
        gpiod_line_set_value(pump_line, 0);
        gpiod_line_release(pump_line);
    }
    if (ce0_line) {
        gpiod_line_release(ce0_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int init_gpio() {
    chip = gpiod_chip_open_by_name(CE0_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    ce0_line = gpiod_chip_get_line(chip, CE0_LINE);
    if (!ce0_line) {
        perror("Failed to get CE0 line");
        return -1;
    }

    int ret = gpiod_line_request_output(ce0_line, "spi_ce0", 1);
    if (ret < 0) {
        perror("Failed to request CE0 line as output");
        return -1;
    }

    pump_line = gpiod_chip_get_line(chip, PUMP_LINE);
    if (!pump_line) {
        perror("Failed to get pump line");
        return -1;
    }

    ret = gpiod_line_request_output(pump_line, "pump", 0);
    if (ret < 0) {
        perror("Failed to request pump line as output");
        return -1;
    }

    return 0;
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        return -1;
    }

    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        return -1;
    }

    return 0;
}

int init_log() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }
    return 0;
}

uint16_t read_adc(uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to transfer SPI message");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

void log_moisture(uint16_t adc_value, float moisture_percent, int pump_status) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strcspn(timestamp, "\n")] = 0; // Remove newline

    fprintf(log_file, "%s, ADC: %d, Moisture: %.2f%%, Pump: %s\n",
            timestamp, adc_value, moisture_percent, pump_status ? "ON" : "OFF");
    fflush(log_file);
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0 || init_spi() < 0 || init_log() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        gpiod_line_set_value(ce0_line, 0);

        uint16_t adc_value = read_adc(ADC_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float moisture_percent = 100.0 * (ADC_DRY - adc_value) / (ADC_DRY - ADC_WET);
        int pump_status = moisture_percent < 30.0;

        gpiod_line_set_value(pump_line, pump_status);

        log_moisture(adc_value, moisture_percent, pump_status);

        gpiod_line_set_value(ce0_line, 1);

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

