#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_CE 8
#define LED_PIN 21
#define ADC_CHANNEL 0
#define VCC 3.3
#define SENSITIVITY_MV_PER_MT 1.65
#define THRESHOLD_MT 10.0
#define LOG_FILE "magnetic_log.txt"
#define DELAY_MS 100

volatile sig_atomic_t running = 1;

void cleanup(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (running) {
        uint8_t tx[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
        uint8_t rx[3];
        if (spiXfer(spi_handle, tx, rx, 3) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            break;
        }

        uint16_t adc_value = ((rx[1] & 3) << 8) | rx[2];
        double voltage = adc_value * VCC / 1023.0;
        double field_mT = (voltage - VCC / 2) * 1000 / SENSITIVITY_MV_PER_MT;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s: %.2f mT\n", timestamp, field_mT);
        fflush(log_file);

        if (field_mT > THRESHOLD_MT) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }

        gpioDelay(DELAY_MS * 1000);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioWrite(LED_PIN, PI_LOW);
    gpioTerminate();

    return EXIT_SUCCESS;
}

