#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define ADC_CHANNEL 0
#define ADC_BITS 10
#define ADC_REF_VOLTAGE 3.3
#define CURRENT_SCALE 0.01 // 100 mV/A

static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;

void cleanup() {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int setup_gpio() {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "mlx91209_enable", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return -1;
    }

    return 0;
}

int setup_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return -1;
    }

    uint8_t bits = ADC_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup();
        return -1;
    }

    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        cleanup();
        return -1;
    }

    return 0;
}

int read_adc() {
    uint8_t tx[] = {1, (8 + ADC_CHANNEL) << 4, 0};
    uint8_t rx[3];

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .speed_hz = 1000000,
        .bits_per_word = ADC_BITS,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to transfer SPI message");
        return -1;
    }

    int value = ((rx[1] & 3) << 8) | rx[2];
    return value;
}

double convert_to_current(int adc_value) {
    double voltage = (adc_value * ADC_REF_VOLTAGE) / (1 << ADC_BITS);
    return voltage / CURRENT_SCALE;
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR ||
        signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0 || setup_spi() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Failed to enable sensor");
            cleanup();
            return EXIT_FAILURE;
        }

        usleep(10000); // 10 ms delay

        int adc_value = read_adc();
        if (adc_value < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        double current = convert_to_current(adc_value);

        if (gpiod_line_set_value(gpio_line, 0) < 0) {
            perror("Failed to disable sensor");
            cleanup();
            return EXIT_FAILURE;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f\n", timestamp, current);
        fflush(log_file);

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

