#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define VDD 5.0
#define CURRENT_SCALE 50.0 / 2.5

volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int sig) {
    exit_flag = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open SPI0
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    FILE *log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!exit_flag) {
        // SPI transfer
        uint8_t tx[3] = {0x01, 0x80 | (MCP3008_CHANNEL << 4), 0x00};
        uint8_t rx[3];
        int result = spiXfer(spi_handle, tx, rx, 3);
        if (result < 0) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        // Compute 10-bit result
        uint16_t adc_value = ((rx[1] & 0x03) << 8) | rx[2];

        // Convert to voltage
        double voltage = (adc_value / 1023.0) * VDD;

        // Check voltage range
        if (voltage < 0.0 || voltage > VDD) {
            fprintf(stderr, "Voltage out of range: %f V\n", voltage);
            continue;
        }

        // Convert to current
        double current = (voltage - 2.5) * CURRENT_SCALE;

        // Get current time
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Log current
        fprintf(log_file, "%s %.2f A\n", timestamp, current);
        fflush(log_file);

        // Delay 100 ms
        gpioDelay(100000);
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

