#define LOG_INTERVAL_US 1000000

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int debounce_sensor(struct gpiod_line *line) {
    int count = 0;
    for (int i = 0; i < SAMPLES; i++) {
        if (gpiod_line_get_value(line) == 0) {
            count++;
        }
        usleep(SAMPLE_INTERVAL_US);
    }
    return count > SAMPLES / 2 ? 0 : 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor1_line, *sensor2_line;
    int sensor1_state, sensor2_state;

    // Open GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!sensor1_line) {
        perror("Failed to get GPIO line for sensor 1");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!sensor2_line) {
        perror("Failed to get GPIO line for sensor 2");
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0) {
        perror("Failed to request input for sensor 1");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        perror("Failed to request input for sensor 2");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        sensor1_state = debounce_sensor(sensor1_line);
        sensor2_state = debounce_sensor(sensor2_line);

        printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_state, sensor2_state);

        if (sensor1_state == 0 && sensor2_state == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        usleep(LOG_INTERVAL_US);
    }

    // Clean up
    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

