#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <stdbool.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t terminate = 0;

void signal_handler(int signal) {
    terminate = 1;
}

int read_mcp3008(int channel) {
    uint8_t tx_buf[3] = {0x01, 0x80 | (channel << 4), 0x00};
    uint8_t rx_buf[3] = {0};
    int result = spi_xfer(SPI_CHANNEL, tx_buf, rx_buf, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }
    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC) adc_value = MIN_ADC;
    if (adc_value > MAX_ADC) adc_value = MAX_ADC;
    double moisture_percentage = 100.0 - ((adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC)) * 100.0;
    return moisture_percentage < 0 ? 0 : (moisture_percentage > 100 ? 100 : moisture_percentage);
}

void log_data(double moisture_level) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(file, "%s,%.2f\n", timestamp, moisture_level);
    fclose(file);
}

int spi_setup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }
    return spi_handle;
}

int main() {
    signal(SIGINT, signal_handler);

    int spi_handle = spi_setup();
    if (spi_handle < 0) {
        return EXIT_FAILURE;
    }

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            double moisture_level = calculate_moisture_level(adc_value);
            log_data(moisture_level);
            printf("Moisture Level: %.2f%%\n", moisture_level);
        }
        sleep(READ_DELAY);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

