#include <pigpio.h>

#define PIR_GPIO 17
#define DEBOUNCE_MS 200
#define POLL_MS 50
#define IMAGE_DIR "/home/pi/security_cam/"
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define ISO 8601

volatile sig_atomic_t running = 1;

void sig_handler(int signum) {
    running = 0;
}

void log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

void capture_image() {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

    char image_path[100];
    snprintf(image_path, sizeof(image_path), "%s%s_%dx%d.jpg", IMAGE_DIR, timestamp, IMAGE_WIDTH, IMAGE_HEIGHT);

    pid_t pid = fork();
    if (pid == -1) {
        log_event("Failed to fork for image capture");
        return;
    } else if (pid == 0) {
        char *args[] = {"libcamera-still", "-o", image_path, "-w", "1280", "-h", "720", "-q", "100", NULL};
        execvp(args[0], args);
        log_event("Failed to exec libcamera-still");
        exit(EXIT_FAILURE);
    } else {
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            log_event("Image capture successful");
        } else {
            log_event("Image capture failed");
        }
    }
}

