#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <signal.h>

#define DEFAULT_DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FORMAT V4L2_PIX_FMT_GREY
#define BUFFER_COUNT 1

static int fd = -1;
static void *buffer_start = NULL;
static size_t buffer_length = 0;
static int frame_count = 0;

void cleanup() {
    if (buffer_start) {
        munmap(buffer_start, buffer_length);
        buffer_start = NULL;
    }
    if (fd != -1) {
        close(fd);
        fd = -1;
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, stopping...\n", signum);
    cleanup();
    exit(0);
}

int main(int argc, char *argv[]) {
    const char *device = DEFAULT_DEVICE;
    if (argc > 1) {
        device = argv[1];
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd = open(device, O_RDWR | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        cleanup();
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device %s is no video capture device\n", device);
        cleanup();
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        cleanup();
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        cleanup();
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        cleanup();
        return EXIT_FAILURE;
    }

    buffer_start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer_start == MAP_FAILED) {
        perror("mmap");
        cleanup();
        return EXIT_FAILURE;
    }
    buffer_length = buf.length;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        cleanup();
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        struct timeval tv = {2, 0}; // 2 seconds timeout
        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            perror("select");
            break;
        } else if (r == 0) {
            printf("select timeout\n");
            continue;
        }

        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            if (errno == EAGAIN) {
                continue;
            }
            perror("VIDIOC_DQBUF");
            break;
        }

        char filename[256];
        snprintf(filename, sizeof(filename), "image_%04d.pgm", ++frame_count);
        FILE *f = fopen(filename, "wb");
        if (!f) {
            perror("fopen");
            break;
        }

        fprintf(f, "P5\n%d %d\n255\n", WIDTH, HEIGHT);
        if (fwrite(buffer_start, 1, buf.bytesused, f) != buf.bytesused) {
            perror("fwrite");
            fclose(f);
            break;
        }
        fclose(f);

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            break;
        }
    }

    ioctl(fd, VIDIOC_STREAMOFF, &type);
    cleanup();
    return EXIT_SUCCESS;
}

