#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <time.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define BUFFER_COUNT 4
#define LOG_FILE "frame_log.txt"

static int fd = -1;
static struct v4l2_buffer buf[BUFFER_COUNT];
static void *buffer_start[BUFFER_COUNT];
static unsigned int buffer_length[BUFFER_COUNT];
static FILE *log_file = NULL;

void cleanup() {
    if (fd != -1) {
        for (int i = 0; i < BUFFER_COUNT; ++i) {
            if (buffer_start[i]) {
                munmap(buffer_start[i], buffer_length[i]);
            }
        }
        close(fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);
    return r;
}

int main() {
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct timeval timeout;
    fd_set fds;
    int i, r;

    signal(SIGINT, signal_handler);

    fd = open(DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Cannot open device");
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        perror("VIDIOC_S_FMT");
        cleanup();
        return EXIT_FAILURE;
    }

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        perror("VIDIOC_REQBUFS");
        cleanup();
        return EXIT_FAILURE;
    }

    for (i = 0; i < BUFFER_COUNT; ++i) {
        memset(&buf[i], 0, sizeof(buf[i]));
        buf[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf[i].memory = V4L2_MEMORY_MMAP;
        buf[i].index = i;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf[i])) {
            perror("VIDIOC_QUERYBUF");
            cleanup();
            return EXIT_FAILURE;
        }

        buffer_length[i] = buf[i].length;
        buffer_start[i] = mmap(NULL, buffer_length[i], PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf[i].m.offset);
        if (MAP_FAILED == buffer_start[i]) {
            perror("mmap");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    for (i = 0; i < BUFFER_COUNT; ++i) {
        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf[i])) {
            perror("VIDIOC_QBUF");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        perror("VIDIOC_STREAMON");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Cannot open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        timeout.tv_sec = 2;
        timeout.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &timeout);
        if (-1 == r) {
            if (EINTR == errno) {
                continue;
            }
            perror("select");
            break;
        }

        if (0 == r) {
            fprintf(stderr, "select timeout\n");
            break;
        }

        if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf[0])) {
            switch (errno) {
                case EAGAIN:
                    continue;
                case EIO:
                    continue;
                default:
                    perror("VIDIOC_DQBUF");
                    break;
            }
            break;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        fprintf(log_file, "%ld.%06ld\n", ts.tv_sec, ts.tv_nsec / 1000);

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf[0])) {
            perror("VIDIOC_QBUF");
            break;
        }
    }

    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        perror("VIDIOC_STREAMOFF");
    }

    cleanup();
    return EXIT_SUCCESS;
}

