    if (!log_file) {
        perror("Cannot open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        timeout.tv_sec = 2;
        timeout.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &timeout);
        if (-1 == r) {
            if (EINTR == errno) {
