                case EIO:
                    continue;
                default:
                    perror("VIDIOC_DQBUF");
                    break;
            }
            break;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        fprintf(log_file, "%ld.%06ld\n", ts.tv_sec, ts.tv_nsec / 1000);

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf[0])) {
            perror("VIDIOC_QBUF");
            break;
        }
    }

    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        perror("VIDIOC_STREAMOFF");
    }

    cleanup();
    return EXIT_SUCCESS;
