#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
    void *start;
    size_t length;
};

static int fd = -1;
static struct buffer *buffers;
static unsigned int n_buffers;
static FILE *file = NULL;

void errno_exit(const char *s) {
    perror(s);
    exit(EXIT_FAILURE);
}

int xioctl(int fh, int request, void *arg) {
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    if (-1 == r) {
        errno_exit(request == VIDIOC_DQBUF ? "VIDIOC_DQBUF" : "ioctl");
    }

    return r;
}

void process_image(const void *p, size_t len) {
    if (fwrite(p, 1, len, file) != len) {
        perror("fwrite");
        exit(EXIT_FAILURE);
    }
}

void stop_streaming(void) {
    enum v4l2_buf_type type;
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        perror("VIDIOC_STREAMOFF");
    }
}

void unmap_buffers(void) {
    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("munmap");
        }
    }
}

void free_buffers(void) {
    free(buffers);
}

void close_file(void) {
    if (file) {
        fclose(file);
    }
}

void close_device(void) {
    if (fd != -1) {
        close(fd);
    }
}

void cleanup(void) {
    stop_streaming();
    unmap_buffers();
    free_buffers();
    close_file();
    close_device();
}

void sigint_handler(int s) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(int argc, char **argv) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    enum v4l2_buf_type type;
    struct v4l2_buffer buf;
    unsigned int i;

    fd = open("/dev/video0", O_RDWR, 0);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        if (EINVAL == errno) {
            fprintf(stderr, "/dev/video0 is no V4L2 device\n");
            exit(EXIT_FAILURE);
        } else {
            perror("VIDIOC_QUERYCAP");
            exit(EXIT_FAILURE);
        }
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is no video capture device\n");
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming i/o\n");
        exit(EXIT_FAILURE);
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 1920;
    fmt.fmt.pix.height = 1080;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        perror("VIDIOC_S_FMT");
        exit(EXIT_FAILURE);
    }

    CLEAR(req);
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        if (EINVAL == errno) {
            fprintf(stderr, "Device does not support memory mapping\n");
            exit(EXIT_FAILURE);
        } else {
            perror("VIDIOC_REQBUFS");
            exit(EXIT_FAILURE);
        }
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        CLEAR(buf);

        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            perror("VIDIOC_QUERYBUF");
            exit(EXIT_FAILURE);
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            perror("mmap");
            exit(EXIT_FAILURE);
        }
    }

    for (unsigned int i = 0; i < n_buffers; ++i) {
        CLEAR(buf);

        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            perror("VIDIOC_QBUF");
            exit(EXIT_FAILURE);
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        perror("VIDIOC_STREAMON");
        exit(EXIT_FAILURE);
    }

    file = fopen("image.jpg", "wb");
    if (!file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    CLEAR(buf);

    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
        perror("VIDIOC_DQBUF");
        exit(EXIT_FAILURE);
    }

    if (buf.bytesused > 0) {
        process_image(buffers[buf.index].start, buf.bytesused);
    }

    if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
        perror("VIDIOC_QBUF");
        exit(EXIT_FAILURE);
    }

    cleanup();

    return 0;
}

