void set_servo_duty(struct gpiod_chip *chip, unsigned int line_offset, int duty) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, line_offset);
    if (!line) {
        perror("gpiod_chip_get_line");
        return;
    }

    int ret = gpiod_line_request_output(line, "servo", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        return;
    }

    unsigned int pulse_width = (PWM_PERIOD * duty) / 1000;
    gpiod_line_set_value(line, 1);
