#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <signal.h>
#include <time.h>

#define WIDTH 640
#define HEIGHT 480
#define FORMAT V4L2_PIX_FMT_YUYV
#define NUM_BUFFERS 4
#define BLUR_RADIUS 2
#define JPEG_QUALITY 75

static int fd = -1;
static struct v4l2_buffer buf;
static struct v4l2_requestbuffers req;
static void *buffers[NUM_BUFFERS];
static int buffer_index = 0;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (fd != -1) {
        if (ioctl(fd, VIDIOC_STREAMOFF, &buf.type) == -1) {
            perror("VIDIOC_STREAMOFF");
        }
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (munmap(buffers[i], buf.length) == -1) {
                perror("munmap");
            }
        }
        if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
            perror("VIDIOC_REQBUFS");
        }
        close(fd);
    }
}

void signal_handler(int signum) {
    running = 0;
}

void yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb24, int width, int height) {
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x += 2) {
            unsigned char y0 = yuyv[(y * width + x) * 2];
            unsigned char u = yuyv[(y * width + x) * 2 + 1];
            unsigned char y1 = yuyv[(y * width + x + 2) * 2];
            unsigned char v = yuyv[(y * width + x + 2) * 2 + 1];

            int r0 = y0 + 1.402 * (v - 128);
            int g0 = y0 - 0.34414 * (u - 128) - 0.71414 * (v - 128);
            int b0 = y0 + 1.772 * (u - 128);

            int r1 = y1 + 1.402 * (v - 128);
            int g1 = y1 - 0.34414 * (u - 128) - 0.71414 * (v - 128);
            int b1 = y1 + 1.772 * (u - 128);

            r0 = r0 < 0 ? 0 : (r0 > 255 ? 255 : r0);
            g0 = g0 < 0 ? 0 : (g0 > 255 ? 255 : g0);
            b0 = b0 < 0 ? 0 : (b0 > 255 ? 255 : b0);

            r1 = r1 < 0 ? 0 : (r1 > 255 ? 255 : r1);
            g1 = g1 < 0 ? 0 : (g1 > 255 ? 255 : g1);
            b1 = b1 < 0 ? 0 : (b1 > 255 ? 255 : b1);

            rgb24[(y * width + x) * 3] = b0;
            rgb24[(y * width + x) * 3 + 1] = g0;
            rgb24[(y * width + x) * 3 + 2] = r0;

            rgb24[(y * width + x + 1) * 3] = b1;
            rgb24[(y * width + x + 1) * 3 + 1] = g1;
            rgb24[(y * width + x + 1) * 3 + 2] = r1;
        }
    }
}

void box_blur(unsigned char *rgb24, int width, int height, int radius) {
    unsigned char *blurred = malloc(width * height * 3);
    if (!blurred) {
        perror("malloc");
        cleanup();
        exit(EXIT_FAILURE);
    }

    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int sum_r = 0, sum_g = 0, sum_b = 0;
            int count = 0;
            for (int i = -radius; i <= radius; i++) {
                for (int j = -radius; j <= radius; j++) {
                    int nx = x + i;
                    int ny = y + j;
                    if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
                        sum_r += rgb24[(ny * width + nx) * 3];
                        sum_g += rgb24[(ny * width + nx) * 3 + 1];
                        sum_b += rgb24[(ny * width + nx) * 3 + 2];
                        count++;
                    }
                }
            }
            blurred[(y * width + x) * 3] = sum_r / count;
            blurred[(y * width + x) * 3 + 1] = sum_g / count;
            blurred[(y * width + x) * 3 + 2] = sum_b / count;
        }
    }

    memcpy(rgb24, blurred, width * height * 3);
    free(blurred);
}

void save_jpeg(const unsigned char *rgb24, int width, int height, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile = fopen(filename, "wb");
    if (!outfile) {
        perror("fopen");
        cleanup();
        exit(EXIT_FAILURE);
    }

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row_pointer[1];
    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = (JSAMPROW)&rgb24[cinfo.next_scanline * width * 3];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    fclose(outfile);
}

int main() {
    signal(SIGINT, signal_handler);

    fd = open("/dev/video0", O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        cleanup();
        exit(EXIT_FAILURE);
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        cleanup();
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            cleanup();
            exit(EXIT_FAILURE);
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (running) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        struct timeval tv;
        tv.tv_sec = 2;
        tv.tv_usec = 0;

        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            perror("select");
            cleanup();
            exit(EXIT_FAILURE);
        } else if (r == 0) {
            fprintf(stderr, "Timeout waiting for frame\n");
            continue;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            perror("VIDIOC_DQBUF");
            cleanup();
            exit(EXIT_FAILURE);
        }

        unsigned char *yuyv = buffers[buf.index];
        unsigned char *rgb24 = malloc(WIDTH * HEIGHT * 3);
        if (!rgb24) {
            perror("malloc");
            cleanup();
            exit(EXIT_FAILURE);
        }

        yuyv_to_rgb24(yuyv, rgb24, WIDTH, HEIGHT);
        box_blur(rgb24, WIDTH, HEIGHT, BLUR_RADIUS);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char filename[100];
        strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", tm_info);

        save_jpeg(rgb24, WIDTH, HEIGHT, filename);

        free(rgb24);

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    cleanup();
    return 0;
}

