#include <string.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

void print_capabilities(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        exit(EXIT_FAILURE);
    }

    printf("Driver Caps:\n");
    printf("  Driver: %s\n", cap.driver);
    printf("  Card: %s\n", cap.card);
    printf("  Bus info: %s\n", cap.bus_info);
    printf("  Version: %u.%u.%u\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);
    printf("  Capabilities: %08x\n", cap.capabilities);
}

void print_frame_sizes(int fd) {
    struct v4l2_frmsizeenum fsize;
    CLEAR(fsize);
    fsize.pixel_format = V4L2_PIX_FMT_MJPEG; // Example format, change as needed

    printf("Supported Frame Sizes:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fsize) == 0) {
        switch (fsize.type) {
            case V4L2_FRMSIZE_TYPE_DISCRETE:
                printf("  Discrete: %ux%u\n", fsize.discrete.width, fsize.discrete.height);
                break;
            case V4L2_FRMSIZE_TYPE_CONTINUOUS:
                printf("  Continuous: %ux%u to %ux%u\n", fsize.stepwise.min_width, fsize.stepwise.min_height,
                       fsize.stepwise.max_width, fsize.stepwise.max_height);
                break;
            case V4L2_FRMSIZE_TYPE_STEPWISE:
                printf("  Stepwise: %ux%u to %ux%u, step %ux%u\n", fsize.stepwise.min_width, fsize.stepwise.min_height,
                       fsize.stepwise.max_width, fsize.stepwise.max_height,
                       fsize.stepwise.step_width, fsize.stepwise.step_height);
                break;
        }
        fsize.index++;
    }
}

void print_frame_intervals(int fd, unsigned int width, unsigned int height) {
    struct v4l2_frmivalenum fival;
    CLEAR(fival);
    fival.pixel_format = V4L2_PIX_FMT_MJPEG; // Example format, change as needed
    fival.width = width;
    fival.height = height;

    printf("Supported Frame Intervals for %ux%u:\n", width, height);
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fival) == 0) {
        switch (fival.type) {
            case V4L2_FRMIVAL_TYPE_DISCRETE:
                printf("  Discrete: %u/%u\n", fival.discrete.numerator, fival.discrete.denominator);
                break;
            case V4L2_FRMIVAL_TYPE_CONTINUOUS:
                printf("  Continuous: %u/%u to %u/%u\n", fival.stepwise.min.numerator, fival.stepwise.min.denominator,
                       fival.stepwise.max.numerator, fival.stepwise.max.denominator);
                break;
            case V4L2_FRMIVAL_TYPE_STEPWISE:
                printf("  Stepwise: %u/%u to %u/%u, step %u/%u\n", fival.stepwise.min.numerator, fival.stepwise.min.denominator,
                       fival.stepwise.max.numerator, fival.stepwise.max.denominator,
                       fival.stepwise.step.numerator, fival.stepwise.step.denominator);
                break;
        }
        fival.index++;
    }
}

void check_autofocus(int fd) {
    struct v4l2_queryctrl queryctrl;
    CLEAR(queryctrl);
    queryctrl.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) == 0) {
        printf("Autofocus is supported.\n");
    } else {
        printf("Autofocus is not supported.\n");
    }
}

int main() {
    const char *dev_name = "/dev/video0";
    int fd = open(dev_name, O_RDWR);
    if (fd == -1) {
        perror("Cannot open device");
        exit(EXIT_FAILURE);
    }

    print_capabilities(fd);
    print_frame_sizes(fd);
    print_frame_intervals(fd, 1920, 1080); // Example resolution, change as needed
    check_autofocus(fd);

    close(fd);
    return 0;
}

