#include <signal.h>
#include <pigpio.h>

#define PAN_GPIO 4
#define TILT_GPIO 5
#define UP_GPIO 6
#define DOWN_GPIO 7
#define LEFT_GPIO 8
#define RIGHT_GPIO 9

#define CENTER_POSITION 1500
#define MIN_POSITION 1000
#define MAX_POSITION 2000
#define STEP 10
#define LOOP_DELAY 50000 // 50 ms in microseconds

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure GPIO pins
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);
    gpioSetMode(UP_GPIO, PI_INPUT);
    gpioSetMode(DOWN_GPIO, PI_INPUT);
    gpioSetMode(LEFT_GPIO, PI_INPUT);
    gpioSetMode(RIGHT_GPIO, PI_INPUT);

    // Enable internal pull-ups for buttons
    gpioSetPullUpDown(UP_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_GPIO, PI_PUD_UP);

    // Initialize servos to center position
    gpioServo(PAN_GPIO, CENTER_POSITION);
    gpioServo(TILT_GPIO, CENTER_POSITION);

    printf("Pan-Tilt System Initialized\n");
    printf("PAN: GPIO%d, TILT: GPIO%d\n", PAN_GPIO, TILT_GPIO);
    printf("UP: GPIO%d, DOWN: GPIO%d, LEFT: GPIO%d, RIGHT: GPIO%d\n", UP_GPIO, DOWN_GPIO, LEFT_GPIO, RIGHT_GPIO);
    printf("Center Position: %d microseconds\n", CENTER_POSITION);

    int pan_position = CENTER_POSITION;
    int tilt_position = CENTER_POSITION;

    while (running) {
        if (gpioRead(UP_GPIO) == 0) {
            tilt_position = (tilt_position + STEP > MAX_POSITION) ? MAX_POSITION : tilt_position + STEP;
            gpioServo(TILT_GPIO, tilt_position);
        }
        if (gpioRead(DOWN_GPIO) == 0) {
            tilt_position = (tilt_position - STEP < MIN_POSITION) ? MIN_POSITION : tilt_position - STEP;
            gpioServo(TILT_GPIO, tilt_position);
        }
        if (gpioRead(LEFT_GPIO) == 0) {
            pan_position = (pan_position - STEP < MIN_POSITION) ? MIN_POSITION : pan_position - STEP;
            gpioServo(PAN_GPIO, pan_position);
        }
        if (gpioRead(RIGHT_GPIO) == 0) {
            pan_position = (pan_position + STEP > MAX_POSITION) ? MAX_POSITION : pan_position + STEP;
            gpioServo(PAN_GPIO, pan_position);
        }

        gpioDelay(LOOP_DELAY);
    }

    // Clean up
    gpioServo(PAN_GPIO, 0);
    gpioServo(TILT_GPIO, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

