#include <pigpio.h>
#include <curl/curl.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2000000 // 2 seconds in microseconds
#define CAMERA_CMD "libcamera-still -o %s -q 85 -w 640 -h 480"
#define CAPTURE_DIR "motion_captures"
#define JSON_TEMPLATE "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_status\":\"%s\",\"gpio_pin\":%d}"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void send_data_to_server(const char *server_ip, const char *server_port, const char *filename, const char *timestamp, const char *motion_status, int gpio_pin) {
    CURL *curl;
    CURLcode res;
    char json[1024];

    snprintf(json, sizeof(json), JSON_TEMPLATE, filename, timestamp, motion_status, gpio_pin);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        char url[256];
        snprintf(url, sizeof(url), "http://%s:%s/upload", server_ip, server_port);
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
}

void capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), CAMERA_CMD, filename);
    if(system(command) != 0) {
        fprintf(stderr, "Failed to capture image\n");
    }
}

int main(int argc, char *argv[]) {
    if(argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *server_ip = argv[1];
    const char *server_port = argv[2];

    if(gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if(gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if(gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct stat st = {0};
    if(stat(CAPTURE_DIR, &st) == -1) {
        if(mkdir(CAPTURE_DIR, 0755) != 0) {
            fprintf(stderr, "Failed to create directory %s\n", CAPTURE_DIR);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timespec last_motion_time = {0};
    while(running) {
        if(gpioRead(GPIO_PIN) == PI_HIGH) {
            struct timespec current_time;
            clock_gettime(CLOCK_REALTIME, &current_time);
            if(current_time.tv_sec - last_motion_time.tv_sec > 2) {
                char filename[256];
                struct tm *tm_info;
                char timestamp[80];

                clock_gettime(CLOCK_REALTIME, &last_motion_time);
                tm_info = localtime(&last_motion_time.tv_sec);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
                snprintf(filename, sizeof(filename), "%s/motion_%s_%06ld.jpg", CAPTURE_DIR, timestamp, last_motion_time.tv_nsec / 1000);

                capture_image(filename);
                send_data_to_server(server_ip, server_port, filename, timestamp, "detected", GPIO_PIN);
            }
        }
        usleep(100000); // 100 ms
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

