#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <sys/types.h>
#include <sys/wait.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define TIMEOUT_MS 2000

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    running = 0;
}

void capture_image() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char filename[100];
    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S_%.3ld.jpg", tm_info, now % 1000);
    snprintf(filename, sizeof(filename), "%s/%s", IMAGE_DIR, filename);

    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout %d --nopreview", filename, TIMEOUT_MS);

    log_event("Motion detected, capturing image...");
    int status = system(command);
    if (status == -1) {
        log_event("Failed to execute libcamera-still command.");
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        log_event("libcamera-still command failed with exit status.");
    } else {
        log_event("Image captured successfully.");
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(line, "pir_motion_sensor");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_edge_detection(line, GPIOD_LINE_EDGE_RISING);
    if (ret < 0) {
        perror("Failed to set edge detection");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Motion capture system initialized.");

    while (running) {
        ret = gpiod_line_event_wait(line, DEBOUNCE_MS * 1000);
        if (ret < 0) {
            perror("Failed to wait for GPIO event");
            continue;
        }

        if (ret == 0) {
            continue; // Timeout, no event
        }

        struct gpiod_line_event event;
        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("Failed to read GPIO event");
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            capture_image();
        }
    }

    cleanup();
    log_event("Motion capture system terminated.");
    return EXIT_SUCCESS;
}

