        fprintf(stderr, "Error: Angle out of range (0-180 degrees)\n");
        return;
    }
    int pulse_width = MIN_PULSE + (angle * (MAX_PULSE - MIN_PULSE) / 180);
    gpioServo(gpio, pulse_width);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PAN_GPIO, FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, FREQUENCY);

    set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);

    signal(SIGINT, handle_sigint);

    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    while (running) {
        printf("Enter direction (w/a/s/d) or 'q' to quit: ");
        char input;
        scanf(" %c", &input);

        switch (input) {
            case 'w':
                if (tilt_angle + ANGLE_INCREMENT <= 180) {
                    tilt_angle += ANGLE_INCREMENT;
                    set_servo_angle(TILT_GPIO, tilt_angle);
                } else {
                    fprintf(stderr, "Error: Tilt angle exceeds maximum (180 degrees)\n");
                }
                break;
            case 's':
                if (tilt_angle - ANGLE_INCREMENT >= 0) {
                    tilt_angle -= ANGLE_INCREMENT;
                    set_servo_angle(TILT_GPIO, tilt_angle);
                } else {
                    fprintf(stderr, "Error: Tilt angle below minimum (0 degrees)\n");
                }
                break;
            case 'a':
                if (pan_angle - ANGLE_INCREMENT >= 0) {
                    pan_angle -= ANGLE_INCREMENT;
                    set_servo_angle(PAN_GPIO, pan_angle);
                } else {
                    fprintf(stderr, "Error: Pan angle below minimum (0 degrees)\n");
                }
                break;
            case 'd':
                if (pan_angle + ANGLE_INCREMENT <= 180) {
                    pan_angle += ANGLE_INCREMENT;
                    set_servo_angle(PAN_GPIO, pan_angle);
                } else {
                    fprintf(stderr, "Error: Pan angle exceeds maximum (180 degrees)\n");
                }
                break;
            case 'q':
                running = 0;
                break;
            default:
                printf("Invalid input. Use w/a/s/d to move or 'q' to quit.\n");
        }

        gpioDelay(DELAY_MS * 1000);
    }

    set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);
    gpioTerminate();

    return 0;
}

