#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450
#define LCD_I2C_BUS 1
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

volatile int pulse_count = 0;
double total_volume = 0.0;
int lcd_handle = -1;

void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_LOW) {
        pulse_count++;
    }
}

void update_lcd() {
    char buffer[32];
    double current_flow_rate = (pulse_count / PULSES_PER_LITER) * 60.0;
    total_volume += current_flow_rate / 60.0;

    snprintf(buffer, sizeof(buffer), "Flow: %.2f L/min\nVolume: %.2f L", current_flow_rate, total_volume);

    for (int i = 0; i < LCD_HEIGHT; i++) {
        char line[LCD_WIDTH + 1];
        strncpy(line, buffer + i * LCD_WIDTH, LCD_WIDTH);
        line[LCD_WIDTH] = '\0';
        i2cWriteDevice(lcd_handle, line, LCD_WIDTH);
        usleep(50000); // Small delay between lines
    }
}

void signal_handler(int signum) {
    if (lcd_handle >= 0) {
        i2cClose(lcd_handle);
    }
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISR(FLOW_SENSOR_GPIO, RISING_EDGE, pulse_callback) < 0) {
        fprintf(stderr, "Failed to set ISR\n");
        gpioTerminate();
        return 1;
    }

    lcd_handle = i2cOpen(LCD_I2C_BUS, LCD_I2C_ADDR, 0);
    if (lcd_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        double current_flow_rate = (pulse_count / PULSES_PER_LITER) * 60.0;
        total_volume += current_flow_rate / 60.0;

        printf("Flow: %.2f L/min, Volume: %.2f L\n", current_flow_rate, total_volume);

        if (time(NULL) % 10 == 0) {
            update_lcd();
        }

        pulse_count = 0;
        sleep(1);
    }

    return 0;
}

