    running = 0;
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(ANEMOMETER_PIN, PI_INPUT);
    gpioSetAlertFunc(ANEMOMETER_PIN, anemometer_callback);
}

void init_i2c(int *i2c_handle) {
    *i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (*i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        exit(EXIT_FAILURE);
    }
}

void init_spi(int *spi_handle) {
    *spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (*spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(EXIT_FAILURE);
    }
}

void write_i2c(int i2c_handle, const char *data, int len) {
    if (i2cWriteDevice(i2c_handle, data, len) < 0) {
        fprintf(stderr, "I2C write failed\n");
    }
}

