        lcd_set_cursor(i2c_handle, 1, 0);
        lcd_print(i2c_handle, "Speed:");
        lcd_set_cursor(i2c_handle, 1, 7);
        lcd_print(i2c_handle, speed_str);
        lcd_print(i2c_handle, " m/s");

        anemometer_count = 0;
        usleep(SAMPLE_INTERVAL * 1000);
    }

    cleanup(i2c_handle, spi_handle);
    return 0;
