#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

#define FLOW_SENSOR_GPIO 17
#define FLOW_SENSOR_PULSES_PER_LITER 7.5
#define I2C_BUS 1
#define I2C_ADDRESS 0x27
#define LCD_CLEAR 0x01
#define LCD_HOME 0x02
#define LCD_SET_CURSOR_LINE1 0x80
#define LCD_SET_CURSOR_LINE2 0xC0
#define LCD_BACKLIGHT 0x08

volatile unsigned int pulse_count = 0;
volatile unsigned int last_pulse_count = 0;
volatile time_t last_time = 0;

void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_LOW) {
        pulse_count++;
    }
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetAlertFunc(FLOW_SENSOR_GPIO, pulse_callback) < 0) {
        fprintf(stderr, "Failed to set GPIO alert function\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    int fd = wiringPiI2CSetupInterface("/dev/i2c-1", I2C_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    wiringPiI2CWrite(fd, LCD_CLEAR | LCD_BACKLIGHT);
    wiringPiI2CWrite(fd, LCD_HOME | LCD_BACKLIGHT);
    wiringPiI2CWrite(fd, LCD_SET_CURSOR_LINE1 | LCD_BACKLIGHT);
    wiringPiI2CWrite(fd, 'F');
    wiringPiI2CWrite(fd, 'l');
    wiringPiI2CWrite(fd, 'o');
    wiringPiI2CWrite(fd, 'w');
    wiringPiI2CWrite(fd, ' ');
    wiringPiI2CWrite(fd, 'R');
    wiringPiI2CWrite(fd, 'a');
    wiringPiI2CWrite(fd, 't');
    wiringPiI2CWrite(fd, 'e');
    wiringPiI2CWrite(fd, ':');
    wiringPiI2CWrite(fd, LCD_SET_CURSOR_LINE2 | LCD_BACKLIGHT);
}

void update_lcd(float flow_rate) {
    int fd = wiringPiI2CSetupInterface("/dev/i2c-1", I2C_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return;
    }

    wiringPiI2CWrite(fd, LCD_SET_CURSOR_LINE2 | LCD_BACKLIGHT);
    char buffer[10];
    snprintf(buffer, sizeof(buffer), "%.2f L/min", flow_rate);
    for (int i = 0; i < 8; i++) {
        wiringPiI2CWrite(fd, buffer[i] | LCD_BACKLIGHT);
    }
}

void signal_handler(int signum) {
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();
    setup_i2c();

    while (1) {
        time_t current_time = time(NULL);
        if (current_time - last_time >= 1) {
            float flow_rate = (pulse_count - last_pulse_count) / FLOW_SENSOR_PULSES_PER_LITER * 60.0;
            update_lcd(flow_rate);
            last_pulse_count = pulse_count;
            last_time = current_time;
        }
        usleep(100000); // 100ms sleep
    }

    gpioTerminate();
    return 0;
}

