#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define ROWS 8
#define COLS 8

const unsigned int row_gpios[ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
const unsigned int col_gpios[COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

struct gpiod_chip *chip;
struct gpiod_line_bulk rows, cols;

void cleanup() {
    gpiod_line_release_bulk(&cols);
    gpiod_line_release_bulk(&rows);
    gpiod_chip_close(chip);
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_FAILURE);
}

void init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    if (gpiod_chip_get_lines(chip, row_gpios, ROWS, &rows) < 0) {
        perror("Failed to get row GPIO lines");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_chip_get_lines(chip, col_gpios, COLS, &cols) < 0) {
        perror("Failed to get column GPIO lines");
        cleanup();
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < ROWS; i++) {
        if (gpiod_line_request_output(rows.lines[i], "led_matrix", 0) < 0) {
            perror("Failed to request row GPIO line as output");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < COLS; i++) {
        if (gpiod_line_request_output(cols.lines[i], "led_matrix", 1) < 0) {
            perror("Failed to request column GPIO line as output");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }
}

void scan_display(const int pattern[ROWS][COLS]) {
    for (int row = 0; row < ROWS; row++) {
        gpiod_line_set_value(rows.lines[row], 1);
        for (int col = 0; col < COLS; col++) {
            gpiod_line_set_value(cols.lines[col], !pattern[row][col]);
        }
        usleep(800);
        gpiod_line_set_value(rows.lines[row], 0);
    }
}

void left_to_right_wave(int pattern[ROWS][COLS]) {
    for (int col = 0; col < COLS; col++) {
        for (int row = 0; row < ROWS; row++) {
            pattern[row][col] = 1;
            if (col > 0) pattern[row][col - 1] = 0;
        }
        scan_display(pattern);
    }
}

void right_to_left_wave(int pattern[ROWS][COLS]) {
    for (int col = COLS - 1; col >= 0; col--) {
        for (int row = 0; row < ROWS; row++) {
            pattern[row][col] = 1;
            if (col < COLS - 1) pattern[row][col + 1] = 0;
        }
        scan_display(pattern);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    init_gpio();

    int pattern[ROWS][COLS] = {0};

    while (1) {
        left_to_right_wave(pattern);
        right_to_left_wave(pattern);
    }

    cleanup();
    return 0;
}

