#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX75031_ADDR 0x4C
#define DISTANCE_REG 0x0D
#define SAMPLE_INTERVAL_US 100000

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    signal(SIGINT, handle_sigint);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("depth_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
    }

    while (running) {
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Failed to get timestamp\n");
            break;
        }

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", gmtime(&ts.tv_sec));

        int result = i2cWriteByte(i2c_handle, DISTANCE_REG);
        if (result < 0) {
            fprintf(log_file, "%s,-1\n", timestamp);
            fprintf(stderr, "I2C write failed: %d\n", result);
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "I2C re-open failed: %d\n", i2c_handle);
                break;
            }
            continue;
        }

        uint8_t buffer[2];
        result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buffer, 2);
        if (result < 0) {
            fprintf(log_file, "%s,-1\n", timestamp);
            fprintf(stderr, "I2C read failed: %d\n", result);
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "I2C re-open failed: %d\n", i2c_handle);
                break;
            }
            continue;
        }

        uint16_t distance = (buffer[0] << 8) | buffer[1];
        fprintf(log_file, "%s,%u\n", timestamp, distance);

        fflush(log_file);
        usleep(SAMPLE_INTERVAL_US);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

