#define SI1145_COMMAND_REG 0x18
#define SI1145_PART_ID 0x45
#define SI1145_INIT_COMMAND 0x11

#define I2C_BUS 1
#define SAMPLE_INTERVAL_MS 500

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void log_reading(const char *timestamp, int proximity, int ambient) {
    FILE *log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        log_error("Failed to open log file for writing");
        return;
    }
    fprintf(log_file, "%s, Proximity: %d, Ambient: %d\n", timestamp, proximity, ambient);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio library");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SI1145_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Verify PART ID
    char part_id;
    if (i2cReadByteData(i2c_handle, SI1145_PART_ID_REG, &part_id) < 0) {
        log_error("Failed to read PART ID register");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (part_id != SI1145_PART_ID) {
        log_error("Incorrect PART ID");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Initialize sensor
    if (i2cWriteByteData(i2c_handle, SI1145_COMMAND_REG, SI1145_INIT_COMMAND) < 0) {
        log_error("Failed to initialize sensor");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        int proximity, ambient;
        if (i2cReadWordData(i2c_handle, 0x02, &proximity) < 0 || i2cReadWordData(i2c_handle, 0x04, &ambient) < 0) {
            log_error("Failed to read sensor data");
            continue;
        }

        log_reading(timestamp, proximity, ambient);

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

