#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR_LINE 4
#define LED_LINE 17
#define SENSOR_CHIP_NAME "gpiochip4"
#define LED_CHIP_NAME "gpiochip4"
#define LOG_FILE "proximity.log"
#define POLL_INTERVAL_US 100000

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    fprintf(log_file, "%s %s\n", timestamp, message);
    fclose(log_file);
}

int main() {
    struct gpiod_chip *sensor_chip = NULL, *led_chip = NULL;
    struct gpiod_line *sensor_line = NULL, *led_line = NULL;
    int ret;

    // Open GPIO chips
    sensor_chip = gpiod_chip_open_by_name(SENSOR_CHIP_NAME);
    if (!sensor_chip) {
        perror("Failed to open sensor GPIO chip");
        sensor_chip = gpiod_chip_open_by_name("gpiochip0");
        if (!sensor_chip) {
            perror("Failed to open fallback sensor GPIO chip");
            return EXIT_FAILURE;
        }
    }

    led_chip = gpiod_chip_open_by_name(LED_CHIP_NAME);
    if (!led_chip) {
        perror("Failed to open LED GPIO chip");
        led_chip = gpiod_chip_open_by_name("gpiochip0");
        if (!led_chip) {
            perror("Failed to open fallback LED GPIO chip");
            gpiod_chip_close(sensor_chip);
            return EXIT_FAILURE;
        }
    }

    // Request GPIO lines
    sensor_line = gpiod_chip_get_line(sensor_chip, SENSOR_LINE);
    if (!sensor_line) {
        perror("Failed to get sensor GPIO line");
        gpiod_chip_close(sensor_chip);
        gpiod_chip_close(led_chip);
        return EXIT_FAILURE;
    }

