#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_KEY_REG 0x07
#define CH_LIST_REG 0x4F
#define COMMAND_REG 0x30
#define PS1_DATA_REG 0x18
#define ALS_VIS_DATA_REG 0x22

#define PART_ID_VALUE 0x45
#define HW_KEY_VALUE 0x17
#define CH_LIST_VALUE 0x03 // Enable PS1 and ALS_VIS

#define ALS_FORCE 0x06
#define PS_FORCE 0x07

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void log_data(FILE *log_file, uint16_t ps1, uint16_t als_vis) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s,%u,%u\n", timestamp, ps1, als_vis);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t part_id;
    if (i2cReadByteData(i2c_handle, PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (part_id != PART_ID_VALUE) {
        fprintf(stderr, "Incorrect PART_ID: expected 0x45, got 0x%02X\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, HW_KEY_REG, HW_KEY_VALUE) < 0) {
        fprintf(stderr, "Failed to write HW_KEY register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, CH_LIST_REG, CH_LIST_VALUE) < 0) {
        fprintf(stderr, "Failed to write CH_LIST register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("biometric_data.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        if (i2cWriteByteData(i2c_handle, COMMAND_REG, ALS_FORCE) < 0) {
            fprintf(stderr, "Failed to trigger ALS measurement\n");
            break;
        }

        if (i2cWriteByteData(i2c_handle, COMMAND_REG, PS_FORCE) < 0) {
            fprintf(stderr, "Failed to trigger PS measurement\n");
            break;
        }

        uint16_t als_vis;
        if (i2cReadWordData(i2c_handle, ALS_VIS_DATA_REG, &als_vis) < 0) {
            fprintf(stderr, "Failed to read ALS_VIS data\n");
            break;
        }

        uint16_t ps1;
        if (i2cReadWordData(i2c_handle, PS1_DATA_REG, &ps1) < 0) {
            fprintf(stderr, "Failed to read PS1 data\n");
            break;
        }

        log_data(log_file, ps1, als_vis);
        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

