#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define TIMEOUT_US 30000
#define POLL_INTERVAL_US 60000000
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define WATER_REMINDER_CM 15

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void log_entry(const char *message) {
    FILE *log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("Failed to get current time");
        fclose(log_file);
        return;
    }

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));
    fprintf(log_file, "%s.%06ld - %s\n", timestamp, ts.tv_nsec / 1000, message);
    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    struct gpiod_line_event event;
    struct timespec start_time, end_time;
    int ret;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret < 0) {
        perror("Failed to request trigger line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(echo_line, "echo");
    if (ret < 0) {
        perror("Failed to request echo line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        // Generate 10 microsecond trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo to rise
        ret = gpiod_line_event_wait(echo_line, TIMEOUT_US);
        if (ret < 0) {
            perror("Failed to wait for echo rise");
            log_entry("Echo rise timeout");
            continue;
        } else if (ret == 0) {
            log_entry("Echo rise timeout");
            continue;
        }

        ret = gpiod_line_event_read(echo_line, &event);
        if (ret < 0) {
            perror("Failed to read echo rise event");
            log_entry("Echo rise event read error");
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            log_entry("Unexpected echo event type");
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &start_time);

        // Wait for echo to fall
        ret = gpiod_line_event_wait(echo_line, TIMEOUT_US);
        if (ret < 0) {
            perror("Failed to wait for echo fall");
            log_entry("Echo fall timeout");
            continue;
        } else if (ret == 0) {
            log_entry("Echo fall timeout");
            continue;
        }

        ret = gpiod_line_event_read(echo_line, &event);
        if (ret < 0) {
            perror("Failed to read echo fall event");
            log_entry("Echo fall event read error");
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
            log_entry("Unexpected echo event type");
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &end_time);

        long pulse_duration_ns = (end_time.tv_sec - start_time.tv_sec) * 1000000000 +
                                 (end_time.tv_nsec - start_time.tv_nsec);

        double distance_cm = (pulse_duration_ns * 34300.0) / 2000000.0;

        if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
            log_entry("Invalid distance measurement");
            continue;
        }

        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Distance: %.2f cm", distance_cm);
        log_entry(log_message);

        if (distance_cm < WATER_REMINDER_CM) {
            log_entry("Time to water the plant!");
        }

        usleep(POLL_INTERVAL_US);
    }

    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

