#define I2C_BUS 1
#define I2C_ADDR 0x39
#define SENSOR_ID_REG 0x92
#define ENABLE_REG 0x80
#define ATIME_REG 0x81
#define WTIME_REG 0x83
#define PPULSE_REG 0x8E
#define CONTROL_REG 0xF1
#define CONFIG2_REG 0x90
#define RED_REG 0x96
#define GREEN_REG 0x98
#define BLUE_REG 0x9A
#define PROXIMITY_REG 0x9C

#define SENSOR_ID 0xAB
#define PROXIMITY_THRESHOLD 200

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void init_sensor(int handle) {
    if (i2cWriteByteData(handle, ENABLE_REG, 0x03) < 0) {
        fprintf(stderr, "Failed to write to ENABLE_REG\n");
        exit(EXIT_FAILURE);
    }
    if (i2cWriteByteData(handle, ATIME_REG, 0xDB) < 0) {
        fprintf(stderr, "Failed to write to ATIME_REG\n");
        exit(EXIT_FAILURE);
    }
    if (i2cWriteByteData(handle, WTIME_REG, 0xF6) < 0) {
        fprintf(stderr, "Failed to write to WTIME_REG\n");
        exit(EXIT_FAILURE);
    }
    if (i2cWriteByteData(handle, PPULSE_REG, 0x87) < 0) {
        fprintf(stderr, "Failed to write to PPULSE_REG\n");
        exit(EXIT_FAILURE);
    }
    if (i2cWriteByteData(handle, CONTROL_REG, 0x03) < 0) {
        fprintf(stderr, "Failed to write to CONTROL_REG\n");
        exit(EXIT_FAILURE);
    }
    if (i2cWriteByteData(handle, CONFIG2_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to write to CONFIG2_REG\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t sensor_id;
    if (i2cReadByteData(handle, SENSOR_ID_REG, &sensor_id) < 0) {
        fprintf(stderr, "Failed to read SENSOR_ID_REG\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sensor_id != SENSOR_ID) {
        fprintf(stderr, "Incorrect sensor ID\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    init_sensor(handle);

    FILE *log_file = fopen("color_proximity_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t proximity;
        if (i2cReadByteData(handle, PROXIMITY_REG, &proximity) < 0) {
            fprintf(stderr, "Failed to read PROXIMITY_REG, reinitializing sensor\n");
            i2cClose(handle);
            handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (handle < 0) {
                fprintf(stderr, "Failed to reopen I2C bus\n");
                break;
            }
            init_sensor(handle);
            continue;
        }

        if (proximity > PROXIMITY_THRESHOLD) {
            uint16_t red, green, blue;
            uint8_t buffer[6];
            if (i2cReadI2CBlockData(handle, RED_REG, buffer, 6) < 0) {
                fprintf(stderr, "Failed to read RGB registers, reinitializing sensor\n");
                i2cClose(handle);
                handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
                if (handle < 0) {
                    fprintf(stderr, "Failed to reopen I2C bus\n");
                    break;
                }
                init_sensor(handle);
                continue;
            }

            red = (buffer[0] << 8) | buffer[1];
            green = (buffer[2] << 8) | buffer[3];
            blue = (buffer[4] << 8) | buffer[5];

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s, %d, %d, %d, %d\n", timestamp, proximity, red, green, blue);
            fflush(log_file);
        }

        usleep(100000);
    }

    fclose(log_file);
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

