#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SI1182_ADDRESS 0x5A
#define PART_ID_REG 0x00
#define MEAS_RATE0_REG 0x08
#define COMMAND_REG 0x47
#define PS_DATA0_REG 0x24
#define PS_DATA1_REG 0x25

#define SI1182_PART_ID 0x42

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd;
    FILE *csv_file;
    struct sigaction sa;

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open CSV file
    csv_file = fopen("heartrate.csv", "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Read PART_ID register
    uint8_t part_id;
    if (i2c_smbus_read_byte_data(i2c_fd, PART_ID_REG) < 0) {
        perror("Failed to read PART_ID register");
        fclose(csv_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X\n", part_id);
        fclose(csv_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure continuous proximity measurement
    if (i2c_smbus_write_byte_data(i2c_fd, MEAS_RATE0_REG, 0x01) < 0) {
        perror("Failed to write MEAS_RATE0 register");
        fclose(csv_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Issue reset/start command
    if (i2c_smbus_write_byte_data(i2c_fd, COMMAND_REG, 0x01) < 0) {
        perror("Failed to write COMMAND register");
        fclose(csv_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        fclose(csv_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        uint16_t ps_data0, ps_data1;
        uint16_t proximity_data;
        double bpm = 0.0; // Placeholder BPM calculation

        // Read proximity data
        ps_data0 = i2c_smbus_read_byte_data(i2c_fd, PS_DATA0_REG);
        ps_data1 = i2c_smbus_read_byte_data(i2c_fd, PS_DATA1_REG);

        if (ps_data0 < 0 || ps_data1 < 0) {
            fprintf(stderr, "Failed to read proximity data\n");
            continue;
        }

        proximity_data = (ps_data1 << 8) | ps_data0;

        // Calculate BPM (placeholder)
        bpm = proximity_data * 0.1; // Example calculation

        // Get current time
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        // Write to CSV
        fprintf(csv_file, "%s,%.1f\n", timestamp, bpm);
        fflush(csv_file);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    fclose(csv_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

