#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L0X_I2C_ADDRESS 0x29
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B
#define GPIO_TRIGGER 17
#define TIMEOUT_MS 100

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void log_distance(FILE *log_file, uint16_t distance_mm) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = ts.tv_sec + ts.tv_nsec / 1e9;
    fprintf(log_file, "%.6f,%u\n", timestamp, distance_mm);
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_sigint);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, VL53L0X_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, VL53L0X_I2C_ADDRESS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (i2cReadByteData(i2c_handle, 0x00, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (who_am_i != 0xEE) {
        fprintf(stderr, "Sensor not found at address 0x%02X\n", VL53L0X_I2C_ADDRESS);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetPullUpDnControl(GPIO_TRIGGER, PI_PUD_UP);

    FILE *log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioWaitForEdge(GPIO_TRIGGER, PI_FALLING_EDGE, 1000) > 0) {
            if (i2cWriteByteData(i2c_handle, SYSRANGE_START, 0x01) < 0) {
                fprintf(stderr, "Failed to start ranging\n");
                continue;
            }

            struct timespec start, now;
            clock_gettime(CLOCK_MONOTONIC, &start);

            while (1) {
                uint8_t status;
                if (i2cReadByteData(i2c_handle, RESULT_INTERRUPT_STATUS, &status) < 0) {
                    fprintf(stderr, "Failed to read RESULT_INTERRUPT_STATUS\n");
                    break;
                }

                if (status & 0x01) {
                    uint8_t result[14];
                    if (i2cReadI2CBlockData(i2c_handle, RESULT_RANGE_STATUS, result, 14) < 0) {
                        fprintf(stderr, "Failed to read result block\n");
                        break;
                    }

                    uint16_t distance_mm = (result[10] << 8) | result[11];
                    log_distance(log_file, distance_mm);

                    if (i2cWriteByteData(i2c_handle, SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
                        fprintf(stderr, "Failed to clear interrupt\n");
                    }

                    break;
                }

                clock_gettime(CLOCK_MONOTONIC, &now);
                if (timespec_diff_ms(&now, &start) > TIMEOUT_MS) {
                    fprintf(stderr, "Ranging timed out\n");
                    break;
                }

                usleep(10000); // 10 ms
            }
        }
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

int timespec_diff_ms(struct timespec *a, struct timespec *b) {
    int diff_sec = a->tv_sec - b->tv_sec;
    int diff_nsec = a->tv_nsec - b->tv_nsec;
    return (diff_sec * 1000) + (diff_nsec / 1000000);
}

