#define I2C_BUS 1
#define SENSOR_ADDR 0x6A
#define LED_PIN 17
#define DISTANCE_THRESHOLD 200  // 20 cm in mm

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_distance(int distance) {
    FILE *log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s, %d mm\n", timestamp, distance);
    fclose(log_file);
}

int read_distance(int i2c_handle) {
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, data, 2) < 0) {
        perror("Failed to read distance");
        return -1;
    }

    // Combine the two bytes to form the distance in mm
    int distance = (data[0] << 8) | data[1];
    return distance;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
