        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            log_distance(distance);
            gpioWrite(LED_PIN, distance < DISTANCE_THRESHOLD ? PI_ON : PI_OFF);
        }

        time_sleep(0.1);  // Sleep for 100 ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

