#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x60
#define PROXIMITY_REG 0x18
#define AMBIENT_REG 0x16
#define MAX_RETRIES 3
#define LOG_FILE "biometric_log.txt"

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int read_i2c_register(int handle, uint8_t reg, uint16_t *value) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = i2cReadWordData(handle, reg, value);
        if (result >= 0) {
            return 0;
        }
        retries++;
        usleep(100000); // 100 ms delay before retry
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        uint16_t proximity, ambient;
        if (read_i2c_register(i2c_handle, PROXIMITY_REG, &proximity) == 0 &&
            read_i2c_register(i2c_handle, AMBIENT_REG, &ambient) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s - Proximity: %u, Ambient: %u\n", timestamp, proximity, ambient);
            fflush(log_file);
        } else {
            fprintf(stderr, "Failed to read from sensor\n");
        }
        usleep(500000); // 500 ms delay
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

