#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x50
#define COMMAND_FRAME {0x50, 0x0A, 0x00, 0x01}
#define RESPONSE_FRAME_SIZE 15
#define SAMPLES_PER_CYCLE 10
#define DELAY_BETWEEN_CYCLES 100000 // 100 ms in microseconds
#define THRESHOLD_DISTANCE 1000 // 1000 mm

int i2c_fd = -1;
FILE *log_file = NULL;

void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    close_resources();
    exit(signum);
}

int main() {
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close_resources();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close_resources();
        return EXIT_FAILURE;
    }

    unsigned char command_frame[] = COMMAND_FRAME;
    unsigned char response_frame[RESPONSE_FRAME_SIZE];
    int total_distance = 0;
    int valid_samples = 0;

    while (1) {
        total_distance = 0;
        valid_samples = 0;

        for (int i = 0; i < SAMPLES_PER_CYCLE; i++) {
            // Write command frame
            if (write(i2c_fd, command_frame, sizeof(command_frame)) != sizeof(command_frame)) {
                perror("Failed to write to I2C device");
                continue;
            }

            // Wait at least 10 ms
            usleep(10000);

            // Read response frame
            if (read(i2c_fd, response_frame, RESPONSE_FRAME_SIZE) != RESPONSE_FRAME_SIZE) {
                perror("Failed to read from I2C device");
                continue;
            }

            // Validate header
            if (response_frame[0] != SENSOR_ADDRESS) {
                fprintf(stderr, "Invalid response header\n");
                continue;
            }

            // Extract distance
            uint16_t distance = (response_frame[11] << 8) | response_frame[12];
            total_distance += distance;
            valid_samples++;
        }

        if (valid_samples > 0) {
            int average_distance = total_distance / valid_samples;
            if (average_distance < THRESHOLD_DISTANCE) {
                // Log intrusion event
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
                fprintf(log_file, "%s: Intrusion detected, average distance: %d mm\n", timestamp, average_distance);
                fflush(log_file);
            }
        }

        // Wait for the next cycle
        usleep(DELAY_BETWEEN_CYCLES);
    }

    close_resources();
    return EXIT_SUCCESS;
}

