#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define MODEL_ID_REG 0xC0
#define MODEL_ID_VALUE 0xEE
#define SYSRANGE_START_REG 0x00
#define RESULT_INTERRUPT_STATUS_REG 0x13
#define RESULT_RANGE_STATUS_REG 0x14
#define SYSTEM_INTERRUPT_CLEAR_REG 0x0B
#define TIMEOUT_US 100000
#define LOOP_INTERVAL_US 500000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t model_id;
    if (i2cReadByteData(handle, MODEL_ID_REG, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID: %s\n", strerror(errno));
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (model_id != MODEL_ID_VALUE) {
        fprintf(stderr, "Invalid model ID: 0x%02X\n", model_id);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (i2cWriteByteData(handle, SYSRANGE_START_REG, 0x01) < 0) {
            fprintf(stderr, "Failed to start ranging: %s\n", strerror(errno));
            continue;
        }

        struct timespec start, now;
        clock_gettime(CLOCK_MONOTONIC, &start);

        uint8_t interrupt_status;
        while (1) {
            if (i2cReadByteData(handle, RESULT_INTERRUPT_STATUS_REG, &interrupt_status) < 0) {
                fprintf(stderr, "Failed to read interrupt status: %s\n", strerror(errno));
                break;
            }

            if (interrupt_status & 0x01) {
                break;
            }

            clock_gettime(CLOCK_MONOTONIC, &now);
            if (timespec_diff_us(&now, &start) > TIMEOUT_US) {
                fprintf(stderr, "Ranging timed out\n");
                break;
            }

            usleep(1000);
        }

        if (interrupt_status & 0x01) {
            uint16_t distance;
            uint8_t distance_bytes[2];
            if (i2cReadI2CBlockData(handle, RESULT_RANGE_STATUS_REG, distance_bytes, 2) < 0) {
                fprintf(stderr, "Failed to read distance: %s\n", strerror(errno));
            } else {
                distance = (distance_bytes[1] << 8) | distance_bytes[0];
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                printf("%04d-%02d-%02d %02d:%02d:%02d Distance: %u mm\n",
                       tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                       tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                       distance);
            }

            if (i2cWriteByteData(handle, SYSTEM_INTERRUPT_CLEAR_REG, 0x01) < 0) {
                fprintf(stderr, "Failed to clear interrupt: %s\n", strerror(errno));
            }
        }

        usleep(LOOP_INTERVAL_US);
    }

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

long timespec_diff_us(struct timespec *a, struct timespec *b) {
    return (a->tv_sec - b->tv_sec) * 1000000 + (a->tv_nsec - b->tv_nsec) / 1000;
}

