#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SI1182_I2C_ADDR 0x39
#define SI1182_CONFIG_REG 0x18
#define SI1182_IRQ_STATUS_REG 0x25
#define SI1182_PROX_RESULT_REG 0x2A

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_handle;
    int ret;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1182_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Initialize sensor by writing 0x01 to CONFIG register
    uint8_t config_data = 0x01;
    ret = i2cWriteByteData(i2c_handle, SI1182_CONFIG_REG, config_data);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        // Check if data is ready by reading bit 0 of IRQ status register
        uint8_t irq_status;
        ret = i2cReadByteData(i2c_handle, SI1182_IRQ_STATUS_REG, &irq_status);
        if (ret < 0) {
            fprintf(stderr, "Failed to read IRQ status register\n");
            continue;
        }

        if (irq_status & 0x01) {
            // Read 16-bit proximity result from registers 0x2A (LSB) and 0x2B (MSB)
            uint16_t proximity_result;
            uint8_t lsb, msb;
            ret = i2cReadByteData(i2c_handle, SI1182_PROX_RESULT_REG, &lsb);
            if (ret < 0) {
                fprintf(stderr, "Failed to read proximity result LSB\n");
                continue;
            }
            ret = i2cReadByteData(i2c_handle, SI1182_PROX_RESULT_REG + 1, &msb);
            if (ret < 0) {
                fprintf(stderr, "Failed to read proximity result MSB\n");
                continue;
            }
            proximity_result = (msb << 8) | lsb;

            // Print the proximity result
            printf("Proximity Result: %d\n", proximity_result);
        }

        // Sleep for 500 ms
        gpioDelay(500000);
    }

    // Close I2C handle and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

