            uint8_t lsb, msb;
            ret = i2cReadByteData(i2c_handle, SI1182_PROX_RESULT_REG, &lsb);
            if (ret < 0) {
                fprintf(stderr, "Failed to read proximity result LSB\n");
                continue;
            }
            ret = i2cReadByteData(i2c_handle, SI1182_PROX_RESULT_REG + 1, &msb);
            if (ret < 0) {
                fprintf(stderr, "Failed to read proximity result MSB\n");
                continue;
            }
            proximity_result = (msb << 8) | lsb;

            // Print the proximity result
            printf("Proximity Result: %d\n", proximity_result);
        }

        // Sleep for 500 ms
        gpioDelay(500000);
    }

    // Close I2C handle and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}
