#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MLX75030_ADDRESS 0x4C
#define DISTANCE_REGISTER 0x00
#define MM_PER_COUNT 0.125

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct timespec sleep_time = {0, 500000000}; // 500 ms

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set the slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Verify the device responds
    uint8_t dummy;
    if (read(i2c_fd, &dummy, 1) < 0) {
        fprintf(stderr, "Device not responding at address 0x%02X\n", MLX75030_ADDRESS);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to install signal handler");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        uint8_t buffer[2];
        if (read(i2c_fd, buffer, 2) == 2) {
            uint16_t distance = (buffer[1] << 8) | buffer[0];
            double distance_mm = distance * MM_PER_COUNT;
            printf("Distance: %.1f mm\n", distance_mm);
        } else {
            perror("Failed to read distance from sensor");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    close(i2c_fd);
    return EXIT_SUCCESS;
}

