#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 200000  // 200 ms
#define MAX_PULSE_US 38000  // 38 ms

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    atexit(gpioTerminate);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    while (running) {
        // Send a 10 microsecond trigger pulse
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, PI_LOW);

        // Wait for the echo rising edge
        int start_tick = gpioTick();
        while (gpioRead(ECHO_PIN) == PI_LOW) {
            if (gpioTick() - start_tick > TIMEOUT_US) {
                fprintf(stderr, "Echo rising-edge timeout\n");
                continue;
            }
        }

        // Measure the echo pulse width
        start_tick = gpioTick();
        while (gpioRead(ECHO_PIN) == PI_HIGH) {
            if (gpioTick() - start_tick > TIMEOUT_US) {
                fprintf(stderr, "Echo falling-edge timeout\n");
                continue;
            }
        }
        int pulse_us = gpioTick() - start_tick;

        // Validate the pulse duration
        if (pulse_us <= 0 || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Invalid pulse duration: %d us\n", pulse_us);
            continue;
        }

        // Calculate distance in cm
        double distance_cm = (pulse_us * 0.0343) / 2.0;

        // Log the reading with a timestamp
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%09ld: Distance = %.2f cm\n", ts.tv_sec, ts.tv_nsec, distance_cm);

        // Wait for 1 second before the next reading
        gpioDelay(1000000);
    }

    return EXIT_SUCCESS;
}

