#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/serial0"
#define LED_PIN 17
#define MAGIC_WORD_SIZE 8
#define RANGE_PROFILE_SIZE 128
#define RANGE_BIN_SIZE 2
#define RANGE_BINS 64
#define RANGE_RESOLUTION 0.0486
#define DISTANCE_THRESHOLD 1.0
#define LOG_FILE "intrusion_log.csv"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_intrusion(double distance) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fclose(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    int uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("Failed to open UART device");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct termios options;
    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, B115200);
    cfsetospeed(&options, B115200);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~CRTSCTS;
    options.c_cflag |= CREAD | CLOCAL;
    options.c_lflag &= ~ICANON;
    options.c_lflag &= ~ECHO;
    options.c_lflag &= ~ECHOE;
    options.c_lflag &= ~ECHONL;
    options.c_lflag &= ~ISIG;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;

    tcsetattr(uart_fd, TCSANOW, &options);

    unsigned char magic_word[MAGIC_WORD_SIZE];
    unsigned char range_profile[RANGE_PROFILE_SIZE];

    while (running) {
        ssize_t bytes_read = read(uart_fd, magic_word, MAGIC_WORD_SIZE);
        if (bytes_read != MAGIC_WORD_SIZE) {
            if (bytes_read == -1) {
                perror("Failed to read magic word");
            } else {
                fprintf(stderr, "Incomplete magic word read\n");
            }
            continue;
        }

        if (memcmp(magic_word, "\x02\x01\x04\x03\x06\x05\x08\x07", MAGIC_WORD_SIZE) != 0) {
            fprintf(stderr, "Invalid magic word\n");
            continue;
        }

        bytes_read = read(uart_fd, range_profile, RANGE_PROFILE_SIZE);
        if (bytes_read != RANGE_PROFILE_SIZE) {
            if (bytes_read == -1) {
                perror("Failed to read range profile");
            } else {
                fprintf(stderr, "Incomplete range profile read\n");
            }
            continue;
        }

        for (int i = 0; i < RANGE_BINS; i++) {
            uint16_t range = (range_profile[i * RANGE_BIN_SIZE + 1] << 8) | range_profile[i * RANGE_BIN_SIZE];
            double distance = range * RANGE_RESOLUTION;
            if (distance <= DISTANCE_THRESHOLD) {
                gpioWrite(LED_PIN, PI_HIGH);
                log_intrusion(distance);
                sleep(2);
                gpioWrite(LED_PIN, PI_LOW);
                break;
            }
        }
    }

    close(uart_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

