#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR_GPIO 17
#define BUZZER_GPIO 18
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_state_transition(const char *state) {
    FILE *log_file = fopen("obstacle_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s - %s\n", timestamp, state);
    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line, *buzzer_line;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(sensor_line, "obstacle_sensor");
    if (ret < 0) {
        perror("Failed to request sensor line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

