#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x69
#define DISTANCE_REG_HIGH 0x31
#define DISTANCE_REG_LOW 0x32
#define GPIO_ALERT_PIN 17
#define DISTANCE_THRESHOLD 1000 // 10.0 cm in mm

volatile sig_atomic_t shutdown_requested = 0;

void signal_handler(int signum) {
    shutdown_requested = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!shutdown_requested) {
        if (shutdown_requested) break;

        uint8_t distance_high, distance_low;
        if (i2cReadByteData(i2c_handle, DISTANCE_REG_HIGH, &distance_high) < 0) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }
        if (shutdown_requested) break;

        if (i2cReadByteData(i2c_handle, DISTANCE_REG_LOW, &distance_low) < 0) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }
        if (shutdown_requested) break;

        uint16_t distance = (distance_high << 8) | distance_low;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        fprintf(log_file, "%s, %u mm\n", timestamp, distance);
        fflush(log_file);

        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(GPIO_ALERT_PIN, PI_HIGH);
        } else {
            gpioWrite(GPIO_ALERT_PIN, PI_LOW);
        }

        usleep(100000); // 100 ms
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

