#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define MODEL_ID_REG 0x010F
#define MODEL_ID_VALUE 0xEA
#define SOFTWARE_RESET_REG 0x0000
#define SYSTEM_MODE_START_REG 0x0007
#define SYSRANGE_START_REG 0x0000
#define RESULT_INTERRUPT_STATUS_REG 0x0013
#define RESULT_RANGE_STATUS_REG 0x0078
#define SYSTEM_INTERRUPT_CLEAR_REG 0x0014

#define TIMEOUT_MS 100
#define LOG_FILE "distance_log.csv"
#define POLL_INTERVAL_MS 100

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void release_resources(int i2c_handle, FILE *log_file) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    int i2c_handle = -1;
    FILE *log_file = NULL;
    struct timespec ts;
    char timestamp[20];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        release_resources(i2c_handle, log_file);
        return EXIT_FAILURE;
    }

    uint16_t model_id;
    if (i2cReadWordData(i2c_handle, MODEL_ID_REG, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID\n");
        release_resources(i2c_handle, log_file);
        return EXIT_FAILURE;
    }

    if (model_id != MODEL_ID_VALUE) {
        fprintf(stderr, "Invalid model ID: 0x%04X\n", model_id);
        release_resources(i2c_handle, log_file);
        return EXIT_FAILURE;
    }

    if (i2cWriteWordData(i2c_handle, SOFTWARE_RESET_REG, 0x00) < 0) {
        fprintf(stderr, "Software reset failed\n");
        release_resources(i2c_handle, log_file);
        return EXIT_FAILURE;
    }
    gpioDelay(2000);

    if (i2cWriteWordData(i2c_handle, SYSTEM_MODE_START_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to start continuous ranging\n");
        release_resources(i2c_handle, log_file);
        return EXIT_FAILURE;
    }

    if (i2cWriteWordData(i2c_handle, SYSRANGE_START_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        release_resources(i2c_handle, log_file);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t sysrange_start;
        if (i2cReadWordData(i2c_handle, SYSRANGE_START_REG, &sysrange_start) < 0) {
            fprintf(stderr, "Failed to read SYSRANGE_START_REG\n");
            release_resources(i2c_handle, log_file);
            return EXIT_FAILURE;
        }

        if (sysrange_start & 0x01) {
            gpioDelay(100000);
            continue;
        }

        uint16_t interrupt_status;
        if (i2cReadWordData(i2c_handle, RESULT_INTERRUPT_STATUS_REG, &interrupt_status) < 0) {
            fprintf(stderr, "Failed to read RESULT_INTERRUPT_STATUS_REG\n");
            release_resources(i2c_handle, log_file);
            return EXIT_FAILURE;
        }

        if (interrupt_status & 0x01) {
            uint16_t distance;
            if (i2cReadWordData(i2c_handle, RESULT_RANGE_STATUS_REG, &distance) < 0) {
                fprintf(stderr, "Failed to read RESULT_RANGE_STATUS_REG\n");
                release_resources(i2c_handle, log_file);
                return EXIT_FAILURE;
            }

            distance = (distance >> 8) | (distance << 8);

            if (!log_file) {
                log_file = fopen(LOG_FILE, "w");
                if (!log_file) {
                    fprintf(stderr, "Failed to open log file\n");
                    release_resources(i2c_handle, log_file);
                    return EXIT_FAILURE;
                }
                fprintf(log_file, "timestamp,distance_mm\n");
            }

            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts));
            fprintf(log_file, "%s,%u\n", timestamp, distance);

            if (distance < 300) {
                printf("STOP\n");
            } else if (distance < 600) {
                printf("APPROACH\n");
            } else if (distance < 1200) {
                printf("SLOW\n");
            } else {
                printf("CLEAR\n");
            }

            if (i2cWriteWordData(i2c_handle, SYSTEM_INTERRUPT_CLEAR_REG, 0x01) < 0) {
                fprintf(stderr, "Failed to clear interrupt\n");
                release_resources(i2c_handle, log_file);
                return EXIT_FAILURE;
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    release_resources(i2c_handle, log_file);
    return EXIT_SUCCESS;
}

