#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x45
#define LED_PIN 18
#define SAMPLE_INTERVAL_US 100000
#define BLINK_MIN_FREQ 1.0
#define BLINK_MAX_FREQ 10.0
#define BLINK_MIN_PERIOD_US 1000000.0 / BLINK_MAX_FREQ
#define BLINK_MAX_PERIOD_US 1000000.0 / BLINK_MIN_FREQ
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_US 10000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for LED\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timespec last_sample_time;
    clock_gettime(CLOCK_MONOTONIC, &last_sample_time);

    double blink_period_us = BLINK_MIN_PERIOD_US;
    int led_state = 0;
    gpioWrite(LED_PIN, led_state);

    while (running) {
        struct timespec current_time;
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        if (timespec_diff_us(&current_time, &last_sample_time) >= SAMPLE_INTERVAL_US) {
            last_sample_time = current_time;

            uint8_t distance_data[2];
            int retries = I2C_RETRIES;
            while (retries > 0) {
                if (i2cReadDevice(i2c_handle, distance_data, 2) == 2) {
                    break;
                }
                retries--;
                usleep(I2C_RETRY_DELAY_US);
            }

            if (retries == 0) {
                fprintf(stderr, "Failed to read distance data from sensor\n");
                continue;
            }

            uint16_t distance = (distance_data[0] << 8) | distance_data[1];
            double blink_freq = BLINK_MIN_FREQ + (BLINK_MAX_FREQ - BLINK_MIN_FREQ) * (distance - 50) / 450.0;
            blink_freq = fmax(BLINK_MIN_FREQ, fmin(BLINK_MAX_FREQ, blink_freq));
            blink_period_us = 1000000.0 / blink_freq;

            printf("Distance: %d mm, Blink Frequency: %.2f Hz\n", distance, blink_freq);
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed_us = timespec_diff_us(&now, &last_sample_time);

        if (elapsed_us >= blink_period_us / 2.0) {
            led_state = !led_state;
            gpioWrite(LED_PIN, led_state);
            last_sample_time = now;
        }

        usleep(1000);
