#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27
#define DEBOUNCE_MS 50
#define POLL_MS 10
#define LOG_FILE "proximity_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_event(FILE *log_file, int sensor_id, const char *event_type) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state1 = gpioRead(SENSOR1_GPIO);
    int last_state2 = gpioRead(SENSOR2_GPIO);
    time_t last_change1 = time(NULL);
    time_t last_change2 = time(NULL);

    while (running) {
        int current_state1 = gpioRead(SENSOR1_GPIO);
        int current_state2 = gpioRead(SENSOR2_GPIO);
        time_t now = time(NULL);

        if (current_state1 != last_state1 && difftime(now, last_change1) >= DEBOUNCE_MS / 1000.0) {
            if (current_state1 == PI_LOW) {
                log_event(log_file, 1, "DETECTED");
            } else {
                log_event(log_file, 1, "CLEARED");
            }
            last_state1 = current_state1;
            last_change1 = now;
        }

        if (current_state2 != last_state2 && difftime(now, last_change2) >= DEBOUNCE_MS / 1000.0) {
            if (current_state2 == PI_LOW) {
                log_event(log_file, 2, "DETECTED");
            } else {
                log_event(log_file, 2, "CLEARED");
            }
            last_state2 = current_state2;
            last_change2 = now;
        }

        gpioDelay(POLL_MS * 1000);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

