#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09
#define TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500

static int i2c_fd = -1;
static FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int i2c_register_read(int reg, uint8_t *value) {
    uint8_t buffer[1] = {reg};
    if (write(i2c_fd, buffer, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_register_write(uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(i2c_fd, buffer, 2) != 2) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

void log_distance(uint16_t distance_mm) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "%s,%u\n", timestamp, distance_mm);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        if (i2c_register_write(MEAS_TRIGGER, 0x01) != 0) {
            continue;
        }

        struct timespec start, current;
        clock_gettime(CLOCK_MONOTONIC, &start);

        uint8_t status;
        do {
            clock_gettime(CLOCK_MONOTONIC, &current);
            if ((current.tv_sec - start.tv_sec) * 1000 + (current.tv_nsec - start.tv_nsec) / 1000000 >= TIMEOUT_MS) {
                fprintf(stderr, "Timeout waiting for measurement\n");
                break;
            }
            if (i2c_register_read(MEAS_STATUS, &status) != 0) {
                break;
            }
        } while ((status & 0x01) == 0);

        if ((status & 0x01) != 0) {
            uint8_t dist_high, dist_low;
            if (i2c_register_read(DIST_HIGH, &dist_high) == 0 && i2c_register_read(DIST_LOW, &dist_low) == 0) {
                uint16_t distance_mm = (dist_high << 8) | dist_low;
                log_distance(distance_mm);
            }
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

