#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define VL53L5CX_I2C_ADDRESS 0x29
#define VL53L5CX_ZONE_COUNT 64
#define VL53L5CX_ZONE_SIZE 3

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct sigaction sa;
    uint8_t buffer[VL53L5CX_ZONE_COUNT * VL53L5CX_ZONE_SIZE];
    uint16_t distances[VL53L5CX_ZONE_COUNT];

    // Set up signal handler for SIGINT
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open the I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(EXIT_FAILURE);
    }

