#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L4CX_I2C_ADDRESS 0x29
#define SOFT_RESET_REG 0x7FFF
#define SYSTEM_START_REG 0x0009
#define INTERRUPT_STATUS_REG 0x0046
#define DISTANCE_HIGH_REG 0x0096
#define DISTANCE_LOW_REG 0x0097

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, VL53L4CX_I2C_ADDRESS, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Soft reset
    if (i2cWriteWordData(handle, SOFT_RESET_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to write soft reset\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(10000); // Wait 10 ms

    // Start ranging
    if (i2cWriteWordData(handle, SYSTEM_START_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        uint16_t status = i2cReadWordData(handle, INTERRUPT_STATUS_REG);
        if (status < 0) {
            fprintf(stderr, "Failed to read interrupt status\n");
            continue;
        }

        if (status & 0x01) { // Check if bit 0 is set
            uint16_t distance_high = i2cReadWordData(handle, DISTANCE_HIGH_REG);
            uint16_t distance_low = i2cReadWordData(handle, DISTANCE_LOW_REG);
            if (distance_high < 0 || distance_low < 0) {
                fprintf(stderr, "Failed to read distance\n");
                continue;
            }

            uint16_t distance = (distance_high << 8) | distance_low;

            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            char timestamp[30];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts));
            printf("Timestamp: %s.%06ld, Distance: %u mm\n", timestamp, ts.tv_nsec / 1000, distance);
        }

        gpioDelay(500000); // Wait 500 ms
    }

    i2cClose(handle);
    gpioTerminate();
    return 0;
}

