#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define VL53L1X_I2C_ADDRESS 0x29
#define SOFT_RESET 0x0001
#define I2C_SLAVE__DEVICE_ADDRESS 0x0001
#define SYSTEM__MODE_START 0x0007
#define RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100
#define MEASUREMENT_INTERVAL 500

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void init_sensor(pi_i2c_t i2c_handle) {
    uint8_t reset = 0x00;
    uint8_t address = 0x29;

    // Soft reset
    if (i2cWriteReg8(i2c_handle, SOFT_RESET, reset) < 0) {
        fprintf(stderr, "Failed to soft reset VL53L1X\n");
        return;
    }
    gpioDelay(10000); // Wait for reset to complete

    // Set I2C address
    if (i2cWriteReg8(i2c_handle, I2C_SLAVE__DEVICE_ADDRESS, address) < 0) {
        fprintf(stderr, "Failed to set I2C address for VL53L1X\n");
        return;
    }

    // Start continuous ranging
    if (i2cWriteReg8(i2c_handle, SYSTEM__MODE_START, 0x01) < 0) {
        fprintf(stderr, "Failed to start continuous ranging for VL53L1X\n");
        return;
    }
}

int main() {
    pi_i2c_t i2c_handle;
    int result;
    uint16_t distance;
    uint8_t distance_bytes[2];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Setup signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize buzzer GPIO
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, PI_LOW);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Initialize sensor
    init_sensor(i2c_handle);

    while (running) {
        // Read distance
        result = i2cReadReg16(i2c_handle, RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, &distance);
        if (result < 0) {
            fprintf(stderr, "Failed to read distance from VL53L1X\n");
            // Re-initialize sensor
            init_sensor(i2c_handle);
            continue;
        }

        // Check distance and control buzzer
        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(BUZZER_GPIO, PI_HIGH);
        } else {
            gpioWrite(BUZZER_GPIO, PI_LOW);
        }

        // Wait for next measurement
        gpioDelay(MEASUREMENT_INTERVAL * 1000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

