This code sets up a Raspberry Pi to interface with a VL53L1X time-of-flight sensor using the pigpio library. It configures the sensor for continuous ranging and checks the distance every 500 ms. If the distance is below 100 mm, it activates a buzzer connected to GPIO 22. The program handles I2C errors by logging them and re-initializing the sensor. It also ensures clean resource release on all exit paths, including handling SIGINT for graceful shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17
#define TIMEOUT_US 50000
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define MIN_PULSE_US 1000
#define MAX_PULSE_US 2000
#define LOG_FILE "sensor_data.log"
#define LOG_INTERVAL_US 200000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, PI_LOW);
    gpioServo(SERVO_PIN, 0);
}

void cleanup_gpio() {
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

double measure_distance() {
    gpioWrite(TRIGGER_PIN, PI_HIGH);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, PI_LOW);

    int start_time = gpioTick();
    while (gpioRead(ECHO_PIN) == PI_LOW) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            return -1.0; // Timeout
        }
    }

    start_time = gpioTick();
    while (gpioRead(ECHO_PIN) == PI_HIGH) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            return -1.0; // Timeout
        }
    }

    int pulse_width = gpioTick() - start_time;
    double distance_cm = (pulse_width * 0.0343) / 2.0;
    return distance_cm;
}

int map_distance_to_angle(double distance_cm) {
    if (distance_cm < MIN_DISTANCE_CM) distance_cm = MIN_DISTANCE_CM;
    if (distance_cm > MAX_DISTANCE_CM) distance_cm = MAX_DISTANCE_CM;

    int pulse_width = MIN_PULSE_US + ((MAX_PULSE_US - MIN_PULSE_US) * (distance_cm - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM));
    return pulse_width;
}

void log_reading(double distance_cm, int angle) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %d\n", timestamp, distance_cm, angle);
    fclose(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();

    while (running) {
        double distance_cm = measure_distance();
        if (distance_cm >= 0) {
            int angle = map_distance_to_angle(distance_cm);
            gpioServo(SERVO_PIN, angle);
