#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <mqueue.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS 1
#define VL53L1X_I2C_ADDRESS 0x29
#define MODEL_ID_REG 0x010F
#define MODEL_ID_VALUE 0xEA
#define SW_RESET_REG 0x0000
#define TIMING_BUDGET_REG 0x0024
#define RANGING_START_REG 0x0080
#define DATA_READY_REG 0x0089
#define DISTANCE_REG 0x0096
#define BUZZER_GPIO 23
#define QUEUE_NAME "/vl53l1x_queue"
#define QUEUE_MODE 0666
#define QUEUE_SIZE 10
#define QUEUE_MSG_SIZE 10

mqd_t mq;
int i2c_handle;
int buzzer_handle;

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (buzzer_handle >= 0) {
        gpioWrite(buzzer_handle, PI_LOW);
        gpioTerminate();
    }
    if (mq >= 0) {
        mq_close(mq);
        mq_unlink(QUEUE_NAME);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    buzzer_handle = gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    if (buzzer_handle < 0) {
        fprintf(stderr, "GPIO setup failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    mq = mq_open(QUEUE_NAME, O_CREAT | O_RDWR, QUEUE_MODE, NULL);
    if (mq == (mqd_t)-1) {
        fprintf(stderr, "Message queue creation failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint16_t model_id;
    if (i2cReadWordData(i2c_handle, MODEL_ID_REG, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (model_id != MODEL_ID_VALUE) {
        fprintf(stderr, "Incorrect model ID: 0x%04X\n", model_id);
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2cWriteWordData(i2c_handle, SW_RESET_REG, 0x00) < 0 ||
        i2cWriteWordData(i2c_handle, SW_RESET_REG, 0x01) < 0) {
        fprintf(stderr, "Software reset failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2cWriteWordData(i2c_handle, TIMING_BUDGET_REG, 50000) < 0) {
        fprintf(stderr, "Timing budget configuration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2cWriteWordData(i2c_handle, RANGING_START_REG, 0x01) < 0) {
        fprintf(stderr, "Ranging start failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t data_ready;
        if (i2cReadByteData(i2c_handle, DATA_READY_REG, &data_ready) < 0) {
            fprintf(stderr, "Failed to read data ready status\n");
            continue;
        }
        if (data_ready & 0x01) {
            uint16_t distance;
            if (i2cReadWordData(i2c_handle, DISTANCE_REG, &distance) < 0) {
                fprintf(stderr, "Failed to read distance\n");
                continue;
            }
            char msg[QUEUE_MSG_SIZE];
            snprintf(msg, QUEUE_MSG_SIZE, "Distance: %d mm", distance);
            if (mq_send(mq, msg, strlen(msg) + 1, 0) < 0) {
                fprintf(stderr, "Message queue send failed: %s\n", strerror(errno));
            }
            if (distance < 100) {
                gpioWrite(BUZZER_GPIO, PI_HIGH);
                usleep(100000); // 100 ms
                gpioWrite(BUZZER_GPIO, PI_LOW);
            }
        }
        usleep(50000); // 50 ms
    }

    cleanup();
    return EXIT_SUCCESS;
}

