code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <paho-mqtt/MQTTClient.h>

#define I2C_BUS 1
#define VL53L1X_I2C_ADDR 0x29
#define SERVO_GPIO 18
#define SERVO_OPEN_PWM 1500
#define SERVO_CLOSE_PWM 500
#define DISTANCE_THRESHOLD 200 // 20 cm in mm
#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_CLIENT_ID "gate_controller"
#define MQTT_TOPIC "gate/control"
#define MQTT_QOS 1

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_event(const char *event) {
    FILE *log_file = fopen("gate_log.txt", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %s\n", ctime(&now), event);
        fclose(log_file);
    }
}

int i2c_init(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", bus, addr);
        return -1;
    }
    return handle;
}

void i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    uint8_t data[2] = {reg, value};
    if (i2cWriteI2CBlockData(handle, reg, data, 2) < 0) {
        fprintf(stderr, "I2C write error\n");
    }
}

uint16_t i2c_read_word(int handle, uint8_t reg) {
    uint8_t data[2];
    if (i2cReadI2CBlockData(handle, reg, data, 2) < 0) {
        fprintf(stderr, "I2C read error\n");
        return 0xFFFF;
    }
    return (data[0] << 8) | data[1];
}

void vl53l1x_init(int handle) {
    i2c_write_byte(handle, 0x0000, 0x00); // Software reset
    sleep(1);
    i2c_write_byte(handle, 0x0000, 0x01); // Boot
    sleep(1);
    i2c_write_byte(handle, 0x0020, 0x01); // Start ranging
}

uint16_t vl53l1x_read_distance(int handle) {
    return i2c_read_word(handle, 0x001E);
}

void servo_set_position(int gpio, int pwm) {
    gpioServo(gpio, pwm);
}

void mqtt_callback(void *context, char *topicName, int topicLen, MQTTClient_message *message) {
    char *payload = (char *)message->payload;
    if (strcmp(payload, "force_open") == 0) {
        servo_set_position(SERVO_GPIO, SERVO_OPEN_PWM);
        log_event("Gate forced open");
    } else if (strcmp(payload, "force_close") == 0) {
        servo_set_position(SERVO_GPIO, SERVO_CLOSE_PWM);
        log_event("Gate forced close");
    } else if (strcmp(payload, "status_request") == 0) {
        // Implement status request handling
    }
    MQTTClient_freeMessage(&message);
    MQTTClient_free(topicName);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = i2c_init(I2C_BUS, VL53L1X_I2C_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    vl53l1x_init(i2c_handle);

    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT connection failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    MQTTClient_setCallback(client, NULL, mqtt_callback);

    if (MQTTClient_subscribe(client, MQTT_TOPIC, MQTT_QOS) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT subscription failed\n");
        MQTTClient_disconnect(client, 1000);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        uint16_t distance = vl53l1x_read_distance(i2c_handle);
        if (distance < DISTANCE_THRESHOLD) {
            servo_set_position(SERVO_GPIO, SERVO_OPEN_PWM);
            log_event("Gate opened due to object detection");
        } else {
            servo_set_position(SERVO_GPIO, SERVO_CLOSE_PWM);
            log_event("Gate closed");
        }
        sleep(1);
    }

    MQTTClient_unsubscribe(client, MQTT_TOPIC);
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

