#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIG_GPIO 23
#define ECHO_GPIO 24
#define LOG_FILE "distance_log.txt"
#define MEASURE_INTERVAL_US 200000
#define TIMEOUT_US 60000
#define MIN_PULSE_WIDTH_US 100
#define MAX_PULSE_WIDTH_US 30000
#define SPEED_OF_SOUND_CM_US 0.0343

volatile uint32_t rising_edge_tick = 0;
volatile uint32_t falling_edge_tick = 0;
volatile int valid_echo_received = 0;
FILE *log_file = NULL;

void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
    printf("[%s] %s\n", timestamp, message);
}

void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_TIMEOUT) {
        log_message("Timeout waiting for echo.");
        return;
    }
    if (level == PI_LOW) {
        rising_edge_tick = tick;
    } else if (level == PI_HIGH) {
        falling_edge_tick = tick;
        valid_echo_received = 1;
    }
}

void handle_signal(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIG_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG_GPIO mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_GPIO mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_GPIO, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set ECHO_GPIO pull-down resistor.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(ECHO_GPIO, echo_callback) < 0) {
        fprintf(stderr, "Failed to set ECHO_GPIO alert function.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        gpioWrite(TRIG_GPIO, PI_LOW);
        gpioDelay(2);
        gpioWrite(TRIG_GPIO, PI_HIGH);
        gpioDelay(10);
        gpioWrite(TRIG_GPIO, PI_LOW);

        valid_echo_received = 0;
        gpioSetWatchdog(ECHO_GPIO, TIMEOUT_US / 1000);

        while (!valid_echo_received) {
            gpioDelay(1000);
        }

        gpioSetWatchdog(ECHO_GPIO, 0);

        uint32_t pulse_width = falling_edge_tick - rising_edge_tick;
        if (pulse_width < MIN_PULSE_WIDTH_US || pulse_width > MAX_PULSE_WIDTH_US) {
            log_message("Invalid pulse width detected.");
            continue;
        }

        double distance_cm = (pulse_width * SPEED_OF_SOUND_CM_US) / 2.0;
        char message[100];
        snprintf(message, sizeof(message), "Distance: %.2f cm", distance_cm);
        log_message(message);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

