#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_SHUTDOWN_PIN 23
#define VL53L1X_INTERRUPT_PIN 24
#define SERVO_PIN 18
#define SERVO_OPEN_US 1000
#define SERVO_CLOSE_US 2000
#define DISTANCE_THRESHOLD_OPEN 50
#define DISTANCE_THRESHOLD_CLOSE 60
#define HYSTERESIS 5

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_state(const char *state, int distance) {
    FILE *log_file = fopen("parking_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s - State: %s, Distance: %d cm\n", time_str, state, distance);
    fclose(log_file);
}

int read_register(int handle, uint8_t reg, uint8_t *data) {
    if (i2cReadByteData(handle, reg) < 0) {
        perror("I2C read failed");
        return -1;
    }
    *data = i2cReadByteData(handle, reg);
    return 0;
}

int write_register(int handle, uint8_t reg, uint8_t data) {
    if (i2cWriteByteData(handle, reg, data) < 0) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int init_vl53l1x(int handle) {
    uint8_t model_id;
    if (read_register(handle, 0x00, &model_id) < 0) {
        return -1;
    }

    if (model_id != 0xEE) {
        fprintf(stderr, "Invalid sensor model ID: 0x%02X\n", model_id);
        return -1;
    }

    if (write_register(handle, 0x00, 0x01) < 0) { // Start measurement
        return -1;
    }

    return 0;
}

int read_distance(int handle) {
    uint8_t distance_high, distance_low;
    if (read_register(handle, 0x1E, &distance_high) < 0 || read_register(handle, 0x1F, &distance_low) < 0) {
        return -1;
    }

    return (distance_high << 8) | distance_low;
}

void set_servo_position(int pin, int us) {
    gpioServo(pin, us);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(VL53L1X_SHUTDOWN_PIN, PI_OUTPUT);
    gpioSetMode(VL53L1X_INTERRUPT_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(VL53L1X_SHUTDOWN_PIN, 1); // Power on the sensor
    sleep(1);

    int i2c_handle = i2cOpen(1, VL53L1X_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    set_servo_position(SERVO_PIN, SERVO_CLOSE_US);
    log_state("Closed", 0);

    int last_distance = -1;
    int last_state = 0; // 0: closed, 1: open

    while (running) {
        int distance = read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }

        int state = 0;
        if (distance <= DISTANCE_THRESHOLD_OPEN) {
            state = 1;
        } else if (distance >= DISTANCE_THRESHOLD_CLOSE + HYSTERESIS) {
            state = 0;
        }

        if (state != last_state) {
            if (state == 1) {
                set_servo_position(SERVO_PIN, SERVO_OPEN_US);
                log_state("Opened", distance);
            } else {
                set_servo_position(SERVO_PIN, SERVO_CLOSE_US);
                log_state("Closed", distance);
            }
            last_state = state;
        }

        last_distance = distance;
        usleep(100000); // 100 ms
    }

    set_servo_position(SERVO_PIN, SERVO_CLOSE_US);
    log_state("Closed", last_distance);

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

