This code sets up a Raspberry Pi 4 Model B to control a smart parking gate using the pigpio library. It uses a VL53L1X time-of-flight sensor to detect objects and a servo motor to open and close the gate. The program logs the gate state changes with timestamps and distances to a file. It handles sensor initialization, I2C communication, and signal handling for clean resource release.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define VL53L1X_I2C_ADDR 0x29
#define GPIO_OPEN 18
#define GPIO_CLOSE 19
#define I2C_BUS 1
#define DISTANCE_THRESHOLD 200 // 20 cm in mm
#define POLL_INTERVAL 500 // 500 ms

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_event(const char *event) {
    FILE *log_file = fopen("gate_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_OPEN, PI_OUTPUT) < 0 || gpioSetMode(GPIO_CLOSE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, VL53L1X_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Soft reset
    uint8_t soft_reset[2] = {0x00, 0x02};
    if (i2cWriteI2CBlockData(i2c_handle, 0x00FE, soft_reset, 2) < 0) {
        fprintf(stderr, "Failed to perform soft reset\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for reset to complete
    gpioDelay(100000);

    // Configure timing budget
    uint8_t timing_budget[2] = {0x00, 0x20}; // 20 ms
