#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/time.h>

#define I2C_BUS 1
#define VL53L1X_I2C_ADDR 0x29
#define GPIO_TRIGGER 24
#define GPIO_FORWARD 17
#define GPIO_BACKWARD 18

#define VL53L1X_SOFT_RESET 0x0000
#define VL53L1X_START_MEASURE 0x0000
#define VL53L1X_STATUS 0x0089
#define VL53L1X_DISTANCE_HIGH 0x0096
#define VL53L1X_DISTANCE_LOW 0x0097

#define DISTANCE_THRESHOLD_MIN 100
#define DISTANCE_THRESHOLD_MAX 300

volatile sig_atomic_t running = 1;

void sig_handler(int signum) {
    running = 0;
}

void stop_motor() {
    gpioWrite(GPIO_FORWARD, PI_LOW);
    gpioWrite(GPIO_BACKWARD, PI_LOW);
}

void handle_distance(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        int i2c_handle = i2cOpen(I2C_BUS, VL53L1X_I2C_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Failed to open I2C bus: %s\n", pigpio_error(i2c_handle));
            return;
        }

        // Soft reset
        if (i2cWriteWordData(i2c_handle, VL53L1X_SOFT_RESET, 0x00) < 0) {
            fprintf(stderr, "Failed to soft reset VL53L1X: %s\n", pigpio_error(i2c_handle));
            i2cClose(i2c_handle);
            return;
        }
        gpioDelay(1000);

        // Start measurement
        if (i2cWriteWordData(i2c_handle, VL53L1X_START_MEASURE, 0x01) < 0) {
            fprintf(stderr, "Failed to start measurement: %s\n", pigpio_error(i2c_handle));
            i2cClose(i2c_handle);
            return;
        }

        // Poll for data ready
        int retries = 0;
        while (1) {
            uint16_t status = i2cReadWordData(i2c_handle, VL53L1X_STATUS);
            if (status < 0) {
                fprintf(stderr, "Failed to read status: %s\n", pigpio_error(status));
                i2cClose(i2c_handle);
                return;
            }
            if (status & 0x01) {
                break;
            }
            if (retries++ > 10) {
                fprintf(stderr, "Timeout waiting for data ready\n");
                i2cClose(i2c_handle);
                return;
            }
            gpioDelay(1000);
        }

        // Read distance
        uint16_t distance = i2cReadWordData(i2c_handle, VL53L1X_DISTANCE_HIGH);
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance: %s\n", pigpio_error(distance));
            i2cClose(i2c_handle);
            return;
        }
        distance = (distance >> 8) | (distance << 8); // Swap bytes

        printf("Distance: %d mm\n", distance);

        // Control motor
        if (distance < DISTANCE_THRESHOLD_MIN) {
            gpioWrite(GPIO_FORWARD, PI_HIGH);
            gpioWrite(GPIO_BACKWARD, PI_LOW);
            printf("Motor: Forward\n");
        } else if (distance > DISTANCE_THRESHOLD_MAX) {
            gpioWrite(GPIO_FORWARD, PI_LOW);
            gpioWrite(GPIO_BACKWARD, PI_HIGH);
            printf("Motor: Backward\n");
        } else {
            stop_motor();
            printf("Motor: Stop\n");
        }

        i2cClose(i2c_handle);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetSignalFunc(SIGINT, sig_handler);
    gpioSetSignalFunc(SIGTERM, sig_handler);

    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetMode(GPIO_FORWARD, PI_OUTPUT);
    gpioSetMode(GPIO_BACKWARD, PI_OUTPUT);

    gpioSetISRFunc(GPIO_TRIGGER, RISING_EDGE, 0, handle_distance);

    while (running) {
        gpioDelay(100000); // Sleep for 100 ms
    }

    stop_motor();
    gpioTerminate();

    return EXIT_SUCCESS;
}

