#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>

#define I2C_DEV "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define ELECONFIG0 0x5E
#define ELECONFIG1 0x5F
#define MHDR 0x2B
#define NHDR 0x2C
#define NCLR 0x2D
#define FDLR 0x2E
#define AUTOCONFIG0 0x5A
#define AUTOCONFIG1 0x5B
#define AUTOCONFIG2 0x5C
#define AUTOCONFIG3 0x5D
#define AUTOCONFIG4 0x5E
#define AUTOCONFIG5 0x5F
#define SOFT_RESET 0x80
#define RESET_VALUE 0x63
#define VALIDATION_REG 0x00
#define VALIDATION_VALUE 0x00
#define TOUCH_STATUS0 0x00
#define TOUCH_STATUS1 0x01

#define GPIO_CHIP "gpiochip0"
#define LED_PINS {17, 18, 27, 22}

struct gpiod_chip *chip;
struct gpiod_line *led_lines[4];
int i2c_fd;
int log_fd;

void cleanup() {
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_release(led_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int i2c_write_byte(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_byte(int reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("I2C write reg failed");
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

void log_event(const char *message) {
    time_t now = time(NULL);
    char *time_str = ctime(&now);
    time_str[strcspn(time_str, "\n")] = '\0';
    dprintf(log_fd, "%s: %s\n", time_str, message);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Soft reset
    if (i2c_write_byte(SOFT_RESET, RESET_VALUE) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    usleep(10000); // Wait for reset

    // Validate sensor presence
    uint8_t validation;
    if (i2c_read_byte(VALIDATION_REG, &validation) < 0 || validation != VALIDATION_VALUE) {
        fprintf(stderr, "Sensor validation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize sensor
    if (i2c_write_byte(ELECONFIG0, 0x00) < 0 || // Stop mode
        i2c_write_byte(MHDR, 0x01) < 0 ||       // Baseline filtering
        i2c_write_byte(NHDR, 0x01) < 0 ||       // Baseline filtering
        i2c_write_byte(NCLR, 0x0E) < 0 ||       // Baseline filtering
        i2c_write_byte(FDLR, 0x00) < 0 ||       // Baseline filtering
        i2c_write_byte(AUTOCONFIG0, 0x0B) < 0 || // Auto-configuration thresholds
        i2c_write_byte(AUTOCONFIG1, 0xC8) < 0 || // Auto-configuration thresholds
        i2c_write_byte(AUTOCONFIG2, 0x82) < 0 || // Auto-configuration thresholds
        i2c_write_byte(AUTOCONFIG3, 0xB4) < 0 || // Auto-configuration thresholds
        i2c_write_byte(AUTOCONFIG4, 0x0B) < 0 || // Auto-configuration thresholds
        i2c_write_byte(AUTOCONFIG5, 0xC8) < 0 || // Auto-configuration thresholds
        i2c_write_byte(ELECONFIG0, 0x0C) < 0) {  // Run mode
        cleanup();
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, LED_PINS[i]);
        if (!led_lines[i]) {
            perror("Failed to get GPIO line");
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(led_lines[i], "led", 0) < 0) {
            perror("Failed to request GPIO line as output");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    // Open log file
    log_fd = open("proximity_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t status0, status1;
        if (i2c_read_byte(TOUCH_STATUS0, &status0) < 0 || i2c_read_byte(TOUCH_STATUS1, &status1) < 0) {
            log_event("I2C read failed, retrying...");
            continue;
        }

        int active_electrode = -1;
        for (int i = 0; i < 12; i++) {
            if ((i < 8 && (status0 & (1 << i))) || (i >= 8 && (status1 & (1 << (i - 8))))) {
                active_electrode = i;
                break;
            }
        }

        if (active_electrode != -1) {
            int pattern = active_electrode % 16;
            for (int i = 0; i < 4; i++) {
                int bit = (pattern >> i) & 1;
                gpiod_line_set_value(led_lines[i], bit);
            }
            char message[64];
            snprintf(message, sizeof(message), "Electrode %d active, pattern 0x%02X", active_electrode, pattern);
            log_event(message);
        } else {
            for (int i = 0; i < 4; i++) {
                gpiod_line_set_value(led_lines[i], 0);
            }
            log_event("No electrode active");
        }

        usleep(50000); // 50 ms polling interval
    }

    cleanup();
    return EXIT_SUCCESS;
}

