    usleep(10000); // Wait for reset

    // Validate sensor presence
    uint8_t validation;
    if (i2c_read_byte(VALIDATION_REG, &validation) < 0 || validation != VALIDATION_VALUE) {
        fprintf(stderr, "Sensor validation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize sensor
    if (i2c_write_byte(ELECONFIG0, 0x00) < 0 || // Stop mode
        i2c_write_byte(MHDR, 0x01) < 0 ||       // Baseline filtering
        i2c_write_byte(NHDR, 0x01) < 0 ||       // Baseline filtering
        i2c_write_byte(NCLR, 0x0E) < 0 ||       // Baseline filtering
        i2c_write_byte(FDLR, 0x00) < 0 ||       // Baseline filtering
        i2c_write_byte(AUTOCONFIG0, 0x0B) < 0 || // Auto-configuration thresholds
        i2c_write_byte(AUTOCONFIG1, 0xC8) < 0 || // Auto-configuration thresholds
        i2c_write_byte(AUTOCONFIG2, 0x82) < 0 || // Auto-configuration thresholds
        i2c_write_byte(AUTOCONFIG3, 0xB4) < 0 || // Auto-configuration thresholds
        i2c_write_byte(AUTOCONFIG4, 0x0B) < 0 || // Auto-configuration thresholds
        i2c_write_byte(AUTOCONFIG5, 0xC8) < 0 || // Auto-configuration thresholds
        i2c_write_byte(ELECONFIG0, 0x0C) < 0) {  // Run mode
        cleanup();
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, LED_PINS[i]);
        if (!led_lines[i]) {
            perror("Failed to get GPIO line");
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(led_lines[i], "led", 0) < 0) {
            perror("Failed to request GPIO line as output");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    // Open log file
    log_fd = open("proximity_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t status0, status1;
        if (i2c_read_byte(TOUCH_STATUS0, &status0) < 0 || i2c_read_byte(TOUCH_STATUS1, &status1) < 0) {
            log_event("I2C read failed, retrying...");
            continue;
        }

        int active_electrode = -1;
        for (int i = 0; i < 12; i++) {
            if ((i < 8 && (status0 & (1 << i))) || (i >= 8 && (status1 & (1 << (i - 8))))) {
                active_electrode = i;
                break;
            }
        }

        if (active_electrode != -1) {
            int pattern = active_electrode % 16;
            for (int i = 0; i < 4; i++) {
                int bit = (pattern >> i) & 1;
                gpiod_line_set_value(led_lines[i], bit);
            }
            char message[64];
            snprintf(message, sizeof(message), "Electrode %d active, pattern 0x%02X", active_electrode, pattern);
            log_event(message);
        } else {
            for (int i = 0; i < 4; i++) {
                gpiod_line_set_value(led_lines[i], 0);
            }
            log_event("No electrode active");
        }

        usleep(50000); // 50 ms polling interval
    }

    cleanup();
    return EXIT_SUCCESS;
}
