        fprintf(stderr, "Failed to write debounce register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(i2c_handle, AFE_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to write AFE config register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(i2c_handle, BASELINE_FILTER_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to write baseline filter register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        char status;
        if (i2cReadByteData(i2c_handle, 0x00, &status) < 0) {
            fprintf(stderr, "Failed to read status register\n");
            continue;
        }

        if (status & (1 << 0)) { // Check if electrode 0 is touched
            gpioWrite(LED_PIN, PI_ON);
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            timestamp[strcspn(timestamp, "\n")] = 0; // Remove newline
            FILE *log_file = fopen("proximity.log", "a");
            if (log_file) {
                fprintf(log_file, "%s: Proximity detected on electrode 0\n", timestamp);
                fclose(log_file);
            }
            sleep(1);
            gpioWrite(LED_PIN, PI_OFF);
        }
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

