#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>
#include <stdbool.h>
#include <atomic.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 30000
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0

volatile sig_atomic_t sigint_received = 0;

void sigint_handler(int sig) {
    sigint_received = 1;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void log_distance(FILE *log_file, double distance) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        log_error("Failed to get current time");
        return;
    }

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts));

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file);
}

double measure_distance(struct gpiod_chip *chip, struct gpiod_line *trigger_line, struct gpiod_line *echo_line) {
    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        log_error("Failed to request trigger line as output");
        return -1.0;
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        log_error("Failed to request echo line as input");
        gpiod_line_release(trigger_line);
        return -1.0;
    }

    // Trigger sequence
    gpiod_line_set_value(trigger_line, 0);
    usleep(5);
    gpiod_line_set_value(trigger_line, 1);
    usleep(10);
    gpiod_line_set_value(trigger_line, 0);

    // Wait for echo rising edge
    struct timespec timeout;
    timeout.tv_sec = 0;
    timeout.tv_nsec = TIMEOUT_US * 1000;

    if (gpiod_line_event_wait(echo_line, &timeout) < 0) {
        log_error("Failed to wait for echo rising edge");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        return -1.0;
    }

    struct gpiod_line_event event;
    if (gpiod_line_event_read(echo_line, &event) < 0) {
        log_error("Failed to read echo event");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        return -1.0;
    }

    if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
        log_error("Unexpected echo event type");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        return -1.0;
    }

    // Measure echo pulse width
    struct timespec start, end;
    if (clock_gettime(CLOCK_MONOTONIC, &start) == -1) {
        log_error("Failed to get start time");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        return -1.0;
    }

    while (gpiod_line_get_value(echo_line) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
            log_error("Failed to get end time");
            gpiod_line_release(echo_line);
            gpiod_line_release(trigger_line);
            return -1.0;
        }

        if (timespec_subtract(&end, &start) > TIMEOUT_US * 1000) {
            log_error("Echo pulse width timeout");
            gpiod_line_release(echo_line);
            gpiod_line_release(trigger_line);
            return -1.0;
        }
    }

    long pulse_us = timespec_subtract(&end, &start) / 1000;

    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);

    double distance = (pulse_us * 0.0343) / 2.0;
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        log_error("Distance out of range");
        return -1.0;
    }

    return distance;
}

int timespec_subtract(const struct timespec *a, const struct timespec *b) {
    struct timespec result;
    if ((a->tv_sec < b->tv_sec) || (a->tv_sec == b->tv_sec && a->tv_nsec < b->tv_nsec)) {
        return 0;
    }

    result.tv_sec = a->tv_sec - b->tv_sec;
    if (a->tv_nsec < b->tv_nsec) {
        result.tv_nsec = a->tv_nsec + 1000000000 - b->tv_nsec;
        result.tv_sec--;
    } else {
        result.tv_nsec = a->tv_nsec - b->tv_nsec;
    }

    return result.tv_sec * 1000000 + result.tv_nsec / 1000;
}

int main() {
    signal(SIGINT, sigint_handler);

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpiod_line *trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        log_error("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        log_error("Failed to get echo line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!sigint_received) {
        double distance = measure_distance(chip, trigger_line, echo_line);
        if (distance >= 0.0) {
            log_distance(log_file, distance);
        }

        sleep(1);
    }

    fclose(log_file);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

