    struct gpiod_line *echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        log_error("Failed to get echo line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!sigint_received) {
        double distance = measure_distance(chip, trigger_line, echo_line);
        if (distance >= 0.0) {
            log_distance(log_file, distance);
        }

        sleep(1);
    }

    fclose(log_file);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
