volatile uint32_t echo_start_tick = 0;
volatile uint32_t echo_end_tick = 0;
volatile int echo_received = 0;
FILE *log_file = NULL;

void sig_handler(int signum) {
    gpioSetISRFuncEx(ECHO_GPIO, 0, 0, NULL, NULL);
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(signum);
}

void echo_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_TIMEOUT) {
        echo_received = 0;
        return;
    }

    if (level == PI_LOW) {
        echo_start_tick = tick;
    } else if (level == PI_HIGH) {
        echo_end_tick = tick;
        echo_received = 1;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    log_file = fopen("distance_log.txt", "a");
