    signal(SIGTERM, sig_handler);

    gpioSetMode(TRIG_GPIO, PI_OUTPUT);
    gpioSetMode(ECHO_GPIO, PI_INPUT);
    gpioSetISRFuncEx(ECHO_GPIO, EITHER_EDGE, 0, echo_callback, NULL);

    while (1) {
        gpioWrite(TRIG_GPIO, PI_LOW);
        gpioDelay(2);
        gpioWrite(TRIG_GPIO, PI_HIGH);
        gpioDelay(TRIGGER_US);
        gpioWrite(TRIG_GPIO, PI_LOW);

        gpioSetWatchdog(ECHO_GPIO, 25000); // 25ms timeout

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        double pulse_us = 0;
        if (echo_received) {
            pulse_us = (echo_end_tick - echo_start_tick) * 1e6 / (double)gpioTick();
            if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
                echo_received = 0;
                continue;
