#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define XSHUT_PIN 27
#define CONTINUOUS_MODE_REG 0x0018
#define TIMEOUT_REG 0x0019
#define START_RANGING_REG 0x0020
#define DISTANCE_REG 0x0014
#define STATUS_REG 0x0016

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialise pigpio");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(XSHUT_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO27 as output");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    gpioWrite(XSHUT_PIN, 1); // Enable the sensor

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    // Configure the sensor
    if (i2cWriteWordData(handle, CONTINUOUS_MODE_REG, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to continuous mode register");
        i2cClose(handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (i2cWriteWordData(handle, TIMEOUT_REG, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to timeout register");
        i2cClose(handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (i2cWriteWordData(handle, START_RANGING_REG, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to write to start ranging register");
        i2cClose(handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint16_t distance;
        uint8_t status;

        if (i2cReadWordData(handle, DISTANCE_REG, &distance) < 0) {
            syslog(LOG_ERR, "Failed to read distance");
            continue;
        }

        if (i2cReadByteData(handle, STATUS_REG, &status) < 0) {
            syslog(LOG_ERR, "Failed to read status");
            continue;
        }

        syslog(LOG_INFO, "Timestamp: %ld, Distance: %d mm, Status: 0x%02X", time(NULL), distance, status);

        usleep(100000); // Wait 100 ms
    }

    i2cClose(handle);
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

