#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define MODEL_ID_REG 0x010F
#define RANGING_MODE_REG 0x0021
#define START_RANGING_REG 0x0015
#define DISTANCE_REG 0x0089
#define GPIO_GATE 24

#define MODEL_ID 0xEA
#define DISTANCE_THRESHOLD 200 // 20 cm in mm

volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen("gate_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Read model ID
    uint8_t model_id;
    if (i2cReadByteData(i2c_handle, MODEL_ID_REG, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (model_id != MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X\n", model_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set ranging mode to short
    if (i2cWriteByteData(i2c_handle, RANGING_MODE_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to set ranging mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, START_RANGING_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up GPIO for gate actuator
    gpioSetMode(GPIO_GATE, PI_OUTPUT);
    gpioWrite(GPIO_GATE, 0); // Start closed

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        uint16_t distance;
        uint8_t high_byte, low_byte;

        if (i2cReadByteData(i2c_handle, DISTANCE_REG, &high_byte) < 0) {
            log_message("Failed to read distance high byte");
            continue;
        }

        if (i2cReadByteData(i2c_handle, DISTANCE_REG + 1, &low_byte) < 0) {
            log_message("Failed to read distance low byte");
            continue;
        }

        distance = (high_byte << 8) | low_byte;

        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Distance: %d mm", distance);
        log_message(log_message);

        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(GPIO_GATE, 1); // Open gate
            log_message("Gate opened");
        } else {
            gpioWrite(GPIO_GATE, 0); // Close gate
            log_message("Gate closed");
        }

        usleep(100000); // 100 ms
    }

    gpioWrite(GPIO_GATE, 0); // Ensure gate is closed on exit
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

