#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define TIMEOUT_US 30000
#define SAMPLE_COUNT 5
#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define MIN_PULSE_WIDTH_US 500
#define MAX_PULSE_WIDTH_US 2500
#define DEFAULT_SERVO_ANGLE 90

volatile sig_atomic_t running = 1;
FILE *log_file;
int sample_index = 0;
double samples[SAMPLE_COUNT];
double current_distance = -1.0;
int pulse_width = 0;
int pulse_start_tick = 0;
int pulse_end_tick = 0;
int pulse_width_ready = 0;

void handle_sigint(int sig) {
    running = 0;
}

void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == PI_HIGH) {
            pulse_start_tick = tick;
        } else if (level == PI_LOW) {
            pulse_end_tick = tick;
            pulse_width = pulse_end_tick - pulse_start_tick;
            if (pulse_width < 0) {
                pulse_width += 1 << 32; // Handle wrap-around
            }
            pulse_width_ready = 1;
        }
    }
}

double calculate_distance(int pulse_width) {
    double distance = (double)pulse_width * SPEED_OF_SOUND_CM_PER_US / 2.0;
    return distance;
}

int map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return DEFAULT_SERVO_ANGLE;
    }
    double normalized_distance = (distance - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    double angle = 90.0 + 45.0 * log10(normalized_distance + 1.0);
    return (int)angle;
}

int map_angle_to_pulse_width(int angle) {
    return (int)(MIN_PULSE_WIDTH_US + (MAX_PULSE_WIDTH_US - MIN_PULSE_WIDTH_US) * (angle / 180.0));
}

void log_data(double distance, int angle) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.1f,%d\n", timestamp, distance, angle);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Failed to register echo pin alert function\n");
        gpioTerminate();
        return 1;
    }

    if (gpioServo(SERVO_PIN, map_angle_to_pulse_width(DEFAULT_SERVO_ANGLE)) < 0) {
        fprintf(stderr, "Failed to set default servo angle\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("distance_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (deg)\n");
    fflush(log_file);

    signal(SIGINT, handle_sigint);

    while (running) {
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, PI_LOW);

        int timeout = 0;
        while (!pulse_width_ready && timeout < TIMEOUT_US) {
            gpioDelay(1);
            timeout++;
        }

        if (pulse_width_ready) {
            double distance = calculate_distance(pulse_width);
            samples[sample_index] = distance;
            sample_index = (sample_index + 1) % SAMPLE_COUNT;

            double sum = 0.0;
            for (int i = 0; i < SAMPLE_COUNT; i++) {
                sum += samples[i];
            }
            current_distance = sum / SAMPLE_COUNT;

            int angle = map_distance_to_angle(current_distance);
            int pulse_width = map_angle_to_pulse_width(angle);

