#define READ_INTERVAL_US 50000

volatile sig_atomic_t running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for LED\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // STMicroelectronics recommended initialization sequence
    uint8_t init_sequence[] = {
        0x00, 0x00, // Software reset
        0x00, 0x01, // Wait for reset to complete
        0x00, 0x00, // Set default configuration
        0x00, 0x01, // Enable signal rate check
        0x00, 0x00, // Configure cross-talk compensation
        0x00, 0x01  // Start ranging
    };

    for (int i = 0; i < sizeof(init_sequence) / 2; i++) {
        if (i2cWriteByteData(i2c_handle, init_sequence[i * 2], init_sequence[i * 2 + 1]) < 0) {
            fprintf(stderr, "Failed to write to I2C device during initialization\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    uint16_t readings[BUFFER_SIZE];
    int buffer_index = 0;
    signal(SIGINT, sigint_handler);

    while (running) {
        uint16_t distance = 0;
        if (i2cReadWordData(i2c_handle, 0x0010) < 0) {
            fprintf(stderr, "Failed to read distance from I2C device\n");
        } else {
            distance = i2cReadWordData(i2c_handle, 0x0010);
            readings[buffer_index] = distance;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            if (distance < 200) {
                gpioWrite(GPIO_LED, PI_HIGH);
            } else {
                gpioWrite(GPIO_LED, PI_LOW);
            }
        }

        usleep(READ_INTERVAL_US);
    }

    gpioWrite(GPIO_LED, PI_LOW);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

