#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define PROXIMITY_REG_HIGH 0x08
#define PROXIMITY_REG_LOW 0x09
#define GPIO_PIN 27

volatile int interrupt_flag = 0;
int i2c_handle = -1;
int log_fd = -1;
int threshold = DEFAULT_THRESHOLD;
unsigned short i2c_address = DEFAULT_I2C_ADDRESS;

void log_event(const char *status, unsigned short proximity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    dprintf(log_fd, "%s, Proximity: %u, Status: %s\n", timestamp, proximity, status);
}

void interrupt_handler(int gpio, int level, uint32_t tick) {
    if (level == PI_RISING) {
        interrupt_flag = 1;
    }
}

void cleanup() {
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
    gpioTerminate();
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (unsigned short)strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a <i2c_address>] [-t <threshold>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpioSetISRFunc(GPIO_PIN, RISING_EDGE, 0, interrupt_handler) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    log_fd = open("proximity.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        if (interrupt_flag) {
            unsigned short proximity_high = i2cReadByteData(i2c_handle, PROXIMITY_REG_HIGH);
            unsigned short proximity_low = i2cReadByteData(i2c_handle, PROXIMITY_REG_LOW);
            unsigned short proximity = (proximity_high << 8) | proximity_low;

            if (proximity < 0) {
                fprintf(stderr, "Failed to read proximity value\n");
            } else {
                const char *status = (proximity <= threshold) ? "SAFE" : "ALERT";
                log_event(status, proximity);
            }

            interrupt_flag = 0;
        }
        usleep(10000); // Sleep for 10ms
    }

    cleanup();
    return 0;
}

