#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18
#define MIN_DISTANCE 2
#define MAX_DISTANCE 200
#define MIN_FREQ 200
#define MAX_FREQ 2000
#define TIMEOUT 200000

volatile sig_atomic_t running = 1;

void cleanup(int sig) {
    running = 0;
    gpioSetPWMfrequency(SPEAKER_PIN, 0);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(SPEAKER_PIN, MIN_FREQ);
    gpioPWM(SPEAKER_PIN, 500000); // 50% duty cycle

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (running) {
        gpioTrigger(TRIGGER_PIN, 10, 1);

        int start_time = gpioTick();
        while (gpioRead(ECHO_PIN) == 0 && gpioTick() - start_time < TIMEOUT);

        if (gpioRead(ECHO_PIN) == 1) {
            start_time = gpioTick();
            while (gpioRead(ECHO_PIN) == 1 && gpioTick() - start_time < TIMEOUT);
        }

        int echo_time = gpioTick() - start_time;
        if (echo_time > 0 && echo_time < TIMEOUT) {
            double distance = (echo_time * 0.0343) / 2;
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                double frequency = MIN_FREQ * exp(distance / 50);
                if (frequency < MIN_FREQ) frequency = MIN_FREQ;
                if (frequency > MAX_FREQ) frequency = MAX_FREQ;
                gpioSetPWMfrequency(SPEAKER_PIN, frequency);
            }
        }

        gpioDelay(10000); // 10 ms delay
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

