#define MAX_DISTANCE 400.0

volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int sig) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN as output\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN as input\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, PI_LOW);

    signal(SIGINT, handle_sigint);

    while (!exit_flag) {
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        gpioDelay(10);  // 10 us trigger pulse
        gpioWrite(TRIGGER_PIN, PI_LOW);

        int echo_start = gpioTick();
        int echo_end = gpioTick();

        while (gpioRead(ECHO_PIN) == PI_LOW && !exit_flag) {
            if (gpioTick() - echo_start > TIMEOUT) {
                printf("Invalid reading\n");
                break;
            }
        }

        if (exit_flag) break;

        echo_start = gpioTick();

        while (gpioRead(ECHO_PIN) == PI_HIGH && !exit_flag) {
            if (gpioTick() - echo_start > TIMEOUT) {
                printf("Invalid reading\n");
                break;
            }
        }

        if (exit_flag) break;

        echo_end = gpioTick();

        if (gpioTick() - echo_start > TIMEOUT) {
            printf("Invalid reading\n");
            continue;
        }

        int pulse_width = echo_end - echo_start;
        double distance = (double)pulse_width / 2 / 29.1;

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < 10.0) {
                printf(" Too close!");
            }
            printf("\n");
        }

        gpioDelay(500000);  // 500 ms
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

