#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define CS_PIN 8

#define REG_CONTINUOUS_MODE 0x01
#define REG_RANGE 0x02
#define REG_TRIGGER 0x00
#define REG_DISTANCE_LOW 0x0C
#define REG_DISTANCE_HIGH 0x0D

#define LOG_FILE "distance_log.csv"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void init_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int init_sensor(int spi_handle) {
    uint8_t tx[3], rx[3];

    // Continuous measurement mode
    tx[0] = REG_CONTINUOUS_MODE;
    tx[1] = 0x01;
    tx[2] = 0x00;
    if (spiXfer(spi_handle, tx, rx, 3) < 0) {
        fprintf(stderr, "Failed to set continuous measurement mode\n");
        return -1;
    }

    // Range 5m
    tx[0] = REG_RANGE;
    tx[1] = 0x00;
    tx[2] = 0x00;
    if (spiXfer(spi_handle, tx, rx, 3) < 0) {
        fprintf(stderr, "Failed to set range\n");
        return -1;
    }

    // Trigger measurement
    tx[0] = REG_TRIGGER;
    tx[1] = 0x01;
    tx[2] = 0x00;
    if (spiXfer(spi_handle, tx, rx, 3) < 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return -1;
    }

    return 0;
}

int read_distance(int spi_handle) {
    uint8_t tx[3], rx[3];

    // Read distance low byte
    tx[0] = REG_DISTANCE_LOW | 0x80; // Read command
    tx[1] = 0x00;
    tx[2] = 0x00;
    if (spiXfer(spi_handle, tx, rx, 3) < 0) {
        fprintf(stderr, "Failed to read distance low byte\n");
        return -1;
    }

    // Read distance high byte
    tx[0] = REG_DISTANCE_HIGH | 0x80; // Read command
    tx[1] = 0x00;
    tx[2] = 0x00;
    if (spiXfer(spi_handle, tx, rx, 3) < 0) {
        fprintf(stderr, "Failed to read distance high byte\n");
        return -1;
    }

    return (rx[2] << 8) | rx[1];
}

int main() {
    int spi_handle;
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (init_sensor(spi_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    init_signal_handlers();

    while (running) {
        int distance = read_distance(spi_handle);
        if (distance >= 200 && distance <= 5000) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log_file, "%s, %d\n", timestamp, distance);
            fflush(log_file);
        } else {
            fprintf(stderr, "Invalid distance reading: %d\n", distance);
        }
        usleep(100000); // 100 ms delay
    }

    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return EXIT_SUCCESS;
}

