#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SI1175_ADDRESS 0x60
#define ALS_VISIBLE_LOW_REG 0x22
#define ALS_VISIBLE_HIGH_REG 0x23
#define LOG_FILE "proximity_log.csv"

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int main() {
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    if (fprintf(log_file, "timestamp,als_visible\n") < 0) {
        perror("Failed to write header to log file");
        cleanup();
        return EXIT_FAILURE;
    }

    setup_signal_handlers();

    while (1) {
        uint8_t buffer[2];
        if (write(i2c_fd, &ALS_VISIBLE_LOW_REG, 1) != 1) {
            perror("Failed to write register address");
            continue;
        }

        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read from I2C");
            continue;
        }

        uint16_t als_visible = (buffer[1] << 8) | buffer[0];

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        if (fprintf(log_file, "%s,%u\n", timestamp, als_visible) < 0) {
            perror("Failed to write to log file");
            break;
        }

        fflush(log_file);
        sleep(5);
    }

    cleanup();
    return EXIT_SUCCESS;
}

