#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SI1182_I2C_ADDRESS 0x39
#define SI1182_PART_ID_REG 0x00
#define SI1182_MEAS_RATE_REG 0x08
#define SI1182_ALS_VIS_DATA_REG 0x22
#define SI1182_PROX_DATA_REG 0x24

#define PART_ID_VALUE 0x45

int i2c_fd = -1;
FILE *log_file = NULL;

void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, exiting...\n", signum);
    close_resources();
    exit(EXIT_SUCCESS);
}

void init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close_resources();
        exit(EXIT_FAILURE);
    }
}

void init_sensor() {
    uint8_t part_id;
    if (write(i2c_fd, &SI1182_PART_ID_REG, 1) != 1) {
        perror("Failed to write to I2C");
        close_resources();
        exit(EXIT_FAILURE);
    }
    if (read(i2c_fd, &part_id, 1) != 1) {
        perror("Failed to read from I2C");
        close_resources();
        exit(EXIT_FAILURE);
    }
    if (part_id != PART_ID_VALUE) {
        fprintf(stderr, "Sensor part ID mismatch, expected 0x%02X, got 0x%02X\n", PART_ID_VALUE, part_id);
        close_resources();
        exit(EXIT_FAILURE);
    }

    uint8_t meas_rate = 0x07;
    if (write(i2c_fd, &SI1182_MEAS_RATE_REG, 1) != 1) {
        perror("Failed to write to I2C");
        close_resources();
        exit(EXIT_FAILURE);
    }
    if (write(i2c_fd, &meas_rate, 1) != 1) {
        perror("Failed to write to I2C");
        close_resources();
        exit(EXIT_FAILURE);
    }
}

uint16_t read_register(uint8_t reg) {
    uint8_t buffer[2];
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to I2C");
        close_resources();
        exit(EXIT_FAILURE);
    }
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read from I2C");
        close_resources();
        exit(EXIT_FAILURE);
    }
    return (buffer[1] << 8) | buffer[0];
}

void log_reading() {
    uint16_t als_vis = read_register(SI1182_ALS_VIS_DATA_REG);
    uint16_t proximity = read_register(SI1182_PROX_DATA_REG);
    double lux = als_vis * 0.1;

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s.%03d,%.1f,%u\n", timestamp, (int)(now % 1000), lux, proximity);
    printf("%s.%03d,%.1f,%u\n", timestamp, (int)(now % 1000), lux, proximity);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    init_i2c();
    init_sensor();

    while (1) {
        log_reading();
        usleep(100000); // 100 ms
    }

    close_resources();
    return 0;
}

