#define MAX_RETRIES 3

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(stderr, "[%s] Error: %s\n", timestamp, message);
}

void log_proximity(unsigned short proximity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        log_error("Failed to open log file");
        return;
    }
    fprintf(log, "[%s] Proximity: %hu\n", timestamp, proximity);
    fclose(log);
}

int initialise_sensor(int handle) {
    struct {
        uint8_t reg;
        uint8_t value;
    } init_sequence[] = {
        {0x07, 0x03}, {0x06, 0x02}, {0x1A, 0x00}, {0x21, 0x0B}, {0x24, 0x00},
        {0x22, 0x49}, {0x0C, 0x03}, {0x0F, 0x0F}, {0x11, 0x03}, {0x0D, 0x07},
        {0x80, 0x03}
    };

    for (size_t i = 0; i < sizeof(init_sequence) / sizeof(init_sequence[0]); i++) {
        if (i2cWriteByteData(handle, init_sequence[i].reg, init_sequence[i].value) < 0) {
            log_error("I2C write failed");
            return -1;
        }
    }

    return 0;
}

