    uint8_t low_byte, high_byte;
    if (i2cReadByteData(handle, 0x16, &low_byte) < 0) {
        log_error("I2C read failed");
        return -1;
    }
    if (i2cReadByteData(handle, 0x17, &high_byte) < 0) {
        log_error("I2C read failed");
        return -1;
    }
    return (high_byte << 8) | low_byte;
}

