    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(1, I2C_ADDR, 0);
    if (handle < 0) {
        log_error("I2C open failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialise_sensor(handle) < 0) {
        log_error("Sensor initialisation failed");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        unsigned short proximity = read_proximity(handle);
        if (proximity != -1) {
            log_proximity(proximity);
        }
        gpioDelay(2000); // 2 ms delay
    }

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

