#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define MAX_DISTANCE 20.0
#define TRIGGER_PULSE_US 10

volatile uint32_t start_time = 0;
volatile uint32_t end_time = 0;
volatile int echo_rising = 0;

void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        start_time = tick;
        echo_rising = 1;
    } else if (level == PI_LOW && echo_rising) {
        end_time = tick;
        echo_rising = 0;
    }
}

void handle_sigint(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set echo pin alert function\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        gpioWrite(TRIGGER_PIN, PI_LOW);
        gpioDelay(2);
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, PI_LOW);

        if (end_time > start_time) {
