#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define MIN_DISTANCE 20
#define MAX_DISTANCE 200
#define MIN_PULSE 500
#define MAX_PULSE 2500
#define NEUTRAL_PULSE 1500

#define TIMEOUT 30000 // 30 ms timeout for echo

volatile sig_atomic_t running = 1;

void cleanup(int sig) {
    running = 0;
}

double measure_distance() {
    gpioWrite(TRIGGER_PIN, PI_LOW);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, PI_HIGH);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, PI_LOW);

    int start_time = gpioTick();
    int end_time = gpioTick();

    while (gpioRead(ECHO_PIN) == PI_LOW) {
        if (gpioTick() - start_time > TIMEOUT) {
            return -1.0; // Timeout
        }
    }

    start_time = gpioTick();

    while (gpioRead(ECHO_PIN) == PI_HIGH) {
        if (gpioTick() - start_time > TIMEOUT) {
            return -1.0; // Timeout
        }
    }

    end_time = gpioTick();

    double duration = (end_time - start_time) / 1e6;
    double distance = duration * 34300 / 2; // Speed of sound in cm/s

    return distance;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioSetSignalFunc(SIGINT, cleanup);

    while (running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            printf("Sensor error, retrying...\n");
            continue;
        }

        printf("Distance: %.2f cm\n", distance);

        int pulse_width;
        if (distance <= MIN_DISTANCE) {
            pulse_width = MAX_PULSE;
        } else if (distance >= MAX_DISTANCE) {
            pulse_width = MIN_PULSE;
        } else {
            pulse_width = MIN_PULSE + (MAX_PULSE - MIN_PULSE) * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
        }

        gpioServo(SERVO_PIN, pulse_width);

        gpioDelay(100000); // 100 ms delay
    }

    gpioServo(SERVO_PIN, 0); // Stop servo
    gpioTerminate();

    return EXIT_SUCCESS;
}

