#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_MODEL_ID_REG 0x010F
#define VL53L1X_MODEL_ID 0xEA
#define VL53L1X_SYSTEM_CONTROL_REG 0x0081
#define VL53L1X_SYSTEM_MODE_START 0x04
#define VL53L1X_MEASURE_PERIOD_REG 0x004E
#define VL53L1X_DISTANCE_REG 0x008F
#define SERVO_GPIO 18
#define SERVO_MIN_US 1000
#define SERVO_MAX_US 2000
#define SERVO_CLOSE_US 1000
#define SERVO_OPEN_US 2000
#define DISTANCE_THRESHOLD_CLOSE 200
#define DISTANCE_THRESHOLD_OPEN 250

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int i2c_read_word(int fd, uint16_t reg) {
    uint8_t buf[2] = {(reg >> 8) & 0xFF, reg & 0xFF};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("I2C read");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

int i2c_write_word(int fd, uint16_t reg, uint16_t value) {
    uint8_t buf[4] = {(reg >> 8) & 0xFF, reg & 0xFF, (value >> 8) & 0xFF, value & 0xFF};
    if (write(fd, buf, 4) != 4) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

void log_event(const char *event) {
    FILE *log_file = fopen("gate_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s - %s\n", ctime(&now), event);
    fclose(log_file);
}

int main() {
    signal(SIGINT, sigint_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    int model_id = i2c_read_word(i2c_fd, VL53L1X_MODEL_ID_REG);
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Invalid VL53L1X model ID: %04X\n", model_id);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (i2c_write_word(i2c_fd, VL53L1X_MEASURE_PERIOD_REG, 0x0014) < 0) {
        fprintf(stderr, "Failed to set timing budget\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (i2c_write_word(i2c_fd, VL53L1X_SYSTEM_CONTROL_REG, VL53L1X_SYSTEM_MODE_START) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetPWMfrequency(SERVO_GPIO, 50);
    gpioSetPWMrange(SERVO_GPIO, 1000);
    gpioSetPWMdutycycle(SERVO_GPIO, SERVO_CLOSE_US / 10);

    int last_state = 0; // 0: closed, 1: open

    while (running) {
        int distance = i2c_read_word(i2c_fd, VL53L1X_DISTANCE_REG);
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }

        int current_state = (distance < DISTANCE_THRESHOLD_CLOSE) ? 1 : 0;

        if (current_state != last_state) {
            if (current_state) {
                gpioSetPWMdutycycle(SERVO_GPIO, SERVO_OPEN_US / 10);
                log_event("Gate opened");
            } else {
                gpioSetPWMdutycycle(SERVO_GPIO, SERVO_CLOSE_US / 10);
                log_event("Gate closed");
            }
            last_state = current_state;
        }

        usleep(100000); // 100 ms
    }

    gpioSetPWMdutycycle(SERVO_GPIO, 0);
    gpioTerminate();
    close(i2c_fd);
    return 0;
}

