#define MAX_DISTANCE_CM 400
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

volatile sig_atomic_t running = 1;

