    running = 0;
}

double measure_distance() {
    gpioWrite(TRIGGER_PIN, PI_LOW);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, PI_HIGH);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, PI_LOW);

    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == PI_LOW) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1.0;
        }
    }

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == PI_HIGH) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1.0;
        }
    }

    uint32_t pulse_duration_us = gpioTick() - start_tick;
    double distance_cm = (pulse_duration_us * 0.0343) / 2.0;
    return distance_cm;
}

