#define MPU6050_ADDR 0x68
#define WHO_AM_I_REG 0x75
#define PWR_MGMT_1_REG 0x6B
#define SAMPLE_RATE_DIV_REG 0x19
#define ACCEL_CONFIG_REG 0x1C
#define GYRO_CONFIG_REG 0x1B
#define DATA_START_REG 0x3B
#define DATA_BLOCK_SIZE 14

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU6050 initialization started...\n");

    // Verify the sensor is present
    char who_am_i;
    if (i2cReadByteData(handle, WHO_AM_I_REG, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "Sensor not found (WHO_AM_I = 0x%02X)\n", who_am_i);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Reset the device
    if (i2cWriteByteData(handle, PWR_MGMT_1_REG, 0x80) < 0) {
        fprintf(stderr, "Failed to reset device\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(100000); // Wait for 100 ms

    // Clear the sleep bit
    if (i2cWriteByteData(handle, PWR_MGMT_1_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to clear sleep bit\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set sample rate divider to 7 for 125 Hz output
    if (i2cWriteByteData(handle, SAMPLE_RATE_DIV_REG, 7) < 0) {
        fprintf(stderr, "Failed to set sample rate divider\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure accelerometer for ±2 g range
    if (i2cWriteByteData(handle, ACCEL_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure accelerometer\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure gyroscope for ±250 deg/s range
    if (i2cWriteByteData(handle, GYRO_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure gyroscope\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU6050 initialization complete.\n");

    while (running) {
        char data[DATA_BLOCK_SIZE];
        if (i2cReadI2CBlockData(handle, DATA_START_REG, data, DATA_BLOCK_SIZE) < 0) {
            fprintf(stderr, "Failed to read data block\n");
            continue;
        }

        int16_t ax = (data[0] << 8) | data[1];
        int16_t ay = (data[2] << 8) | data[3];
        int16_t az = (data[4] << 8) | data[5];
        int16_t temp = (data[6] << 8) | data[7];
        int16_t gx = (data[8] << 8) | data[9];
        int16_t gy = (data[10] << 8) | data[11];
        int16_t gz = (data[12] << 8) | data[13];

        printf("Accel: X=%d, Y=%d, Z=%d\n", ax, ay, az);
        printf("Temp: %d\n", temp);
        printf("Gyro: X=%d, Y=%d, Z=%d\n", gx, gy, gz);

        gpioDelay(100000); // Wait for 100 ms
    }

    printf("Shutting down MPU6050 reader...\n");
    i2cClose(handle);
    gpioTerminate();
    printf("Shutdown complete.\n");

    return EXIT_SUCCESS;
}

