#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define MEASURE_CMD 0xFD
#define READ_DELAY 10000 // 10 ms
#define LOG_INTERVAL 5000000 // 5 seconds

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_temperature_humidity(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f%%\n", temperature, humidity);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        if (i2cWriteByte(i2c_handle, MEASURE_CMD) < 0) {
            fprintf(stderr, "I2C write error: %s\n", strerror(errno));
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus: %s\n", strerror(errno));
                gpioTerminate();
                return EXIT_FAILURE;
            }
            continue;
        }

        gpioDelay(READ_DELAY);

        uint8_t buffer[6];
        if (i2cReadI2CBlockData(i2c_handle, 0, buffer, 6) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus: %s\n", strerror(errno));
                gpioTerminate();
                return EXIT_FAILURE;
            }
            continue;
        }

        if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        uint16_t raw_temp = (buffer[0] << 8) | buffer[1];
        uint16_t raw_hum = (buffer[3] << 8) | buffer[4];

        float temperature = -45 + 175.0 * raw_temp / 65535.0;
        float humidity = -6 + 125.0 * raw_hum / 65535.0;
        humidity = humidity < 0 ? 0 : (humidity > 100 ? 100 : humidity);

        log_temperature_humidity(temperature, humidity);

        gpioDelay(LOG_INTERVAL);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

