#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define I2C_BUFFER_SIZE 2

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    uint8_t buffer[I2C_BUFFER_SIZE];
    struct timespec ts;

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        goto cleanup;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        goto cleanup;
    }

    // Open log file
    log_file = fopen("temperature_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Write header if file is empty
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Ambient Temperature,Object Temperature\n");
    }

    while (running) {
        // Read ambient temperature
        buffer[0] = AMBIENT_TEMP_REG;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to I2C device");
            goto cleanup;
        }
        if (read(i2c_fd, buffer, I2C_BUFFER_SIZE) != I2C_BUFFER_SIZE) {
            perror("Failed to read from I2C device");
            goto cleanup;
        }
        uint16_t ambient_temp = (buffer[0] << 8) | buffer[1];
        float ambient_temp_c = (ambient_temp * 0.02) - 273.15;

        // Read object temperature
        buffer[0] = OBJECT_TEMP_REG;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to I2C device");
            goto cleanup;
        }
        if (read(i2c_fd, buffer, I2C_BUFFER_SIZE) != I2C_BUFFER_SIZE) {
            perror("Failed to read from I2C device");
            goto cleanup;
        }
        uint16_t object_temp = (buffer[0] << 8) | buffer[1];
        float object_temp_c = (object_temp * 0.02) - 273.15;

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            perror("Failed to get current time");
            goto cleanup;
        }

        // Log the temperatures
        fprintf(log_file, "%ld.%09ld,%f,%f\n", ts.tv_sec, ts.tv_nsec, ambient_temp_c, object_temp_c);
        fflush(log_file);

        // Sleep for 5 seconds
        sleep(5);
    }

cleanup:
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
