#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDR 0x25
#define I2C_BUS 1
#define CMD_CONFIG 0x36
#define CMD_CONFIG_VAL 0x08
#define READ_LEN 9
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteWordData(handle, CMD_CONFIG, CMD_CONFIG_VAL) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("pressure_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (°C)\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t buffer[READ_LEN];
        if (i2cReadI2CBlockData(handle, 0x00, buffer, READ_LEN) < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            break;
        }

        if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5] || crc8(buffer + 6, 2) != buffer[8]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        uint16_t pressure_raw = (buffer[0] << 8) | buffer[1];
        uint16_t temperature_raw = (buffer[3] << 8) | buffer[4];
        uint16_t scale_factor = (buffer[6] << 8) | buffer[7];

        double pressure_pa = (pressure_raw * 100.0) / scale_factor;
        double temperature_c = (temperature_raw * 200.0 / scale_factor) - 50.0;

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c);
        fflush(log_file);

        time_sleep(1);
    }

    fclose(log_file);
    i2cClose(handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

