#define CMD_TEMP_NO_HOLD 0xF3
#define CMD_HUMIDITY_NO_HOLD 0xF5
#define SAMPLE_INTERVAL 5

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    signal(SIGINT, sigint_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %s\n", pigpio_error());
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("sensor_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        // Read temperature
        if (i2cWriteByte(i2c_handle, CMD_TEMP_NO_HOLD) < 0) {
            fprintf(stderr, "I2C write failed: %s\n", pigpio_error());
            goto cleanup;
        }

        uint16_t temp_raw = 0;
        for (int i = 0; i < 20; i++) {
            usleep(1000); // Poll every 1 ms
            int count = i2cReadDevice(i2c_handle, (char *)&temp_raw, 2);
            if (count == 2) {
                break;
            }
        }

        if (temp_raw == 0) {
            fprintf(stderr, "Failed to read temperature\n");
            goto cleanup;
        }

        double temperature = (175.72 * temp_raw / 65536.0) - 46.85;

        // Read humidity
        if (i2cWriteByte(i2c_handle, CMD_HUMIDITY_NO_HOLD) < 0) {
            fprintf(stderr, "I2C write failed: %s\n", pigpio_error());
            goto cleanup;
        }

        uint16_t humidity_raw = 0;
        for (int i = 0; i < 20; i++) {
            usleep(1000); // Poll every 1 ms
            int count = i2cReadDevice(i2c_handle, (char *)&humidity_raw, 2);
            if (count == 2) {
                break;
            }
        }

        if (humidity_raw == 0) {
            fprintf(stderr, "Failed to read humidity\n");
            goto cleanup;
        }

        double humidity = (125.0 * humidity_raw / 65536.0) - 6.0;
        humidity = humidity < 0 ? 0 : (humidity > 100 ? 100 : humidity);

        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

        fprintf(log_file, "%s - Temperature: %.2f°C, Humidity: %.2f%%RH\n", timestamp, temperature, humidity);
        printf("%s - Temperature: %.2f°C, Humidity: %.2f%%RH\n", timestamp, temperature, humidity);

        fflush(log_file);
        sleep(SAMPLE_INTERVAL);
    }

cleanup:
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

