#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x25
#define TRIGGER_MEASUREMENT 0x362F
#define READ_LENGTH 9
#define CRC8_POLYNOMIAL 0x31
#define LOG_FILE "airflow_data.txt"

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (°C)\n") < 0) {
        perror("Failed to write header to log file");
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    uint8_t command[2] = {TRIGGER_MEASUREMENT >> 8, TRIGGER_MEASUREMENT & 0xFF};
    uint8_t buffer[READ_LENGTH];

    while (running) {
        if (write(i2c_fd, command, sizeof(command)) != sizeof(command)) {
            perror("Failed to write to I2C device");
            break;
        }

        usleep(45000); // Wait for 45 ms

        if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
            perror("Failed to read from I2C device");
            break;
        }

        if (calculate_crc8(buffer, 3) != buffer[3] ||
            calculate_crc8(buffer + 3, 3) != buffer[6] ||
            calculate_crc8(buffer + 6, 3) != buffer[9]) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        uint32_t pressure_raw = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
        uint32_t temperature_raw = (buffer[3] << 16) | (buffer[4] << 8) | buffer[5];
        uint32_t scale_factor_raw = (buffer[6] << 16) | (buffer[7] << 8) | buffer[8];

        double pressure_pa = (double)pressure_raw / scale_factor_raw;
        double temperature_c = (double)temperature_raw / 200.0 - 45.0;

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c) < 0) {
            perror("Failed to write to log file");
            break;
        }

        fflush(log_file);
        usleep(100000); // Wait for 100 ms
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

