#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_message(const char *filename, const char *message) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        fprintf(stderr, "Failed to open %s for logging\n", filename);
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(file, "[%s] %s\n", timestamp, message);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        log_message("error_log.txt", "I2C open failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        if (i2cWriteWordData(handle, MEASURE_CMD >> 8, MEASURE_CMD & 0xFF) < 0) {
            log_message("error_log.txt", "I2C write failed");
            break;
        }

        gpioDelay(15000); // Wait for conversion

        uint8_t buffer[3];
        if (i2cReadI2CBlockData(handle, 0x00, buffer, 3) < 0) {
            log_message("error_log.txt", "I2C read failed");
            break;
        }

        uint8_t calculated_crc = crc8(buffer, 2);
        if (calculated_crc != buffer[2]) {
            log_message("error_log.txt", "CRC mismatch");
            break;
        }

        uint16_t raw = (buffer[0] << 8) | buffer[1];
        double temperature = -45.0 + 175.0 * (raw / 65535.0);

        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Temperature: %.2f°C", temperature);
        log_message("enclosure_temp_log.txt", log_message);

        gpioDelay(5000000); // Wait for 5 seconds
    }

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

