#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define PRESSURE_SCALE_FACTOR 240.0
#define TEMPERATURE_SCALE_FACTOR 200.0
#define TEMPERATURE_OFFSET -45.0

static int i2c_fd = -1;
static FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

unsigned char calculate_crc8(unsigned char *data, size_t length) {
    unsigned char crc = CRC8_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    unsigned char command[2] = {(CONTINUOUS_MEASUREMENT_CMD >> 8) & 0xFF, CONTINUOUS_MEASUREMENT_CMD & 0xFF};
    if (write(i2c_fd, command, sizeof(command)) != sizeof(command)) {
        perror("Failed to send continuous measurement command");
        cleanup();
        return EXIT_FAILURE;
    }

    usleep(1000); // Wait at least 1 ms

    unsigned char response[6];
    if (read(i2c_fd, response, sizeof(response)) != sizeof(response)) {
        perror("Failed to read sensor response");
        cleanup();
        return EXIT_FAILURE;
    }

    unsigned char pressure_crc = calculate_crc8(response, 2);
    unsigned char temperature_crc = calculate_crc8(response + 4, 2);
    if (pressure_crc != response[2] || temperature_crc != response[5]) {
        fprintf(stderr, "CRC validation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    uint32_t pressure_raw = (response[0] << 16) | (response[1] << 8) | response[2];
    uint32_t temperature_raw = (response[4] << 8) | response[5];

    double pressure_pa = pressure_raw * PRESSURE_SCALE_FACTOR;
    double temperature_c = (temperature_raw * TEMPERATURE_SCALE_FACTOR) + TEMPERATURE_OFFSET;

    log_file = fopen("airflow_data.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c);
    fclose(log_file);
    log_file = NULL;

    cleanup();
    return EXIT_SUCCESS;
}

