#include <pigpio.h>

#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xE3
#define HUMID_CMD 0xE5
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define RETRY_COUNT 3
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0

typedef struct {
    time_t timestamp;
    double temperature;
    double humidity;
} Reading;

Reading buffer[BUFFER_SIZE];
int buffer_index = 0;

void log_reading(double temperature, double humidity) {
    time_t now = time(NULL);
    buffer[buffer_index].timestamp = now;
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    printf("Timestamp: %s", ctime(&now));
    printf("Temperature: %.2f °C\n", temperature);
    printf("Humidity: %.2f %%\n", humidity);
}

double convert_temperature(uint16_t raw) {
    return 175.72 * raw / 65536.0 - 46.85;
}

double convert_humidity(uint16_t raw) {
    return 125.0 * raw / 65536.0 - 6.0;
}

uint16_t read_i2c_word(int handle, uint8_t cmd) {
    uint8_t data[2];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteByte(handle, cmd) == 0) {
            usleep(10000); // Wait at least 10 ms
            if (i2cReadDevice(handle, data, 2) == 2) {
                return (data[0] << 8) | data[1];
            }
        }
        retries--;
        if (retries > 0) {
            usleep(100000); // Wait 100 ms before retrying
        }
    }

    fprintf(stderr, "Failed to read from I2C device\n");
    exit(EXIT_FAILURE);
}

void handle_sigint(int sig) {
    gpioWrite(FAN_GPIO, PI_LOW);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, PI_LOW);

    signal(SIGINT, handle_sigint);

    while (1) {
        uint16_t temp_raw = read_i2c_word(i2c_handle, TEMP_CMD);
        uint16_t humid_raw = read_i2c_word(i2c_handle, HUMID_CMD);

        double temperature = convert_temperature(temp_raw);
        double humidity = convert_humidity(humid_raw);

        log_reading(temperature, humidity);

        if (temperature > TEMP_THRESHOLD_HIGH) {
            gpioWrite(FAN_GPIO, PI_HIGH);
        } else if (temperature < TEMP_THRESHOLD_LOW) {
            gpioWrite(FAN_GPIO, PI_LOW);
        }

        sleep(2);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

