#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/time.h>

#define I2C_ADDR 0x62
#define I2C_BUS 1
#define LED_PIN 17
#define BUFFER_SIZE 20

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} SensorReading;

SensorReading buffer[BUFFER_SIZE];
volatile int buffer_index = 0;
volatile int running = 1;

void sig_handler(int signum) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_reading(const SensorReading *reading) {
    printf("CO2: %u ppm, Temperature: %.2f C, Humidity: %.2f %%\n",
           reading->co2, reading->temperature, reading->humidity);
}

void handle_sensor_data(uint8_t *data) {
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5] || crc8(data + 6, 2) != data[8]) {
        fprintf(stderr, "CRC error in sensor data\n");
        return;
    }

    SensorReading reading;
    reading.co2 = (data[0] << 8) | data[1];
    reading.temperature = ((data[3] << 8) | data[4]) / 200.0;
    reading.humidity = ((data[6] << 8) | data[7]) / 100.0;

    buffer[buffer_index] = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    log_reading(&reading);

    gpioWrite(LED_PIN, reading.co2 > 1000 ? PI_ON : PI_OFF);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        gpioTerminate();
        return 1;
    }

    uint8_t start_cmd[] = {0x21, 0xB1};
    if (i2cWriteDevice(i2c_handle, start_cmd, sizeof(start_cmd)) < 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        uint8_t status_cmd[] = {0xE4, 0xB8};
        if (i2cWriteDevice(i2c_handle, status_cmd, sizeof(status_cmd)) < 0) {
            fprintf(stderr, "Failed to send get_data_ready_status command\n");
            break;
        }

        uint8_t status;
        if (i2cReadDevice(i2c_handle, &status, 1) < 0) {
            fprintf(stderr, "Failed to read data ready status\n");
            break;
        }

        if (status & 0x01) {
            uint8_t read_cmd[] = {0xEC, 0x05};
            if (i2cWriteDevice(i2c_handle, read_cmd, sizeof(read_cmd)) < 0) {
                fprintf(stderr, "Failed to send read_measurement command\n");
                break;
            }

            uint8_t data[9];
            if (i2cReadDevice(i2c_handle, data, sizeof(data)) < 0) {
                fprintf(stderr, "Failed to read measurement data\n");
                break;
            }

            handle_sensor_data(data);
        }

        sleep(5);
    }

    uint8_t stop_cmd[] = {0x3F, 0x86};
    i2cWriteDevice(i2c_handle, stop_cmd, sizeof(stop_cmd));
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

