#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SENSOR_PIN 4
#define SAMPLE_INTERVAL 5000000 // 5 seconds in microseconds
#define TIMEOUT 50000 // 50 ms in microseconds
#define MIN_TEMP -40
#define MAX_TEMP 150
#define CONSECUTIVE_FAILURES_THRESHOLD 3

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_temperature(FILE *log_file, double temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
}

double read_temperature() {
    uint32_t start_tick, end_tick, high_time = 0, total_time = 0;
    int consecutive_failures = 0;

    while (running) {
        start_tick = gpioTick();
        while (gpioRead(SENSOR_PIN) == PI_LOW && gpioTick() - start_tick < TIMEOUT);
        if (gpioRead(SENSOR_PIN) == PI_LOW) {
            consecutive_failures++;
            if (consecutive_failures >= CONSECUTIVE_FAILURES_THRESHOLD) {
                FILE *log_file = fopen("temperature_log.txt", "a");
                if (log_file) {
                    log_temperature(log_file, -999.0); // Error code for sensor malfunction
                    fclose(log_file);
                }
                return -999.0;
            }
            continue;
        }
        high_time = gpioTick() - start_tick;

        start_tick = gpioTick();
        while (gpioRead(SENSOR_PIN) == PI_HIGH && gpioTick() - start_tick < TIMEOUT);
        if (gpioRead(SENSOR_PIN) == PI_HIGH) {
            consecutive_failures++;
            if (consecutive_failures >= CONSECUTIVE_FAILURES_THRESHOLD) {
                FILE *log_file = fopen("temperature_log.txt", "a");
                if (log_file) {
                    log_temperature(log_file, -999.0); // Error code for sensor malfunction
                    fclose(log_file);
                }
                return -999.0;
            }
            continue;
        }
        total_time = gpioTick() - start_tick;

        if (total_time == 0) {
            consecutive_failures++;
            if (consecutive_failures >= CONSECUTIVE_FAILURES_THRESHOLD) {
                FILE *log_file = fopen("temperature_log.txt", "a");
                if (log_file) {
                    log_temperature(log_file, -999.0); // Error code for sensor malfunction
                    fclose(log_file);
                }
                return -999.0;
            }
            continue;
        }

        double temperature = 4215.0 - (2143.0 * high_time / total_time);
        if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
            consecutive_failures++;
            if (consecutive_failures >= CONSECUTIVE_FAILURES_THRESHOLD) {
                FILE *log_file = fopen("temperature_log.txt", "a");
                if (log_file) {
                    log_temperature(log_file, -999.0); // Error code for sensor malfunction
                    fclose(log_file);
                }
                return -999.0;
            }
            continue;
        }

        consecutive_failures = 0;
        return temperature;
    }

    return -999.0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);

    FILE *log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        double temperature = read_temperature();
        if (temperature != -999.0) {
            log_temperature(log_file, temperature);
        }
        gpioDelay(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

