#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

#define I2C_ADDR 0x44
#define I2C_BUS 1
#define MEASURE_CMD 0x2400
#define CRC8_POLYNOMIAL 0x31
#define RETRIES 3
#define LOG_INTERVAL 5
#define SIMULATION_PERIOD 3600

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

double convert_temperature(uint16_t raw_temp) {
    return -45.0 + 175.0 * raw_temp / 65535.0;
}

double convert_humidity(uint16_t raw_hum) {
    return 100.0 * raw_hum / 65535.0;
}

void simulate_offset(double *temp, double *hum, double time_elapsed) {
    double offset_temp = 2.0 * sin(2 * M_PI * time_elapsed / SIMULATION_PERIOD);
    double offset_hum = 5.0 * sin(2 * M_PI * time_elapsed / SIMULATION_PERIOD);
    *temp += offset_temp;
    *hum += offset_hum;
}

void log_data(FILE *log_file, double temp, double hum) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temp, hum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    double start_time = time(NULL);
    while (running) {
        uint8_t command[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
        if (i2cWriteDevice(i2c_handle, command, 2) < 0) {
            fprintf(stderr, "I2C write failed\n");
            goto retry;
        }

        usleep(15000);

        uint8_t result[6];
        if (i2cReadDevice(i2c_handle, result, 6) < 0) {
            fprintf(stderr, "I2C read failed\n");
            goto retry;
        }

        uint16_t raw_temp = (result[0] << 8) | result[1];
        uint16_t raw_hum = (result[3] << 8) | result[4];

        if (crc8(result, 2) != result[2] || crc8(result + 3, 2) != result[5]) {
            fprintf(stderr, "CRC check failed\n");
            goto retry;
        }

        double temp = convert_temperature(raw_temp);
        double hum = convert_humidity(raw_hum);
        double time_elapsed = time(NULL) - start_time;
        simulate_offset(&temp, &hum, time_elapsed);

        log_data(log_file, temp, hum);
        fflush(log_file);

        sleep(LOG_INTERVAL);
        continue;

retry:
        for (int i = 0; i < RETRIES; i++) {
            sleep(1);
            if (running) {
                break;
            }
        }
        if (!running) {
            break;
        }
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

