#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define CONVERSION_TIME_US 45000

typedef struct {
    uint16_t pressure;
    uint16_t temperature;
    uint8_t scale_factor;
} SensorData;

uint8_t crc8(const uint8_t *data, size_t len, uint8_t crc) {
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void handle_sigint(int sig) {
    exit(0);
}

int main() {
    int i2c_fd = -1;
    int csv_fd = -1;
    SensorData data;
    uint8_t buffer[9];
    struct timespec ts;
    char timestamp[20];

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        goto cleanup;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        goto cleanup;
    }

    // Open CSV file
    if ((csv_fd = open("airflow.csv", O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Failed to open CSV file");
        goto cleanup;
    }

    // Write CSV header
    dprintf(csv_fd, "Timestamp,Pressure (Pa),Temperature (°C)\n");

    while (1) {
        // Send continuous measurement command
        uint8_t cmd[2] = {CONTINUOUS_MEASUREMENT_CMD >> 8, CONTINUOUS_MEASUREMENT_CMD & 0xFF};
        if (write(i2c_fd, cmd, 2) != 2) {
            perror("Failed to send measurement command");
            goto cleanup;
        }

        // Wait for conversion
        usleep(CONVERSION_TIME_US);

        // Read data
        if (read(i2c_fd, buffer, 9) != 9) {
            perror("Failed to read data");
            goto cleanup;
        }

        // Validate CRCs
        if (crc8(buffer, 3, CRC8_INIT) != buffer[3] ||
            crc8(buffer + 4, 3, CRC8_INIT) != buffer[7] ||
            crc8(buffer + 8, 1, CRC8_INIT) != buffer[9]) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        // Extract data
        data.pressure = (buffer[0] << 8) | buffer[1];
        data.temperature = (buffer[4] << 8) | buffer[5];
        data.scale_factor = buffer[8];

        // Convert to pressure and temperature
        double pressure_pa = data.pressure * 250.0 / (1 << data.scale_factor);
        double temperature_c = data.temperature * 200.0 / (1 << data.scale_factor) - 50.0;

        // Get timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Write to CSV
        dprintf(csv_fd, "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c);

        // Sleep for 1 second
        sleep(1);
    }

cleanup:
    if (i2c_fd >= 0) close(i2c_fd);
    if (csv_fd >= 0) close(csv_fd);
    return 0;
}

