#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/stat.h>

#define I2C_ADDR 0x44
#define I2C_BUS 1
#define MEASUREMENT_CMD 0x2400
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define SAMPLE_INTERVAL 5

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_to_csv(double temperature, double humidity) {
    static FILE *fp = NULL;
    static int header_written = 0;

    if (!fp) {
        fp = fopen("environment.csv", "a");
        if (!fp) {
            perror("Failed to open CSV file");
            return;
        }
    }

    if (!header_written) {
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
        header_written = 1;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        if (i2cWriteWordData(i2c_handle, MEASUREMENT_CMD >> 8, MEASUREMENT_CMD & 0xFF) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            continue;
        }

        usleep(15000); // Wait at least 15 ms

        uint8_t buffer[6];
        if (i2cReadI2CBlockData(i2c_handle, 0, buffer, 6) < 0) {
            fprintf(stderr, "Failed to read I2C data\n");
            continue;
        }

        if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        uint16_t temp_raw = (buffer[0] << 8) | buffer[1];
        uint16_t humidity_raw = (buffer[3] << 8) | buffer[4];

        double temperature = -45 + 175.0 * temp_raw / 65535.0;
        double humidity = 100.0 * humidity_raw / 65535.0;

        log_to_csv(temperature, humidity);

        sleep(SAMPLE_INTERVAL);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

