#define CONVERSION_TIME_US 1000000
#define CRC8_POLYNOMIAL 0x31
#define FILE_PATH "airflow.dat"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int file_handle = open(FILE_PATH, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (file_handle < 0) {
        fprintf(stderr, "Failed to open file %s\n", FILE_PATH);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (i2cWriteWordData(i2c_handle, CONTINUOUS_MEASUREMENT_CMD >> 8, CONTINUOUS_MEASUREMENT_CMD & 0xFF) < 0) {
            fprintf(stderr, "I2C write failed\n");
            break;
        }

        usleep(CONVERSION_TIME_US);

        uint8_t buffer[9];
        if (i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 9) < 0) {
            fprintf(stderr, "I2C read failed\n");
            break;
        }

        uint8_t pressure_crc = calculate_crc8(buffer, 3);
        uint8_t temperature_crc = calculate_crc8(buffer + 3, 3);

        if (pressure_crc != buffer[2] || temperature_crc != buffer[5]) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        uint32_t raw_pressure = ((uint32_t)buffer[0] << 16) | ((uint32_t)buffer[1] << 8) | buffer[3];
        uint32_t raw_temperature = ((uint32_t)buffer[4] << 8) | buffer[5];
        uint32_t scale_factor = ((uint32_t)buffer[6] << 16) | ((uint32_t)buffer[7] << 8) | buffer[8];

        float pressure = (raw_pressure / scale_factor) - 1000.0;
        float temperature = (raw_temperature / 200.0) - 45.0;

        if (write(file_handle, &pressure, sizeof(pressure)) != sizeof(pressure) ||
            write(file_handle, &temperature, sizeof(temperature)) != sizeof(temperature)) {
            fprintf(stderr, "Failed to write to file\n");
            break;
        }

        sleep(1);
    }

    close(file_handle);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

