#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQ 25000
#define SAMPLE_INTERVAL_US 100000

#define STATUS_BITS_MASK 0xC000
#define RAW_FLOW_SHIFT 2

#define MIN_COUNTS 1638
#define MAX_COUNTS 14745
#define MIN_FLOW 0.0
#define MAX_FLOW 10.0

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

void log_flow(FILE *log_file, double flow) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        log_error("Failed to get current time");
        return;
    }
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    fprintf(log_file, "%s,%f\n", timestamp, flow);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        log_error("Failed to set PWM frequency");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint16_t raw_flow;
        int result = i2cReadWordData(i2c_handle, 0x00, (char *)&raw_flow);
        if (result < 0) {
            log_error("I2C read failed");
            continue;
        }

        raw_flow &= ~STATUS_BITS_MASK;
        raw_flow >>= RAW_FLOW_SHIFT;

        double flow = MIN_FLOW + (MAX_FLOW - MIN_FLOW) * (raw_flow - MIN_COUNTS) / (MAX_COUNTS - MIN_COUNTS);
