#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

#define WHO_AM_I_VALUE 0xB1
#define CTRL_REG1_VALUE 0xB0

volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int sig) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(1, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i;
    if (i2cReadByteData(i2c_handle, WHO_AM_I_REG, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, CTRL_REG1, CTRL_REG1_VALUE) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (!exit_flag) {
        uint8_t press_out_xl, press_out_l, press_out_h;
        uint8_t temp_out_l, temp_out_h;

        if (i2cReadByteData(i2c_handle, PRESS_OUT_XL, &press_out_xl) < 0 ||
            i2cReadByteData(i2c_handle, PRESS_OUT_L, &press_out_l) < 0 ||
            i2cReadByteData(i2c_handle, PRESS_OUT_H, &press_out_h) < 0) {
            fprintf(stderr, "Failed to read pressure data\n");
            continue;
        }

        int32_t pressure = (press_out_h << 16) | (press_out_l << 8) | press_out_xl;
        pressure = (pressure >> 8) & 0xFFFFFF;
        if (pressure & 0x800000) {
            pressure |= 0xFF000000;
        }
        double pressure_hpa = pressure / 4096.0;

        if (i2cReadByteData(i2c_handle, TEMP_OUT_L, &temp_out_l) < 0 ||
            i2cReadByteData(i2c_handle, TEMP_OUT_H, &temp_out_h) < 0) {
            fprintf(stderr, "Failed to read temperature data\n");
            continue;
        }

        int16_t temperature = (temp_out_h << 8) | temp_out_l;
        double temperature_celsius = 42.5 + temperature / 480.0;

        time_t now = time(NULL);
        struct tm tm_info;
        localtime_r(&now, &tm_info);

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

        fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure_hpa, temperature_celsius);
        fflush(log_file);

        gpioDelay(1000000); // 1 second delay
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

