#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define TEMP_REG 0x00
#define LED_PIN 17
#define BUFFER_SIZE 10

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_handle;
    int temp_buffer[BUFFER_SIZE] = {0};
    int buffer_index = 0;
    double running_average = 0.0;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Set up LED pin
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t raw_temp;
        int temp;

        // Read temperature from STLM75
        raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
        if (raw_temp < 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        // Swap bytes and extract temperature
        raw_temp = ((raw_temp >> 8) & 0xFF) | ((raw_temp << 8) & 0xFF00);
        temp = (int16_t)raw_temp >> 7;
        temp = temp / 2;

        // Update circular buffer and running average
        running_average -= temp_buffer[buffer_index];
        temp_buffer[buffer_index] = temp;
        running_average += temp;
        running_average /= BUFFER_SIZE;

        // Update LED based on running average
        if (running_average > 28.0) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }

        // Move to the next buffer position
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpioWrite(LED_PIN, PI_LOW);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

