#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x61
#define MEASUREMENT_INTERVAL 2000 // 2 seconds in milliseconds

#define CMD_CONTINUOUS_MEASUREMENT 0x0010
#define CMD_SET_MEASUREMENT_INTERVAL 0x4600
#define CMD_GET_DATA_READY 0x0202
#define CMD_READ_MEASUREMENT 0x0300

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

#define LOG_FILE "air_quality.log"

volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_data(double co2, double temp, double humidity) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(log, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temp, humidity);
    fflush(log);
    fclose(log);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    uint8_t cmd[2];
    uint8_t data[2];

    // Set measurement interval to 2 seconds
    cmd[0] = CMD_SET_MEASUREMENT_INTERVAL >> 8;
    cmd[1] = CMD_SET_MEASUREMENT_INTERVAL & 0xFF;
    data[0] = MEASUREMENT_INTERVAL >> 8;
    data[1] = MEASUREMENT_INTERVAL & 0xFF;
    uint8_t crc = crc8(data, 2);
    if (i2cWriteDevice(i2c_handle, cmd, 2) < 0 || i2cWriteDevice(i2c_handle, data, 3) < 0) {
        fprintf(stderr, "Failed to set measurement interval\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start continuous measurement with ambient pressure compensation disabled
    cmd[0] = CMD_CONTINUOUS_MEASUREMENT >> 8;
    cmd[1] = CMD_CONTINUOUS_MEASUREMENT & 0xFF;
    data[0] = 0x00;
    data[1] = 0x00;
    crc = crc8(data, 2);
    if (i2cWriteDevice(i2c_handle, cmd, 2) < 0 || i2cWriteDevice(i2c_handle, data, 3) < 0) {
        fprintf(stderr, "Failed to start continuous measurement\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        // Poll data-ready flag
        cmd[0] = CMD_GET_DATA_READY >> 8;
        cmd[1] = CMD_GET_DATA_READY & 0xFF;
        if (i2cWriteDevice(i2c_handle, cmd, 2) < 0) {
            fprintf(stderr, "Failed to poll data-ready flag\n");
            continue;
        }

        uint8_t ready[3];
        if (i2cReadDevice(i2c_handle, ready, 3) < 0) {
            fprintf(stderr, "Failed to read data-ready flag\n");
            continue;
        }

        if (ready[0] != 0x00 || ready[1] != 0x00 || ready[2] != 0x00) {
            // Data is ready, read measurement
            cmd[0] = CMD_READ_MEASUREMENT >> 8;
            cmd[1] = CMD_READ_MEASUREMENT & 0xFF;
            if (i2cWriteDevice(i2c_handle, cmd, 2) < 0) {
                fprintf(stderr, "Failed to start reading measurement\n");
                continue;
            }

            uint8_t measurement[18];
            if (i2cReadDevice(i2c_handle, measurement, 18) < 0) {
                fprintf(stderr, "Failed to read measurement\n");
                continue;
            }

            // Verify CRC for each value
            for (int i = 0; i < 6; i++) {
                uint8_t expected_crc = crc8(measurement + i * 3, 2);
                if (measurement[i * 3 + 2] != expected_crc) {
                    fprintf(stderr, "CRC mismatch for value %d\n", i);
                    continue;
                }
            }

            // Extract values
            uint32_t co2 = (measurement[0] << 24) | (measurement[1] << 16) | (measurement[2] << 8) | measurement[3];
            uint32_t temp = (measurement[6] << 24) | (measurement[7] << 16) | (measurement[8] << 8) | measurement[9];
            uint32_t humidity = (measurement[12] << 24) | (measurement[13] << 16) | (measurement[14] << 8) | measurement[15];

            // Convert to actual values
            co2 /= 100.0;
            temp /= 100.0;
            humidity /= 100.0;

            // Log data
            log_data(co2, temp, humidity);

            // Simulate ventilation system
            if (co2 < 800) {
                printf("Ventilation: OFF\n");
            } else if (co2 < 1200) {
                printf("Ventilation: LOW\n");
            } else {
                printf("Ventilation: HIGH\n");
            }
        }

        usleep(MEASUREMENT_INTERVAL * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

