#define I2C_BUS 1
#define DEFAULT_SAMPLE_INTERVAL 1000

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main(int argc, char *argv[]) {
    int sample_interval = DEFAULT_SAMPLE_INTERVAL;
    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval <= 0) {
            fprintf(stderr, "Invalid sample interval: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, SDP32_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X\n", SDP32_I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteWordData(handle, SDP32_CMD_START_CONTINUOUS_MEASUREMENT >> 8, SDP32_CMD_START_CONTINUOUS_MEASUREMENT & 0xFF) < 0) {
        fprintf(stderr, "Failed to send start continuous measurement command\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
