            fprintf(stderr, "I2C read failed\n");
            break;
        }

        uint16_t pressure_raw = (buffer[0] << 8) | buffer[1];
        uint16_t temperature_raw = (buffer[3] << 8) | buffer[4];
        uint16_t scale_factor_raw = (buffer[6] << 8) | buffer[7];

        if (buffer[2] != crc8(buffer, 2) || buffer[5] != crc8(buffer + 3, 2) || buffer[8] != crc8(buffer + 6, 2)) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        double pressure_pa = (double)pressure_raw / scale_factor_raw;

