#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define HDC1000_ADDRESS 0x40
#define CONFIG_REGISTER 0x02
#define TEMP_REGISTER 0x00
#define HUMIDITY_REGISTER 0x01

#define RESOLUTION_14BIT 0x2000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct sigaction sa;
    unsigned char config_data[2] = {CONFIG_REGISTER, RESOLUTION_14BIT};
    unsigned char read_buffer[4];
    float temperature, humidity;

    // Set up signal handler for SIGINT and SIGTERM
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open the I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Configure the sensor
    if (write(i2c_fd, config_data, 2) != 2) {
        perror("Failed to write to configuration register");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Write the temperature register pointer
        if (write(i2c_fd, &TEMP_REGISTER, 1) != 1) {
            perror("Failed to write to temperature register pointer");
            continue;
        }

        // Wait for the conversion to complete
        usleep(20000);

        // Read 4 bytes (2 bytes temperature + 2 bytes humidity)
        if (read(i2c_fd, read_buffer, 4) != 4) {
            perror("Failed to read from sensor");
            continue;
        }

        // Convert raw values to temperature and humidity
        temperature = ((read_buffer[0] << 8) | read_buffer[1]) / 65536.0 * 165.0 - 40.0;
        humidity = ((read_buffer[2] << 8) | read_buffer[3]) / 65536.0 * 100.0;

        // Print the results
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        // Wait for 5 seconds before the next reading
        sleep(5);
    }

    // Close the I2C device
    close(i2c_fd);

    return 0;
}

