#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SI7051_I2C_ADDR 0x40
#define I2C_BUS 1
#define READ_TIMEOUT_MS 500
#define LOG_INTERVAL_MS 5000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_temperature(int handle) {
    uint8_t command = 0xF3; // Command to start temperature measurement
    uint8_t data[3];

    // Send the measurement command
    if (i2cWriteByte(handle, command) < 0) {
        fprintf(stderr, "Failed to send measurement command\n");
        return -1;
    }

    // Wait for the measurement to complete
    gpioDelay(10000); // 10 ms

    // Read the temperature data
    int bytes_read = i2cReadDevice(handle, data, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Failed to read temperature data: %d bytes read\n", bytes_read);
        return -1;
    }

    // Calculate temperature in Celsius
    uint16_t temp_raw = (data[0] << 8) | data[1];
    float temperature = (175.72 * temp_raw / 65536.0) - 46.85;

    return temperature;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int handle = i2cOpen(I2C_BUS, SI7051_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int temperature = read_temperature(handle);
        if (temperature >= 0) {
            printf("Temperature: %.2f C\n", temperature);
        }
        gpioDelay(LOG_INTERVAL_MS);
    }

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
