#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x63
#define CALIBRATION_CMD 0x50
#define MEASUREMENT_CMD 0x40
#define MEASUREMENT_DELAY 7000 // 7 ms in microseconds
#define READ_DELAY 5000000 // 5 seconds in microseconds

volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

void log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

void log_reading(double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialization failed");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("I2C open failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    uint8_t calibration_data[8];
    if (i2cReadI2CBlockData(i2c_handle, CALIBRATION_CMD, calibration_data, 8) < 0) {
        log_error("Failed to read calibration data");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Extract calibration coefficients (example, actual extraction depends on datasheet)
    int16_t scale_factor_lut = (calibration_data[0] << 8) | calibration_data[1];
    int16_t scale_factor_h = (calibration_data[2] << 8) | calibration_data[3];
    int16_t scale_factor_p = (calibration_data[4] << 8) | calibration_data[5];

    while (running) {
        if (i2cWriteByte(i2c_handle, MEASUREMENT_CMD) < 0) {
            log_error("Failed to trigger measurement");
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY);

        uint8_t measurement_data[6];
        if (i2cReadI2CBlockData(i2c_handle, 0x00, measurement_data, 6) < 0) {
            log_error("Failed to read measurement data");
            continue;
        }

        if (memcmp(measurement_data, "\xFF\xFF\xFF\xFF\xFF\xFF", 6) == 0) {
            log_error("Sensor returned all 0xFF, possible absence");
            continue;
        }

        // Extract raw temperature and pressure (example, actual extraction depends on datasheet)
        int16_t raw_temperature = (measurement_data[0] << 8) | measurement_data[1];
        uint32_t raw_pressure = (measurement_data[2] << 16) | (measurement_data[3] << 8) | measurement_data[4];

        // Apply compensation formulas (example, actual formulas depend on datasheet)
        double temperature = (raw_temperature * scale_factor_lut) / 100.0;
        double pressure = (raw_pressure * scale_factor_p) / 100.0;

        log_reading(temperature, pressure);

        gpioDelay(READ_DELAY);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

