#define I2C_DEVICE "/dev/i2c-1"
#define MLX90819_ADDRESS 0x60
#define PRESSURE_MSB_REG 0xAA
#define PRESSURE_LSB_REG 0xAB
#define SCALING_FACTOR 0.1

int i2c_fd = -1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, exiting...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT)");
        exit(EXIT_FAILURE);
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM)");
        exit(EXIT_FAILURE);
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90819_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        uint8_t reg = PRESSURE_MSB_REG;
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Failed to write to I2C register");
            continue;
        }

        uint8_t buffer[2];
        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read from I2C device");
            continue;
        }

        uint16_t raw_pressure = (buffer[0] << 8) | buffer[1];
        double pressure_kPa = raw_pressure * SCALING_FACTOR;

        time_t now = time(NULL);
        printf("%sPressure: %.2f kPa\n", ctime(&now), pressure_kPa);

        sleep(1);
    }

    cleanup();
    return 0;
}

