#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t cmd[2] = {CONTINUOUS_MEASUREMENT_CMD >> 8, CONTINUOUS_MEASUREMENT_CMD & 0xFF};
    if (write(i2c_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to send continuous measurement command");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    sleep(1); // Wait for the sensor to stabilize

    FILE *log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t buffer[9];
        if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
            perror("Failed to read from I2C device");
            break;
        }

        uint16_t pressure_raw = (buffer[0] << 8) | buffer[1];
        uint16_t temperature_raw = (buffer[3] << 8) | buffer[4];
        uint8_t pressure_crc = buffer[2];
        uint8_t temperature_crc = buffer[5];

        if (crc8(buffer, 2) != pressure_crc || crc8(buffer + 3, 2) != temperature_crc) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        double pressure = pressure_raw / 60.0;
        double temperature = temperature_raw / 200.0;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
        fflush(log_file);

        sleep(1); // Sample every second
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

