#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE 1024 * 1024 // 1 MB

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void log_data(double temperature, double humidity) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(log_file);

    // Check file size and truncate if necessary
    struct stat st;
    if (stat(LOG_FILE, &st) == 0 && st.st_size > LOG_FILE_SIZE) {
        if (truncate(LOG_FILE, 0) != 0) {
            perror("Failed to truncate log file");
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        // Trigger a measurement
        if (i2cWriteByte(i2c_handle, 0x00) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            break;
        }

        // Wait for the measurement to complete
        usleep(MEASUREMENT_DELAY);

        // Read 4 bytes from the sensor
        uint8_t buffer[4];
        if (i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 4) < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            break;
        }

        // Validate status bits
        if ((buffer[0] & 0x80) != 0x80) {
            fprintf(stderr, "Sensor status bits indicate an error\n");
            break;
        }

        // Extract raw values
        uint16_t raw_T = ((buffer[0] & 0x7F) << 8) | buffer[1];
        uint16_t raw_H = (buffer[2] << 8) | buffer[3];

        // Convert raw values to temperature and humidity
        double temperature = raw_T * 165.0 / 16383.0 - 40.0;
        double humidity = raw_H * 100.0 / 16383.0;

        // Log the data
        log_data(temperature, humidity);

        // Wait for 5 seconds before the next measurement
        sleep(5);
    }

    // Clean up resources
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

