This code initializes the pigpio library, opens the I2C bus, and continuously reads temperature and humidity data from the HIH6130 sensor. It logs the data with an ISO-8601 timestamp and handles errors and signals appropriately. The log file is truncated when it exceeds 1 MB.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define TICK_TIME_US 3
#define SYNCHRONIZATION_PULSE_TICKS 56
#define VALID_NIBBLE_MIN_TICKS 12
#define VALID_NIBBLE_MAX_TICKS 271
#define CHECKSUM_MODULO 16

#define SCALE 1.0
#define OFFSET 0.0

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fclose(log_file);
}

int read_nibble(int gpio, int *ticks) {
    int start_tick = gpioTick();
    int pulse_width = 0;

    while (gpioRead(gpio) == PI_LOW) {
        if (gpioTick() - start_tick > VALID_NIBBLE_MAX_TICKS * TICK_TIME_US) {
            return -1; // Bus error: pulse too long
        }
    }

    while (gpioRead(gpio) == PI_HIGH) {
        pulse_width++;
        if (gpioTick() - start_tick > VALID_NIBBLE_MAX_TICKS * TICK_TIME_US) {
            return -1; // Bus error: pulse too long
        }
    }

    if (pulse_width < VALID_NIBBLE_MIN_TICKS || pulse_width > VALID_NIBBLE_MAX_TICKS) {
        return -1; // Bus error: invalid pulse width
    }

    *ticks = pulse_width;
    return (pulse_width - VALID_NIBBLE_MIN_TICKS) / (VALID_NIBBLE_MAX_TICKS - VALID_NIBBLE_MIN_TICKS) * 15;
}

int read_sent_sensor(int gpio) {
    int ticks;
    int nibbles[8];
    int checksum = 0;

    // Synchronization pulse
    if (gpioRead(gpio) == PI_HIGH) {
        return -2; // Sensor absent: no synchronization pulse
    }

    for (int i = 0; i < SYNCHRONIZATION_PULSE_TICKS; i++) {
        if (gpioRead(gpio) == PI_HIGH) {
            return -2; // Sensor absent: no synchronization pulse
        }
        gpioDelay(TICK_TIME_US);
    }

    // Read status nibble
    if (read_nibble(gpio, &ticks) < 0) {
        return -1; // Bus error
    }
    nibbles[0] = ticks;

    // Read data nibbles
    for (int i = 1; i < 4; i++) {
        if (read_nibble(gpio, &ticks) < 0) {
            return -1; // Bus error
        }
        nibbles[i] = ticks;
        checksum += ticks;
    }

    // Read checksum nibble
    if (read_nibble(gpio, &ticks) < 0) {
        return -1; // Bus error
    }
    nibbles[4] = ticks;

    // Validate checksum
    if ((checksum + nibbles[4]) % CHECKSUM_MODULO != 0) {
        return -1; // Bus error: checksum mismatch
    }

    // Combine data nibbles to form 12-bit raw value
    int raw_value = (nibbles[1] << 8) | (nibbles[2] << 4) | nibbles[3];

    // Convert raw value to pressure
    double pressure = raw_value * SCALE + OFFSET;
    log_pressure(pressure);

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDnControl(GPIO_PIN, PI_PUD_UP);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        int result = read_sent_sensor(GPIO_PIN);
        if (result == -2) {
            log_error("Sensor absent");
        } else if (result == -1) {
            log_error("Bus error");
        }
        gpioDelay(1000000); // Wait for 1 second before next read
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

