#include <sys/types.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define DEVICE_ID_REG 0x0F
#define TEMP_REG 0x00
#define DEVICE_ID 0x0117
#define SAMPLE_INTERVAL 60

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_handle;
    int file_handle;
    float temperature;
    uint16_t raw_temp;
    uint8_t buffer[2];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Verify device ID
    if (i2cReadWordData(i2c_handle, DEVICE_ID_REG) != DEVICE_ID) {
        fprintf(stderr, "Device ID mismatch\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open file for writing
    file_handle = open("greenhouse_temps.dat", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file_handle < 0) {
        perror("Failed to open file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        // Read temperature register
        if (i2cReadI2CBlockData(i2c_handle, TEMP_REG, buffer, 2) != 2) {
            fprintf(stderr, "Failed to read temperature register\n");
            continue;
        }

        // Combine bytes and convert to float
        raw_temp = (buffer[0] << 8) | buffer[1];
        temperature = (float)raw_temp * 0.0078125;

        // Write temperature to file as little-endian float
        if (write(file_handle, &temperature, sizeof(float)) != sizeof(float)) {
            perror("Failed to write to file");
        }

        // Sleep for the specified interval
        sleep(SAMPLE_INTERVAL);
    }

    // Clean up resources
    close(file_handle);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

