#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_data(FILE *log_file, double temperature, double humidity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s, Temperature: %.2f°C, Humidity: %.2f%%RH\n", timestamp, temperature, humidity);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        if (i2cWriteByte(i2c_handle, MEASURE_HIGH_PRECISION) < 0) {
            fprintf(stderr, "I2C write failed\n");
            break;
        }

        usleep(8500); // Wait at least 8.5 ms for conversion

        uint8_t buffer[6];
        if (i2cReadI2CBlockData(i2c_handle, 0, buffer, 6) < 0) {
            fprintf(stderr, "I2C read failed\n");
            break;
        }

        uint16_t raw_temp = (buffer[0] << 8) | buffer[1];
        uint16_t raw_hum = (buffer[3] << 8) | buffer[4];

        if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
            fprintf(stderr, "CRC validation failed\n");
            break;
        }

        double temperature = -45 + 175 * (raw_temp / 65535.0);
        double humidity = -6 + 125 * (raw_hum / 65535.0);

        log_data(log_file, temperature, humidity);

        sleep(5);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

