#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL 5

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_handle;
    int pigpio_init_status;
    uint16_t temperature_buffer[BUFFER_SIZE];
    size_t buffer_index = 0;

    // Initialize pigpio library
    pigpio_init_status = gpioInitialise();
    if (pigpio_init_status < 0) {
        fprintf(stderr, "Failed to initialize pigpio library: %d\n", pigpio_init_status);
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t data[2];
        int read_status = i2cReadI2CBlockData(i2c_handle, TEMP_REG, data, 2);
        if (read_status < 0) {
            fprintf(stderr, "Failed to read temperature: %d\n", read_status);
            continue;
        }

        // Convert big-endian data to uint16_t
        uint16_t temperature = (data[0] << 8) | data[1];
        temperature_buffer[buffer_index] = temperature;

        // Persist buffer to file
        FILE *file = fopen("temperature_log.dat", "wb");
        if (file == NULL) {
            fprintf(stderr, "Failed to open file for writing: %s\n", strerror(errno));
            continue;
        }
        size_t written = fwrite(temperature_buffer, sizeof(uint16_t), BUFFER_SIZE, file);
        if (written != BUFFER_SIZE) {
            fprintf(stderr, "Failed to write to file: %s\n", strerror(errno));
        }
        fclose(file);

        // Update buffer index
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Sleep for the sample interval
        sleep(SAMPLE_INTERVAL);
    }

    // Graceful shutdown
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

