#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TMP117_REG_TEMP 0x00
#define TMP117_RESOLUTION 0.0078125
#define MAX_RETRIES 3

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void log_temperature(int handle, FILE *log_file) {
    uint8_t buffer[2];
    int ret;

    ret = i2cReadI2CBlockData(handle, TMP117_REG_TEMP, buffer, 2);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %d\n", ret);
        return;
    }

    int16_t raw_temp = (buffer[0] << 8) | buffer[1];
    double temperature = raw_temp * TMP117_RESOLUTION;

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_sigint);

    int handle = -1;
    FILE *log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    int retries = 0;
    while (running && retries < MAX_RETRIES) {
        handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
        if (handle >= 0) {
            break;
        }
        fprintf(stderr, "Failed to open I2C device, retrying... (%d/%d)\n", retries + 1, MAX_RETRIES);
        retries++;
        sleep(1);
    }

    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device after %d retries\n", MAX_RETRIES);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (running) {
        log_temperature(handle, log_file);
        sleep(1);
    }

    i2cClose(handle);
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

