#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define I2C_READ_LEN 4
#define LOG_FILE "flow_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_handle;
    FILE *log_file;
    uint8_t buffer[I2C_READ_LEN];
    double slpm, celsius;
    int raw_flow, raw_temp;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Discard first two reads
    i2cReadDevice(i2c_handle, buffer, I2C_READ_LEN);
    i2cReadDevice(i2c_handle, buffer, I2C_READ_LEN);

    while (running) {
        // Read data from sensor
        if (i2cReadDevice(i2c_handle, buffer, I2C_READ_LEN) < 0) {
            fprintf(log_file, "Error reading from I2C device\n");
            fflush(log_file);
            // Attempt to reinitialize I2C handle
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(log_file, "Failed to reinitialize I2C handle\n");
                fflush(log_file);
                break;
            }
            continue;
        }

        // Extract raw values
        raw_flow = (buffer[0] << 6) | (buffer[1] >> 2);
        raw_temp = ((buffer[1] & 0x03) << 10) | (buffer[2] << 2) | (buffer[3] >> 6);

        // Convert raw values
        slpm = ((raw_flow / 16384.0) - 0.1) / 0.8 * 25.0;
        celsius = ((raw_temp / 4096.0) - 0.1) / 0.8 * 80.0 - 40.0;

        // Log data
        fprintf(log_file, "%.2f,%.2f\n", slpm, celsius);
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up resources
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

