#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define SAMPLE_INTERVAL 2000000 // 2 seconds in microseconds
#define TIMEOUT 100000 // 100 ms timeout in microseconds

FILE *log_file;
volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "[%s] ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

void log_reading(int humidity, int temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "[%s] Humidity: %d%%, Temperature: %d°C\n", timestamp, humidity, temperature);
    fflush(log_file);
}

int read_dht11() {
    uint8_t data[5] = {0};
    int bit_count = 0;
    int byte_count = 0;
    int bit_value = 0;
    int start_time = 0;
    int end_time = 0;
    int duration = 0;

    // Pull line low for at least 18 ms
    gpioWrite(GPIO_PIN, PI_LOW);
    gpioDelay(18000);
    gpioWrite(GPIO_PIN, PI_HIGH);

    // Wait for sensor response
    start_time = gpioTick();
    while (gpioRead(GPIO_PIN) == PI_HIGH) {
        if (gpioTick() - start_time > TIMEOUT) {
            log_error("Sensor response timeout");
            return -1;
        }
    }

    // Wait for sensor to pull line low
    start_time = gpioTick();
    while (gpioRead(GPIO_PIN) == PI_LOW) {
        if (gpioTick() - start_time > TIMEOUT) {
            log_error("Sensor low pulse timeout");
            return -1;
        }
    }

    // Wait for sensor to pull line high
    start_time = gpioTick();
    while (gpioRead(GPIO_PIN) == PI_HIGH) {
        if (gpioTick() - start_time > TIMEOUT) {
            log_error("Sensor high pulse timeout");
            return -1;
        }
    }

    // Read 40 data bits
    for (bit_count = 0; bit_count < 40; bit_count++) {
        // Wait for the start of a bit (low pulse)
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == PI_LOW) {
            if (gpioTick() - start_time > TIMEOUT) {
                log_error("Bit low pulse timeout");
                return -1;
            }
        }

        // Wait for the end of the bit (high pulse)
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == PI_HIGH) {
            if (gpioTick() - start_time > TIMEOUT) {
                log_error("Bit high pulse timeout");
                return -1;
            }
        }

        // Calculate the duration of the high pulse
        end_time = gpioTick();
        duration = end_time - start_time;

        // Determine the bit value
        if (duration > 30) {
            bit_value = 1;
        } else {
            bit_value = 0;
        }

        // Store the bit in the data array
        data[byte_count] = (data[byte_count] << 1) | bit_value;
        bit_count++;

        if (bit_count % 8 == 0) {
            byte_count++;
        }
    }

    // Validate the checksum
    if (data[0] + data[1] + data[2] + data[3] != data[4]) {
        log_error("Checksum failure");
        return -1;
    }

    // Log the reading
    log_reading(data[0], data[2]);

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, PI_HIGH);

    log_file = fopen("dht11_readings.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        read_dht11();
        gpioDelay(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    gpioTerminate();

    return 0;
}
