#define SHT31D_I2C_ADDR 0x44
#define SHT31D_CMD 0x2C06
#define I2C_BUS 1
#define I2C_RETRIES 3
#define LOG_FILE "sht31d_data.log"

volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_data(const char *timestamp, float temperature, float humidity) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(log);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SHT31D_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        uint8_t cmd[2] = {SHT31D_CMD >> 8, SHT31D_CMD & 0xFF};
        int retries = I2C_RETRIES;
        while (retries > 0) {
            if (i2cWriteDevice(i2c_handle, cmd, 2) == 0) {
                break;
            }
            retries--;
            if (retries == 0) {
                fprintf(stderr, "Failed to write to SHT31D\n");
                break;
            }
        }

        if (retries > 0) {
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

            uint8_t data[6];
            retries = I2C_RETRIES;
            while (retries > 0) {
                if (i2cReadDevice(i2c_handle, data, 6) == 6) {
                    break;
                }
                retries--;
                if (retries == 0) {
                    fprintf(stderr, "Failed to read from SHT31D\n");
                    break;
                }
            }

            if (retries > 0) {
                if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
                    fprintf(stderr, "CRC validation failed\n");
                } else {
                    uint16_t temp_raw = (data[0] << 8) | data[1];
                    uint16_t humidity_raw = (data[3] << 8) | data[4];
                    float temperature = -45.0 + 175.0 * temp_raw / 65535.0;
                    float humidity = 100.0 * humidity_raw / 65535.0;
                    log_data(timestamp, temperature, humidity);
                }
            }
        }

        sleep(5);
    }

    fclose(log);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

