#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x64
#define SENSOR2_ADDR 0x65
#define DEVICE_ID_REG 0x00
#define RED_REG 0x64
#define GREEN_REG 0x66
#define BLUE_REG 0x68
#define DEVICE_ID 0x2A
#define BLOCK_SIZE 2

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_register(int handle, uint8_t reg, uint16_t *value) {
    uint8_t buffer[BLOCK_SIZE];
    if (i2cReadI2CBlockData(handle, reg, buffer, BLOCK_SIZE) < 0) {
        fprintf(stderr, "Failed to read from register 0x%02X\n", reg);
        return -1;
    }
    *value = (buffer[1] << 8) | buffer[0];
    return 0;
}

int write_register(int handle, uint8_t reg, uint16_t value) {
    uint8_t buffer[BLOCK_SIZE] = {value & 0xFF, (value >> 8) & 0xFF};
    if (i2cWriteI2CBlockData(handle, reg, buffer, BLOCK_SIZE) < 0) {
        fprintf(stderr, "Failed to write to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

double calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    double X = -0.14282 * red + 1.54924 * green - 1.41500 * blue;
    double Y = -0.32466 * red + 1.57837 * green - 1.25198 * blue;
    double Z = -0.68202 * red + 0.77073 * green + 0.56331 * blue;

    double x = X / (X + Y + Z);
    double y = Y / (X + Y + Z);

    double n = (x - 0.3320) / (0.1858 - y);

    double cct;
    if (n <= -0.55) {
        cct = 437 * n + 3604;
    } else if (n <= 0.20) {
        cct = 289.7 * n + 6823.4;
    } else {
        cct = 138.51773 * n + 3755.39811;
    }

    return cct;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int sensor1_handle = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    int sensor2_handle = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);

    if (sensor1_handle < 0 || sensor2_handle < 0) {
        fprintf(stderr, "Failed to open I2C devices\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("cct_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(sensor1_handle);
        i2cClose(sensor2_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint16_t device_id1, device_id2;
        if (read_register(sensor1_handle, DEVICE_ID_REG, &device_id1) < 0 ||
            read_register(sensor2_handle, DEVICE_ID_REG, &device_id2) < 0) {
            goto skip_log;
        }

        if (device_id1 != DEVICE_ID || device_id2 != DEVICE_ID) {
            fprintf(stderr, "Invalid device ID\n");
            goto skip_log;
        }

        uint16_t red1, green1, blue1;
        uint16_t red2, green2, blue2;
        if (read_register(sensor1_handle, RED_REG, &red1) < 0 ||
            read_register(sensor1_handle, GREEN_REG, &green1) < 0 ||
            read_register(sensor1_handle, BLUE_REG, &blue1) < 0 ||
            read_register(sensor2_handle, RED_REG, &red2) < 0 ||
            read_register(sensor2_handle, GREEN_REG, &green2) < 0 ||
            read_register(sensor2_handle, BLUE_REG, &blue2) < 0) {
            goto skip_log;
        }

        double cct1 = calculate_cct(red1, green1, blue1);
        double cct2 = calculate_cct(red2, green2, blue2);
        double average_cct = (cct1 + cct2) / 2.0;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f\n", timestamp, average_cct);
        fflush(log_file);

skip_log:
        sleep(1);
    }

    fclose(log_file);
    i2cClose(sensor1_handle);
    i2cClose(sensor2_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

