#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMP_REG 0x0A2E
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define PMIN_KPA 0
#define PMAX_KPA 800

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_error(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    fprintf(stderr, "[%s] Error: %s\n", timestamp, message);
}

void log_data(int pressure_raw, int temp_raw) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

    double pressure_kPa = (pressure_raw - OUTPUT_MIN) * (PMAX_KPA - PMIN_KPA) / (OUTPUT_MAX - OUTPUT_MIN);
    double temp_C = temp_raw * 0.01 - 40;

    FILE *log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        return;
    }

    fprintf(log_file, "[%s] Pressure: %.2f kPa, Temperature: %.2f C\n", timestamp, pressure_kPa, temp_C);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int pressure_raw = i2cReadWordData(i2c_handle, PRESSURE_REG);
        int temp_raw = i2cReadWordData(i2c_handle, TEMP_REG);

        if (pressure_raw < 0 || temp_raw < 0) {
            log_error("Failed to read from I2C device");
        } else {
            log_data(pressure_raw, temp_raw);
        }

        time_t now = time(NULL);
        time_t next_log = now + 2;
        while (running && time(NULL) < next_log) {
            sleep(1);
        }
    }

