    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    fprintf(stderr, "[%s] Error: %s\n", timestamp, message);
}

void log_data(int pressure_raw, int temp_raw) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

    double pressure_kPa = (pressure_raw - OUTPUT_MIN) * (PMAX_KPA - PMIN_KPA) / (OUTPUT_MAX - OUTPUT_MIN);
    double temp_C = temp_raw * 0.01 - 40;

    FILE *log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        return;
    }

    fprintf(log_file, "[%s] Pressure: %.2f kPa, Temperature: %.2f C\n", timestamp, pressure_kPa, temp_C);
    fclose(log_file);
}

