#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define TEMP_REG 0x00
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define HYSTERESIS_LOW 26.0
#define HYSTERESIS_HIGH 28.0

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    int i2c_handle;
    double buffer[BUFFER_SIZE] = {0.0};
    int buffer_index = 0;
    double running_average = 0.0;
    int fan_state = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up fan GPIO
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, fan_state);

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        char data[2];
        int bytes_read;

        // Read temperature register
        bytes_read = i2cReadI2CBlockData(i2c_handle, TEMP_REG, data, 2);
        if (bytes_read != 2) {
            fprintf(stderr, "Failed to read I2C data: %s\n", strerror(errno));
            continue;
        }

        // Convert temperature
        int16_t raw_temp = (data[0] << 8) | (data[1] & 0xFE);
        double temp = raw_temp * 0.5;

        // Update buffer and running average
        running_average -= buffer[buffer_index];
        buffer[buffer_index] = temp;
        running_average += temp;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        running_average /= BUFFER_SIZE;

        // Control fan with hysteresis
        if (running_average > HYSTERESIS_HIGH && !fan_state) {
            gpioWrite(FAN_GPIO, 1);
            fan_state = 1;
        } else if (running_average < HYSTERESIS_LOW && fan_state) {
            gpioWrite(FAN_GPIO, 0);
            fan_state = 0;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpioWrite(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

