#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define PRESSURE_SCALE_FACTOR 60
#define TEMPERATURE_SCALE_FACTOR 200
#define MAX_PRESSURE 5.0

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("airflow.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (i2cWriteWordData(i2c_handle, CMD_CONTINUOUS_MEASUREMENT >> 8, CMD_CONTINUOUS_MEASUREMENT & 0xFF) < 0) {
            fprintf(stderr, "I2C write failed\n");
            break;
        }

        usleep(45000);

        uint8_t buffer[9];
        if (i2cReadI2CBlockData(i2c_handle, 0, buffer, 9) < 0) {
            fprintf(stderr, "I2C read failed\n");
            break;
        }

        if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5] || crc8(buffer + 6, 2) != buffer[8]) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        int16_t pressure_raw = (buffer[0] << 8) | buffer[1];
        int16_t temperature_raw = (buffer[3] << 8) | buffer[4];
        uint16_t status = (buffer[6] << 8) | buffer[7];

        double pressure_pa = pressure_raw * PRESSURE_SCALE_FACTOR;
        double temperature_c = temperature_raw * TEMPERATURE_SCALE_FACTOR / 100.0;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c);
        fflush(log_file);

        if (pressure_pa > MAX_PRESSURE) {
            fprintf(stderr, "Warning: Pressure exceeds %.1f Pa\n", MAX_PRESSURE);
        }

        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

