#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x4A
#define TEMP_REG 0x00
#define LED_GPIO 17
#define HYSTERESIS_LOW 27
#define HYSTERESIS_HIGH 28

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static int i2c_fd;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int ret;
    uint8_t buffer[2];
    int16_t temp_raw;
    double temp_celsius;

    // Setup signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Request GPIO line
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Configure GPIO line as output
    ret = gpiod_line_request_output(led_line, "led_control", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read temperature from sensor
        buffer[0] = TEMP_REG;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to I2C device");
            cleanup();
            exit(EXIT_FAILURE);
        }

        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read from I2C device");
            cleanup();
            exit(EXIT_FAILURE);
        }

        temp_raw = (buffer[0] << 8) | buffer[1];
        temp_celsius = (temp_raw >> 4) * 0.0625;

        // Log temperature
        printf("Temperature: %.2f °C\n", temp_celsius);

        // Control LED based on temperature
        if (temp_celsius > HYSTERESIS_HIGH) {
            gpiod_line_set_value(led_line, 1);
        } else if (temp_celsius < HYSTERESIS_LOW) {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup resources
    cleanup();
    return 0;
}

