#define CMD_MEASURE_RH_NO_HOLD 0xF5
#define CMD_MEASURE_TEMP_NO_HOLD 0xF3
#define CMD_READ_TEMP_PREV_RH 0xE0
#define I2C_RETRIES 3
#define I2C_DELAY_US 20000

#define TEMP_SCALE 175.72
#define TEMP_OFFSET -46.85
#define HUMIDITY_SCALE 125.0
#define HUMIDITY_OFFSET -6.0

#define LOG_FILE "environment.log"

volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

void log_error(const char *msg) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, msg);
    fprintf(stdout, "[%s] ERROR: %s\n", timestamp, msg);
}

void log_data(double temperature, double humidity) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        log_error("Failed to open log file");
        return;
    }
    fprintf(log, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log);
    fclose(log);
    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
}

int i2c_write_byte(int handle, uint8_t cmd) {
    int retries = I2C_RETRIES;
    while (retries--) {
        if (i2cWriteDevice(handle, &cmd, 1) == 0) {
            return 0;
        }
        log_error("I2C write failed, retrying...");
        usleep(I2C_DELAY_US);
    }
    log_error("I2C write failed after retries");
    return -1;
}

int i2c_read_bytes(int handle, uint8_t *buf, size_t len) {
    int retries = I2C_RETRIES;
    while (retries--) {
        if (i2cReadDevice(handle, buf, len) == 0) {
            return 0;
        }
        log_error("I2C read failed, retrying...");
        usleep(I2C_DELAY_US);
    }
    log_error("I2C read failed after retries");
    return -1;
}

double convert_temperature(uint16_t raw) {
    double temp = (TEMP_SCALE * raw / 65536.0) + TEMP_OFFSET;
    return temp;
}

double convert_humidity(uint16_t raw) {
    double humidity = (HUMIDITY_SCALE * raw / 65536.0) + HUMIDITY_OFFSET;
    if (humidity < 0) humidity = 0;
    if (humidity > 100) humidity = 100;
    return humidity;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t cmd = 0xFA; // Read Electronic ID
    if (i2c_write_byte(i2c_handle, cmd) < 0) {
        log_error("Failed to send read ID command");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    uint8_t id[8];
    if (i2c_read_bytes(i2c_handle, id, 8) < 0) {
        log_error("Failed to read ID");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        if (i2c_write_byte(i2c_handle, CMD_MEASURE_RH_NO_HOLD) < 0) {
            log_error("Failed to send measure RH command");
            continue;
        }
        usleep(20000); // Wait for measurement

        uint8_t rh_data[2];
        if (i2c_read_bytes(i2c_handle, rh_data, 2) < 0) {
            log_error("Failed to read RH data");
            continue;
        }
        uint16_t rh_raw = (rh_data[0] << 8) | rh_data[1];
        double humidity = convert_humidity(rh_raw);

        if (i2c_write_byte(i2c_handle, CMD_READ_TEMP_PREV_RH) < 0) {
            log_error("Failed to send read temp command");
            continue;
        }
        usleep(20000); // Wait for measurement

        uint8_t temp_data[2];
        if (i2c_read_bytes(i2c_handle, temp_data, 2) < 0) {
            log_error("Failed to read temp data");
            continue;
        }
        uint16_t temp_raw = (temp_data[0] << 8) | temp_data[1];
        double temperature = convert_temperature(temp_raw);

        log_data(temperature, humidity);
        sleep(60);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

