#define HDC1080_CONFIG_REG 0x02
#define HDC1080_TEMP_REG 0x00
#define HDC1080_MEASUREMENT_DELAY 20000 // 20 ms in microseconds

#define I2C_BUS 1

volatile sig_atomic_t running = 1;

