    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, HDC1080_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure HDC1080 for 14-bit temperature and humidity resolution
    uint8_t config_data[2] = {0x02, 0x00}; // 14-bit temp, 14-bit humidity
    if (i2cWriteI2CDevice(i2c_handle, config_data, 2) < 0) {
        fprintf(stderr, "Failed to write to HDC1080 configuration register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        // Start a measurement by writing the pointer to register 0x00
        if (i2cWriteByte(i2c_handle, HDC1080_TEMP_REG) < 0) {
            fprintf(stderr, "Failed to start measurement\n");
            continue;
        }

        // Wait for the measurement to complete
        gpioDelay(HDC1080_MEASUREMENT_DELAY);

        // Read 4 bytes: 2 bytes temperature followed by 2 bytes humidity
        uint8_t data[4];
        if (i2cReadI2CDevice(i2c_handle, data, 4) < 0) {
            fprintf(stderr, "Failed to read from HDC1080\n");
            continue;
        }

        // Convert raw values
        uint16_t raw_temp = (data[0] << 8) | data[1];
        uint16_t raw_humidity = (data[2] << 8) | data[3];
        double temperature = (raw_temp / 65536.0) * 165.0 - 40.0;
        double humidity = (raw_humidity / 65536.0) * 100.0;

        // Log the reading with a timestamp
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[80];
