            fprintf(stderr, "Failed to open log file\n");
            continue;
        }

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        fclose(log_file);

        // Wait 5 seconds before the next reading
        sleep(5);
    }

    // Clean up resources
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

