#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x44
#define MEASUREMENT_COMMAND 0x2C
#define MEASUREMENT_REPEATABILTY 0xE0
#define CRC8_POLYNOMIAL 0x31
#define READ_TIMEOUT_US 10000

int i2c_fd = -1;
FILE *log_file = NULL;

void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signum);
    close_resources();
    exit(0);
}

unsigned char calculate_crc8(unsigned char *data, size_t len) {
    unsigned char crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_temperature(double temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close_resources();
        return EXIT_FAILURE;
    }

    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close_resources();
        return EXIT_FAILURE;
    }

    while (1) {
        unsigned char command[2] = {MEASUREMENT_COMMAND, MEASUREMENT_REPEATABILTY};
        if (write(i2c_fd, command, sizeof(command)) != sizeof(command)) {
            perror("Failed to send measurement command");
            continue;
        }

        usleep(READ_TIMEOUT_US);

        unsigned char data[3];
        if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
            perror("Failed to read measurement data");
            continue;
        }

        unsigned char calculated_crc = calculate_crc8(data, 2);
        if (calculated_crc != data[2]) {
            fprintf(stderr, "CRC8 mismatch, expected %02X, got %02X\n", data[2], calculated_crc);
            continue;
