    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("hvac_pressure_log.txt", "a");
    if (!log_file) {
