        fprintf(log_file, "%s,%.2f,%.2f\n", ctime(&now), pressure_Pa, temperature_C);
        fflush(log_file);

        gpioDelay(1000000); // Sample once per second
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

