#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <math.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x63
#define LED_GPIO 17
#define CRC8_POLYNOMIAL 0x31
#define CRC8_SEED 0xFF

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_SEED;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, sigint_handler);

    // Open I2C device
    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO line for LED
    struct gpiod_chip *chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_output(led_line, "baro_led", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Read calibration coefficients
    uint8_t calib_data[8];
    uint8_t cmd[2] = {0x66, 0x00};
    if (write(i2c_fd, cmd, 2) != 2) {
        perror("Failed to write to I2C device");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (read(i2c_fd, calib_data, 8) != 8) {
        perror("Failed to read from I2C device");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Extract calibration coefficients
    int16_t c0 = (calib_data[0] << 8) | calib_data[1];
    int16_t c1 = (calib_data[2] << 8) | calib_data[3];
    int16_t c00 = (calib_data[4] << 8) | calib_data[5];
    int16_t c10 = (calib_data[6] << 8) | calib_data[7];

    while (running) {
        // Trigger measurement
        uint8_t measure_cmd[2] = {0x40, 0x11};
        if (write(i2c_fd, measure_cmd, 2) != 2) {
            perror("Failed to write to I2C device");
            break;
        }

        // Wait for measurement to complete
        usleep(20000);

        // Read measurement data
        uint8_t data[6];
        cmd[0] = 0x00;
        if (write(i2c_fd, cmd, 1) != 1) {
            perror("Failed to write to I2C device");
            break;
        }
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read from I2C device");
            break;
        }

        // Verify CRC
        uint8_t crc = calculate_crc8(data, 5);
        if (crc != data[5]) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        // Extract pressure and temperature
        int32_t pressure_raw = (data[0] << 16) | (data[1] << 8) | data[2];
        int32_t temperature_raw = (data[3] << 16) | (data[4] << 8) | data[5];

        // Convert to Pascals and Celsius
        double pressure = c00 + c10 * temperature_raw / 2048.0 + c0 * pressure_raw / 1024.0 + c1 * pressure_raw * temperature_raw / 2048.0 / 1024.0;
        double temperature = temperature_raw / 2048.0;

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        // Blink LED based on pressure
        if (pressure < 95000) {
            gpiod_line_set_value(led_line, 1);
            usleep(100000);
            gpiod_line_set_value(led_line, 0);
            usleep(100000);
        } else {
            gpiod_line_set_value(led_line, 1);
            usleep(500000);
            gpiod_line_set_value(led_line, 0);
            usleep(500000);
        }
    }

    // Clean up
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

