#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define RAM_REG_AMBIENT 0x06
#define RAM_REG_OBJECT 0x07
#define FAN_GPIO 18
#define TEMP_SCALE 0.02
#define TEMP_OFFSET -273.15
#define FAN_ON_TEMP 30.0
#define FAN_OFF_TEMP 28.0
#define MAX_READ_RETRIES 3
#define READ_DELAY_US 10000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_i2c_register(int handle, uint8_t reg, uint16_t *value) {
    int retries = 0;
    while (retries < MAX_READ_RETRIES) {
        if (i2cReadWordData(handle, reg, value) >= 0) {
            return 0;
        }
        retries++;
        usleep(READ_DELAY_US);
    }
    return -1;
}

double convert_temp(uint16_t raw) {
    return raw * TEMP_SCALE + TEMP_OFFSET;
}

void log_temperature(double ambient, double object) {
    FILE *log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

