#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define SHT40_I2C_ADDR 0x44
#define SHT40_MEASURE_CMD 0xFD
#define SHT40_DATA_LEN 6
#define HTTP_PORT 8080
#define MAX_CLIENTS 5
#define MAX_RETRIES 3

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void cleanup(int i2c_handle) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    uint8_t cmd = SHT40_MEASURE_CMD;
    uint8_t data[SHT40_DATA_LEN];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteByte(i2c_handle, cmd) < 0) {
            fprintf(stderr, "I2C write error: %s\n", pigpio_error());
            retries++;
            continue;
        }

        time_sleep(0.01); // Wait at least 10 ms

        if (i2cReadI2CBlockData(i2c_handle, 0, data, SHT40_DATA_LEN) < 0) {
            fprintf(stderr, "I2C read error: %s\n", pigpio_error());
            retries++;
            continue;
        }

        uint16_t raw_T = (data[0] << 8) | data[1];
        uint16_t raw_RH = (data[3] << 8) | data[4];

        *temperature = -45.0 + 175.0 * (raw_T / 65535.0);
        *humidity = -6.0 + 125.0 * (raw_RH / 65535.0);
        if (*humidity < 0) *humidity = 0;
        if (*humidity > 100) *humidity = 100;

        return 0;
    }

    return -1;
}

void handle_client(int client_sock) {
    char response[1024];
    float temperature, humidity;

    if (read_sht40(i2cOpen(1, SHT40_I2C_ADDR, 0), &temperature, &humidity) < 0) {
        snprintf(response, sizeof(response), "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\n\r\n<html><body><h1>Error reading sensor data</h1></body></html>");
    } else {
        snprintf(response, sizeof(response), "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<html><body><h1>Temperature: %.2f°C, Humidity: %.2f%%</h1></body></html>", temperature, humidity);
    }

    send(client_sock, response, strlen(response), 0);
    close(client_sock);
}

int main() {
    int i2c_handle = -1;
    int server_sock, client_sock;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SHT40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open error: %s\n", pigpio_error());
        cleanup(i2c_handle);
        return 1;
    }

    server_sock = socket(AF_INET, SOCK_STREAM, 0);
    if (server_sock < 0) {
        perror("Socket creation failed");
        cleanup(i2c_handle);
        return 1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(HTTP_PORT);

    if (bind(server_sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        cleanup(i2c_handle);
        close(server_sock);
        return 1;
    }

    if (listen(server_sock, MAX_CLIENTS) < 0) {
        perror("Listen failed");
        cleanup(i2c_handle);
        close(server_sock);
        return 1;
    }

    printf("Server listening on port %d\n", HTTP_PORT);

    while (running) {
        client_sock = accept(server_sock, (struct sockaddr *)&client_addr, &client_len);
        if (client_sock < 0) {
            perror("Accept failed");
            continue;
        }

        handle_client(client_sock);
    }

    cleanup(i2c_handle);
    close(server_sock);
    return 0;
}

