#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define HDC2010_ADDR 0x40
#define MEASUREMENT_CONFIG_REG 0x0E
#define CONFIG_REG 0x0F
#define TEMP_REG 0x00
#define HUMIDITY_REG 0x02
#define MAX_RETRIES 3
#define TIMEOUT_US 500000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set CONFIG register for heater disabled and 14-bit resolution
    uint8_t config_data = 0x00; // Heater disabled, 14-bit resolution
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, config_data) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        // Trigger measurement
        if (i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG_REG, 0x01) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }

        // Wait for measurement to complete
        struct timespec start, now;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (1) {
            uint8_t status;
            if (i2cReadByteData(i2c_handle, MEASUREMENT_CONFIG_REG, &status) < 0) {
                fprintf(stderr, "Failed to read MEASUREMENT_CONFIG register\n");
                break;
            }
            if (!(status & 0x01)) {
                break;
            }
            clock_gettime(CLOCK_MONOTONIC, &now);
            if (now.tv_sec - start.tv_sec > 0 || now.tv_nsec - start.tv_nsec > TIMEOUT_US) {
                fprintf(stderr, "Measurement timed out\n");
                break;
            }
            usleep(10000); // 10 ms delay
        }

        // Read temperature and humidity
        uint16_t temp_raw, humidity_raw;
        if (i2cReadI2CBlockData(i2c_handle, TEMP_REG, (char *)&temp_raw, 2) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }
        if (i2cReadI2CBlockData(i2c_handle, HUMIDITY_REG, (char *)&humidity_raw, 2) < 0) {
            fprintf(stderr, "Failed to read humidity\n");
            continue;
        }

        // Convert raw values to actual temperature and humidity
        double temperature = (temp_raw / 65536.0) * 165.0 - 40.0;
        double humidity = (humidity_raw / 65536.0) * 100.0;

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        sleep(5); // Wait for 5 seconds before next reading
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

