        if (i2cReadI2CBlockData(i2c_handle, TEMP_REG, (char *)&temp_raw, 2) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }
        if (i2cReadI2CBlockData(i2c_handle, HUMIDITY_REG, (char *)&humidity_raw, 2) < 0) {
            fprintf(stderr, "Failed to read humidity\n");
            continue;
        }

        // Convert raw values to actual temperature and humidity
        double temperature = (temp_raw / 65536.0) * 165.0 - 40.0;
        double humidity = (humidity_raw / 65536.0) * 100.0;

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        sleep(5); // Wait for 5 seconds before next reading
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}
