#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define I2C_BUS 1
#define READ_DELAY_US 45000
#define LOG_INTERVAL_US 500000

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len, uint8_t crc) {
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    uint8_t cmd[2] = {(CONTINUOUS_MEASUREMENT_CMD >> 8) & 0xFF, CONTINUOUS_MEASUREMENT_CMD & 0xFF};
    if (i2cWriteDevice(handle, cmd, 2) < 0) {
        fprintf(stderr, "I2C write failed\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        usleep(READ_DELAY_US);

        uint8_t data[6];
        if (i2cReadDevice(handle, data, 6) < 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        uint8_t pressure_crc = crc8(data, 2, 0xFF);
        uint8_t temperature_crc = crc8(data + 3, 2, 0xFF);

        if (pressure_crc != data[2] || temperature_crc != data[5]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        uint16_t pressure = (data[0] << 8) | data[1];
        uint16_t temperature = (data[3] << 8) | data[4];

        printf("Pressure: %d, Temperature: %d\n", pressure, temperature);

        usleep(LOG_INTERVAL_US - READ_DELAY_US);
    }

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

