#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <math.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define RELAY_LINE 17
#define PROFILE_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"
#define SPI_SPEED 500000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 16

typedef struct {
    double kp;
    double ki;
    double kd;
    double setpoint;
    double integral;
    double prev_error;
} PIDController;

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

double read_temperature(int spi_fd) {
    uint16_t data;
    struct spi_ioc_transfer xfer = {
        .tx_buf = NULL,
        .rx_buf = &data,
        .len = sizeof(data),
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1.0;
    }

    if (data & (1 << 2)) {
        fprintf(stderr, "MAX6675: Open circuit detected\n");
        return -1.0;
    }

    return (data >> 3) * 0.25;
}

double pid_update(PIDController *pid, double current_temp) {
    double error = pid->setpoint - current_temp;
    pid->integral += error;
    double derivative = error - pid->prev_error;
    pid->prev_error = error;

    double output = pid->kp * error + pid->ki * pid->integral + pid->kd * derivative;
    return fmax(0.0, fmin(1.0, output));
}

void set_relay_duty_cycle(struct gpiod_chip *chip, int line, double duty_cycle) {
    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, line);
    if (!relay_line) {
        perror("gpiod_chip_get_line");
        return;
    }

    if (gpiod_line_request_output(relay_line, "reflow_oven", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(relay_line);
        return;
    }

    if (duty_cycle > 0.5) {
        gpiod_line_set_value(relay_line, 1);
    } else {
        gpiod_line_set_value(relay_line, 0);
    }

    gpiod_line_release(relay_line);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *profile = fopen(PROFILE_FILE, "r");
    if (!profile) {
        perror("fopen profile");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *log = fopen(LOG_FILE, "w");
    if (!log) {
        perror("fopen log");
        fclose(profile);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    fprintf(log, "Time(s),Temperature(C)\n");

    PIDController pid = {1.0, 0.1, 0.01, 0.0, 0.0, 0.0};
    double current_time = 0.0;
    double target_temp = 0.0;
    int profile_line = 0;

    while (running) {
        if (profile_line == 0) {
            if (fscanf(profile, "%lf,%lf", &current_time, &target_temp) != 2) {
                break;
            }
            profile_line = 1;
        }

        double current_temp = read_temperature(spi_fd);
        if (current_temp < 0.0) {
            continue;
        }

        pid.setpoint = target_temp;
        double duty_cycle = pid_update(&pid, current_temp);
        set_relay_duty_cycle(chip, RELAY_LINE, duty_cycle);

        fprintf(log, "%.1f,%.2f\n", current_time, current_temp);
        fflush(log);

        sleep(1);
        current_time += 1.0;

        if (current_time >= target_temp) {
            profile_line = 0;
        }
    }

    fclose(log);
    fclose(profile);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

