#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <gpiod.h>
#include <math.h>

#define DS18B20_PATH "/sys/bus/w1/devices/28-*/w1_slave"
#define LOG_FILE "greenhouse.log"
#define GPIO_CHIP "gpiochip0"
#define RELAY_LINE 17
#define PWM_LINE 18

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

double read_temperature() {
    FILE *fp;
    char path[100];
    char line[256];
    double temperature = -999.0;

    snprintf(path, sizeof(path), DS18B20_PATH);
    fp = popen(path, "r");
    if (!fp) {
        perror("popen");
        return temperature;
    }

    while (fgets(line, sizeof(line), fp) != NULL) {
        if (strstr(line, "YES")) {
            fgets(line, sizeof(line), fp);
            char *pos = strstr(line, "t=");
            if (pos) {
                temperature = atof(pos + 2) / 1000.0;
            }
            break;
        }
    }

    pclose(fp);
    return temperature;
}

void log_data(FILE *log, double temperature, double setpoint, double pid_output, int pwm_duty) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

    fprintf(log, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, temperature, setpoint, pid_output, pwm_duty);
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return EXIT_FAILURE;
    }

    double setpoint = atof(argv[1]);
    double Kp = atof(argv[2]);
    double Ki = atof(argv[3]);
    double Kd = atof(argv[4]);

    struct gpiod_chip *chip;
    struct gpiod_line *relay_line, *pwm_line;
    int pwm_duty = 0;
    double integral = 0.0, previous_error = 0.0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_LINE);
    pwm_line = gpiod_chip_get_line(chip, PWM_LINE);

    if (!relay_line || !pwm_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "greenhouse_relay", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(pwm_line, "greenhouse_pwm", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("fopen");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        double temperature = read_temperature();
        if (temperature == -999.0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        double error = setpoint - temperature;
        integral += error;
        double derivative = error - previous_error;
        double pid_output = Kp * error + Ki * integral + Kd * derivative;
        previous_error = error;

        pwm_duty = (int)fabs(pid_output);
        if (pwm_duty > 100) pwm_duty = 100;
        if (pwm_duty < 0) pwm_duty = 0;

        gpiod_line_set_value(relay_line, pwm_duty > 0);
        gpiod_line_set_value(pwm_line, pwm_duty);

        log_data(log, temperature, setpoint, pid_output, pwm_duty);
        fflush(log);

        sleep(5);
    }

    gpiod_line_set_value(relay_line, 0);
    gpiod_line_set_value(pwm_line, 0);
    gpiod_chip_close(chip);
    fclose(log);

    return EXIT_SUCCESS;
}

