#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define I2C_RETRIES 3
#define I2C_DELAY 10000 // 10 ms
#define POLL_INTERVAL 5000000 // 5 seconds

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int i2c_write(int fd, const uint8_t *data, size_t len) {
    for (int i = 0; i < I2C_RETRIES; i++) {
        if (write(fd, data, len) == len) {
            return 0;
        }
        usleep(I2C_DELAY);
    }
    return -1;
}

int i2c_read(int fd, uint8_t *data, size_t len) {
    for (int i = 0; i < I2C_RETRIES; i++) {
        if (read(fd, data, len) == len) {
            return 0;
        }
        usleep(I2C_DELAY);
    }
    return -1;
}

double calculate_humidity(const uint8_t *data) {
    uint32_t raw_humidity = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
    return (raw_humidity * 100.0) / 1048576.0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "dehumidifier", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t init_sequence[] = {0xBE, 0x08, 0x00};
    if (i2c_write(i2c_fd, init_sequence, sizeof(init_sequence)) < 0) {
        fprintf(stderr, "Failed to initialize AHT20 sensor\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t trigger_command[] = {0xAC, 0x33, 0x00};
        if (i2c_write(i2c_fd, trigger_command, sizeof(trigger_command)) < 0) {
            fprintf(stderr, "Failed to trigger AHT20 measurement\n");
            goto next_poll;
        }

        usleep(80000); // 80 ms

        uint8_t data[6];
        if (i2c_read(i2c_fd, data, sizeof(data)) < 0) {
            fprintf(stderr, "Failed to read AHT20 data\n");
            goto next_poll;
        }

        if ((data[0] & 0x80) == 0 || (data[0] & 0x08) != 0) {
            fprintf(stderr, "AHT20 sensor not calibrated or busy\n");
            goto next_poll;
        }

        double humidity = calculate_humidity(data);
        time_t now = time(NULL);
        printf("%s: Humidity: %.2f%%\n", ctime(&now), humidity);

        if (humidity > HUMIDITY_THRESHOLD_HIGH) {
            gpiod_line_set_value(line, 1);
        } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
            gpiod_line_set_value(line, 0);
        }

next_poll:
        usleep(POLL_INTERVAL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

