#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

#define I2C_DEV "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define HTU21D_READ_TEMP_HOLD 0xE3
#define HTU21D_READ_HUM_HOLD 0xE5
#define HTU21D_READ_USER_REG 0xE7
#define HTU21D_WRITE_USER_REG 0xE6

#define HTTP_SERVER "api.example.com"
#define HTTP_PORT 80
#define HTTP_PATH "/humidity"

volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

void close_fd(int *fd) {
    if (*fd >= 0) {
        close(*fd);
        *fd = -1;
    }
}

uint16_t read_i2c_word(int i2c_fd, uint8_t reg) {
    uint8_t cmd = reg;
    if (write(i2c_fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "I2C write error: %s", strerror(errno));
        return 0xFFFF;
    }

    uint8_t buffer[3];
    if (read(i2c_fd, buffer, 3) != 3) {
        syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
        return 0xFFFF;
    }

    uint16_t value = (buffer[0] << 8) | buffer[1];
    uint8_t checksum = buffer[2];
    uint8_t calculated_checksum = (uint8_t)(value >> 8) ^ (uint8_t)value ^ 0x00 ^ 0x00;
    if (checksum != calculated_checksum) {
        syslog(LOG_ERR, "I2C CRC mismatch");
        return 0xFFFF;
    }

    return value;
}

float calculate_humidity(uint16_t raw_humidity) {
    return -6 + 125.0 * (raw_humidity / 65535.0);
}

int send_http_post(float humidity) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation error: %s", strerror(errno));
        return -1;
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(HTTP_PORT);

    if (inet_pton(AF_INET, HTTP_SERVER, &serv_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        close_fd(&sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Connection Failed: %s", strerror(errno));
        close_fd(&sockfd);
        return -1;
    }

    char request[256];
    snprintf(request, sizeof(request),
             "POST %s HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: 18\r\n"
             "\r\n"
             "{\"humidity\":%.2f}\r\n",
             HTTP_PATH, HTTP_SERVER, humidity);

    if (send(sockfd, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        close_fd(&sockfd);
        return -1;
    }

    char response[1024];
    int valread = read(sockfd, response, 1024);
    if (valread < 0) {
        syslog(LOG_ERR, "Read failed: %s", strerror(errno));
        close_fd(&sockfd);
        return -1;
    }

    close_fd(&sockfd);
    return 0;
}

int main() {
    openlog("htu21d_humidity", LOG_PID | LOG_CONS, LOG_USER);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open the i2c bus: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave: %s", strerror(errno));
        close_fd(&i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t raw_humidity = read_i2c_word(i2c_fd, HTU21D_READ_HUM_HOLD);
        if (raw_humidity == 0xFFFF) {
            syslog(LOG_ERR, "Failed to read humidity");
        } else {
            float humidity = calculate_humidity(raw_humidity);
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);

            if (send_http_post(humidity) < 0) {
                syslog(LOG_ERR, "Failed to send HTTP POST");
            }
        }

        sleep(60);
    }

    close_fd(&i2c_fd);
    closelog();
    return EXIT_SUCCESS;
}

