    uint8_t data[24];
    if (read_i2c_register(handle, BMP280_CALIB_REG, data, 24) < 0) {
        perror("Failed to read calibration block");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < 24; i += 2) {
        calib[i / 2] = (data[i] << 8) | data[i + 1];
