#define TMP117_I2C_ADDR 0x48
#define TMP117_TEMP_REG 0x00
#define AHT20_I2C_ADDR 0x38
#define AHT20_INIT_CMD 0xBE
#define AHT20_MEASURE_CMD 0xAC
#define AHT20_MEASURE_DATA_LEN 7
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define I2C_DEVICE "/dev/i2c-1"
#define SAMPLE_INTERVAL 1
#define MAX_RETRIES 3
#define BACKOFF_MS 10

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void init_sensors(int i2c_fd) {
    uint8_t init_cmd[] = {AHT20_INIT_CMD, 0x08, 0x00};
    if (write(i2c_fd, init_cmd, sizeof(init_cmd)) != sizeof(init_cmd)) {
        perror("AHT20 init command failed");
    }
}

int read_tmp117(int i2c_fd) {
    uint8_t reg = TMP117_TEMP_REG;
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("TMP117 register write failed");
        return -1;
    }
    uint16_t temp;
    if (read(i2c_fd, &temp, 2) != 2) {
        perror("TMP117 temperature read failed");
        return -1;
    }
    return (int16_t)temp * 0.0078125;
}

int read_aht20(int i2c_fd) {
    uint8_t measure_cmd[] = {AHT20_MEASURE_CMD, 0x33, 0x00};
    if (write(i2c_fd, measure_cmd, sizeof(measure_cmd)) != sizeof(measure_cmd)) {
        perror("AHT20 measure command failed");
        return -1;
    }
    uint8_t data[AHT20_MEASURE_DATA_LEN];
    for (int retries = 0; retries < MAX_RETRIES; retries++) {
        if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
            perror("AHT20 measure read failed");
            continue;
        }
        if (!(data[0] & 0x80)) {
            uint32_t humidity = ((data[1] & 0x0F) << 16) | (data[2] << 8) | data[3];
            uint32_t temperature = ((data[4] << 12) | (data[5] << 4) | (data[6] >> 4));
            return (humidity * 100 / 1048576) * 100 / 100; // Convert to %RH
        }
        usleep(BACKOFF_MS * 1000);
    }
    return -1;
}

int read_pir(struct gpiod_chip *chip, struct gpiod_line *line) {
    return gpiod_line_get_value(line);
}

void log_data(int tmp117_temp, int aht20_humidity, int pir_motion) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char filename[20];
    strftime(filename, sizeof(filename), "log_%Y-%m-%d.csv", tm_info);
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    if (ftell(file) == 0) {
        fprintf(file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    }
    strftime(filename, sizeof(filename), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(file, "%s,%d,%d,%d\n", filename, tmp117_temp, aht20_humidity, pir_motion);
    fclose(file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_I2C_ADDR) < 0) {
        perror("Failed to set TMP117 I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_I2C_ADDR) < 0) {
        perror("Failed to set AHT20 I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    init_sensors(i2c_fd);

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(line, "pir_sensor") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int tmp117_temp = read_tmp117(i2c_fd);
        int aht20_humidity = read_aht20(i2c_fd);
        int pir_motion = read_pir(chip, line);
        log_data(tmp117_temp, aht20_humidity, pir_motion);
        sleep(SAMPLE_INTERVAL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

