#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define RAIN_SENSOR_LINE 17
#define MOTOR_ENA_LINE 22
#define MOTOR_IN1_LINE 23
#define MOTOR_IN2_LINE 24

#define POLL_INTERVAL 2000000 // 2 seconds in microseconds
#define MOTOR_RUN_TIME 5000000 // 5 seconds in microseconds

static struct gpiod_chip *chip;
static struct gpiod_line *rain_sensor_line;
static struct gpiod_line *motor_ena_line;
static struct gpiod_line *motor_in1_line;
static struct gpiod_line *motor_in2_line;

void log_event(const char *message) {
    time_t now = time(NULL);
    printf("%s: %s\n", ctime(&now), message);
}

void cleanup() {
    if (motor_ena_line) {
        gpiod_line_release(motor_ena_line);
    }
    if (motor_in1_line) {
        gpiod_line_release(motor_in1_line);
    }
    if (motor_in2_line) {
        gpiod_line_release(motor_in2_line);
    }
    if (rain_sensor_line) {
        gpiod_line_release(rain_sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void handle_signal(int sig) {
    log_event("Signal received, cleaning up and exiting.");
    cleanup();
    exit(EXIT_SUCCESS);
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    rain_sensor_line = gpiod_chip_get_line(chip, RAIN_SENSOR_LINE);
    if (!rain_sensor_line) {
        perror("Failed to get rain sensor line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    motor_ena_line = gpiod_chip_get_line(chip, MOTOR_ENA_LINE);
    motor_in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_LINE);
    motor_in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_LINE);

    if (!motor_ena_line || !motor_in1_line || !motor_in2_line) {
