#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27

#define SAMPLE_INTERVAL_US 500000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void set_rgb(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

int get_cpu_load() {
    FILE *fp;
    char buffer[1024];
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long total, prev_total = 0, prev_idle = 0;
    double load;

    fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("Failed to open /proc/stat");
        exit(EXIT_FAILURE);
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Failed to read /proc/stat");
        fclose(fp);
        exit(EXIT_FAILURE);
    }

    sscanf(buffer, "cpu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
           &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice);

    fclose(fp);

    total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    load = ((double)(total - prev_total) - (idle - prev_idle)) / (total - prev_total) * 100;

    prev_total = total;
    prev_idle = idle;

    return (int)load;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int load = get_cpu_load();
        int red, green, blue;

        if (load <= 50) {
            green = 255;
            red = (load * 5) / 100;
            blue = 0;
        } else {
            green = 255 - ((load - 50) * 5) / 100;
            red = 255;
            blue = 0;
        }

        set_rgb(red, green, blue);

        usleep(SAMPLE_INTERVAL_US);
    }

    set_rgb(0, 0, 0);
    gpioTerminate();

    return 0;
}

