#define BMP280_CALIB_REG_END 0xA1
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_STATUS_REG 0xF3
#define BMP280_DATA_REG 0xF7
#define BMP280_FORCED_MODE 0x11
#define BMP280_TEMP_OSRS_X1 0x27
#define BMP280_PRESS_OSRS_X1 0xA7
#define BMP280_I2C_BUS 1
#define UDP_SERVER_IP "192.168.1.100"
#define UDP_SERVER_PORT 5000
#define INTERVAL 5

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

