        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cReadByteData(i2c_handle, BMP280_CHIP_ID_REG, &chip_id) < 0) {
        fprintf(stderr, "Failed to read chip ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP280_CALIB_REG_START, (char *)&calib, sizeof(calib)) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
