        if (i2cReadI2CBlockData(i2c_handle, BMP280_DATA_REG, (char *)&adc_T, 3) < 0) {
            fprintf(stderr, "Failed to read temperature data\n");
            break;
        }

        if (i2cReadI2CBlockData(i2c_handle, BMP280_DATA_REG + 3, (char *)&adc_P, 3) < 0) {
            fprintf(stderr, "Failed to read pressure data\n");
            break;
