#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define FAN_GPIO 18
#define PWM_FREQ 1000
#define BUFFER_SIZE 20

typedef struct {
    time_t timestamp;
    double temperature;
    int pwm_duty;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

void log_entry(time_t timestamp, double temperature, int pwm_duty) {
    log_buffer[buffer_index].timestamp = timestamp;
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].pwm_duty = pwm_duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

void handle_sigint(int sig) {
    gpioPWM(FAN_GPIO, 0);
    spiClose(SPI_CHANNEL);
    gpioTerminate();

    printf("Log Buffer Contents:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (log_buffer[i].timestamp != 0) {
            printf("%s - Temp: %.2f°C, PWM: %d\n",
                   ctime(&log_buffer[i].timestamp),
                   log_buffer[i].temperature,
                   log_buffer[i].pwm_duty);
        }
    }

    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ);

    signal(SIGINT, handle_sigint);

    while (1) {
        unsigned char spi_data[4];
        if (spiXfer(spi_handle, spi_data, spi_data, 4) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        uint32_t raw_data = (spi_data[0] << 24) | (spi_data[1] << 16) | (spi_data[2] << 8) | spi_data[3];
        int fault = (raw_data >> 16) & 0x01;
        int fault_type = raw_data & 0x07;

        if (fault) {
            fprintf(stderr, "MAX31855 fault detected: ");
            if (fault_type & 0x01) fprintf(stderr, "OC ");
            if (fault_type & 0x02) fprintf(stderr, "SCG ");
            if (fault_type & 0x04) fprintf(stderr, "SCV ");
            fprintf(stderr, "\n");
            continue;
        }

        int temp_raw = (raw_data >> 18) & 0x3FFF;
        double temperature = (temp_raw * 0.25) - 273.15;

        int pwm_duty = 0;
        if (temperature >= 25 && temperature < 40) {
            pwm_duty = (int)((temperature - 25) * 2);
        } else if (temperature >= 40 && temperature < 60) {
            pwm_duty = 50 + (int)((temperature - 40) * 3.33);
        } else if (temperature >= 60) {
            pwm_duty = 255;
        }

        gpioPWM(FAN_GPIO, pwm_duty);
        log_entry(time(NULL), temperature, pwm_duty);

        sleep(1);
    }

    return 0;
}

