#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define BMP180_I2C_ADDR 0x77
#define OSS 3
#define GPIO_PIN 2
#define LOG_FILE "altitude_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_data(FILE *file, double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(file);
}

int read_register(int handle, uint8_t reg) {
    uint8_t data;
    if (i2cReadByteData(handle, reg) < 0) {
        perror("i2cReadByteData");
        return -1;
    }
    return data;
}

int write_register(int handle, uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(handle, reg, value) < 0) {
        perror("i2cWriteByteData");
        return -1;
    }
    return 0;
}

int read_calibration_data(int handle, int16_t *calibration) {
    for (int i = 0; i < 11; i++) {
        int16_t value = read_register(handle, 0xAA + i * 2);
        if (value < 0) return -1;
        calibration[i] = value;
    }
    return 0;
}

double calculate_temperature(int16_t UT, int16_t *calibration) {
    int32_t X1 = ((UT - (int32_t)calibration[0]) * (int32_t)calibration[3]) >> 11;
    int32_t X2 = ((int32_t)calibration[1] << 11) / 2;
    int32_t B5 = X1 + X2;
    return ((B5 + 8) >> 4) / 10.0;
}

double calculate_pressure(int32_t UP, int16_t *calibration) {
    int32_t X1 = ((int32_t)calibration[6] * (int32_t)(UP >> 8)) >> 11;
    int32_t X2 = ((int32_t)calibration[7] * (int32_t)(UP >> 11)) >> 11;
    int32_t X3 = ((X1 + X2) + (int32_t)calibration[8]) >> 1;
    int32_t B3 = (((int32_t)calibration[1] * 4 + X3) << OSS) + 2;
    int32_t X1 = (int32_t)calibration[9] * (int32_t)(UP >> 13);
    int32_t X2 = (int32_t)(calibration[10] * (int32_t)(UP >> 11)) >> 15;
    int32_t X3 = X1 + X2 + 32768;
    int32_t B4 = ((int32_t)calibration[2] * (int32_t)X3) >> 14;
    int32_t B7 = ((UP - B3) * (50000 >> OSS));
    int32_t p;
    if (B7 < 0x80000000) {
        p = (B7 << 1) / B4;
    } else {
        p = (B7 / B4) << 1;
    }
    int32_t X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    p += (X1 + X2 + 3791) >> 4;
    return p;
}

void interrupt_callback(int gpio, int level, uint32_t tick) {
    static int logging = 0;
    logging = !logging;
    printf("Logging: %s\n", logging ? "ON" : "OFF");
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFunc(GPIO_PIN, RISING_EDGE, 0, interrupt_callback) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(1, BMP180_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    int16_t calibration[11];
    if (read_calibration_data(i2c_handle, calibration) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        if (write_register(i2c_handle, 0xF4, 0x2E) < 0) {
            perror("Failed to write temperature control register");
            break;
        }
        gpioDelay(4600); // Wait for temperature conversion

        int16_t UT = read_register(i2c_handle, 0xF6) << 8 | read_register(i2c_handle, 0xF7);
        if (UT < 0) break;

        if (write_register(i2c_handle, 0xF4, (0x34 + (OSS << 6))) < 0) {
            perror("Failed to write pressure control register");
            break;
        }
        gpioDelay(4600 + 1354 * (1 << OSS)); // Wait for pressure conversion

        int32_t UP = read_register(i2c_handle, 0xF6) << 16 | read_register(i2c_handle, 0xF7) << 8 | read_register(i2c_handle, 0xF8);
        UP >>= (8 - OSS);
        if (UP < 0) break;

        double temperature = calculate_temperature(UT, calibration);
        double pressure = calculate_pressure(UP, calibration);

        log_data(log_file, temperature, pressure);
        gpioDelay(1000000); // 1-second interval
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

