#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define SPI_SPEED 1000000
#define CSV_FILE "rtd_log.csv"

#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_HIGH_FAULT_THRESHOLD_MSB_REG 0x03
#define MAX31865_HIGH_FAULT_THRESHOLD_LSB_REG 0x04
#define MAX31865_LOW_FAULT_THRESHOLD_MSB_REG 0x05
#define MAX31865_LOW_FAULT_THRESHOLD_LSB_REG 0x06
#define MAX31865_FAULT_STATUS_REG 0x07

#define MAX31865_CONFIG_BIAS 0x80
#define MAX31865_CONFIG_3WIRE 0x40
#define MAX31865_CONFIG_FAULT_CLEAR 0x20
#define MAX31865_CONFIG_50HZ_FILTER 0x10
#define MAX31865_CONFIG_60HZ_FILTER 0x00

#define RTD_A 3.9083e-3
#define RTD_B -5.775e-7
#define RTD_C -4.183e-12

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void log_temperature(FILE *log_file, double temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
}

int main() {
    int spi_fd = -1;
    FILE *log_file = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    struct spi_ioc_transfer xfer[2];
    uint8_t tx[2] = {0};
    uint8_t rx[2] = {0};
    double temperature = 0.0;

    // Register signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device");
        goto cleanup;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        log_error("Failed to set SPI mode");
        goto cleanup;
    }

    // Set SPI bits per word
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        log_error("Failed to set SPI bits per word");
        goto cleanup;
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        log_error("Failed to set SPI speed");
        goto cleanup;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        log_error("Failed to open GPIO chip");
        goto cleanup;
    }

    // Get CS line
    cs_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!cs_line) {
        log_error("Failed to get CS line");
        goto cleanup;
    }

    // Request CS line
    if (gpiod_line_request_output(cs_line, "rtd_cs", 1) < 0) {
        log_error("Failed to request CS line");
        goto cleanup;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        goto cleanup;
    }

    // Initialize MAX31865
    tx[0] = MAX31865_CONFIG_REG | MAX31865_CONFIG_BIAS | MAX31865_CONFIG_3WIRE;
    xfer[0].tx_buf = (unsigned long)tx;
    xfer[0].rx_buf = (unsigned long)NULL;
    xfer[0].len = 1;
    xfer[0].speed_hz = SPI_SPEED;
    xfer[0].bits_per_word = 8;
    xfer[0].cs_change = 1;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), xfer) < 0) {
        log_error("Failed to initialize MAX31865");
        goto cleanup;
    }

    while (running) {
        // Read RTD registers
        tx[0] = MAX31865_RTD_MSB_REG | 0x80; // Read 2 bytes, MSB first
        xfer[0].tx_buf = (unsigned long)tx;
        xfer[0].rx_buf = (unsigned long)NULL;
        xfer[0].len = 1;
        xfer[0].speed_hz = SPI_SPEED;
        xfer[0].bits_per_word = 8;
        xfer[0].cs_change = 1;

        xfer[1].tx_buf = (unsigned long)NULL;
        xfer[1].rx_buf = (unsigned long)rx;
        xfer[1].len = 2;
        xfer[1].speed_hz = SPI_SPEED;
        xfer[1].bits_per_word = 8;
        xfer[1].cs_change = 0;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer) < 0) {
            log_error("Failed to read RTD registers");
            sleep(5);
            continue;
        }

        // Read fault status register
        tx[0] = MAX31865_FAULT_STATUS_REG | 0x80; // Read 1 byte
        xfer[0].tx_buf = (unsigned long)tx;
        xfer[0].rx_buf = (unsigned long)NULL;
        xfer[0].len = 1;
        xfer[0].speed_hz = SPI_SPEED;
        xfer[0].bits_per_word = 8;
        xfer[0].cs_change = 1;

        xfer[1].tx_buf = (unsigned long)NULL;
        xfer[1].rx_buf = (unsigned long)rx;
