#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BME280_ADDR 0x76
#define BME280_CHIP_ID_REG 0xD0
#define BME280_CHIP_ID 0x60
#define BME280_CTRL_MEAS_REG 0xF4
#define BME280_CONFIG_REG 0xF5
#define BME280_PRESS_MSB_REG 0xF7
#define BME280_TEMP_MSB_REG 0xFA
#define BME280_HUM_MSB_REG 0xFD

#define CTRL_MEAS_VAL 0x27 // Normal mode, temp x16, press x16
#define CONFIG_VAL 0xA0    // Standby time 1000 ms, filter off

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_data(int i2c_fd, FILE *log_file) {
    uint8_t data[8];
    uint32_t pressure, temperature, humidity;
    double temp_C, hum_percent, press_hPa;
    struct timespec ts;
    char timestamp[20];

    // Read pressure, temperature, and humidity
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return;
    }

    if (i2c_smbus_read_i2c_block_data(i2c_fd, BME280_PRESS_MSB_REG, 8, data) != 8) {
        perror("Failed to read sensor data");
        return;
    }

    pressure = ((uint32_t)data[0] << 12) | ((uint32_t)data[1] << 4) | (data[2] >> 4);
    temperature = ((uint32_t)data[3] << 12) | ((uint32_t)data[4] << 4) | (data[5] >> 4);
    humidity = ((uint32_t)data[6] << 8) | data[7];

    // Convert raw data to actual values
    temp_C = (temperature / 100.0);
    hum_percent = (humidity / 1024.0);
    press_hPa = (pressure / 256.0);

    // Get current timestamp
    clock_gettime(CLOCK_REALTIME, &ts);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

    // Log data to CSV
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temp_C, hum_percent, press_hPa);
    fflush(log_file);
}

int main() {
    int i2c_fd;
    FILE *log_file;
    struct sigaction sa;

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful exit
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Verify BME280 chip ID
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t chip_id = i2c_smbus_read_byte_data(i2c_fd, BME280_CHIP_ID_REG);
    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "BME280 chip ID mismatch: expected 0x60, got 0x%02X\n", chip_id);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure BME280
    if (i2c_smbus_write_byte_data(i2c_fd, BME280_CTRL_MEAS_REG, CTRL_MEAS_VAL) < 0 ||
        i2c_smbus_write_byte_data(i2c_fd, BME280_CONFIG_REG, CONFIG_VAL) < 0) {
        perror("Failed to configure BME280");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_file = fopen("bme280_log.csv", "a")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write header if file is empty
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");
    }

    // Main loop
    while (running) {
        log_data(i2c_fd, log_file);
        sleep(5);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

