This code sets up a Raspberry Pi Zero W to log temperature, humidity, and pressure data from a BME280 sensor to a CSV file every 5 seconds. It uses the standard Linux I2C dev interface and handles errors and resource cleanup gracefully.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BMP180_ADDR 0x77
#define OSS 0
#define SAMPLE_INTERVAL_US 50000
#define BUFFER_SIZE 1200 // 60 seconds * 20 samples/second
#define ALERT_GPIO 24
#define ALERT_THRESHOLD 5

typedef struct {
    double pressure;
    uint64_t timestamp;
} PressureReading;

PressureReading buffer[BUFFER_SIZE];
volatile int buffer_index = 0;
volatile int alert_active = 0;

void cleanup(int sig) {
    gpioSetTimerFuncEx(0, 0, NULL);
    gpioWrite(ALERT_GPIO, PI_LOW);
    gpioTerminate();
    exit(0);
}

void read_calibration_coefficients(int i2c_handle, uint16_t *coefficients) {
    for (int i = 0; i < 11; i++) {
        coefficients[i] = i2cReadWordData(i2c_handle, 0xAA + i * 2);
        if (coefficients[i] == PI_I2C_READ_FAILED) {
            fprintf(stderr, "Failed to read calibration coefficient %d\n", i);
            exit(EXIT_FAILURE);
        }
    }
}

double read_pressure(int i2c_handle, uint16_t *coefficients) {
    if (i2cWriteByteData(i2c_handle, 0xF4, 0x34) < 0) {
        fprintf(stderr, "Failed to write to BMP180 control register\n");
        exit(EXIT_FAILURE);
    }
    usleep(5000);

    uint8_t msb = i2cReadByteData(i2c_handle, 0xF6);
    uint8_t lsb = i2cReadByteData(i2c_handle, 0xF7);
    uint8_t xlsb = i2cReadByteData(i2c_handle, 0xF8);

    if (msb == PI_I2C_READ_FAILED || lsb == PI_I2C_READ_FAILED || xlsb == PI_I2C_READ_FAILED) {
        fprintf(stderr, "Failed to read pressure data\n");
        exit(EXIT_FAILURE);
    }

    int32_t up = (msb << 16) | (lsb << 8) | xlsb;

    int32_t x1 = (up - (int32_t)coefficients[0] * 2) * (int32_t)coefficients[1] / 2048;
    int32_t x2 = (int32_t)coefficients[2] * up / 4096;
    int32_t b5 = x1 + x2;
    int32_t b3 = ((b5 + 8) >> 4) + ((int32_t)coefficients[4] * 2);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)coefficients[5] * b6 * b6) / 2048;
    int32_t x2 = (b6 * (int32_t)coefficients[6]) / 64;
    int32_t x3 = (x1 + x2 + 2) / 4;
    uint32_t b4 = (uint32_t)coefficients[3] * (x3 + 32768) / 256;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t pressure = b7 < 0x80000000 ? (b7 * 2) / b4 : (b7 / b4) * 2;

    return pressure / 100.0;
}

void sample_pressure(int i2c_handle, uint16_t *coefficients) {
    double pressure = read_pressure(i2c_handle, coefficients);
    buffer[buffer_index].pressure = pressure;
    buffer[buffer_index].timestamp = gpioTick();
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    double sum = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i].pressure;
    }
    double average = sum / BUFFER_SIZE;

    if (fabs(pressure - average) > ALERT_THRESHOLD) {
        if (!alert_active) {
            gpioWrite(ALERT_GPIO, PI_HIGH);
            fprintf(stderr, "Alert: Pressure deviation exceeded threshold\n");
            alert_active = 1;
        }
    } else {
        if (alert_active) {
            gpioWrite(ALERT_GPIO, PI_LOW);
            fprintf(stderr, "Alert: Pressure deviation within threshold\n");
            alert_active = 0;
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    int i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t coefficients[11];
    read_calibration_coefficients(i2c_handle, coefficients);

    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, PI_LOW);

    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, sample_pressure, (void *)(intptr_t)i2c_handle);

    while (1) {
        sleep(1);
    }

    return 0;
}

