        perror("Failed to write pressure command");
        return -1;
    }
    usleep(4500 + 250 * (1 << BMP180_OSS)); // Wait for conversion

    uint32_t up = (i2cReadWordData(handle, BMP180_REG_RESULT) << 8) | i2cReadByte(handle, BMP180_REG_RESULT + 2);
    if (up == -1) {
        perror("Failed to read pressure data");
        return -1;
    }

    // Placeholder for calibration calculations
    double pressure = up / 100.0;
    return pressure;
}

void timer_callback() {
    int handle = i2cOpen(I2C_BUS, BMP180_I2C_ADDR, 0);
    if (handle < 0) {
        perror("Failed to open I2C device");
        return;
    }

    if (read_calib_data(handle) < 0) {
        i2cClose(handle);
        return;
    }

    double temperature = read_temperature(handle);
    if (temperature < 0) {
        i2cClose(handle);
        return;
    }

    double pressure = read_pressure(handle);
    if (pressure < 0) {
        i2cClose(handle);
        return;
    }

    log_data(temperature, pressure);
    i2cClose(handle);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = &timer_callback;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGALRM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    struct itimerval timer;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_usec = SAMPLE_INTERVAL_US;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_usec = SAMPLE_INTERVAL_US;
    if (setitimer(ITIMER_REAL, &timer, NULL) < 0) {
        perror("setitimer");
        gpioTerminate();
        return 1;
    }

    while (running) {
        pause();
    }

    gpioTerminate();
    return 0;
}

