#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define FAN_GPIO 18
#define PWM_FREQ 25000
#define DUTY_MIN 0
#define DUTY_MAX 255
#define TEMP_MIN 40000
#define TEMP_MAX 70000
#define LOG_FILE "fan_log.txt"
#define LOG_INTERVAL 5

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    int temp;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        perror("Failed to open temperature file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Failed to read temperature");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    temp = atoi(buffer);
    return temp;
}

int calculate_duty(int temp) {
    if (temp < TEMP_MIN) return DUTY_MIN;
    if (temp > TEMP_MAX) return DUTY_MAX;

    return (temp - TEMP_MIN) * (DUTY_MAX - DUTY_MIN) / (TEMP_MAX - TEMP_MIN);
}

void log_data(int temp, int duty) {
    FILE *log;
    time_t now;
    struct tm *tm_info;

    log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    time(&now);
    tm_info = localtime(&now);

    fprintf(log, "%04d-%02d-%02d %02d:%02d:%02d - Temp: %d°C, Duty: %d\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            temp / 1000, duty);

    fclose(log);
}

int main() {
    int temp, duty;
    struct sigaction sa;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ);

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        temp = read_cpu_temp();
        if (temp < 0) {
            sleep(LOG_INTERVAL);
            continue;
        }

        duty = calculate_duty(temp);
        gpioPWM(FAN_GPIO, duty);
        log_data(temp, duty);

        sleep(LOG_INTERVAL);
    }

    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

