#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pthread.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define LM75_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define LED_PIN 18

volatile sig_atomic_t running = 1;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t lock;
} CircularBuffer;

CircularBuffer temp_buffer;

void signal_handler(int sig) {
    running = 0;
}

void* read_temp_thread(void* arg) {
    int i2c_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *led_line;
    float temp;
    int16_t raw_temp;
    float sum = 0.0;
    int i;

    if (pthread_mutex_init(&temp_buffer.lock, NULL) != 0) {
        fprintf(stderr, "Failed to initialize mutex\n");
        exit(EXIT_FAILURE);
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "lm75_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        if (read(i2c_fd, &raw_temp, 2) != 2) {
            perror("Failed to read from I2C");
            close(i2c_fd);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        temp = (float)raw_temp / 256.0;

        pthread_mutex_lock(&temp_buffer.lock);
        temp_buffer.buffer[temp_buffer.head] = temp;
        if (temp_buffer.count < BUFFER_SIZE) {
            temp_buffer.count++;
        }
        temp_buffer.head = (temp_buffer.head + 1) % BUFFER_SIZE;

        sum = 0.0;
        for (i = 0; i < temp_buffer.count; i++) {
            sum += temp_buffer.buffer[i];
        }
        float average = sum / temp_buffer.count;
        pthread_mutex_unlock(&temp_buffer.lock);

        if (temp > 28.0) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        printf("Temperature: %.2f°C, Average: %.2f°C\n", temp, average);
        sleep(1);
    }

    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    pthread_mutex_destroy(&temp_buffer.lock);

    return NULL;
}

int main() {
    pthread_t thread;

    signal(SIGINT, signal_handler);

    if (pthread_create(&thread, NULL, read_temp_thread, NULL) != 0) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    pthread_join(thread, NULL);

    return 0;
}

