#include <wiringPiSPI.h>
#include <json-c/json.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define RTD_REF_RESISTANCE 430.0
#define RTD_NOMINAL_RESISTANCE 100.0
#define RTD_A 0.0039083
#define RTD_B -0.0000005772
#define RTD_C -0.000000000004183
#define PWM_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define TARGET_TEMP 25.0
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define CONTROL_INTERVAL 100000 // 100 ms in microseconds
#define FAULT_SHUTDOWN_TEMP 80.0

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

double rtd_code_to_resistance(uint16_t code) {
    return (code / 32768.0) * RTD_REF_RESISTANCE;
}

double resistance_to_temperature(double resistance) {
    double t = (resistance / RTD_NOMINAL_RESISTANCE - 1.0);
    double t2 = t * t;
    double t3 = t2 * t;
    return t * (1.0 + RTD_A + RTD_B * t + RTD_C * t3);
}

uint16_t read_rtd_code(int spi_fd) {
    uint8_t tx[2] = {0x01, 0x00};
    uint8_t rx[2];
    if (wiringPiSPIDataRW(SPI_CHANNEL, tx, 2) < 0) {
        perror("SPI read failed");
        return 0xFFFF; // Invalid code
    }
    return ((uint16_t)rx[0] << 8) | rx[1];
}

void init_max31865(int spi_fd) {
    uint8_t config = 0xC1;
    uint8_t tx[2] = {0x80, config};
    if (wiringPiSPIDataRW(SPI_CHANNEL, tx, 2) < 0) {
        perror("SPI write failed");
        exit(EXIT_FAILURE);
    }
}

void check_faults(int spi_fd) {
    uint8_t tx[2] = {0x07, 0x00};
    uint8_t rx[1];
    if (wiringPiSPIDataRW(SPI_CHANNEL, tx, 2) < 0) {
        perror("SPI read failed");
        exit(EXIT_FAILURE);
    }
    if (rx[0] & 0x01) {
        fprintf(stderr, "Open circuit fault detected\n");
        exit(EXIT_FAILURE);
    }
    if (rx[0] & 0x02) {
        fprintf(stderr, "Short to VCC fault detected\n");
        exit(EXIT_FAILURE);
    }
    if (rx[0] & 0x04) {
        fprintf(stderr, "Short to GND fault detected\n");
        exit(EXIT_FAILURE);
    }
}

void load_config(const char *filename, double *target_temp, double *Kp, double *Ki, double *Kd) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open config file, using defaults\n");
        return;
    }
    struct json_object *parsed_json;
    parsed_json = json_object_from_file(filename);
    if (!parsed_json) {
        fprintf(stderr, "Failed to parse JSON, using defaults\n");
        fclose(file);
        return;
    }
    if (json_object_object_get_ex(parsed_json, "target", &parsed_json)) {
        *target_temp = json_object_get_double(parsed_json);
    }
    if (json_object_object_get_ex(parsed_json, "Kp", &parsed_json)) {
        *Kp = json_object_get_double(parsed_json);
    }
    if (json_object_object_get_ex(parsed_json, "Ki", &parsed_json)) {
        *Ki = json_object_get_double(parsed_json);
    }
    if (json_object_object_get_ex(parsed_json, "Kd", &parsed_json)) {
        *Kd = json_object_get_double(parsed_json);
    }
    json_object_put(parsed_json);
    fclose(file);
}

int main(int argc, char *argv[]) {
    double target_temp = TARGET_TEMP;
    double Kp = Kp;
    double Ki = Ki;
    double Kd = Kd;
    load_config("config.json", &target_temp, &Kp, &Ki, &Kd);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    int spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    init_max31865(spi_fd);

    double integral = 0.0;
    double last_error = 0.0;
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
