        double error = target_temp - temperature;
        integral += error * CONTROL_INTERVAL / 1000000.0;
        double derivative = (error - last_error) / (CONTROL_INTERVAL / 1000000.0);
        double output = Kp * error + Ki * integral + Kd * derivative;
        if (output < 0) output = 0;
        if (output > PWM_RANGE) output = PWM_RANGE;
        gpioPWM(PWM_GPIO, (int)output);
        last_error = error;
        usleep(CONTROL_INTERVAL);
    }

    gpioPWM(PWM_GPIO, 0);
    gpioTerminate();
    close(spi_fd);
    return EXIT_SUCCESS;
