#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define BMP180_I2C_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_RESULT 0xF6
#define BMP180_TEMP_CONVERSION 0x2E
#define BMP180_PRESSURE_CONVERSION 0x34
#define BMP180_OVERSAMPLING_ULTRA_HIGH_RES 0x3F

#define TEMP_THRESHOLD 3000 // 30.0°C in millidegrees Celsius
#define PRESSURE_THRESHOLD 95000 // 950 hPa in millipascals

#define I2C_DEVICE "/dev/i2c-1"
#define MAX_RETRIES 3

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int i2c_write_byte(int reg, int value) {
    unsigned char buf[2] = {reg, value};
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write(i2c_fd, buf, 2) == 2) {
            return 0;
        }
        retries++;
        perror("i2c_write_byte");
        sleep(1);
    }
    return -1;
}

int i2c_read_bytes(int reg, unsigned char *buf, int len) {
    if (i2c_write_byte(reg, 0) < 0) {
        return -1;
    }
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (read(i2c_fd, buf, len) == len) {
            return 0;
        }
        retries++;
        perror("i2c_read_bytes");
        sleep(1);
    }
    return -1;
}

int bmp180_read_raw_temp() {
    unsigned char buf[2];
    if (i2c_write_byte(BMP180_REG_CONTROL, BMP180_TEMP_CONVERSION) < 0) {
        return -1;
    }
    usleep(5000); // Wait for conversion
    if (i2c_read_bytes(BMP180_REG_RESULT, buf, 2) < 0) {
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

int bmp180_read_raw_pressure() {
    unsigned char buf[3];
    if (i2c_write_byte(BMP180_REG_CONTROL, BMP180_PRESSURE_CONVERSION | BMP180_OVERSAMPLING_ULTRA_HIGH_RES) < 0) {
        return -1;
    }
    usleep(75000); // Wait for conversion
    if (i2c_read_bytes(BMP180_REG_RESULT, buf, 3) < 0) {
        return -1;
    }
    return ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OVERSAMPLING_ULTRA_HIGH_RES);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("breach_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        int raw_temp = bmp180_read_raw_temp();
        if (raw_temp < 0) {
            fprintf(log_file, "Error reading temperature\n");
            fflush(log_file);
            continue;
        }

        int raw_pressure = bmp180_read_raw_pressure();
        if (raw_pressure < 0) {
            fprintf(log_file, "Error reading pressure\n");
            fflush(log_file);
            continue;
        }

        if (raw_temp > TEMP_THRESHOLD || raw_pressure < PRESSURE_THRESHOLD) {
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            timestamp[strcspn(timestamp, "\n")] = 0; // Remove newline

            fprintf(log_file, "%s: Temperature = %d m°C, Pressure = %d mPa\n", timestamp, raw_temp, raw_pressure);
            fflush(log_file);
        }

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

