    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    // Read uncompensated temperature
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, (0x2E | (BMP180_TEMP_OSS << 6))) != 0) {
        fprintf(stderr, "Failed to write temperature control\n");
        return;
    }
    gpioDelay(5000); // Wait for conversion

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_RESULT, (char *)data, 2) != 2) {
        fprintf(stderr, "Failed to read temperature result\n");
        return;
    }

    ut = (data[0] << 8) | data[1];

    // Read uncompensated pressure
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, (0x34 | (BMP180_PRESS_OSS << 6))) != 0) {
        fprintf(stderr, "Failed to write pressure control\n");
        return;
    }
    gpioDelay(8000); // Wait for conversion

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_RESULT, (char *)data, 3) != 3) {
        fprintf(stderr, "Failed to read pressure result\n");
        return;
    }

    up = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_PRESS_OSS);

    // Calculate true temperature
    int32_t x1 = (ut - ac6) * ac5 / 32768;
    int32_t x2 = mc * 2048 / (x1 + md);
    int32_t b5 = x1 + x2;
    float temperature = (b5 + 8) / 16.0;

    // Calculate true pressure
    int32_t b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6 / 4096)) / 2048;
    x2 = ac2 * b6 / 2048;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((ac1 * 4 + x3) << BMP180_PRESS_OSS) + 2) / 4;
    x1 = ac3 * b6 / 8192;
    x2 = (b1 * (b6 * b6 / 4096)) / 65536;
    x3 = ((x1 + x2) + 2) / 4;
    uint32_t b4 = ac4 * (uint32_t)(32768 + x3);
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_PRESS_OSS);
    int32_t pressure;
    if (b7 < 0x80000000) {
        pressure = (b7 * 2) / b4;
    } else {
        pressure = (b7 / b4) * 2;
    }
    x1 = (pressure / 256) * (pressure / 256);
    x1 = (x1 * 3038) / 65536;
    x2 = (-7357 * pressure) / 65536;
    pressure = pressure + (x1 + x2 + 3791) / 16;

    // Store reading in buffer
    clock_gettime(CLOCK_REALTIME, &buffer[buffer_index].timestamp);
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    // Print reading
    printf("Timestamp: %ld.%09ld, Temperature: %.2f°C, Pressure: %.2fPa\n",
           buffer[buffer_index].timestamp.tv_sec, buffer[buffer_index].timestamp.tv_nsec,
           buffer[buffer_index].temperature, buffer[buffer_index].pressure);

    // Control fan
    if (temperature > 30.0) {
        gpioWrite(fan_handle, PI_HIGH);
    } else {
        gpioWrite(fan_handle, PI_LOW);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP180_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        gpioTerminate();
        return 1;
    }

    fan_handle = gpioSetMode(FAN_GPIO, PI_OUTPUT);
    if (fan_handle < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    timer_id = gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, sample_sensor, NULL);
    if (timer_id < 0) {
        fprintf(stderr, "Timer initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        gpioDelay(1000000); // Sleep for 1 second
    }

    return 0;
}
