#include <pigpio.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 2000000
#define TARGET_TEMP 25.0
#define MAX_DUTY_CYCLE 0.8
#define Kp 1.0
#define Ki 0.1
#define Kd 0.05
#define LOG_FILE "heater_log.csv"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_entry(FILE *log, double temp, double duty) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log, "%s,%.2f,%.2f\n", timestamp, temp, duty);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for heater\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double integral = 0.0;
    double last_error = 0.0;
    double last_time = 0.0;

    while (running) {
        double current_time = time(NULL);
        double dt = current_time - last_time;
        if (dt <= 0) continue;

        uint8_t spi_data[4];
        if (spiXfer(spi_handle, spi_data, spi_data, 4) < 0) {
            fprintf(log, "SPI read failed\n");
            gpioPWM(HEATER_GPIO, 0);
            log_entry(log, -1.0, 0.0);
            last_time = current_time;
            continue;
        }

        uint32_t raw_temp = (spi_data[0] << 16) | (spi_data[1] << 8) | spi_data[2];
        if (raw_temp & 0x800000) {
            fprintf(log, "MAX31855 fault detected\n");
            gpioPWM(HEATER_GPIO, 0);
            log_entry(log, -1.0, 0.0);
            last_time = current_time;
            continue;
        }

        double temp = (raw_temp >> 18) * 0.25;

        double error = TARGET_TEMP - temp;
        integral += error * dt;
        double derivative = (error - last_error) / dt;

        double duty_cycle = Kp * error + Ki * integral + Kd * derivative;
        if (duty_cycle > MAX_DUTY_CYCLE) {
            duty_cycle = MAX_DUTY_CYCLE;
            integral -= error * dt; // Anti-windup
        } else if (duty_cycle < 0) {
            duty_cycle = 0;
        }

        gpioPWM(HEATER_GPIO, (uint32_t)(duty_cycle * 1000000));

        log_entry(log, temp, duty_cycle);

        last_error = error;
        last_time = current_time;
        usleep(100000); // 100 ms
    }

    gpioPWM(HEATER_GPIO, 0);
    spiClose(spi_handle);
    fclose(log);
    gpioTerminate();

    return EXIT_SUCCESS;
}
```

This code provides a robust implementation for controlling a resistive heater using a solid-state relay on a Raspberry Pi 3 Model B+ with the pigpio library. It reads temperature data from a MAX31855 thermocouple amplifier over SPI, implements a PI controller with anti-windup, and logs temperature and PWM duty cycle to a CSV file. The program handles errors, graceful shutdown, and signal interrupts.

