#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void set_rgb(int red, int green, int blue) {
    gpioPWM(RED_PIN, 255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN, 255 - blue);
}

int read_temperature() {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("Failed to open temperature file");
        return -1;
    }

    char buffer[12];
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Failed to read temperature");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *endptr;
    long temp = strtol(buffer, &endptr, 10);
    if (endptr == buffer || *endptr != '\n' || temp < 0) {
        fprintf(stderr, "Invalid temperature value: %s\n", buffer);
        return -1;
    }

    return (int)temp;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int temp = read_temperature();
        if (temp != -1) {
            int red = 0, green = 0, blue = 0;

            if (temp < 40000) {
                blue = 255;
            } else if (temp < 60000) {
                green = 255;
            } else {
                red = 255;
            }

            set_rgb(red, green, blue);
            printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temp, red, green, blue);
        }

        usleep(500000); // 0.5 seconds
    }

    set_rgb(255, 255, 255); // Turn off all channels
    gpioTerminate();

    return EXIT_SUCCESS;
}

