#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_dht22(int gpio) {
    uint8_t data[5] = {0};
    int bits[40] = {0};
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Send start signal
        gpioWrite(gpio, PI_LOW);
        gpioDelay(1000); // 1 ms
        gpioWrite(gpio, PI_HIGH);
        gpioDelay(30); // 30 us

        // Wait for response
        if (gpioRead(gpio) == PI_LOW) {
            gpioDelay(80); // 80 us
            for (int i = 0; i < 40; i++) {
                while (gpioRead(gpio) == PI_LOW); // Wait for low
                gpioDelay(40); // 40 us
                bits[i] = gpioRead(gpio);
                while (gpioRead(gpio) == PI_HIGH); // Wait for high
            }
            break;
        }
        retries++;
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read from DHT22 after %d retries\n", MAX_RETRIES);
        return -1;
    }

    // Parse data
    for (int i = 0; i < 8; i++) {
        data[0] <<= 1;
        data[0] |= bits[i];
    }
    for (int i = 8; i < 16; i++) {
        data[1] <<= 1;
        data[1] |= bits[i];
    }
    for (int i = 16; i < 24; i++) {
        data[2] <<= 1;
        data[2] |= bits[i];
    }
    for (int i = 24; i < 32; i++) {
        data[3] <<= 1;
        data[3] |= bits[i];
    }
    for (int i = 32; i < 40; i++) {
        data[4] <<= 1;
        data[4] |= bits[i];
    }

    // Validate checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    return 0;
}

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    return size * nmemb;
}

int post_data(const char *url, const char *json) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    }
    curl_global_cleanup();

    return res == CURLE_OK ? 0 : -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, PI_HIGH);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (read_dht22(DHT22_GPIO) == 0) {
            char json[100];
            snprintf(json, sizeof(json), "{\"temperature\":%.1f,\"humidity\":%.1f}",
                     (data[2] * 256 + data[3]) / 10.0, (data[0] * 256 + data[1]) / 10.0);

            if (post_data("http://yourserver.com/api/humidity", json) != 0) {
                fprintf(stderr, "Failed to post data\n");
            }
        }
        sleep(60); // Read every 60 seconds
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

