#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define BMP180_I2C_ADDR 0x77
#define BMP180_I2C_BUS 1
#define BMP180_OSS 3
#define BMP180_CONVERSION_DELAY_US 26000
#define DEBOUNCE_US 200000
#define LOG_FILE "pressure_log.txt"

volatile int logging_enabled = 0;
volatile uint32_t last_interrupt_tick = 0;

typedef struct {
    uint16_t ac1;
    uint16_t ac2;
    uint16_t ac3;
    uint16_t b1;
    uint16_t b2;
    uint16_t mb;
    uint16_t mc;
    uint16_t md;
} bmp180_calib_coeffs;

bmp180_calib_coeffs calib_coeffs;

void log_pressure(int fd, int32_t pressure) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: Pressure = %d hPa\n", timestamp, pressure);
    fclose(log_file);
}

void button_isr(int gpio, int level, uint32_t tick) {
    if (level == PI_LOW) {
        uint32_t current_tick = gpioTick();
        if (current_tick - last_interrupt_tick > DEBOUNCE_US) {
            last_interrupt_tick = current_tick;
            logging_enabled = !logging_enabled;
            if (logging_enabled) {
                printf("Logging enabled\n");
            } else {
                printf("Logging disabled\n");
            }
        }
    }
}

int32_t bmp180_read_raw_pressure(int fd) {
    uint8_t oss = BMP180_OSS;
    uint8_t control = 0x34 | (oss << 6);
    if (i2cWriteByteData(fd, 0xF4, control) < 0) {
        perror("Failed to write to BMP180 control register");
        return -1;
    }

    usleep(BMP180_CONVERSION_DELAY_US);

    uint8_t msb, lsb, xlsb;
    if (i2cReadI2CBlockData(fd, 0xF6, &msb, 1) < 0 ||
        i2cReadI2CBlockData(fd, 0xF7, &lsb, 1) < 0 ||
        i2cReadI2CBlockData(fd, 0xF8, &xlsb, 1) < 0) {
        perror("Failed to read from BMP180 pressure registers");
        return -1;
    }

    return ((int32_t)msb << 16) | ((int32_t)lsb << 8) | (int32_t)xlsb;
}

int32_t bmp180_calculate_pressure(int32_t ut, int32_t up) {
    int32_t x1, x2, x3, b3, b5, b6, p;
    uint32_t b4, b7;

    x1 = ((int32_t)ut - (int32_t)calib_coeffs.ac6) * (int32_t)calib_coeffs.ac5 >> 15;
    x2 = ((int32_t)calib_coeffs.mc << 11) / (x1 + calib_coeffs.md);
    b5 = x1 + x2;

    b6 = b5 - 4000;
    x1 = (calib_coeffs.b2 * (b6 * b6 >> 12)) >> 11;
    x2 = (calib_coeffs.ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = ((((int32_t)calib_coeffs.ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2;

    x1 = (calib_coeffs.ac3 * b6) >> 13;
    x2 = (calib_coeffs.b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (calib_coeffs.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);

    if (b7 < 0x80000000) {
        p = (b7 << 1) / b4;
    } else {
        p = (b7 / b4) << 1;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    return p;
}

int32_t bmp180_read_pressure(int fd) {
    int32_t ut = bmp180_read_raw_temperature(fd);
    if (ut < 0) {
        return -1;
    }

    int32_t up = bmp180_read_raw_pressure(fd);
    if (up < 0) {
        return -1;
    }

    return bmp180_calculate_pressure(ut, up);
}

int32_t bmp180_read_raw_temperature(int fd) {
    if (i2cWriteByteData(fd, 0xF4, 0x2E) < 0) {
        perror("Failed to write to BMP180 control register for temperature");
        return -1;
    }

    usleep(4500);

    uint8_t msb, lsb;
    if (i2cReadI2CBlockData(fd, 0xF6, &msb, 1) < 0 ||
        i2cReadI2CBlockData(fd, 0xF7, &lsb, 1) < 0) {
        perror("Failed to read from BMP180 temperature registers");
        return -1;
    }

    return ((int32_t)msb << 8) | (int32_t)lsb;
}

int32_t bmp180_calculate_temperature(int32_t ut) {
    int32_t x1, x2;

    x1 = ((int32_t)ut - (int32_t)calib_coeffs.ac6) * (int32_t)calib_coeffs.ac5 >> 15;
    x2 = ((int32_t)calib_coeffs.mc << 11) / (x1 + calib_coeffs.md);
    return (x1 + x2 + 8) >> 4;
}

int32_t bmp180_read_temperature(int fd) {
    int32_t ut = bmp180_read_raw_temperature(fd);
    if (ut < 0) {
        return -1;
    }

    return bmp180_calculate_temperature(ut);
}

void signal_handler(int signum) {
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetISRFunc(4, FALLING_EDGE, DEBOUNCE_US, button_isr) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    int fd = i2cOpen(BMP180_I2C_BUS, BMP180_I2C_ADDR, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    for (int i = 0; i < 8; i++) {
        uint8_t reg = 0xAA + i * 2;
        uint16_t value = i2cReadWordData(fd, reg);
        if (value < 0) {
            fprintf(stderr, "Failed to read calibration coefficient from register 0x%02X\n", reg);
            i2cClose(fd);
            gpioTerminate();
            return 1;
        }

        switch (reg) {
            case 0xAA: calib_coeffs.ac1 = value; break;
            case 0xAC: calib_coeffs.ac2 = value; break;
            case 0xAE: calib_coeffs.ac3 = value; break;
            case 0xB0: calib_coeffs.b1 = value; break;
