#include <pigpio.h>
#include <curl/curl.h>

#define GPIO_PIN 4
#define DEFAULT_URL "http://your-server.com/api/humidity"
#define MAX_RETRIES 3
#define READ_INTERVAL 10

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_dht22(int gpio) {
    int bits[40] = {0};
    int bit_count = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Start signal
        gpioWrite(gpio, PI_LOW);
        gpioDelay(1000); // 1 ms
        gpioWrite(gpio, PI_HIGH);
        gpioDelay(40); // 20-40 µs

        // Wait for response
        gpioSetMode(gpio, PI_INPUT);
        gpioSetPullUpDn(gpio, PI_PUD_UP);
        gpioDelay(10); // 10 µs

        // Read response
        for (int i = 0; i < 40; i++) {
            while (gpioRead(gpio) == PI_HIGH) {
                if (gpioTick() > 10000) {
                    syslog(LOG_ERR, "Timeout waiting for response");
                    goto retry;
                }
            }
            gpioDelay(30); // 30 µs
            bits[i] = gpioRead(gpio);
            while (gpioRead(gpio) == PI_LOW) {
                if (gpioTick() > 10000) {
                    syslog(LOG_ERR, "Timeout waiting for response");
                    goto retry;
                }
            }
        }

        // Validate checksum
        int humidity = (bits[0] << 8) | bits[1];
        int temperature = (bits[2] << 8) | bits[3];
        int checksum = bits[4];
        if (checksum == ((humidity & 0xFF) + (humidity >> 8) + (temperature & 0xFF) + (temperature >> 8))) {
            return humidity;
        } else {
            syslog(LOG_ERR, "Checksum failure");
        }

retry:
        retries++;
        gpioDelay(2000000); // 2 seconds
    }

    syslog(LOG_ERR, "Failed to read from DHT22 after %d retries", MAX_RETRIES);
    return -1;
}

int post_humidity(const char *url, int humidity) {
    CURL *curl;
    CURLcode res;
    char json[100];
    snprintf(json, sizeof(json), "{\"humidity\": %d}", humidity);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        } else {
            long http_code = 0;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
            if (http_code < 200 || http_code >= 300) {
                syslog(LOG_ERR, "HTTP response code: %ld", http_code);
            } else {
                syslog(LOG_INFO, "Humidity posted successfully");
            }
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    } else {
        syslog(LOG_ERR, "Failed to initialize libcurl");
        return -1;
    }

    curl_global_cleanup();
    return 0;
}

int main(int argc, char *argv[]) {
    const char *url = DEFAULT_URL;
    int opt;

    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <url>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    openlog("dht22_poster", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        closelog();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int humidity = read_dht22(GPIO_PIN);
        if (humidity >= 0) {
            if (post_humidity(url, humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity");
            }
        }
        sleep(READ_INTERVAL);
    }

    gpioTerminate();
    closelog();
    return 0;
}

