#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/stat.h>
#include <sys/types.h>

#define TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define COOLING_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_STATE_PATH "/sys/class/thermal/cooling_device0/max_state"
#define LOG_PATH "/var/log/fan_control.log"

#define RETRY_DELAY 1
#define READ_BUFFER_SIZE 10

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_PATH, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%s: %s\n", asctime(tm_info), message);
    fclose(log_file);
}

int read_file(const char *path, char *buffer, size_t size) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file");
        return -1;
    }

    ssize_t bytes_read = read(fd, buffer, size - 1);
    if (bytes_read == -1) {
        perror("Failed to read file");
        close(fd);
        return -1;
    }

    buffer[bytes_read] = '\0';
    close(fd);
    return 0;
}

int write_file(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd == -1) {
        perror("Failed to open file");
        return -1;
    }

    if (write(fd, value, strlen(value)) == -1) {
        perror("Failed to write file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int get_max_state() {
    char buffer[READ_BUFFER_SIZE];
    if (read_file(MAX_STATE_PATH, buffer, sizeof(buffer)) == -1) {
        return -1;
    }

    return atoi(buffer);
}

int get_cpu_temperature() {
    char buffer[READ_BUFFER_SIZE];
    if (read_file(TEMP_PATH, buffer, sizeof(buffer)) == -1) {
        return -1;
    }

    return atoi(buffer);
}

void set_fan_state(int state) {
    static int last_state = -1;
    if (state == last_state) {
        return;
    }

    char state_str[2];
    snprintf(state_str, sizeof(state_str), "%d", state);

    if (write_file(COOLING_PATH, state_str) == -1) {
        return;
    }

    last_state = state;
    char log_message[100];
    snprintf(log_message, sizeof(log_message), "Fan state set to %d", state);
    log_message(log_message);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int max_state = get_max_state();
    if (max_state == -1) {
        log_message("Failed to get max state");
        return EXIT_FAILURE;
    }

    while (running) {
        int cpu_temp = get_cpu_temperature();
        if (cpu_temp == -1) {
            log_message("Failed to read CPU temperature");
            sleep(RETRY_DELAY);
            continue;
        }

        int fan_state = 0;
        if (cpu_temp >= 65000) {
            fan_state = 3;
        } else if (cpu_temp >= 55000) {
            fan_state = 2;
        } else if (cpu_temp >= 45000) {
            fan_state = 1;
        }

        if (fan_state > max_state) {
            fan_state = max_state;
        }

        set_fan_state(fan_state);
        sleep(5);
    }

    set_fan_state(0);
    log_message("Fan control shutting down");
    return EXIT_SUCCESS;
}

