#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/time.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_CLK 11
#define SPI_CS 8
#define SPI_DO 9
#define PWM_FREQ 1000
#define SAMPLE_RATE 500000
#define LOG_FILE "heater_log.txt"
#define TARGET_TEMP 50.0
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define MAX_TEMP 100.0
#define MIN_TEMP 0.0

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_message(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s\n", message);
        fclose(log);
    }
}

double read_temperature() {
    uint32_t data;
    int status = spiXfer(SPI_CHANNEL, NULL, (char *)&data, 4);
    if (status < 0) {
        log_message("SPI communication error");
        return -1.0;
    }

    if (data & 0x01) {
        log_message("MAX31855 fault detected");
        return -1.0;
    }

    if (data & 0x02) {
        log_message("MAX31855 open circuit");
        return -1.0;
    }

    if (data & 0x04) {
        log_message("MAX31855 short to GND");
        return -1.0;
    }

    if (data & 0x08) {
        log_message("MAX31855 short to VCC");
        return -1.0;
    }

    int32_t temp = (data >> 18) & 0x3FFF;
    if (temp & 0x2000) {
        temp |= 0xFFFFC000;
    }

    return temp * 0.25;
}

void pid_control(double target, double current, double *integral, double *prev_error, double *output) {
    double error = target - current;
    *integral += error;
    double derivative = error - *prev_error;
    *output = Kp * error + Ki * *integral + Kd * derivative;
    *prev_error = error;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(HEATER_GPIO, 100) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMdutycycle(HEATER_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        gpioTerminate();
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SAMPLE_RATE, 0) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    double integral = 0.0;
    double prev_error = 0.0;
    double output = 0.0;
    struct timeval last_log_time;
    gettimeofday(&last_log_time, NULL);

    while (running) {
        double current_temp = read_temperature();
        if (current_temp < 0.0) {
            gpioSetPWMdutycycle(HEATER_GPIO, 0);
            integral = 0.0;
            prev_error = 0.0;
            output = 0.0;
            continue;
        }

        if (current_temp > MAX_TEMP || current_temp < MIN_TEMP) {
            gpioSetPWMdutycycle(HEATER_GPIO, 0);
            log_message("Temperature out of safe range");
            integral = 0.0;
            prev_error = 0.0;
            output = 0.0;
            continue;
        }

        pid_control(TARGET_TEMP, current_temp, &integral, &prev_error, &output);
        if (output < 0.0) {
            output = 0.0;
        } else if (output > 100.0) {
            output = 100.0;
        }

        gpioSetPWMdutycycle(HEATER_GPIO, output);

        struct timeval current_time;
        gettimeofday(&current_time, NULL);
        if (current_time.tv_sec - last_log_time.tv_sec >= 1) {
            char log_entry[256];
            snprintf(log_entry, sizeof(log_entry), "Temperature: %.2f°C, PWM: %.2f%%, PID Output: %.2f", current_temp, output, output);
            log_message(log_entry);
            gettimeofday(&last_log_time, NULL);
        }

        usleep(100000); // 100 ms
    }

    gpioSetPWMdutycycle(HEATER_GPIO, 0);
    spiClose(SPI_CHANNEL);
    gpioTerminate();
    return 0;
}

