#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/time.h>

#define GPIO_PIN 18
#define PWM_FREQ 25000
#define TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define SAMPLE_INTERVAL 5

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_temperature_and_duty(FILE *log_file, double temperature, double duty_cycle) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file);
}

double read_temperature() {
    FILE *temp_file = fopen(TEMP_PATH, "r");
    if (!temp_file) {
        perror("Failed to open temperature file");
        exit(EXIT_FAILURE);
    }

    char buffer[10];
    if (fgets(buffer, sizeof(buffer), temp_file) == NULL) {
        perror("Failed to read temperature");
        fclose(temp_file);
        exit(EXIT_FAILURE);
    }

    fclose(temp_file);
    return atof(buffer) / 1000.0; // Convert millidegrees to degrees Celsius
}

double calculate_duty_cycle(double temperature) {
    if (temperature <= 40.0) {
        return 0.0;
    } else if (temperature >= 70.0) {
        return 100.0;
    } else {
        return (temperature - 40.0) * 100.0 / 30.0;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(GPIO_PIN, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Temperature (°C),Duty Cycle (%)\n");
    fflush(log_file);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        double temperature = read_temperature();
        double duty_cycle = calculate_duty_cycle(temperature);

        if (gpioSetPWMrange(GPIO_PIN, 100) < 0) {
            fprintf(stderr, "Failed to set PWM range\n");
            break;
        }

        if (gpioSetPWMdutycycle(GPIO_PIN, (unsigned int)duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }

        log_temperature_and_duty(log_file, temperature, duty_cycle);
        sleep(SAMPLE_INTERVAL);
    }

    gpioSetPWMdutycycle(GPIO_PIN, 0);
    gpioTerminate();
    fclose(log_file);

    return EXIT_SUCCESS;
}

