#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define CONTINUOUS_MEASUREMENT_CMD 0x3608
#define CRC8_POLYNOMIAL 0x07
#define MAX_RETRIES 3

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

uint8_t calculate_crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(int handle, uint8_t addr, uint8_t *data, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cWriteByte(handle, (CONTINUOUS_MEASUREMENT_CMD >> 8) & 0xFF) == 0 &&
            i2cWriteByte(handle, CONTINUOUS_MEASUREMENT_CMD & 0xFF) == 0 &&
            i2cReadDevice(handle, data, len) == len) {
            return 0;
        }
        retries++;
        time_sleep(0.1);
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int sensor1_handle = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    int sensor2_handle = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);

    if (sensor1_handle < 0 || sensor2_handle < 0) {
        fprintf(stderr, "Failed to open I2C devices\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(sensor1_handle);
        i2cClose(sensor2_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t sensor1_data[3];
        uint8_t sensor2_data[3];

        if (read_sensor(sensor1_handle, SENSOR1_ADDR, sensor1_data, 3) == 0 &&
            read_sensor(sensor2_handle, SENSOR2_ADDR, sensor2_data, 3) == 0) {
            if (sensor1_data[2] == calculate_crc8(sensor1_data, 2) &&
                sensor2_data[2] == calculate_crc8(sensor2_data, 2)) {
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

                float flow1 = (sensor1_data[0] << 8 | sensor1_data[1]) * 0.01;
                float flow2 = (sensor2_data[0] << 8 | sensor2_data[1]) * 0.01;

                fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
                fflush(log_file);
            }
        }

        time_sleep(1.0);
    }

    fclose(log_file);
    i2cClose(sensor1_handle);
    i2cClose(sensor2_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

