#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <pthread.h>
#include <time.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define INTERVAL 1000000 // 1 second in microseconds

volatile unsigned int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file;

void signal_handler(int signum) {
    pthread_mutex_lock(&pulse_mutex);
    gpioSetISRFunc(GPIO_PIN, 0, 0, NULL); // Unregister ISR
    pthread_mutex_unlock(&pulse_mutex);

    gpioTerminate();
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    exit(signum);
}

void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "failed to open log file\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetISRFunc(GPIO_PIN, RISING_EDGE, 0, pulse_callback) < 0) {
        fprintf(stderr, "ISR registration failed\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    while (1) {
        pthread_mutex_lock(&pulse_mutex);
        unsigned int count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = (count * 60.0) / 1.0; // 1 pulse per revolution
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

        fprintf(log_file, "%s: %.2f RPM\n", timestamp, rpm);
        fflush(log_file);

        gpioDelay(INTERVAL); // Sleep for 1 second
    }

    return 0;
}

