    if (!led_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led_line, "adpd144ri_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        uint16_t red, ir;
        if (i2c_read_fifo(&red, &ir) != 0) {
            fprintf(stderr, "Failed to read FIFO data\n");
            continue;
        }

        // Log timestamped readings
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(log_file, "%s,%u,%u\n", timestamp, red, ir);
        fflush(log_file);

        // Trigger LED if IR reading exceeds threshold
        if (ir > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

