#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define PART_ID_REG 0x00
#define FIFO_DATA_REG 0x0A
#define LED_GPIO 17
#define THRESHOLD 2000
#define SAMPLE_INTERVAL 100 // in milliseconds

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int i2c_read_register(int reg, uint8_t *data) {
    uint8_t buffer[1] = {reg};
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    if (read(i2c_fd, data, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int i2c_read_fifo(uint16_t *red, uint16_t *ir) {
    uint8_t buffer[4];
    if (i2c_read_register(FIFO_DATA_REG, buffer) != 0) {
        return -1;
    }
    *red = (buffer[0] << 8) | buffer[1];
    *ir = (buffer[2] << 8) | buffer[3];
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    // Verify sensor presence
    uint8_t part_id;
    if (i2c_read_register(PART_ID_REG, &part_id) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (part_id != 0x14) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X\n", part_id);
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize GPIO for LED
    gpio_chip = gpiod_chip_open_by_label("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }
    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led_line, "adpd144ri_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        uint16_t red, ir;
        if (i2c_read_fifo(&red, &ir) != 0) {
            fprintf(stderr, "Failed to read FIFO data\n");
            continue;
        }

        // Log timestamped readings
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(log_file, "%s,%u,%u\n", timestamp, red, ir);
        fflush(log_file);

        // Trigger LED if IR reading exceeds threshold
        if (ir > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}
