    struct gpiod_line *line_out = NULL;
    struct gpiod_line *line_gain = NULL;
    FILE *log_file = NULL;
    struct timespec ts;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the output line for GAIN
    line_gain = gpiod_chip_get_line(chip, GPIO_GAIN);
    if (!line_gain) {
        perror("Failed to get GPIO line for GAIN");
        ret = EXIT_FAILURE;
        goto exit;
    }

    ret = gpiod_line_request_output(line_gain, CONSUMER, 0);
    if (ret < 0) {
        perror("Failed to request output for GAIN");
        ret = EXIT_FAILURE;
        goto exit;
    }

    // Request the input line for OUT
    line_out = gpiod_chip_get_line(chip, GPIO_OUT);
    if (!line_out) {
        perror("Failed to get GPIO line for OUT");
        ret = EXIT_FAILURE;
        goto exit;
    }

    ret = gpiod_line_request_input(line_out, CONSUMER);
    if (ret < 0) {
        perror("Failed to request input for OUT");
        ret = EXIT_FAILURE;
        goto exit;
    }

    // Open the log file
    log_file = fopen("audio_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        ret = EXIT_FAILURE;
        goto exit;
    }

    // Set GAIN to LOW for 60dB gain
    ret = gpiod_line_set_value(line_gain, 0);
    if (ret < 0) {
        perror("Failed to set GAIN to LOW");
        ret = EXIT_FAILURE;
        goto exit;
    }

    printf("Audio peak detector started. Press Ctrl+C to stop.\n");

    // Main loop
    while (running) {
        int value = gpiod_line_get_value(line_out);
        if (value < 0) {
            perror("Failed to read GPIO line value");
            ret = EXIT_FAILURE;
            goto exit;
        }

        if (value == 1) {
            // Get current time
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                perror("Failed to get current time");
                ret = EXIT_FAILURE;
                goto exit;
            }

            // Format and write the log entry
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts));
            fprintf(log_file, "%s LEVEL 1\n", timestamp);
            fflush(log_file);
        }

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

exit:
    // Clean up resources
    if (log_file) {
        fclose(log_file);
    }
    if (line_out) {
        gpiod_line_release(line_out);
    }
    if (line_gain) {
        gpiod_line_release(line_gain);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

