#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDR 0x36
#define I2C_BUS 1
#define CMD_START_MEASUREMENT 0x3608
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t cmd[2] = {(CMD_START_MEASUREMENT >> 8) & 0xFF, CMD_START_MEASUREMENT & 0xFF};
    if (i2cWriteDevice(i2c_handle, cmd, 2) < 0) {
        fprintf(stderr, "I2C write failed: %s\n", pigpio_error(i2c_handle));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("flow_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        uint8_t buffer[3];
        if (i2cReadDevice(i2c_handle, buffer, 3) < 0) {
            fprintf(stderr, "I2C read failed: %s\n", pigpio_error(i2c_handle));
            continue;
        }

        uint16_t raw_flow = (buffer[0] << 8) | buffer[1];
        uint8_t calculated_crc = crc8(buffer, 2);
        if (calculated_crc != buffer[2]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        double flow_rate_uL_min = raw_flow / 1000.0;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.3f\n", timestamp, flow_rate_uL_min);
        fflush(log_file);

        time_sleep(1.0);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

