#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x70
#define REGISTER_START 0x00
#define READ_LENGTH 7
#define LOG_FILE "air_quality_log.csv"

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void log_data(int iaq, int tvoc, int eco2) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log, "%s,%d,%d,%d\n", timestamp, iaq, tvoc, eco2);
    fclose(log);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        char buffer[READ_LENGTH];
        int status = i2cReadI2CBlockData(i2c_handle, REGISTER_START, buffer, READ_LENGTH);
        if (status < 0) {
            fprintf(stderr, "I2C read failed: %d\n", status);
            break;
        }

        int tvoc = (buffer[1] << 8) | buffer[2];
        int eco2 = (buffer[5] << 8) | buffer[6];

        double iaq = 100 - (tvoc / 10.0) - ((eco2 - 400) / 50.0);
        iaq = (iaq < 0) ? 0 : ((iaq > 100) ? 100 : iaq);

        log_data((int)iaq, tvoc, eco2);

        sleep(5);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

