#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <signal.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>

#define PCM_DEVICE "default"
#define SAMPLE_RATE 48000
#define CHANNELS 2
#define FORMAT SND_PCM_FORMAT_S32_LE
#define BUFFER_SIZE 1024
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17

static volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    int ret;
    snd_pcm_t *handle;
    snd_pcm_hw_params_t *params;
    snd_pcm_uframes_t frames;
    int buffer_size;
    char *buffer;
    FILE *file;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    // Open ALSA PCM device
    if ((ret = snd_pcm_open(&handle, PCM_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Cannot open audio device %s (%s)\n", PCM_DEVICE, snd_strerror(ret));
        return 1;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&params);

    // Initialize hardware parameters
    if ((ret = snd_pcm_hw_params_any(handle, params)) < 0) {
        fprintf(stderr, "Cannot initialize hardware parameters (%s)\n", snd_strerror(ret));
        snd_pcm_close(handle);
        return 1;
    }

    // Set access type
    if ((ret = snd_pcm_hw_params_set_access(handle, params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Cannot set access type (%s)\n", snd_strerror(ret));
        snd_pcm_close(handle);
        return 1;
    }

    // Set sample format
    if ((ret = snd_pcm_hw_params_set_format(handle, params, FORMAT)) < 0) {
        fprintf(stderr, "Cannot set sample format (%s)\n", snd_strerror(ret));
        snd_pcm_close(handle);
        return 1;
    }

    // Set sample rate
    unsigned int rate = SAMPLE_RATE;
    if ((ret = snd_pcm_hw_params_set_rate_near(handle, params, &rate, 0)) < 0) {
        fprintf(stderr, "Cannot set sample rate (%s)\n", snd_strerror(ret));
        snd_pcm_close(handle);
        return 1;
    }

    // Set number of channels
    if ((ret = snd_pcm_hw_params_set_channels(handle, params, CHANNELS)) < 0) {
        fprintf(stderr, "Cannot set channel count (%s)\n", snd_strerror(ret));
        snd_pcm_close(handle);
        return 1;
    }

    // Apply hardware parameters
    if ((ret = snd_pcm_hw_params(handle, params)) < 0) {
        fprintf(stderr, "Cannot set hardware parameters (%s)\n", snd_strerror(ret));
        snd_pcm_close(handle);
        return 1;
    }

    // Get buffer size
    snd_pcm_hw_params_get_buffer_size(params, &frames);
    buffer_size = frames * snd_pcm_format_width(FORMAT) / 8 * CHANNELS;

    // Allocate buffer
    buffer = (char *)malloc(buffer_size);
    if (!buffer) {
        fprintf(stderr, "Cannot allocate buffer\n");
        snd_pcm_close(handle);
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Cannot open GPIO chip");
        free(buffer);
        snd_pcm_close(handle);
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Cannot get GPIO line");
        gpiod_chip_close(chip);
        free(buffer);
        snd_pcm_close(handle);
        return 1;
    }

    // Request GPIO line
    if (gpiod_line_request_output(line, "inmp441_lr_select", 0) < 0) {
        perror("Cannot request GPIO line");
        gpiod_chip_close(chip);
        free(buffer);
        snd_pcm_close(handle);
        return 1;
    }

    // Open file for writing
    file = fopen("audio_capture.pcm", "wb");
    if (!file) {
        perror("Cannot open file for writing");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        free(buffer);
        snd_pcm_close(handle);
        return 1;
    }

    // Set signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Cannot set signal handler");
        fclose(file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        free(buffer);
        snd_pcm_close(handle);
        return 1;
    }

    // Main loop
    while (running) {
        // Read data from ALSA
        ret = snd_pcm_readi(handle, buffer, frames);
        if (ret == -EPIPE) {
            // Overrun occurred, try to recover
            fprintf(stderr, "Buffer overrun, trying to recover...\n");
            snd_pcm_prepare(handle);
        } else if (ret < 0) {
            fprintf(stderr, "Read error: %s\n", snd_strerror(ret));
            break;
        }

        // Process and write 24-bit to 16-bit conversion
        for (int i = 0; i < ret * CHANNELS; i += 2) {
            int32_t sample = ((int32_t *)buffer)[i];
            int16_t pcm_sample = (sample >> 8) & 0xFFFF;
            fwrite(&pcm_sample, sizeof(pcm_sample), 1, file);
        }
    }

    // Clean up
    fclose(file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    free(buffer);
    snd_pcm_close(handle);

    return 0;
}

