#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define FAN_PIN 18
#define SAMPLE_INTERVAL 50000  // 50 ms in microseconds
#define DEBOUNCE_INTERVAL 50000  // 50 ms in microseconds
#define PWM_FREQ 100  // 100 Hz
#define MAX_DUTY_CYCLE 80  // 80%

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_event(const char *event) {
    time_t now = time(NULL);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    FILE *log_file = fopen("flame_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "[%s] %s\n", timestamp, event);
        fclose(log_file);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    atexit(gpioTerminate);

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for sensor pin\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for fan pin\n");
        return EXIT_FAILURE;
    }

    gpioSetAlertFunc(SENSOR_PIN, NULL);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("System start");

    int last_flame_detected = 0;
    struct timespec last_flame_time = {0, 0};
    int flame_duration = 0;

    while (running) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor pin\n");
            break;
        }

        if (sensor_value == PI_LOW) {
            if (!last_flame_detected) {
                last_flame_detected = 1;
                clock_gettime(CLOCK_REALTIME, &last_flame_time);
                log_event("Flame detected");
            }
        } else {
            if (last_flame_detected) {
                last_flame_detected = 0;
                struct timespec current_time;
                clock_gettime(CLOCK_REALTIME, &current_time);
                flame_duration = (current_time.tv_sec - last_flame_time.tv_sec) * 1000 +
                                 (current_time.tv_nsec - last_flame_time.tv_nsec) / 1000000;
                gpioPWM(FAN_PIN, 0);
                log_event("Flame ended");
            }
        }

        if (last_flame_detected) {
            struct timespec current_time;
            clock_gettime(CLOCK_REALTIME, &current_time);
            flame_duration = (current_time.tv_sec - last_flame_time.tv_sec) * 1000 +
                             (current_time.tv_nsec - last_flame_time.tv_nsec) / 1000000;
            int duty_cycle = (int)(MAX_DUTY_CYCLE * (1 - exp(-flame_duration / 1000.0)));
            gpioPWM(FAN_PIN, duty_cycle);
        }

        gpioDelay(SAMPLE_INTERVAL);
    }

    gpioPWM(FAN_PIN, 0);
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_INPUT);

    log_event("Shutdown");

    return EXIT_SUCCESS;
}

