#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 20
#define LOG_FILE "flame_log.txt"

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_state_transition(FILE *log_file, int new_state) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    if (new_state) {
        fprintf(log_file, "%s - Flame Detected\n", timestamp);
    } else {
        fprintf(log_file, "%s - Flame Cleared\n", timestamp);
    }
    fflush(log_file);
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    int current_state = 0;

    // Open signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    // Request line for input
    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        perror("gpiod_line_request_input");
        goto cleanup;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        goto cleanup;
    }

    // Main loop
    while (running) {
        int new_state = gpiod_line_get_value(line);
        if (new_state < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (new_state != current_state) {
            log_state_transition(log_file, new_state);
            current_state = new_state;
        }

        usleep(100000); // 100 milliseconds
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

