#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x44
#define RESULT_REG 0x00
#define CONFIG_REG 0x01
#define CONFIG_CONTINUOUS 0xC000
#define CONFIG_100MS 0x0000
#define CONFIG_AUTO_FULL_SCALE 0x0000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

void log_data(const char *filename, double lux) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    FILE *file = fopen(filename, "a");
    if (!file) {
        log_error("Failed to open log file");
        return;
    }
    fprintf(file, "[%s] Lux: %.2f\n", timestamp, lux);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio library");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t config = CONFIG_CONTINUOUS | CONFIG_100MS | CONFIG_AUTO_FULL_SCALE;
    if (i2cWriteWordData(i2c_handle, CONFIG_REG, config) < 0) {
        log_error("Failed to write configuration to sensor");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint16_t result;
        if (i2cReadWordData(i2c_handle, RESULT_REG, &result) < 0) {
            log_error("Failed to read data from sensor");
            sleep(1);
            continue;
        }

        int exponent = (result >> 12) & 0x0F;
        int mantissa = result & 0x0FFF;
        double lux = 0.01 * pow(2, exponent) * mantissa;

        log_data("light_data.txt", lux);

        sleep(1);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

