#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define INTERVAL 1

volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int sig) {
    exit_flag = 1;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_config config;
    struct gpiod_line_settings settings;
    int ret;

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Configure the line
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_detect";
    config.num_lines = 1;
    config.lines[0].offset = GPIO_LINE;
    config.lines[0].flags = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.lines[0].bias = GPIOD_LINE_BIAS_PULL_UP;

    // Request the line
    line = gpiod_chip_request_lines(chip, &config);
    if (!line) {
        perror("gpiod_chip_request_lines");
        goto cleanup;
    }

    // Main loop
    while (!exit_flag) {
        int value;
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);

        // Read the line value
        value = gpiod_line_request_get_value(line);
        if (value == -1) {
            perror("gpiod_line_request_get_value");
            goto cleanup;
        }

        // Print the timestamp and flame detection status
        printf("%04d-%02d-%02d %02d:%02d:%02d - Flame Detected: %s\n",
               tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
               tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
               value == 0 ? "YES" : "NO");

        // Sleep for 1 second
        sleep(INTERVAL);
    }

cleanup:
    // Release resources
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

