#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define GPIO_START 2
#define GPIO_END 9
#define POLL_INTERVAL_US 100000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure GPIOs
    for (int i = GPIO_START; i <= GPIO_END; i++) {
        if (gpioSetMode(i, PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(i, PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    // Main loop
    int64_t start_time = gpioTick();
    while (running) {
        int64_t current_time = gpioTick();
        printf("[%+lld ms] ", current_time - start_time);

        for (int i = GPIO_START; i <= GPIO_END; i++) {
            int state = gpioRead(i);
            printf("CH%d=%d ", i - GPIO_START + 1, state);
        }
        printf("\n");

        gpioDelay(POLL_INTERVAL_US);
    }

    // Clean up
    gpioTerminate();
    return EXIT_SUCCESS;
}

