#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES 8
#define GPIO_LINE_OFFSETS {2, 3, 4, 17, 27, 22, 10, 9}
#define POLL_INTERVAL_US 50000

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    struct gpiod_line *line;
    int ret;
    unsigned int line_values[GPIO_LINES];
    const unsigned int line_offsets[GPIO_LINES] = GPIO_LINE_OFFSETS;
    struct timespec ts;

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Request lines
    ret = gpiod_chip_get_lines(chip, line_offsets, GPIO_LINES, &lines);
    if (ret < 0) {
        perror("gpiod_chip_get_lines");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Configure lines as inputs with bias disabled
    for (unsigned int i = 0; i < GPIO_LINES; i++) {
        line = gpiod_line_bulk_get(&lines, i);
        if (!line) {
            fprintf(stderr, "Failed to get line %u\n", line_offsets[i]);
            gpiod_line_bulk_release(&lines);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        ret = gpiod_line_request_input(line, "ttp226_reader");
        if (ret < 0) {
            perror("gpiod_line_request_input");
            gpiod_line_bulk_release(&lines);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        ret = gpiod_line_set_bias(line, GPIOD_LINE_BIAS_DISABLE);
        if (ret < 0) {
            perror("gpiod_line_set_bias");
            gpiod_line_bulk_release(&lines);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Main loop
    while (running) {
        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            gpiod_line_bulk_release(&lines);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Read line values
        ret = gpiod_line_bulk_get_value_bulk(&lines, line_values);
        if (ret < 0) {
            perror("gpiod_line_bulk_get_value_bulk");
            gpiod_line_bulk_release(&lines);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Print timestamp and line values in CSV format
        printf("%ld.%09ld,", ts.tv_sec, ts.tv_nsec);
        for (unsigned int i = 0; i < GPIO_LINES; i++) {
            printf("%u", line_values[i]);
            if (i < GPIO_LINES - 1) {
                printf(",");
            }
        }
        printf("\n");

        // Sleep for poll interval
        usleep(POLL_INTERVAL_US);
    }

    // Release resources
    gpiod_line_bulk_release(&lines);
    gpiod_chip_close(chip);

    return 0;
}

