    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    log_message("Tilt sensor monitoring started");

    int last_state = gpioRead(TILT_SENSOR_GPIO);
    while (running) {
        int current_state = gpioRead(TILT_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read GPIO state\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (current_state != last_state) {
            if (current_state == PI_LOW) {
                log_message("Tilted");
            } else {
                log_message("Not Tilted");
            }
            last_state = current_state;
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    log_message("Tilt sensor monitoring stopped");
    gpioTerminate();
    return EXIT_SUCCESS;
}
