#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR1 0x36
#define I2C_ADDR2 0x37
#define I2C_CMD_REG 0x08
#define I2C_START_MEASUREMENT 0x3608
#define I2C_DATA_REG 0x00
#define DATA_LEN 9
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define SCALE_FACTOR 0.036
#define ALARM_GPIO 17
#define LOG_FILE "flow_log.txt"
#define LOG_INTERVAL 1

static int i2c_fd1 = -1;
static int i2c_fd2 = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *alarm_line = NULL;
static FILE *log_file = NULL;

static void cleanup() {
    if (alarm_line) {
        gpiod_line_release(alarm_line);
        alarm_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
    if (i2c_fd1 != -1) {
        close(i2c_fd1);
        i2c_fd1 = -1;
    }
    if (i2c_fd2 != -1) {
        close(i2c_fd2);
        i2c_fd2 = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

static uint8_t calculate_crc(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sensor(int i2c_fd, uint8_t *data) {
    if (write(i2c_fd, &I2C_DATA_REG, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(i2c_fd, data, DATA_LEN) != DATA_LEN) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

static float process_flow_data(uint8_t *data) {
    uint16_t flow = (data[0] << 8) | data[1];
    uint8_t crc = calculate_crc(data, 2);
    if (crc != data[2]) {
        fprintf(stderr, "CRC error\n");
        return -1.0;
    }
    return flow * SCALE_FACTOR;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd1 = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd1 < 0) {
        perror("Failed to open I2C device 1");
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd1, I2C_SLAVE, I2C_ADDR1) < 0) {
        perror("Failed to set I2C address 1");
        cleanup();
        return EXIT_FAILURE;
    }

    i2c_fd2 = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd2 < 0) {
        perror("Failed to open I2C device 2");
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd2, I2C_SLAVE, I2C_ADDR2) < 0) {
        perror("Failed to set I2C address 2");
        cleanup();
        return EXIT_FAILURE;
    }

    gpio_chip = gpiod_chip_open_by_label("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }
    alarm_line = gpiod_chip_get_line(gpio_chip, ALARM_GPIO);
    if (!alarm_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(alarm_line, "flow_alarm", 0) < 0) {
        perror("Failed to request GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t data1[DATA_LEN];
    uint8_t data2[DATA_LEN];
    uint16_t flow1 = 0;
    uint16_t flow2 = 0;
    int valid1 = 0;
    int valid2 = 0;

    while (1) {
        valid1 = 0;
        valid2 = 0;

        if (write(i2c_fd1, &I2C_CMD_REG, 1) != 1) {
            perror("I2C write to sensor 1");
        } else if (write(i2c_fd1, &I2C_START_MEASUREMENT, 2) != 2) {
            perror("I2C write to sensor 1");
        } else {
            usleep(100000);
            if (read_sensor(i2c_fd1, data1) == 0) {
                flow1 = process_flow_data(data1);
                if (flow1 >= 0.0) {
                    valid1 = 1;
                }
            }
        }

        if (write(i2c_fd2, &I2C_CMD_REG, 1) != 1) {
            perror("I2C write to sensor 2");
        } else if (write(i2c_fd2, &I2C_START_MEASUREMENT, 2) != 2) {
            perror("I2C write to sensor 2");
        } else {
            usleep(100000);
            if (read_sensor(i2c_fd2, data2) == 0) {
                flow2 = process_flow_data(data2);
                if (flow2 >= 0.0) {
                    valid2 = 1;
                }
            }
        }

        float avg_flow = 0.0;
        if (valid1 && valid2) {
            avg_flow = (flow1 + flow2) / 2.0;
        } else if (valid1) {
            avg_flow = flow1;
        } else if (valid2) {
            avg_flow = flow2;
        }

        if (fprintf(log_file, "%.2f\n", avg_flow) < 0) {
            perror("Failed to write to log file");
        }
        fflush(log_file);

        if (gpiod_line_set_value(alarm_line, avg_flow < 0.5) < 0) {
            perror("Failed to set GPIO line");
        }

        sleep(LOG_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

