#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100
#define POLL_INTERVAL_MS 50

typedef struct {
    struct timespec timestamp;
    int reading;
} Detection;

Detection buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_count = 0;

void handle_sigint(int sig) {
    printf("Caught SIGINT, printing buffer contents:\n");
    for (int i = 0; i < buffer_count; i++) {
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer[(buffer_head + i) % BUFFER_SIZE].timestamp.tv_sec));
        printf("%s.%03ld: Reading %d\n", time_str, buffer[(buffer_head + i) % BUFFER_SIZE].timestamp.tv_nsec / 1000000, buffer[(buffer_head + i) % BUFFER_SIZE].reading);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        int reading = gpioRead(GPIO_PIN);
        if (reading == 0) {
            struct timespec current_time;
            clock_gettime(CLOCK_REALTIME, &current_time);
