#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x55
#define MODE_CONTROL_REG 0x1D
#define OPERATING_STATUS_REG 0x1B
#define ACCELERATION_X_REG 0x2A
#define ACCELERATION_Y_REG 0x2C
#define ACCELERATION_Z_REG 0x2E
#define SCALING_FACTOR 0.0009765625

#define BUFFER_SIZE 32

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    int i2c_fd = -1;
    FILE *csv_file = NULL;
    struct sigaction sa;
    char buffer[BUFFER_SIZE];
    time_t now;
    struct tm *tm_info;
    int retries;

    // Set up signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize sensor
    uint8_t mode_control = 0x10;
    if (write(i2c_fd, &mode_control, 1) != 1) {
        perror("Failed to write to MODE_CONTROL register");
    } else {
        // Wait for sensor to become active
        for (int i = 0; i < 20; i++) {
            uint8_t status;
            if (read(i2c_fd, &status, 1) == 1 && (status & 0x01)) {
                break;
            }
            usleep(50000);
        }
        uint8_t status;
        if (read(i2c_fd, &status, 1) != 1 || !(status & 0x01)) {
            fprintf(stderr, "Sensor did not become active within 1 second\n");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }
    }

    // Open CSV file
    csv_file = fopen("fan_health.csv", "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Write header if file is newly created
    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }

    while (running) {
        uint8_t reg = ACCELERATION_X_REG;
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Failed to write to I2C device");
            continue;
        }

        uint8_t data[6];
        retries = 0;
        while (retries < 3 && read(i2c_fd, data, 6) != 6) {
            perror("Failed to read from I2C device");
            retries++;
            usleep(100000);
        }
        if (retries == 3) {
            continue;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        double x_g = x * SCALING_FACTOR;
        double y_g = y * SCALING_FACTOR;
        double z_g = z * SCALING_FACTOR;

        time(&now);
        tm_info = localtime(&now);
        strftime(buffer, BUFFER_SIZE, "%Y-%m-%dT%H:%M:%S", tm_info);

        fprintf(csv_file, "%s,%.6f,%.6f,%.6f\n", buffer, x_g, y_g, z_g);
        fflush(csv_file);

        usleep(500000);
    }

    // Clean up
    if (csv_file) {
        fclose(csv_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

