void log_stall(const char *timestamp) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    // Check for duplicate entry
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        if (strcmp(buffer, timestamp) == 0) {
            fclose(file);
            return; // Duplicate entry found, do not log
        }
    }

    // Log the new entry
    fprintf(file, "%s\n", timestamp);
    fclose(file);
}

