        int sensor1_state = gpioRead(SENSOR1_GPIO);
        int sensor2_state = gpioRead(SENSOR2_GPIO);

        if (sensor1_state == PI_LOW && sensor2_state == PI_LOW) {
            time_t current_time = time(NULL);
            if (current_time - last_stall_time >= STALL_DURATION / 1000) {
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time));
