#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x0E
#define DEVICE_ID_REG 0x00
#define EXPECTED_DEVICE_ID 0x8D
#define CONFIG_REG 0x01
#define CONFIG_CONTINUOUS_MODE 0x00
#define CONFIG_ALL_AXES_ENABLED 0x07
#define CONFIG_50MT_RANGE 0x00
#define X_MSB_REG 0x02
#define Y_MSB_REG 0x04
#define Z_MSB_REG 0x06
#define LSB_SCALE_FACTOR_50MT 0.15 // 150 uT per LSB

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Verify device ID
    char device_id;
    int status = i2cReadByteData(i2c_handle, DEVICE_ID_REG, &device_id);
    if (status < 0) {
        fprintf(stderr, "Failed to read device ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%02X\n", device_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure sensor
    char config = CONFIG_CONTINUOUS_MODE | CONFIG_ALL_AXES_ENABLED | CONFIG_50MT_RANGE;
    status = i2cWriteByteData(i2c_handle, CONFIG_REG, config);
    if (status < 0) {
        fprintf(stderr, "Failed to write configuration\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("magnetic_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X(mT),Y(mT),Z(mT)\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        char x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;
        status = i2cReadI2CBlockData(i2c_handle, X_MSB_REG, &x_msb, 1);
        if (status < 0) {
            fprintf(stderr, "Failed to read X MSB\n");
            continue;
        }
        status = i2cReadI2CBlockData(i2c_handle, X_MSB_REG + 1, &x_lsb, 1);
        if (status < 0) {
            fprintf(stderr, "Failed to read X LSB\n");
            continue;
        }
        status = i2cReadI2CBlockData(i2c_handle, Y_MSB_REG, &y_msb, 1);
        if (status < 0) {
            fprintf(stderr, "Failed to read Y MSB\n");
            continue;
        }
        status = i2cReadI2CBlockData(i2c_handle, Y_MSB_REG + 1, &y_lsb, 1);
        if (status < 0) {
            fprintf(stderr, "Failed to read Y LSB\n");
            continue;
        }
        status = i2cReadI2CBlockData(i2c_handle, Z_MSB_REG, &z_msb, 1);
        if (status < 0) {
            fprintf(stderr, "Failed to read Z MSB\n");
            continue;
        }
        status = i2cReadI2CBlockData(i2c_handle, Z_MSB_REG + 1, &z_lsb, 1);
        if (status < 0) {
            fprintf(stderr, "Failed to read Z LSB\n");
