#define SENSOR_GPIO 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL 2000 // 2 seconds in milliseconds
#define REINIT_INTERVAL 60000 // 60 seconds in milliseconds

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_message(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    fprintf(log, "%s\n", message);
    fclose(log);
}

void log_alert() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    char message[100];
    snprintf(message, sizeof(message), "%s ALERT: Water detected", timestamp);
    log_message(message);
    printf("%s\n", message);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int sensor_state = gpioRead(SENSOR_GPIO);
        if (sensor_state < 0) {
            fprintf(stderr, "GPIO read failed, attempting re-initialization in 60 seconds\n");
            log_message("GPIO read failed, attempting re-initialization in 60 seconds");
            gpioTerminate();
            sleep(REINIT_INTERVAL / 1000);
            if (gpioInitialise() < 0) {
                fprintf(stderr, "pigpio re-initialization failed\n");
                return EXIT_FAILURE;
            }
            if (gpioSetMode(SENSOR_GPIO, PI_INPUT) < 0 || gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN) < 0) {
                fprintf(stderr, "Failed to reconfigure GPIO\n");
                gpioTerminate();
                return EXIT_FAILURE;
            }
            continue;
        }

        if (sensor_state == PI_HIGH) {
            log_alert();
        }

        gpioDelay(POLL_INTERVAL);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

