#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define PULSE_PER_REVOLUTION 1
#define LOG_FILE "rpm_log.txt"

volatile uint32_t pulse_count = 0;
FILE *log_file = NULL;

void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        gpioSdkAtomicIncrement(&pulse_count, 1);
    }
}

void log_rpm() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    uint32_t rpm = (pulse_count * 60) / PULSE_PER_REVOLUTION;
    printf("%s %u\n", timestamp, rpm);

    if (log_file != NULL) {
        fprintf(log_file, "%s %u\n", timestamp, rpm);
        fflush(log_file);
    }

    pulse_count = 0;
}

void signal_handler(int signum) {
    gpioSetAlertFunc(GPIO_PIN, NULL);
    gpioSetTimerFunc(0, NULL);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDnControl(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(GPIO_PIN, pulse_callback) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        gpioSetTimerFunc(0, 1000, log_rpm);
        time_sleep(1);
    }

    return 0;
}

