This code sets up a Raspberry Pi to read RPM from a Melexis MLX90217 Hall-effect sensor using the pigpio library. It counts rising-edge pulses on GPIO 4, computes RPM, logs the result to a file, and handles signals to clean up resources.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>

#define SENSOR_A 17
#define SENSOR_B 27
#define LOG_FILE "rotation_log.txt"

typedef enum {
    CW,
    CCW
} Direction;

typedef struct {
    int sensor_a;
    int sensor_b;
    Direction direction;
} QuadratureState;

QuadratureState state = {0, 0, CW};
pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t state_cond = PTHREAD_COND_INITIALIZER;
volatile sig_atomic_t running = 1;
FILE *log_file = NULL;

void log_rotation(Direction direction) {
    char timestamp[30];
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts));
    fprintf(log_file, "%s.%03ld %s\n", timestamp, ts.tv_nsec / 1000000, direction == CW ? "CW" : "CCW");
    fflush(log_file);
}

void gpio_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&state_mutex);
    if (gpio == SENSOR_A) {
        state.sensor_a = level;
    } else if (gpio == SENSOR_B) {
        state.sensor_b = level;
    }

    int prev_sensor_a = state.sensor_a;
    int prev_sensor_b = state.sensor_b;

    // Determine direction based on previous state
    if (prev_sensor_a == 0 && prev_sensor_b == 0) {
        if (state.sensor_a == 1 && state.sensor_b == 0) {
            state.direction = CW;
        } else if (state.sensor_a == 0 && state.sensor_b == 1) {
            state.direction = CCW;
        }
    } else if (prev_sensor_a == 0 && prev_sensor_b == 1) {
        if (state.sensor_a == 1 && state.sensor_b == 1) {
            state.direction = CW;
        } else if (state.sensor_a == 0 && state.sensor_b == 0) {
            state.direction = CCW;
        }
    } else if (prev_sensor_a == 1 && prev_sensor_b == 1) {
        if (state.sensor_a == 0 && state.sensor_b == 1) {
            state.direction = CW;
        } else if (state.sensor_a == 1 && state.sensor_b == 0) {
            state.direction = CCW;
        }
    } else if (prev_sensor_a == 1 && prev_sensor_b == 0) {
        if (state.sensor_a == 0 && state.sensor_b == 0) {
            state.direction = CW;
        } else if (state.sensor_a == 1 && state.sensor_b == 1) {
            state.direction = CCW;
        }
    }

    log_rotation(state.direction);
    pthread_cond_signal(&state_cond);
    pthread_mutex_unlock(&state_mutex);
}

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_A, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", SENSOR_A);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_B, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", SENSOR_B);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_A, gpio_callback) < 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", SENSOR_A);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_B, gpio_callback) < 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", SENSOR_B);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        pthread_mutex_lock(&state_mutex);
        pthread_cond_wait(&state_cond, &state_mutex);
        pthread_mutex_unlock(&state_mutex);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

