        fprintf(stderr, "Failed to set alert function on GPIO %d\n", SENSOR_A);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_B, gpio_callback) < 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", SENSOR_B);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        pthread_mutex_lock(&state_mutex);
        pthread_cond_wait(&state_cond, &state_mutex);
        pthread_mutex_unlock(&state_mutex);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}
