#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

#define CONSUMER "touch_sensor"
#define TOUCH_PIN 17
#define LED_PIN 18
#define DEBOUNCE_US 50000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line_event event;
    struct timespec timeout = {0, DEBOUNCE_US};
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        goto exit;
    }

    // Request touch sensor line
    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        perror("Failed to get touch sensor line");
        goto exit;
    }

    ret = gpiod_line_request_input(touch_line, CONSUMER);
    if (ret < 0) {
        perror("Failed to request input for touch sensor line");
        goto exit;
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        goto exit;
    }

    ret = gpiod_line_request_output(led_line, CONSUMER, 0);
    if (ret < 0) {
        perror("Failed to request output for LED line");
        goto exit;
    }

    // Main loop
    while (running) {
        ret = gpiod_line_event_wait(touch_line, &timeout);
        if (ret < 0) {
            perror("Failed to wait for line event");
            break;
        } else if (ret == 0) {
            continue; // Timeout, debounce
        }

        ret = gpiod_line_event_read(touch_line, &event);
        if (ret < 0) {
            perror("Failed to read line event");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Toggle LED
            int current_value = gpiod_line_get_value(led_line);
            if (current_value < 0) {
                perror("Failed to get LED line value");
                break;
            }
            ret = gpiod_line_set_value(led_line, !current_value);
            if (ret < 0) {
                perror("Failed to set LED line value");
                break;
            }
        }
    }

exit:
    // Release resources
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

