#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define LED1_PIN 27
#define LED2_PIN 22
#define POLL_INTERVAL_US 50000
#define LOG_BUFFER_SIZE 100

typedef struct {
    time_t timestamp;
    int sensor_pin;
    int new_state;
} LogEntry;

LogEntry log_buffer[LOG_BUFFER_SIZE];
int log_index = 0;
int overflow_count = 0;
volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_event(int sensor_pin, int new_state) {
    time_t now = time(NULL);
    log_buffer[log_index].timestamp = now;
    log_buffer[log_index].sensor_pin = sensor_pin;
    log_buffer[log_index].new_state = new_state;
    log_index = (log_index + 1) % LOG_BUFFER_SIZE;
    if (log_index == 0) {
        overflow_count++;
    }
}

void print_log_buffer() {
    for (int i = 0; i < LOG_BUFFER_SIZE; i++) {
        int index = (log_index + i) % LOG_BUFFER_SIZE;
        if (log_buffer[index].timestamp != 0) {
            printf("Timestamp: %sSensor: %d, State: %d\n",
                   ctime(&log_buffer[index].timestamp),
                   log_buffer[index].sensor_pin,
                   log_buffer[index].new_state);
        }
    }
    printf("Overflow count: %d\n", overflow_count);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR2_PIN, PI_INPUT) < 0 ||
        gpioSetMode(LED1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LED2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(LED1_PIN, PI_LOW);
    gpioWrite(LED2_PIN, PI_LOW);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state1 = gpioRead(SENSOR1_PIN);
    int last_state2 = gpioRead(SENSOR2_PIN);

    while (running) {
        int state1 = gpioRead(SENSOR1_PIN);
        int state2 = gpioRead(SENSOR2_PIN);

        if (state1 != last_state1) {
            gpioWrite(LED1_PIN, state1);
            log_event(SENSOR1_PIN, state1);
            last_state1 = state1;
        }

        if (state2 != last_state2) {
            gpioWrite(LED2_PIN, state2);
            log_event(SENSOR2_PIN, state2);
            last_state2 = state2;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(LED1_PIN, PI_LOW);
    gpioWrite(LED2_PIN, PI_LOW);
    gpioTerminate();

    print_log_buffer();

    return EXIT_SUCCESS;
}

