#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/rain_events.log"
#define POLL_INTERVAL_MS 500

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_event(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log, "[%s] %s\n", timestamp, message);
    fclose(log);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = gpioRead(GPIO_PIN);
    while (running) {
        int current_state = gpioRead(GPIO_PIN);
        if (current_state != last_state) {
            if (current_state == PI_LOW) {
                log_event("Rain Detected");
            } else {
                log_event("No Rain");
            }
            last_state = current_state;
        }
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

