#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define DEBOUNCE_TIME 5000 // 5 ms in microseconds
#define PULSES_PER_REVOLUTION 2

volatile int sensor1_state = 0;
volatile int sensor2_state = 0;
volatile int sensor1_last_state = 0;
volatile int sensor2_last_state = 0;
volatile int sensor1_count = 0;
volatile int sensor2_count = 0;
volatile int last_count = 0;
volatile time_t last_time = 0;
volatile time_t current_time = 0;
volatile double rpm = 0.0;

FILE *log_file = NULL;

void signal_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(signum);
}

void log_state_change(int sensor, int state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (sensor == 1) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, state, sensor2_state);
    } else {
        fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, state);
    }
}

void sensor1_callback(int gpio, int level, uint32_t tick) {
    if (level != sensor1_last_state) {
        sensor1_last_state = level;
        gpioDelay(DEBOUNCE_TIME);
