#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04

#define PART_ID_VALUE 0x1182

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_handle;
    FILE *log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    unsigned char part_id;
    if (i2cReadByteData(i2c_handle, PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (part_id != (PART_ID_VALUE & 0xFF)) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    unsigned char config = 0x01; // Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, config) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        unsigned char heart_rate, spo2;
        if (i2cReadByteData(i2c_handle, HEART_RATE_REG, &heart_rate) < 0) {
            fprintf(stderr, "Failed to read heart rate data\n");
            continue;
        }

        if (i2cReadByteData(i2c_handle, SPO2_REG, &spo2) < 0) {
            fprintf(stderr, "Failed to read SpO2 data\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
        fflush(log_file);

        sleep(1);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return EXIT_SUCCESS;
}

