#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define ALARM_GPIO 27
#define POLL_INTERVAL_US 100000
#define THRESHOLD_US 2000000

FILE *log_file;
volatile sig_atomic_t running = 1;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "%s - %s\n", timestamp, event);
    fflush(log_file);
}

void signal_handler(int signum) {
    running = 0;
}

void cleanup() {
    gpioWrite(ALARM_GPIO, PI_LOW);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_DOWN);
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, PI_LOW);

    log_file = fopen("bridge_integrity.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int sensor1 = gpioRead(SENSOR1_GPIO);
        int sensor2 = gpioRead(SENSOR2_GPIO);

        if (sensor1 == PI_HIGH || sensor2 == PI_HIGH) {
            static struct timespec last_tilt = {0};
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);

            if (last_tilt.tv_sec == 0) {
                log_event("Tilt-start");
                last_tilt = now;
            } else if (timespec_diff_us(&now, &last_tilt) > THRESHOLD_US) {
                log_event("Threshold-exceeded");
                gpioWrite(ALARM_GPIO, PI_HIGH);
            }
        } else {
            static struct timespec last_tilt = {0};
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);

            if (last_tilt.tv_sec != 0) {
                log_event("Tilt-end");
                last_tilt.tv_sec = 0;
                gpioWrite(ALARM_GPIO, PI_LOW);
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

long timespec_diff_us(struct timespec *a, struct timespec *b) {
    return (a->tv_sec - b->tv_sec) * 1000000 + (a->tv_nsec - b->tv_nsec) / 1000;
}

