int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if ((i2c_handle = i2cOpen(1, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    if (write_i2c_register(CTRL1_REG, 0x00) != 0) {
        fprintf(stderr, "Failed to clear power-down bit in CTRL1\n");
        cleanup();
        return 1;
    }

    if ((log_file = fopen("seismic_events.log", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    while (running) {
        unsigned char accel_data[6];
        if (read_i2c_register(ACCEL_X_REG, accel_data, 6) == 0) {
            int x = (accel_data[1] << 8) | accel_data[0];
            int y = (accel_data[3] << 8) | accel_data[2];
            int z = (accel_data[5] << 8) | accel_data[4];
            int vibration_magnitude = sqrt(x * x + y * y + z * z);
            if (vibration_magnitude > THRESHOLD) {
                gpioWrite(LED_PIN, PI_HIGH);
                log_event(vibration_magnitude);
                usleep(1000000); // 1 second
                gpioWrite(LED_PIN, PI_LOW);
            }
        } else {
            fprintf(stderr, "I2C read failed\n");
        }
        usleep(100000); // 100 ms
    }

    cleanup();
    return 0;
}
