#define POLL_INTERVAL_US 50000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *sensor_lines[NUM_SENSORS];
    int sensor_pins[NUM_SENSORS] = SENSOR_PINS;
    int i;

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        goto cleanup;
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("gpiod_line_request_output (LED)");
        goto cleanup;
    }

    // Request sensor lines
    for (i = 0; i < NUM_SENSORS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            perror("gpiod_chip_get_line (sensor)");
            goto cleanup;
        }
        if (gpiod_line_request_input(sensor_lines[i], "sensor") < 0) {
            perror("gpiod_line_request_input (sensor)");
            goto cleanup;
        }
    }

    // Main loop
    while (running) {
        int object_detected = 0;
        for (i = 0; i < NUM_SENSORS; i++) {
            if (gpiod_line_get_value(sensor_lines[i]) == 0) {
                object_detected = 1;
                break;
            }
        }
        gpiod_line_set_value(led_line, object_detected);

        // Sleep without blocking signals
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = POLL_INTERVAL_US * 1000;
        nanosleep(&ts, NULL);
    }

cleanup:
    // Release resources
    for (i = 0; i < NUM_SENSORS; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

