#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define DEBOUNCE_MS 50
#define LOG_FILE "/var/log/flame_events.log"

const int sensor_gpios[NUM_SENSORS] = {2, 3, 4, 17, 27};
const char *sensor_ids[NUM_SENSORS] = {"1", "2", "3", "4", "5"};

volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

void log_event(const char *sensor_id, int gpio) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %m");
        return;
    }

    if (flock(fileno(log_file), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Failed to lock log file: %m");
        fclose(log_file);
        return;
    }

    fprintf(log_file, "%s - Sensor ID: %s (GPIO %d) - Flame Detected\n", timestamp, sensor_id, gpio);
    fflush(log_file);

    if (flock(fileno(log_file), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Failed to unlock log file: %m");
    }

    fclose(log_file);
}

int main() {
    openlog("flame_monitor", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Flame monitor started");

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %m");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_gpios[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "Failed to get GPIO line %d: %m", sensor_gpios[i]);
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }

        int ret = gpiod_line_request_input(lines[i], "flame_monitor");
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to request input on GPIO line %d: %m", sensor_gpios[i]);
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                syslog(LOG_ERR, "Failed to read GPIO line %d: %m", sensor_gpios[i]);
                continue;
            }

            if (value == 0) { // Flame detected
                usleep(DEBOUNCE_MS * 1000);
                int new_value = gpiod_line_get_value(lines[i]);
                if (new_value < 0) {
                    syslog(LOG_ERR, "Failed to read GPIO line %d after debounce: %m", sensor_gpios[i]);
                    continue;
                }

                if (new_value == 0) {
                    log_event(sensor_ids[i], sensor_gpios[i]);
                }
            }
        }

        sleep(1);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    closelog();

    syslog(LOG_INFO, "Flame monitor stopped");
    return EXIT_SUCCESS;
}

