#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define PINS {5, 6, 13, 19, 26, 12, 16, 20}
#define NUM_PINS 8
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_PINS];
    int pin_numbers[NUM_PINS] = PINS;
    int prev_values[NUM_PINS] = {0};
    struct timespec ts;
    int i, ret;

    // Set up signal handler for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Request lines
    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_numbers[i]);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            goto err_close_chip;
        }

        ret = gpiod_line_request_input(lines[i], "touch_sensor");
        if (ret < 0) {
            perror("gpiod_line_request_input");
            goto err_release_lines;
        }
    }

    // Main loop
    while (running) {
        int current_values[NUM_PINS];

        // Read all lines
        for (i = 0; i < NUM_PINS; i++) {
            current_values[i] = gpiod_line_get_value(lines[i]);
            if (current_values[i] < 0) {
                perror("gpiod_line_get_value");
                goto err_release_lines;
            }
        }

        // Check for state changes
        for (i = 0; i < NUM_PINS; i++) {
            if (current_values[i] != prev_values[i]) {
                clock_gettime(CLOCK_REALTIME, &ts);
                printf("%ld-%02ld-%02ldT%02ld:%02ld:%02ld.%03ldZ "
                       "Sensor %d (BCM %d): %s\n",
                       ts.tv_sec / 31536000, (ts.tv_sec / 86400) % 30,
                       (ts.tv_sec / 3600) % 24, (ts.tv_sec / 60) % 60,
                       ts.tv_sec % 60, (ts.tv_nsec / 1000000),
                       i, pin_numbers[i], current_values[i] ? "Touch" : "Release");
                prev_values[i] = current_values[i];
            }
        }

        // Sleep for 50 milliseconds
        usleep(POLL_INTERVAL_US);
    }

    // Clean up
err_release_lines:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
err_close_chip:
    gpiod_chip_close(chip);

    return 0;
}

