#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x10
#define CONFIG_REG 0x00
#define ALS_REG 0x04
#define LED_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 100

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_entry(FILE *log_file, int lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
}

int main() {
    FILE *log_file = fopen("grow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        perror("Failed to open I2C device");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
