#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 17
#define FIRST_GPIO_PIN 2
#define LAST_GPIO_PIN 9
#define DEBOUNCE_TIME 50
#define LOG_FILE "touch_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_touch_event(int channel) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    for (int pin = FIRST_GPIO_PIN; pin <= LAST_GPIO_PIN; pin++) {
        gpioSetMode(pin, PI_INPUT);
        gpioSetPullUpDown(pin, PI_PUD_DOWN);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state[LAST_GPIO_PIN - FIRST_GPIO_PIN + 1] = {0};
    time_t last_change[LAST_GPIO_PIN - FIRST_GPIO_PIN + 1] = {0};

    while (running) {
        for (int pin = FIRST_GPIO_PIN; pin <= LAST_GPIO_PIN; pin++) {
            int channel = pin - FIRST_GPIO_PIN;
            int state = gpioRead(pin);

            if (state != last_state[channel]) {
                last_state[channel] = state;
                last_change[channel] = time(NULL);
            } else if (state == PI_HIGH && difftime(time(NULL), last_change[channel]) > DEBOUNCE_TIME / 1000.0) {
                log_touch_event(pin);
                gpioWrite(LED_PIN, PI_HIGH);
            }
        }

        if (gpioRead(LED_PIN) == PI_HIGH && all_channels_released(last_state)) {
            gpioWrite(LED_PIN, PI_LOW);
        }

        gpioDelay(DEBOUNCE_TIME * 1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

int all_channels_released(int *states) {
    for (int i = 0; i < LAST_GPIO_PIN - FIRST_GPIO_PIN + 1; i++) {
        if (states[i] == PI_HIGH) {
            return 0;
        }
    }
    return 1;
}

