#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810
#define CONVERSION_DELAY 100000 // 100 ms in microseconds

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void log_lux_value(FILE *log_file, double lux) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file);
    printf("%s, %.2f lux\n", timestamp, lux);
}

int main() {
    int i2c_handle;
    FILE *log_file = fopen("light_data.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    uint16_t config_word = (CONFIG_WORD >> 8) | (CONFIG_WORD << 8);
    if (i2cWriteWordData(i2c_handle, CONFIG_REG, config_word) < 0) {
        fprintf(stderr, "Failed to write configuration to OPT3001\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    gpioDelay(CONVERSION_DELAY);

    signal(SIGINT, sigint_handler);

    while (running) {
        uint16_t result_word;
        if (i2cReadWordData(i2c_handle, RESULT_REG, &result_word) < 0) {
            fprintf(stderr, "Failed to read result from OPT3001\n");
            continue;
        }

        result_word = (result_word >> 8) | (result_word << 8);
        uint16_t exponent = (result_word >> 12) & 0x0F;
        uint16_t mantissa = result_word & 0x0FFF;
        double lux = mantissa * 0.01 * (1 << exponent);

        log_lux_value(log_file, lux);

        gpioDelay(1000000); // 1 second delay
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return EXIT_SUCCESS;
}

