        fprintf(log_file, "Failed to initialize pigpio\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(log_file, "Failed to set mode for GPIO %d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(log_file, "Failed to set mode for GPIO %d\n", ALERT_GPIO);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
