            gpioWrite(ALERT_GPIO, PI_HIGH);
            usleep(1000000); // 1 second
            gpioWrite(ALERT_GPIO, PI_LOW);
        } else {
            snprintf(event_message, sizeof(event_message), "No flame detected");
        }

        log_event(log_file, event_message);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    gpioTerminate();
    fclose(log_file);
    return EXIT_SUCCESS;
}

