#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define DEBOUNCE_US 50000
#define LOG_FILE "touch_log.txt"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

void release_resources() {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    int ret;
    struct gpiod_line_event event;
    struct sigaction sa;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        release_resources();
        return EXIT_FAILURE;
    }

    // Request the line as input with pull-down bias
    ret = gpiod_line_request_input(line, "touch_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input: %s\n", strerror(errno));
        release_resources();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_bias(line, GPIOD_LINE_BIAS_PULL_DOWN);
    if (ret < 0) {
        fprintf(stderr, "Failed to set pull-down bias: %s\n", strerror(errno));
        release_resources();
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        release_resources();
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (running) {
        ret = gpiod_line_event_wait(line, DEBOUNCE_US);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for line event: %s\n", strerror(errno));
            break;
        }

        if (ret > 0) {
            ret = gpiod_line_event_read(line, &event);
            if (ret < 0) {
                fprintf(stderr, "Failed to read line event: %s\n", strerror(errno));
                break;
            }

            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                log_event("Touch Detected");
            } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                log_event("Touch Released");
            }
        }
    }

    // Clean up
    release_resources();
    return EXIT_SUCCESS;
}

