#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/stat.h>

#define I2C_BUS 1
#define I2C_ADDR 0x08
#define START_MEASUREMENT_CMD 0x3608
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define RAW_TO_ML_MIN 90.0
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 100.0

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_flow_rate(FILE *log_file, double flow_rate, const char *status) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, status);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("cooling_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        if (i2cWriteWordData(i2c_handle, 0x00, START_MEASUREMENT_CMD) < 0) {
            fprintf(stderr, "I2C write failed\n");
            log_flow_rate(log_file, 0.0, "ERROR");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "I2C re-open failed\n");
                break;
            }
            continue;
        }

        usleep(2000);

        uint8_t buffer[3];
        if (i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 3) < 0) {
            fprintf(stderr, "I2C read failed\n");
            log_flow_rate(log_file, 0.0, "ERROR");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "I2C re-open failed\n");
                break;
            }
            continue;
        }

        uint16_t raw_flow = (buffer[0] << 8) | buffer[1];
        uint8_t calculated_crc = crc8(buffer, 2);
        if (calculated_crc != buffer[2]) {
            fprintf(stderr, "CRC check failed\n");
            log_flow_rate(log_file, 0.0, "ERROR");
            continue;
        }

        double flow_rate = raw_flow / RAW_TO_ML_MIN;
        const char *status = "OK";
        if (flow_rate < MIN_FLOW_RATE || flow_rate > MAX_FLOW_RATE) {
            status = "INVALID";
        }

        log_flow_rate(log_file, flow_rate, status);

        fflush(log_file);
        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

