#define GPIO_MIDDLE 27
#define GPIO_RIGHT 22
#define POLL_INTERVAL_US 50000

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *left_line = NULL;
static struct gpiod_line *middle_line = NULL;
static struct gpiod_line *right_line = NULL;
