    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
}

void sigint_handler(int sig) {
    running = false;
}

int main() {
    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    left_line = gpiod_chip_get_line(chip, GPIO_LEFT);
    middle_line = gpiod_chip_get_line(chip, GPIO_MIDDLE);
    right_line = gpiod_chip_get_line(chip, GPIO_RIGHT);

    if (!left_line || !middle_line || !right_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(left_line, "obstacle_sensor_left") < 0 ||
        gpiod_line_request_input(middle_line, "obstacle_sensor_middle") < 0 ||
        gpiod_line_request_input(right_line, "obstacle_sensor_right") < 0) {
        perror("Failed to request GPIO line as input");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("path_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,left,middle,right\n");

    while (running) {
        int left_value = gpiod_line_get_value(left_line);
        int middle_value = gpiod_line_get_value(middle_line);
        int right_value = gpiod_line_get_value(right_line);

        if (left_value < 0 || middle_value < 0 || right_value < 0) {
            perror("Failed to read GPIO line value");
            cleanup();
            return EXIT_FAILURE;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current time");
            cleanup();
            return EXIT_FAILURE;
        }

        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts));

        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left_value, middle_value, right_value);
        fflush(log_file);

        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

