    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        ret = EXIT_FAILURE;
        goto exit;
    }

    // Configure the line for input with falling edge event detection
    ret = gpiod_line_request_falling_edge_events(line, "flame_sensor");
    if (ret < 0) {
        perror("Failed to request falling edge events");
        ret = EXIT_FAILURE;
        goto exit;
