static struct gpiod_line *flame_sensor_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%s: %s\n", asctime(tm_info), message);
    fflush(log_file);
}

void handle_signal(int sig) {
    running = 0;
}

void cleanup() {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (flame_sensor_line) {
        gpiod_line_release(flame_sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int ret;
    struct sigaction sa;
    int last_flame_state = 1; // Assume no flame initially

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

