    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_LINE);
    if (!flame_sensor_line) {
        fprintf(stderr, "Failed to get flame sensor line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Request input for the flame sensor line
    ret = gpiod_line_request_input(flame_sensor_line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request input for flame sensor line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Get the buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_LINE);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Request output for the buzzer line
    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request output for buzzer line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Log system start
    log_event("System started");

    // Set up signal handlers
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        int current_flame_state = gpiod_line_get_value(flame_sensor_line);
        if (current_flame_state < 0) {
            fprintf(stderr, "Failed to read flame sensor line: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        if (last_flame_state == 1 && current_flame_state == 0) {
            // Flame detected
            log_event("Flame detected");
            gpiod_line_set_value(buzzer_line, 1);
            usleep(BUZZER_DURATION_US);
            gpiod_line_set_value(buzzer_line, 0);
        }

        last_flame_state = current_flame_state;
        usleep(POLL_INTERVAL_US);
    }

    // Log system stop
    log_event("System stopped");

    // Cleanup
    cleanup();
    return EXIT_SUCCESS;
}

