#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define LED_PIN 17
#define DEBOUNCE_MS 200
#define POLL_MS 10
#define LOG_FILE "touch_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_touch_event() {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    if (fprintf(log, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Warning: Failed to write to log file: %s\n", strerror(errno));
    }

    fclose(log);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO%d as input\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetSignalFunc(SIGINT, signal_handler);
    gpioSetSignalFunc(SIGTERM, signal_handler);

    int last_state = gpioRead(TOUCH_PIN);
    time_t last_change_time = time(NULL);

    while (running) {
        int current_state = gpioRead(TOUCH_PIN);
        time_t current_time = time(NULL);

        if (current_state != last_state && current_time - last_change_time >= DEBOUNCE_MS / 1000) {
            last_state = current_state;
            last_change_time = current_time;

            if (current_state == PI_HIGH) {
                gpioWrite(LED_PIN, !gpioRead(LED_PIN));
                log_touch_event();
            }
        }

        usleep(POLL_MS * 1000);
    }

    gpioWrite(LED_PIN, PI_LOW);
    gpioTerminate();
    return EXIT_SUCCESS;
}

