This code sets up a Raspberry Pi Zero W to read a capacitive touch sensor and toggle an LED using the pigpio library. It handles signals for graceful shutdown, logs touch events with timestamps, and implements debouncing to prevent multiple events from a single touch.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO4  4
#define GPIO17 17
#define GPIO27 27

#define LOG_FILE "magnet_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_state_change(int gpio, int state) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s - GPIO%d: %s\n", timestamp, gpio, state ? "Magnet Removed" : "Magnet Present");
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int gpios[] = {GPIO4, GPIO17, GPIO27};
    int initial_states[3] = {-1, -1, -1};

    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(gpios[i], PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO%d as input\n", gpios[i]);
            goto cleanup;
        }
        if (gpioSetPullUpDown(gpios[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "Failed to set pull-up on GPIO%d\n", gpios[i]);
            goto cleanup;
        }
        initial_states[i] = gpioRead(gpios[i]);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        for (int i = 0; i < 3; i++) {
            int current_state = gpioRead(gpios[i]);
            if (current_state < 0) {
                fprintf(stderr, "Failed to read GPIO%d\n", gpios[i]);
                continue;
            }
            if (initial_states[i] == -1) {
                initial_states[i] = current_state;
            } else if (current_state != initial_states[i]) {
                log_state_change(gpios[i], current_state);
                initial_states[i] = current_state;
            }
        }
        gpioDelay(100000); // 100 ms
    }

cleanup:
    gpioTerminate();
    return EXIT_SUCCESS;
}

