#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x3F
#define AVERAGING_REG 0x04
#define ENABLE_REG 0x01
#define HEART_RATE_REG 0x2A

#define PART_ID_VALUE 0x02
#define HW_REV_VALUE 0x01

#define LED_CURRENT_VALUE 0x0F
#define AVERAGING_VALUE 0x03
#define ENABLE_VALUE 0x01

#define MOVING_AVERAGE_SIZE 5

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    signal(SIGINT, handle_sigint);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id != PART_ID_VALUE) {
        fprintf(stderr, "Sensor PART_ID mismatch: expected 0x02, got 0x%02X\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t hw_rev = i2cReadByteData(i2c_handle, HW_REV_REG);
    if (hw_rev != HW_REV_VALUE) {
        fprintf(stderr, "Sensor HW_REV mismatch: expected 0x01, got 0x%02X\n", hw_rev);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, LED_CURRENT_REG, LED_CURRENT_VALUE) < 0) {
        fprintf(stderr, "Failed to write LED current register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, AVERAGING_REG, AVERAGING_VALUE) < 0) {
        fprintf(stderr, "Failed to write averaging register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, ENABLE_REG, ENABLE_VALUE) < 0) {
        fprintf(stderr, "Failed to write enable register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("heart_rate.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int moving_average[MOVING_AVERAGE_SIZE] = {0};
    int moving_average_index = 0;
    int moving_average_sum = 0;

    while (running) {
        int raw_value = i2cReadWordData(i2c_handle, HEART_RATE_REG);
        if (raw_value < 0) {
            fprintf(stderr, "I2C read error, retrying...\n");
            continue;
        }

        int bpm = raw_value * 0.5;
        moving_average_sum -= moving_average[moving_average_index];
        moving_average[moving_average_index] = bpm;
        moving_average_sum += bpm;
        moving_average_index = (moving_average_index + 1) % MOVING_AVERAGE_SIZE;

        int filtered_bpm = moving_average_sum / MOVING_AVERAGE_SIZE;

        if (filtered_bpm >= 30 && filtered_bpm <= 220) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s,%d\n", timestamp, filtered_bpm);
            fflush(log_file);
        }

        time_sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

