#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "flame_log.txt"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_line_event event;
    struct timespec timeout = {0, 100000000}; // 100 ms

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Request line as input with pull-up
    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        perror("Failed to request GPIO line as input");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Configure line for event detection
    if (gpiod_line_event_request_rising_edge(line) < 0) {
        perror("Failed to request rising edge event");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        exit(EXIT_FAILURE);
    }

    printf("Monitoring flame sensor on GPIO17...\n");

    while (running) {
        if (gpiod_line_event_wait(line, &timeout) < 0) {
            if (errno == -EINTR) {
                continue; // Interrupted by signal, continue loop
            }
            perror("Failed to wait for event");
            cleanup();
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_event_read(line, &event) < 0) {
            perror("Failed to read event");
            cleanup();
            exit(EXIT_FAILURE);
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            printf("FLAME DETECTED\n");

            // Get current timestamp
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

            // Write to log file
            fprintf(log_file, "%s: FLAME DETECTED\n", timestamp);
            fflush(log_file);
        }
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

