#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define SENSOR_LINES 8
#define SENSOR_OFFSET 5
#define COUNTER_LINES 8
#define COUNTER_OFFSET 17
#define POLL_INTERVAL_US 10000
#define STABILIZATION_DELAY_US 200000

static struct gpiod_chip *chip = NULL;
static struct gpiod_line_bulk sensor_bulk;
static struct gpiod_line_bulk counter_bulk;
static int sensor_values[SENSOR_LINES] = {0};
static int counter = 0;
static FILE *log_file = NULL;

void cleanup() {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    for (int i = 0; i < COUNTER_LINES; i++) {
        struct gpiod_line *line = gpiod_line_bulk_get_line(&counter_bulk, i);
        if (line) {
            gpiod_line_release(line);
        }
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(0);
}

void log_event(const char *message) {
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file);
    }
    printf("%s\n", message);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int sensor_nums[SENSOR_LINES] = {5, 6, 7, 8, 9, 10, 11, 12};
    int counter_nums[COUNTER_LINES] = {17, 18, 19, 20, 21, 22, 23, 24};

    if (gpiod_chip_get_lines(chip, sensor_nums, SENSOR_LINES, &sensor_bulk) < 0) {
        fprintf(stderr, "Failed to get sensor lines: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_chip_get_lines(chip, counter_nums, COUNTER_LINES, &counter_bulk) < 0) {
        fprintf(stderr, "Failed to get counter lines: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct gpiod_line_request_config config = {
        .consumer = "touch_counter",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    if (gpiod_line_request_bulk(&sensor_bulk, &config) < 0) {
        fprintf(stderr, "Failed to request sensor lines: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request_bulk(&counter_bulk, &config) < 0) {
        fprintf(stderr, "Failed to request counter lines: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    usleep(STABILIZATION_DELAY_US);

    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Warning: Failed to open log file: %s\n", strerror(errno));
    }

    while (1) {
        int new_sensor_values[SENSOR_LINES];
        if (gpiod_line_get_value_bulk(&sensor_bulk, new_sensor_values) < 0) {
            fprintf(stderr, "Error reading sensor lines: %s\n", strerror(errno));
            continue;
        }

        for (int i = 0; i < SENSOR_LINES; i++) {
            if (new_sensor_values[i] && !sensor_values[i]) {
                counter = (counter + 1) % 256;
                char message[100];
                time_t now = time(NULL);
                struct tm *tm_info = gmtime(&now);
                strftime(message, sizeof(message), "%Y-%m-%dT%H:%M:%SZ, Channel: %d, Counter: %d", tm_info, i + 1, counter);
                log_event(message);

                for (int j = 0; j < COUNTER_LINES; j++) {
                    struct gpiod_line *line = gpiod_line_bulk_get_line(&counter_bulk, j);
                    if (line && gpiod_line_set_value(line, (counter >> j) & 1) < 0) {
                        fprintf(stderr, "Error setting counter line %d: %s\n", counter_nums[j], strerror(errno));
                    }
                }
            }
            sensor_values[i] = new_sensor_values[i];
        }

        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

