    usleep(STABILIZATION_DELAY_US);

    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Warning: Failed to open log file: %s\n", strerror(errno));
    }

    while (1) {
        int new_sensor_values[SENSOR_LINES];
        if (gpiod_line_get_value_bulk(&sensor_bulk, new_sensor_values) < 0) {
            fprintf(stderr, "Error reading sensor lines: %s\n", strerror(errno));
            continue;
        }

        for (int i = 0; i < SENSOR_LINES; i++) {
            if (new_sensor_values[i] && !sensor_values[i]) {
                counter = (counter + 1) % 256;
                char message[100];
                time_t now = time(NULL);
                struct tm *tm_info = gmtime(&now);
                strftime(message, sizeof(message), "%Y-%m-%dT%H:%M:%SZ, Channel: %d, Counter: %d", tm_info, i + 1, counter);
                log_event(message);

                for (int j = 0; j < COUNTER_LINES; j++) {
                    struct gpiod_line *line = gpiod_line_bulk_get_line(&counter_bulk, j);
                    if (line && gpiod_line_set_value(line, (counter >> j) & 1) < 0) {
                        fprintf(stderr, "Error setting counter line %d: %s\n", counter_nums[j], strerror(errno));
                    }
                }
            }
            sensor_values[i] = new_sensor_values[i];
        }

        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}
