#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE_17 17
#define GPIO_LINE_18 18
#define LOG_FILE "/var/log/tilt_events.log"
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line18 = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (line17) {
        gpiod_line_release(line17);
        line17 = NULL;
    }
    if (line18) {
        gpiod_line_release(line18);
        line18 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    running = 0;
}

void log_event(int sensor, const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s, Sensor %d %s\n", timestamp, sensor, message);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    int ret;

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO_LINE_17);
    line18 = gpiod_chip_get_line(chip, GPIO_LINE_18);
    if (!line17 || !line18) {
        perror("Failed to get GPIO lines");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure lines as inputs with active-low pull-up
    ret = gpiod_line_request_input(line17, "tilt_sensor_17");
    if (ret < 0) {
        perror("Failed to request input for GPIO17");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_input(line18, "tilt_sensor_18");
    if (ret < 0) {
        perror("Failed to request input for GPIO18");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set bias to pull-up
    ret = gpiod_line_set_bias(line17, GPIOD_LINE_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Failed to set bias for GPIO17");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_set_bias(line18, GPIOD_LINE_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Failed to set bias for GPIO18");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    int last_state_17 = 1;
    int last_state_18 = 1;
    struct timespec last_event_time_17 = {0};
    struct timespec last_event_time_18 = {0};
    struct timespec now;
    struct timespec debounce_time = {0, DEBOUNCE_MS * 1000000};

    while (running) {
        ret = gpiod_line_get_value(line17);
        if (ret < 0) {
            perror("Failed to read GPIO17");
            continue;
        }
        ret = gpiod_line_get_value(line18);
        if (ret < 0) {
            perror("Failed to read GPIO18");
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &now);

        if (ret != last_state_17) {
            if (ret == 0 && (now.tv_sec > last_event_time_17.tv_sec || (now.tv_sec == last_event_time_17.tv_sec && now.tv_nsec > last_event_time_17.tv_nsec + debounce_time.tv_nsec))) {
                log_event(1, "tilted");
                last_event_time_17 = now;
            }
            last_state_17 = ret;
        }

        if (ret != last_state_18) {
            if (ret == 0 && (now.tv_sec > last_event_time_18.tv_sec || (now.tv_sec == last_event_time_18.tv_sec && now.tv_nsec > last_event_time_18.tv_nsec + debounce_time.tv_nsec))) {
                log_event(2, "tilted");
                last_event_time_18 = now;
            }
            last_state_18 = ret;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

