#define SENSOR2_LINE 27
#define LED_LINE 22
#define LOG_FILE "obstacle_log.csv"

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor1 = NULL, *sensor2 = NULL, *led = NULL;
    FILE *log_file = NULL;
    struct timespec ts;
    int sensor1_value, sensor2_value, led_state;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    sensor1 = gpiod_chip_get_line(chip, SENSOR1_LINE);
    sensor2 = gpiod_chip_get_line(chip, SENSOR2_LINE);
    led = gpiod_chip_get_line(chip, LED_LINE);

    if (!sensor1 || !sensor2 || !led) {
        perror("Failed to get GPIO lines");
        goto cleanup;
    }

    // Configure lines
    if (gpiod_line_request_input(sensor1, "sensor1") < 0 ||
        gpiod_line_request_input(sensor2, "sensor2") < 0 ||
        gpiod_line_request_output(led, "led", 0) < 0) {
        perror("Failed to request GPIO lines");
        goto cleanup;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        // Read sensor values
        sensor1_value = gpiod_line_get_value(sensor1);
        sensor2_value = gpiod_line_get_value(sensor2);

        // Determine LED state
        led_state = !(sensor1_value == 0 && sensor2_value == 0);
        gpiod_line_set_value(led, led_state);

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get timestamp");
            goto cleanup;
        }

        // Log the data
        fprintf(log_file, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, sensor1_value, sensor2_value, led_state);
        fflush(log_file);

        // Sleep for 100 ms
        usleep(100000);
    }

cleanup:
    // Turn off LED
    if (led) {
        gpiod_line_set_value(led, 0);
    }

    // Release resources
    if (sensor1) {
        gpiod_line_release(sensor1);
    }
    if (sensor2) {
        gpiod_line_release(sensor2);
    }
    if (led) {
        gpiod_line_release(led);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

