        perror("gpiod_line_set_active_low(CENTER_SENSOR)");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_set_active_low(right_line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_active_low(RIGHT_SENSOR)");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (running) {
        int left_state = gpiod_line_get_value(left_line);
        int center_state = gpiod_line_get_value(center_line);
