#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDRESS 0x49
#define ALS_VIS_DATA_L 0x24
#define ALS_VIS_DATA_H 0x25
#define INTERVAL_US 100000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd;
    char *filename = I2C_BUS;
    int addr = SI1175_ADDRESS;
    unsigned char buffer[2];
    unsigned short als_vis_data;

    // Register signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open the I2C bus
    if ((i2c_fd = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read the LSB of ALS visible data
        buffer[0] = ALS_VIS_DATA_L;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to the i2c bus");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }
        if (read(i2c_fd, buffer, 1) != 1) {
            perror("Failed to read from the i2c bus");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Read the MSB of ALS visible data
        buffer[0] = ALS_VIS_DATA_H;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to the i2c bus");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }
        if (read(i2c_fd, buffer + 1, 1) != 1) {
            perror("Failed to read from the i2c bus");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Combine LSB and MSB into a 16-bit value
        als_vis_data = (buffer[1] << 8) | buffer[0];

        // Log the raw sensor value
        printf("ALS Visible Data: %hu\n", als_vis_data);

        // Wait for the next interval
        usleep(INTERVAL_US);
    }

    // Close the I2C bus
    close(i2c_fd);

    return 0;
}

