#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LEFT 2
#define GPIO_MIDDLE 3
#define GPIO_RIGHT 4
#define POLL_INTERVAL_US 100000

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL, *middle_line = NULL, *right_line = NULL;
    int ret;

    // Set up signal handler for graceful termination
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Get the GPIO lines
    left_line = gpiod_chip_get_line(chip, GPIO_LEFT);
    if (!left_line) {
        perror("gpiod_chip_get_line (left)");
        goto cleanup;
    }

    middle_line = gpiod_chip_get_line(chip, GPIO_MIDDLE);
    if (!middle_line) {
        perror("gpiod_chip_get_line (middle)");
        goto cleanup;
    }

    right_line = gpiod_chip_get_line(chip, GPIO_RIGHT);
    if (!right_line) {
        perror("gpiod_chip_get_line (right)");
        goto cleanup;
    }

    // Request the lines as inputs
    ret = gpiod_line_request_input(left_line, "keywish_left");
    if (ret < 0) {
        perror("gpiod_line_request_input (left)");
        goto cleanup;
    }

    ret = gpiod_line_request_input(middle_line, "keywish_middle");
    if (ret < 0) {
        perror("gpiod_line_request_input (middle)");
        goto cleanup;
    }

    ret = gpiod_line_request_input(right_line, "keywish_right");
    if (ret < 0) {
        perror("gpiod_line_request_input (right)");
        goto cleanup;
    }

    // Poll the lines
    while (running) {
        int left_val = gpiod_line_get_value(left_line);
        int middle_val = gpiod_line_get_value(middle_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || middle_val < 0 || right_val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        printf("L:%d M:%d R:%d\n", left_val, middle_val, right_val);

        usleep(POLL_INTERVAL_US);
    }

cleanup:
    if (left_line) gpiod_line_release(left_line);
    if (middle_line) gpiod_line_release(middle_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip) gpiod_chip_close(chip);

    return 0;
}

