            if (value < 0) {
                perror("gpiod_line_get_value");
                cleanup();
                exit(EXIT_FAILURE);
            }
            printf("CH%d=%d ", i + 1, value);
        }
        printf("\n");

        usleep(POLL_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    return 0;
}

