#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27
#define PWM_FREQ 1000
#define FADE_STEPS 50
#define FADE_INTERVAL 100000 // 5 seconds in microseconds

volatile sig_atomic_t running = 1;

void cleanup() {
    gpioSetPWMfrequency(RED_PIN, 0);
    gpioSetPWMfrequency(GREEN_PIN, 0);
    gpioSetPWMfrequency(BLUE_PIN, 0);
    gpioTerminate();
    closelog();
}

void signal_handler(int sig) {
    running = 0;
}

void hsv_to_rgb(float h, float s, float v, int *r, int *g, int *b) {
    int i;
    float f, p, q, t;

    if (s == 0) {
        *r = *g = *b = (int)(v * 255);
        return;
    }

    h /= 60;
    i = (int)h;
    f = h - i;
    p = v * (1 - s);
    q = v * (1 - s * f);
    t = v * (1 - s * (1 - f));

    switch (i) {
        case 0:
            *r = (int)(v * 255);
            *g = (int)(t * 255);
            *b = (int)(p * 255);
            break;
        case 1:
            *r = (int)(q * 255);
            *g = (int)(v * 255);
            *b = (int)(p * 255);
            break;
        case 2:
            *r = (int)(p * 255);
            *g = (int)(v * 255);
            *b = (int)(t * 255);
            break;
        case 3:
            *r = (int)(p * 255);
            *g = (int)(q * 255);
            *b = (int)(v * 255);
            break;
        case 4:
            *r = (int)(t * 255);
            *g = (int)(p * 255);
            *b = (int)(v * 255);
            break;
        default:
            *r = (int)(v * 255);
            *g = (int)(p * 255);
            *b = (int)(q * 255);
            break;
    }
}

void fade_to_color(int r, int g, int b) {
    int current_r = 0, current_g = 0, current_b = 0;
    int step_r = (r - current_r) / FADE_STEPS;
    int step_g = (g - current_g) / FADE_STEPS;
    int step_b = (b - current_b) / FADE_STEPS;

    for (int i = 0; i < FADE_STEPS; i++) {
        current_r += step_r;
        current_g += step_g;
        current_b += step_b;

        gpioPWM(RED_PIN, 255 - current_r);
        gpioPWM(GREEN_PIN, 255 - current_g);
        gpioPWM(BLUE_PIN, 255 - current_b);

        usleep(FADE_INTERVAL / FADE_STEPS);
    }
}

int main() {
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", RED_PIN);
        cleanup();
        return 1;
    }

    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", GREEN_PIN);
        cleanup();
        return 1;
    }

    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", BLUE_PIN);
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for GPIO%d", RED_PIN);
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for GPIO%d", GREEN_PIN);
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for GPIO%d", BLUE_PIN);
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    srand(time(NULL));

    while (running) {
        float hue = (float)rand() / RAND_MAX * 360;
        int r, g, b;
        hsv_to_rgb(hue, 1.0, 1.0, &r, &g, &b);
        fade_to_color(r, g, b);
    }

    cleanup();
    closelog();
    return 0;
}

