#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEV "/dev/i2c-1"
#define TCS34725_ADDR 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATAL 0x14
#define TCS34725_RDATAL 0x16
#define TCS34725_GDATAL 0x18
#define TCS34725_BDATAL 0x1A
#define TCS34725_PON 0x01
#define TCS34725_AEN 0x02
#define TCS34725_INTEGRATION_TIME 0x00
#define TCS34725_GAIN 0x00
#define LED_GPIO 17
#define RED_THRESHOLD 200
#define POLL_INTERVAL 200

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
}

void signal_handler(int signum) {
    running = 0;
}

int i2c_write_byte(unsigned char reg, unsigned char value) {
    unsigned char buf[2] = {reg | TCS34725_COMMAND_BIT, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("i2c_write_byte");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(unsigned char reg, unsigned char *buf, size_t len) {
    if (i2c_write_byte(reg | TCS34725_COMMAND_BIT, 0) < 0) {
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        perror("i2c_read_bytes");
        return -1;
    }
    return 0;
}

int init_sensor() {
    unsigned char id;
    if (i2c_write_byte(TCS34725_ENABLE, TCS34725_PON) < 0) {
        return -1;
    }
    usleep(10000); // Wait for power on
    if (i2c_write_byte(TCS34725_ENABLE, TCS34725_PON | TCS34725_AEN) < 0) {
        return -1;
    }
    if (i2c_write_byte(TCS34725_ATIME, TCS34725_INTEGRATION_TIME) < 0) {
        return -1;
    }
    if (i2c_write_byte(TCS34725_CONTROL, TCS34725_GAIN) < 0) {
        return -1;
    }
    if (i2c_read_bytes(TCS34725_ID, &id, 1) < 0) {
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Invalid sensor ID: 0x%02X\n", id);
        return -1;
    }
    return 0;
}

void read_sensor_data(unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue) {
    unsigned char data[8];
    if (i2c_read_bytes(TCS34725_CDATAL, data, 8) < 0) {
        fprintf(stderr, "Failed to read sensor data, attempting re-initialization...\n");
        if (init_sensor() < 0) {
            fprintf(stderr, "Re-initialization failed\n");
            exit(EXIT_FAILURE);
        }
        if (i2c_read_bytes(TCS34725_CDATAL, data, 8) < 0) {
            fprintf(stderr, "Failed to read sensor data after re-initialization\n");
            exit(EXIT_FAILURE);
        }
    }
    *clear = (data[1] << 8) | data[0];
    *red = (data[3] << 8) | data[2];
    *green = (data[5] << 8) | data[4];
    *blue = (data[7] << 8) | data[6];
}

void apply_calibration(unsigned int *red, unsigned int *green, unsigned int *blue) {
    // Placeholder for calibration logic
    // Example: *red = (*red * gain) + offset;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (init_sensor() < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    gpio_chip = gpiod_chip_open_by_label("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        exit(EXIT_FAILURE);
    }
    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (running) {
        unsigned int clear, red, green, blue;
        read_sensor_data(&clear, &red, &green, &blue);
        apply_calibration(&red, &green, &blue);
        printf("Calibrated RGB: R=%u, G=%u, B=%u, C=%u\n", red, green, blue, clear);
        if (red > RED_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }
        usleep(POLL_INTERVAL * 1000);
    }

    cleanup();
    return 0;
}

