    unsigned char data[8];
    if (i2c_read_bytes(TCS34725_CDATAL, data, 8) < 0) {
        fprintf(stderr, "Failed to read sensor data, attempting re-initialization...\n");
        if (init_sensor() < 0) {
            fprintf(stderr, "Re-initialization failed\n");
            exit(EXIT_FAILURE);
        }
        if (i2c_read_bytes(TCS34725_CDATAL, data, 8) < 0) {
            fprintf(stderr, "Failed to read sensor data after re-initialization\n");
            exit(EXIT_FAILURE);
        }
    }
    *clear = (data[1] << 8) | data[0];
    *red = (data[3] << 8) | data[2];
    *green = (data[5] << 8) | data[4];
    *blue = (data[7] << 8) | data[6];
}

