#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

#define LED_PIN 18
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define LED_COUNT 10
#define MAX_LUX 1000
#define PWM_RANGE 1023

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_lux(int fd) {
    if (wiringPiI2CWrite(fd, BH1750_CONTINUOUS_HIGH_RES_MODE) == -1) {
        perror("Failed to write to BH1750");
        return -1;
    }
    usleep(180000); // Wait for 180 ms

    int msb = wiringPiI2CReadReg8(fd, 0);
    int lsb = wiringPiI2CReadReg8(fd, 0);
    if (msb == -1 || lsb == -1) {
        perror("Failed to read from BH1750");
        return -1;
    }

    int lux = ((msb << 8) | lsb) / 1.2;
    return lux;
}

int map_lux_to_brightness(int lux) {
    if (lux <= 0) return 0;
    if (lux >= MAX_LUX) return PWM_RANGE;
    return (int)(PWM_RANGE * log1p(lux / (double)MAX_LUX));
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    int fd = wiringPiI2CSetup(BH1750_ADDR);
    if (fd == -1) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int lux = read_lux(fd);
        if (lux == -1) {
            fprintf(stderr, "Failed to read lux, retrying...\n");
            continue;
        }

        int brightness = map_lux_to_brightness(lux);
        gpioPWM(LED_PIN, brightness);

        printf("Lux: %d, Brightness: %d\n", lux, brightness);
        usleep(1000000); // Wait for 1 second
    }

    gpioTerminate();
    close(fd);
    return 0;
}

