#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>

#define BH1750_ADDR 0x23
#define BH1750_CMD 0x20
#define I2C_DEV "/dev/i2c-1"
#define SPI_DEV "/dev/spidev0.0"
#define NUM_LEDS 10
#define SPI_SPEED 1000000

static int i2c_fd = -1;
static int spi_fd = -1;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

void sigint_handler(int sig) {
    running = 0;
}

int i2c_read(uint8_t *data, size_t len) {
    if (read(i2c_fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int i2c_write(uint8_t *data, size_t len) {
    if (write(i2c_fd, data, len) != len) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

void send_apache2_frame(uint8_t brightness) {
    uint8_t frame[NUM_LEDS * 4 + 8];
    for (int i = 0; i < 8; i++) {
        frame[i] = 0;
    }
    for (int i = 0; i < NUM_LEDS; i++) {
        frame[8 + i * 4] = 0xE0 | brightness;
        frame[9 + i * 4] = 0; // Blue
        frame[10 + i * 4] = 0; // Green
        frame[11 + i * 4] = 0; // Red
    }
    for (int i = 0; i < 8; i++) {
        frame[8 + NUM_LEDS * 4 + i] = 0xFF;
    }
    if (spi_transfer(frame, NULL, sizeof(frame)) < 0) {
        exit(EXIT_FAILURE);
    }
}

int main() {
    signal(SIGINT, sigint_handler);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        exit(EXIT_FAILURE);
    }

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
        exit(EXIT_FAILURE);
    }
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        exit(EXIT_FAILURE);
    }

    uint8_t cmd = BH1750_CMD;
    if (i2c_write(&cmd, 1) < 0) {
        cleanup();
        exit(EXIT_FAILURE);
    }
    usleep(120000);

    while (running) {
        uint8_t lux_data[2];
        if (i2c_read(lux_data, 2) < 0) {
            cleanup();
            exit(EXIT_FAILURE);
        }
        uint16_t raw_lux = (lux_data[0] << 8) | lux_data[1];
        float lux = raw_lux / 1.2;
        uint8_t brightness = 0;
        if (lux >= 10 && lux <= 300) {
            brightness = (lux - 10) * 31 / 290;
        }
        send_apache2_frame(brightness);
        usleep(1000000); // 1 second interval
    }

    send_apache2_frame(0); // Turn off LEDs
    cleanup();
    return 0;
}

