#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CMD 0x21
#define BH1750_CONVERSION_TIME 180000 // 180 ms in microseconds
#define SPI_CHANNEL 0
#define SPI_SPEED 8000000 // 8 MHz
#define LED_STRIP_BRIGHTNESS_MIN 0
#define LED_STRIP_BRIGHTNESS_MAX 31
#define FADE_DURATION 500000 // 500 ms in microseconds
#define LOOP_DELAY 100000 // 100 ms in microseconds

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int read_lux(int handle) {
    uint8_t data[2];
    if (i2cWriteByte(handle, BH1750_CMD) < 0) {
        return -1;
    }
    usleep(BH1750_CONVERSION_TIME);
    if (i2cReadDevice(handle, data, 2) < 0) {
        return -1;
    }
    return (data[0] << 8) | data[1];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle_low = i2cOpen(I2C_BUS, BH1750_ADDR_LOW, 0);
    int i2c_handle_high = i2cOpen(I2C_BUS, BH1750_ADDR_HIGH, 0);
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);

    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        int lux_sum = 0;
        int lux_count = 0;

        if (i2c_handle_low >= 0) {
            int lux = read_lux(i2c_handle_low);
            if (lux >= 0) {
                lux_sum += lux;
                lux_count++;
            }
        }

        if (i2c_handle_high >= 0) {
            int lux = read_lux(i2c_handle_high);
            if (lux >= 0) {
                lux_sum += lux;
                lux_count++;
            }
        }

        int average_lux = lux_count > 0 ? lux_sum / lux_count : 0;
        int target_brightness = LED_STRIP_BRIGHTNESS_MAX - (average_lux * LED_STRIP_BRIGHTNESS_MAX / 1000);

        if (target_brightness < LED_STRIP_BRIGHTNESS_MIN) {
            target_brightness = LED_STRIP_BRIGHTNESS_MIN;
        } else if (target_brightness > LED_STRIP_BRIGHTNESS_MAX) {
            target_brightness = LED_STRIP_BRIGHTNESS_MAX;
        }

        for (int i = 0; i < FADE_DURATION; i += LOOP_DELAY) {
            if (!running) {
                break;
            }
            int current_brightness = (i * target_brightness) / FADE_DURATION;
            uint8_t frame[4] = {0x00, 0x00, 0x00, current_brightness};
            spiXfer(spi_handle, frame, NULL, 4);
            usleep(LOOP_DELAY);
        }

        if (running) {
            uint8_t frame[4] = {0x00, 0x00, 0x00, target_brightness};
            spiXfer(spi_handle, frame, NULL, 4);
        }

        usleep(LOOP_DELAY);
    }

    uint8_t off_frame[4] = {0x00, 0x00, 0x00, 0x00};
    spiXfer(spi_handle, off_frame, NULL, 4);

    if (i2c_handle_low >= 0) {
        i2cClose(i2c_handle_low);
    }
    if (i2c_handle_high >= 0) {
        i2cClose(i2c_handle_high);
    }
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

