    uint8_t buf[2];
    for (int i = 0; i < I2C_RETRIES; i++) {
        if (write(i2c_fd, &reg, 1) == 1 && read(i2c_fd, buf, 2) == 2) {
            *value = (buf[0] << 8) | buf[1];
            return 0;
        }
        usleep(I2C_DELAY);
    }
    perror("Failed to read I2C register");
    return -1;
}

