#define SELF_TEST_READ_INTERVAL_US 100000
#define SELF_TEST_READ_COUNT 5
#define SELF_TEST_FLAME_THRESHOLD 5

#define ERROR_PATTERN_LED_BLINKS 5
#define ERROR_PATTERN_BEEP_SHORT_US 200000
#define ERROR_PATTERN_BEEP_LONG_US 600000
#define ERROR_PATTERN_REPETITIONS 3

