static struct gpiod_chip *chip;
static struct gpiod_line *flame_sensor_line;
static struct gpiod_line *buzzer_line;
static struct gpiod_line *led_line;

void log_event(const char *event) {
    time_t now = time(NULL);
    printf("%s: %s\n", ctime(&now), event);
}

void cleanup() {
    if (flame_sensor_line) gpiod_line_release(flame_sensor_line);
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int self_test() {
    log_event("Starting self-test");

    // Blink LED twice
    for (int i = 0; i < SELF_TEST_LED_BLINKS; i++) {
        gpiod_line_set_value(led_line, 1);
        usleep(500000);
        gpiod_line_set_value(led_line, 0);
        usleep(500000);
    }

    // Read flame sensor 5 times
    int flame_detected_count = 0;
    for (int i = 0; i < SELF_TEST_READ_COUNT; i++) {
        int value = gpiod_line_get_value(flame_sensor_line);
        if (value < 0) {
            perror("Failed to read flame sensor");
            cleanup();
            exit(EXIT_FAILURE);
        }
        if (value == 0) flame_detected_count++;
        usleep(SELF_TEST_READ_INTERVAL_US);
    }

    if (flame_detected_count == SELF_TEST_READ_COUNT) {
        log_event("Self-test failed: flame sensor consistently reads LOW");
        return -1;
    }

    log_event("Self-test passed");
    return 0;
}

void error_pattern() {
    log_event("Error pattern activated");

    // Blink LED rapidly
    for (int i = 0; i < ERROR_PATTERN_LED_BLINKS; i++) {
        gpiod_line_set_value(led_line, 1);
        usleep(100000);
        gpiod_line_set_value(led_line, 0);
        usleep(100000);
    }

    // Buzzer short-short-long-short pattern
    for (int i = 0; i < ERROR_PATTERN_REPETITIONS; i++) {
        gpiod_line_set_value(buzzer_line, 1);
        usleep(ERROR_PATTERN_BEEP_SHORT_US);
        gpiod_line_set_value(buzzer_line, 0);
        usleep(ERROR_PATTERN_BEEP_SHORT_US);
        gpiod_line_set_value(buzzer_line, 1);
        usleep(ERROR_PATTERN_BEEP_LONG_US);
        gpiod_line_set_value(buzzer_line, 0);
        usleep(ERROR_PATTERN_BEEP_SHORT_US);
    }
}

