    if (!flame_sensor_line) {
        perror("Failed to get flame sensor line");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        perror("Failed to request input for flame sensor");
        cleanup();
        exit(EXIT_FAILURE);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request output for buzzer");
        cleanup();
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get LED line");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request output for LED");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (self_test() < 0) {
        error_pattern();
        cleanup();
        exit(EXIT_FAILURE);
    }

    log_event("Main loop started");

    while (1) {
        int value = gpiod_line_get_value(flame_sensor_line);
        if (value < 0) {
            perror("Failed to read flame sensor");
            cleanup();
            exit(EXIT_FAILURE);
        }

        if (value == 0) {
            gpiod_line_set_value(buzzer_line, 1);
            gpiod_line_set_value(led_line, 1);
            log_event("Flame detected");

            while (1) {
                int value = gpiod_line_get_value(flame_sensor_line);
                if (value < 0) {
                    perror("Failed to read flame sensor");
                    cleanup();
                    exit(EXIT_FAILURE);
                }
                if (value == 1) {
                    gpiod_line_set_value(buzzer_line, 0);
                    gpiod_line_set_value(led_line, 0);
                    log_event("Flame gone");
                    break;
                }
                usleep(POLL_INTERVAL_US);
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

