#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>

#define I2C_DEV "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define BLINK_MIN_RATE 0.5
#define BLINK_MAX_RATE 5.0

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void setup_gpio(int pin) {
    char path[50];
    snprintf(path, sizeof(path), "/sys/class/gpio/export");
    int export_fd = open(path, O_WRONLY);
    if (export_fd < 0) {
        perror("Failed to open GPIO export");
        exit(EXIT_FAILURE);
    }
    dprintf(export_fd, "%d", pin);
    close(export_fd);

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int direction_fd = open(path, O_WRONLY);
    if (direction_fd < 0) {
        perror("Failed to open GPIO direction");
        exit(EXIT_FAILURE);
    }
    write(direction_fd, "out", 3);
    close(direction_fd);
}

void cleanup_gpio(int pin) {
    char path[50];
    snprintf(path, sizeof(path), "/sys/class/gpio/unexport");
    int unexport_fd = open(path, O_WRONLY);
    if (unexport_fd < 0) {
        perror("Failed to open GPIO unexport");
        exit(EXIT_FAILURE);
    }
    dprintf(unexport_fd, "%d", pin);
    close(unexport_fd);
}

void set_gpio(int pin, int value) {
    char path[50];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int value_fd = open(path, O_WRONLY);
    if (value_fd < 0) {
        perror("Failed to open GPIO value");
        exit(EXIT_FAILURE);
    }
    dprintf(value_fd, "%d", value);
    close(value_fd);
}

int main() {
    signal(SIGINT, signal_handler);

    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        perror("Failed to send I2C command");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    setup_gpio(GPIO_PIN);

    double lux_buffer[BUFFER_SIZE] = {0};
    int buffer_index = 0;
    double total_lux = 0.0;

    while (running) {
        uint8_t raw_data[2];
        if (read(i2c_fd, raw_data, 2) != 2) {
            perror("Failed to read I2C data");
            continue;
        }

        uint16_t raw_value = (raw_data[0] << 8) | raw_data[1];
        double lux = raw_value / 1.2;

        total_lux -= lux_buffer[buffer_index];
        lux_buffer[buffer_index] = lux;
        total_lux += lux;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        double avg_lux = total_lux / BUFFER_SIZE;
        double blink_rate = BLINK_MIN_RATE + (avg_lux / 1000) * 4.5;
        if (blink_rate < BLINK_MIN_RATE) blink_rate = BLINK_MIN_RATE;
        if (blink_rate > BLINK_MAX_RATE) blink_rate = BLINK_MAX_RATE;

        struct timespec on_time, off_time;
        on_time.tv_sec = 0;
        on_time.tv_nsec = (long)(500000000 / blink_rate);
        off_time.tv_sec = 0;
        off_time.tv_nsec = (long)(500000000 / blink_rate);

        set_gpio(GPIO_PIN, 1);
        nanosleep(&on_time, NULL);
