#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define SEVEN_SEG_5 0b01101101 // Binary pattern for digit '5' on a 7-segment display

void shift_out(struct gpiod_chip *chip, unsigned int data, unsigned int clock, unsigned int latch) {
    struct gpiod_line *data_line = gpiod_chip_get_line(chip, data);
    struct gpiod_line *clock_line = gpiod_chip_get_line(chip, clock);
    struct gpiod_line *latch_line = gpiod_chip_get_line(chip, latch);

    if (!data_line || !clock_line || !latch_line) {
        perror("Failed to get GPIO lines");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(data_line, "data", 0) < 0 ||
        gpiod_line_request_output(clock_line, "clock", 0) < 0 ||
        gpiod_line_request_output(latch_line, "latch", 0) < 0) {
        perror("Failed to request GPIO lines as output");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(data_line, (SEVEN_SEG_5 >> i) & 1);
        gpiod_line_set_value(clock_line, 1);
        gpiod_line_set_value(clock_line, 0);
    }

    gpiod_line_set_value(latch_line, 1);
    gpiod_line_set_value(latch_line, 0);

    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(latch_line);
}

int main() {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    while (1) {
        shift_out(chip, DATA_PIN, CLOCK_PIN, LATCH_PIN);
        usleep(500000); // 500 ms on
        shift_out(chip, DATA_PIN, CLOCK_PIN, LATCH_PIN);
        usleep(500000); // 500 ms off
    }

    gpiod_chip_close(chip);
    return 0;
}

