#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define LED_GPIO 17
#define BUTTON_GPIO 18
#define CHIP "gpiochip0"
#define TIMEOUT_MS 1000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    struct gpiod_line_event event;
    int ret;

    // Set up signal handler for graceful termination
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        goto exit;
    }

    // Request LED line as output, initially low
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get LED line");
        goto exit;
    }

    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        goto exit;
    }

    // Request button line as input with internal pull-up and falling-edge event detection
    button_line = gpiod_chip_get_line(chip, BUTTON_GPIO);
    if (!button_line) {
        perror("Failed to get button line");
        goto exit;
    }

    ret = gpiod_line_request_falling_edge_events(button_line, "blink_button");
    if (ret < 0) {
        perror("Failed to request falling-edge events on button line");
        goto exit;
    }

    // Main loop
    while (running) {
        // Toggle LED
        ret = gpiod_line_set_value(led_line, !gpiod_line_get_value(led_line));
        if (ret < 0) {
            perror("Failed to set LED value");
            goto exit;
        }

        // Wait for button event or timeout
        ret = gpiod_line_event_wait(button_line, TIMEOUT_MS);
        if (ret < 0) {
            perror("Failed to wait for button event");
            goto exit;
        } else if (ret > 0) {
            // Read and process button event
            ret = gpiod_line_event_read(button_line, &event);
            if (ret < 0) {
                perror("Failed to read button event");
                goto exit;
            }

            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                printf("Button pressed, stopping blinking.\n");
                running = 0;
            }
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Turn off LED
    ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        perror("Failed to turn off LED");
    }

exit:
    // Release resources
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

