#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 5
#define DELAY_MS 750

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set GPIO5 as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Turn LED on
        gpioWrite(LED_PIN, PI_HIGH);
        printf("LED ON\n");
        fflush(stdout);
        gpioDelay(DELAY_MS * 1000); // gpioDelay takes microseconds

        // Turn LED off
        gpioWrite(LED_PIN, PI_LOW);
        printf("LED OFF\n");
        fflush(stdout);
        gpioDelay(DELAY_MS * 1000); // gpioDelay takes microseconds
    }

    // Clean up
    gpioWrite(LED_PIN, PI_LOW);
    gpioTerminate();
    return EXIT_SUCCESS;
}

