static struct gpiod_line *led_line = NULL;
static struct gpiod_line *button_line = NULL;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (button_line) {
        gpiod_line_release(button_line);
        button_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int ret;

    // Open the gpiochip0 device
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    // Get the LED line
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get LED line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request the LED line as output, initially low
    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Get the button line
    button_line = gpiod_chip_get_line(chip, BUTTON_GPIO);
    if (!button_line) {
        perror("Failed to get button line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request the button line as input with internal pull-down
    ret = gpiod_line_request_input(button_line, "button");
    if (ret < 0) {
        perror("Failed to request button line as input");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int button_state = gpiod_line_get_value(button_line);
        if (button_state < 0) {
            perror("Failed to read button state");
            cleanup();
            return EXIT_FAILURE;
        }

        if (button_state == 1) {
            // Button is pressed, blink the LED
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                perror("Failed to set LED high");
                cleanup();
                return EXIT_FAILURE;
            }
            usleep(BLINK_INTERVAL);

            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("Failed to set LED low");
                cleanup();
                return EXIT_FAILURE;
            }
            usleep(BLINK_INTERVAL);
        } else {
            // Button is released, turn off the LED
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("Failed to set LED low");
                cleanup();
                return EXIT_FAILURE;
            }
            usleep(100000); // Small delay before checking again
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

