            usleep(BLINK_INTERVAL);
        } else {
            // Button is released, turn off the LED
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("Failed to set LED low");
                cleanup();
                return EXIT_FAILURE;
            }
            usleep(100000); // Small delay before checking again
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}
