#include <unistd.h>
#include <gpiod.h>
#include <time.h>

#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18
#define PWM_PERIOD_NS 10000000 // 10 ms
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 10000000 // 100%

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void set_pwm(struct gpiod_line *line, unsigned int duty_cycle) {
    struct timespec on_time, off_time;
    on_time.tv_sec = 0;
    on_time.tv_nsec = (duty_cycle * PWM_PERIOD_NS) / PWM_DUTY_MAX;
    off_time.tv_sec = 0;
    off_time.tv_nsec = PWM_PERIOD_NS - on_time.tv_nsec;

    while (running) {
        gpiod_line_set_value(line, 1);
        clock_nanosleep(CLOCK_MONOTONIC, 0, &on_time, NULL);
        gpiod_line_set_value(line, 0);
        clock_nanosleep(CLOCK_MONOTONIC, 0, &off_time, NULL);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *red_line, *green_line, *blue_line;
    int ret;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    if (!red_line) {
        perror("Failed to get red GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    if (!green_line) {
        perror("Failed to get green GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!blue_line) {
        perror("Failed to get blue GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(red_line, "rgb_led", 0);
    if (ret < 0) {
        perror("Failed to request red GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(green_line, "rgb_led", 0);
    if (ret < 0) {
        perror("Failed to request green GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(blue_line, "rgb_led", 0);
    if (ret < 0) {
        perror("Failed to request blue GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    srand(time(NULL));

    while (running) {
        unsigned int red_duty = (rand() % (PWM_DUTY_MAX - PWM_DUTY_MIN + 1)) + PWM_DUTY_MIN;
        unsigned int green_duty = (rand() % (PWM_DUTY_MAX - PWM_DUTY_MIN + 1)) + PWM_DUTY_MIN;
        unsigned int blue_duty = (rand() % (PWM_DUTY_MAX - PWM_DUTY_MIN + 1)) + PWM_DUTY_MIN;

        set_pwm(red_line, red_duty);
        set_pwm(green_line, green_duty);
        set_pwm(blue_line, blue_duty);

        struct timespec sleep_time = {0, 100000000}; // 100 ms
        clock_nanosleep(CLOCK_MONOTONIC, 0, &sleep_time, NULL);
    }

    gpiod_line_release(red_line);
    gpiod_line_release(green_line);
    gpiod_line_release(blue_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

