#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x19
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define GPIO_PIN 17
#define DEFAULT_THRESHOLD 2.0
#define SENSITIVITY 16384.0
#define POLL_INTERVAL_US 100000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_impact(int handle, FILE *log_file) {
    uint8_t data[6];
    if (i2cReadI2CBlockData(handle, OUT_X_L_A | 0x80, 6, data) < 0) {
        fprintf(stderr, "I2C read error\n");
        return;
    }

    int16_t x = (data[1] << 8) | data[0];
    int16_t y = (data[3] << 8) | data[2];
    int16_t z = (data[5] << 8) | data[4];

    double g_force = sqrt((x * x + y * y + z * z) / (SENSITIVITY * SENSITIVITY));

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: X=%d, Y=%d, Z=%d, G-force=%.2f\n", timestamp, x, y, z, g_force);
}

int main(int argc, char *argv[]) {
    double threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO set mode failed\n");
        gpioTerminate();
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "I2C write CTRL_REG1_A failed\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "I2C write CTRL_REG4_A failed\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t data[6];
        if (i2cReadI2CBlockData(handle, OUT_X_L_A | 0x80, 6, data) < 0) {
            fprintf(stderr, "I2C read error\n");
            break;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        double g_force = sqrt((x * x + y * y + z * z) / (SENSITIVITY * SENSITIVITY));

        if (g_force > threshold) {
            gpioWrite(GPIO_PIN, PI_HIGH);
            usleep(50000);
            gpioWrite(GPIO_PIN, PI_LOW);

            log_impact(handle, log_file);
        }

        usleep(POLL_INTERVAL_US);
    }

    fclose(log_file);
    i2cClose(handle);
    gpioTerminate();

    return 0;
}

