#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x39
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_REG 0x66
#define GREEN_REG 0x68
#define BLUE_REG 0x6A
#define LED_PIN 18
#define SAMPLE_INTERVAL 500
#define RETRY_INTERVAL 100

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

void log_data(FILE *fp, uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
}

uint16_t read_register(uint8_t reg) {
    uint8_t buffer[2];
    if (i2cReadI2CBlockData(I2C_BUS, SENSOR_ADDR, reg, buffer, 2) < 0) {
        log_error("Failed to read from sensor");
        return 0;
    }
    return (buffer[1] << 8) | buffer[0];
}

void write_register(uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(I2C_BUS, SENSOR_ADDR, reg, value) < 0) {
        log_error("Failed to write to sensor");
        return;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if (i2cOpen(I2C_BUS, SENSOR_ADDR, 0) < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    write_register(MODE_REG, 0x01);

    FILE *fp = fopen("color_log.csv", "w");
    if (!fp) {
        log_error("Failed to open CSV file");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(fp, "Timestamp,ALS,Red,Green,Blue\n");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(LED_PIN, 1000);

    while (running) {
        uint16_t als = read_register(ALS_LSB_REG);
        uint16_t red = read_register(RED_REG);
        uint16_t green = read_register(GREEN_REG);
        uint16_t blue = read_register(BLUE_REG);

        log_data(fp, als, red, green, blue);

        uint8_t pwm_duty = (als * 255) / 65535;
        gpioPWM(LED_PIN, pwm_duty);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    fclose(fp);
    gpioPWM(LED_PIN, 0);
    i2cClose(I2C_BUS);
    gpioTerminate();

    return EXIT_SUCCESS;
}

