#define I2C_DEV "/dev/i2c-1"
#define GYRO_ADDR 0x69
#define WHO_AM_I_REG 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SAMPLE_RATE 20
#define CALIBRATION_SAMPLES 100
#define SENSITIVITY 0.00875
#define THRESHOLD 50.0

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int i2c_write_reg(int reg, int value) {
    unsigned char buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("i2c_write_reg");
        return -1;
    }
    return 0;
}

int i2c_read_reg(int reg, unsigned char *buf, int len) {
    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        return -1;
    }
    buf[0] = reg;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("write");
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        perror("read");
        return -1;
    }
    return 0;
}

int i2c_read_block(int reg, unsigned char *buf, int len) {
    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        return -1;
    }
    buf[0] = reg;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("write");
        return -1;
    }
    buf[0] = reg;
    if (read(i2c_fd, buf, len) != len) {
        perror("read");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    unsigned char who_am_i;
    if (i2c_read_reg(WHO_AM_I_REG, &who_am_i, 1) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (who_am_i != 0xD3) {
        fprintf(stderr, "Sensor not found\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_reg(CTRL_REG1, 0x0F) < 0 || i2c_write_reg(CTRL_REG4, 0x00) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    double offsets[3] = {0.0};
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        unsigned char data[6];
        if (i2c_read_block(OUT_X_L, data, 6) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];
        offsets[0] += x;
        offsets[1] += y;
        offsets[2] += z;
        usleep(50000);
    }
    offsets[0] /= CALIBRATION_SAMPLES;
    offsets[1] /= CALIBRATION_SAMPLES;
    offsets[2] /= CALIBRATION_SAMPLES;

    while (1) {
        unsigned char data[6];
        if (i2c_read_block(OUT_X_L, data, 6) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];
        double x_cal = (x - offsets[0]) * SENSITIVITY;
        double y_cal = (y - offsets[1]) * SENSITIVITY;
        double z_cal = (z - offsets[2]) * SENSITIVITY;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        fprintf(log_file, "%s X: %.2f Y: %.2f Z: %.2f\n", timestamp, x_cal, y_cal, z_cal);
        fflush(log_file);

        if (fabs(x_cal) > THRESHOLD || fabs(y_cal) > THRESHOLD || fabs(z_cal) > THRESHOLD) {
            fprintf(stderr, "Warning: Axis exceeded threshold\n");
            fprintf(log_file, "Alert: Axis exceeded threshold\n");
            fflush(log_file);
        }

        usleep(50000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

