#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define DEVID_REG 0x00
#define DATA_REG 0x32
#define LED_PIN 17
#define SAMPLE_RATE_MS 100
#define LOG_FILE "accel_log.txt"
#define THRESHOLD_G 2.0

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_handle;
    FILE *log_file;
    struct sigaction sa;
    double scale_factor = 3.9 / 32768.0; // ±2g range, 13-bit resolution

    // Setup signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Verify DEVID register
    char devid;
    if (i2cReadByteData(i2c_handle, DEVID_REG, &devid) < 0) {
        fprintf(stderr, "Failed to read DEVID register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect DEVID: 0x%02X\n", devid);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure sensor for full-resolution, ±2g range
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x08) < 0 || // Power control: measure mode
        i2cWriteByteData(i2c_handle, 0x31, 0x0B) < 0) { // Data format: full resolution, ±2g
        fprintf(stderr, "Failed to configure ADXL345\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Setup LED pin
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        char data[6];
        if (i2cReadI2CBlockData(i2c_handle, DATA_REG, data, 6) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        double ax = x * scale_factor;
        double ay = y * scale_factor;
        double az = z * scale_factor;

        // Log data
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, ax, ay, az);
        fflush(log_file);

        // Check threshold
        if (fabs(ax) > THRESHOLD_G || fabs(ay) > THRESHOLD_G || fabs(az) > THRESHOLD_G) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }

        usleep(SAMPLE_RATE_MS * 1000);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

