#define DATA_REG 0x01
#define CONTROL_REG 0x00
#define CONTROL_VALUE 0x80
#define SAMPLE_INTERVAL_US 10000

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    FILE *log_file = fopen("audio_log.dat", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    int i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    int i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2\n");
        i2cClose(i2c_handle1);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle1, CONTROL_REG, CONTROL_VALUE) < 0) {
        fprintf(stderr, "Failed to write to control register of sensor 1\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle2, CONTROL_REG, CONTROL_VALUE) < 0) {
        fprintf(stderr, "Failed to write to control register of sensor 2\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            continue;
        }

        int16_t sensor1_data = 0;
        int16_t sensor2_data = 0;

        if (i2cReadWordData(i2c_handle1, DATA_REG) >= 0) {
            sensor1_data = i2cReadWordData(i2c_handle1, DATA_REG);
        } else {
            fprintf(stderr, "Failed to read data from sensor 1\n");
        }

        if (i2cReadWordData(i2c_handle2, DATA_REG) >= 0) {
            sensor2_data = i2cReadWordData(i2c_handle2, DATA_REG);
        } else {
            fprintf(stderr, "Failed to read data from sensor 2\n");
        }

        int16_t tdoa = sensor1_data - sensor2_data;

        fprintf(log_file, "%ld,%ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, sensor1_data, sensor2_data, tdoa);
        fflush(log_file);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();
    fclose(log_file);

    return EXIT_SUCCESS;
}

