#define REGISTER_SIZE 16
#define SAMPLE_DELAY_US 100000
#define DUMMY_DELAY_US 40

#define GYRO_SENSITIVITY 0.005
#define ACCEL_SENSITIVITY 0.00025

#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCEL 0x0A
#define Y_ACCEL 0x0C
#define Z_ACCEL 0x0E

volatile sig_atomic_t running = 1;

void cleanup() {
    gpioTerminate();
}

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *file = fopen("imu_data.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open CSV file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    atexit(cleanup);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
        uint16_t tx[6] = {0x0000 | (X_GYRO << 8), 0x0000, 0x0000 | (Y_GYRO << 8), 0x0000, 0x0000 | (Z_GYRO << 8), 0x0000};
        uint16_t rx[6];

        if (spiXfer(spi_handle, (char *)tx, (char *)rx, 12) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        gyro_x = (rx[1] << 8) | rx[0];
        gyro_y = (rx[3] << 8) | rx[2];
        gyro_z = (rx[5] << 8) | rx[4];

        tx[0] = 0x0000 | (X_ACCEL << 8);
        tx[2] = 0x0000 | (Y_ACCEL << 8);
        tx[4] = 0x0000 | (Z_ACCEL << 8);

        if (spiXfer(spi_handle, (char *)tx, (char *)rx, 12) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        accel_x = (rx[1] << 8) | rx[0];
        accel_y = (rx[3] << 8) | rx[2];
        accel_z = (rx[5] << 8) | rx[4];

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long ms = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

        fprintf(file, "%ld,%.3f,%.3f,%.3f,%.6f,%.6f,%.6f\n",
                ms,
                gyro_x * GYRO_SENSITIVITY,
                gyro_y * GYRO_SENSITIVITY,
                gyro_z * GYRO_SENSITIVITY,
                accel_x * ACCEL_SENSITIVITY,
                accel_y * ACCEL_SENSITIVITY,
                accel_z * ACCEL_SENSITIVITY);

        gpioDelay(SAMPLE_DELAY_US);
    }

    fclose(file);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

