#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_FLAGS 0

#define ADIS16448_READ_CMD(reg) ((reg) | 0x8000)
#define ADIS16448_STALL_TIME 40

#define GYRO_SCALE 0.05
#define ACCL_SCALE 0.00025

#define GYRO_X_REG 0x04
#define GYRO_Y_REG 0x06
#define GYRO_Z_REG 0x08
#define ACCL_X_REG 0x0A
#define ACCL_Y_REG 0x0C
#define ACCL_Z_REG 0x0E

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE | SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        uint16_t gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z;

        // Read Gyro X
        if (spiXfer(spi_handle, (char[]){ADIS16448_READ_CMD(GYRO_X_REG) >> 8, ADIS16448_READ_CMD(GYRO_X_REG) & 0xFF, 0, 0},
                    (char[]){0, 0, (char*)&gyro_x, (char*)&gyro_x + 1}, 4) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            break;
        }
        gpioDelay(ADIS16448_STALL_TIME);
        if (spiXfer(spi_handle, (char[]){0, 0}, (char[]){0, 0}, 2) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            break;
        }

