#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MPU6886_ADDR 0x68
#define WHO_AM_I_REG 0x75
#define PWR_MGMT_1_REG 0x6B
#define ACCEL_CONFIG_REG 0x1C
#define GYRO_CONFIG_REG 0x1B
#define ACCEL_XOUT_H_REG 0x3B
#define GYRO_XOUT_H_REG 0x43
#define READ_RETRIES 3

int i2c_fd = -1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int i2c_write_byte(int reg, char data) {
    char buf[2] = {reg, data};
    int retries = READ_RETRIES;
    while (retries--) {
        if (write(i2c_fd, buf, 2) == 2) {
            return 0;
        }
        perror("i2c_write_byte");
    }
    return -1;
}

int i2c_read_bytes(int reg, char *buf, int len) {
    int retries = READ_RETRIES;
    while (retries--) {
        if (write(i2c_fd, &reg, 1) == 1 && read(i2c_fd, buf, len) == len) {
            return 0;
        }
        perror("i2c_read_bytes");
    }
    return -1;
}

int main() {
    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        return EXIT_FAILURE;
    }

    char who_am_i;
    if (i2c_read_bytes(WHO_AM_I_REG, &who_am_i, 1) < 0) {
        printf("Failed to read WHO_AM_I register\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (who_am_i != 0x86) {
        printf("Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(PWR_MGMT_1_REG, 0x00) < 0) {
        printf("Failed to wake up the MPU6886\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(ACCEL_CONFIG_REG, 0x00) < 0 || i2c_write_byte(GYRO_CONFIG_REG, 0x00) < 0) {
        printf("Failed to set accelerometer and gyroscope configurations\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        char accel_data[6], gyro_data[6];
        if (i2c_read_bytes(ACCEL_XOUT_H_REG, accel_data, 6) < 0 || i2c_read_bytes(GYRO_XOUT_H_REG, gyro_data, 6) < 0) {
            printf("Failed to read sensor data\n");
            continue;
        }

        int16_t accel_x = (accel_data[0] << 8) | accel_data[1];
        int16_t accel_y = (accel_data[2] << 8) | accel_data[3];
        int16_t accel_z = (accel_data[4] << 8) | accel_data[5];
        int16_t gyro_x = (gyro_data[0] << 8) | gyro_data[1];
        int16_t gyro_y = (gyro_data[2] << 8) | gyro_data[3];
        int16_t gyro_z = (gyro_data[4] << 8) | gyro_data[5];

        printf("Accel: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
        printf("Gyro: X=%d, Y=%d, Z=%d\n", gyro_x, gyro_y, gyro_z);

        usleep(50000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

