#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAZ0 0x36

#define LED_PIN 17
#define THRESHOLD_G 2.5
#define SCALE_FACTOR 256.0
#define LOG_FILE "impact_log.txt"
#define POLL_INTERVAL_US 10000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_handle;
    FILE *log_file = NULL;
    struct sigaction sa;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Verify device ID
    char device_id;
    if (i2cReadByteData(i2c_handle, ADXL345_REG_DEVID, &device_id) < 0) {
        fprintf(stderr, "Failed to read device ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (device_id != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure ADXL345
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0 || // Measure mode
        i2cWriteByteData(i2c_handle, ADXL345_REG_DATA_FORMAT, 0x0B) < 0) { // Full resolution, +-2g
        fprintf(stderr, "Failed to configure ADXL345\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up LED
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        char data[6];
        if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, data, 6) < 0) {
            fprintf(stderr, "Failed to read data from ADXL345\n");
            break;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        double ax = x / SCALE_FACTOR;
        double ay = y / SCALE_FACTOR;
        double az = z / SCALE_FACTOR;
        double magnitude = sqrt(ax * ax + ay * ay + az * az);

        if (magnitude > THRESHOLD_G) {
            gpioWrite(LED_PIN, PI_HIGH);
            usleep(500000);
            gpioWrite(LED_PIN, PI_LOW);

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s: Magnitude = %.2f g, X = %.2f g, Y = %.2f g, Z = %.2f g\n",
                    timestamp, magnitude, ax, ay, az);
            fflush(log_file);
        }

        usleep(POLL_INTERVAL_US);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

