        i2cWriteByteData(i2c_handle, ADXL345_REG_DATA_FORMAT, 0x0B) < 0) { // Full resolution, +-2g
        fprintf(stderr, "Failed to configure ADXL345\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up LED
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        char data[6];
        if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, data, 6) < 0) {
            fprintf(stderr, "Failed to read data from ADXL345\n");
            break;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        double ax = x / SCALE_FACTOR;
        double ay = y / SCALE_FACTOR;
        double az = z / SCALE_FACTOR;
        double magnitude = sqrt(ax * ax + ay * ay + az * az);

        if (magnitude > THRESHOLD_G) {
            gpioWrite(LED_PIN, PI_HIGH);
            usleep(500000);
            gpioWrite(LED_PIN, PI_LOW);

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s: Magnitude = %.2f g, X = %.2f g, Y = %.2f g, Z = %.2f g\n",
                    timestamp, magnitude, ax, ay, az);
            fflush(log_file);
        }

        usleep(POLL_INTERVAL_US);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}
```

This code initializes the pigpio library, sets up a signal handler for graceful termination, opens the I2C bus, verifies the ADXL345 device ID, configures the sensor, sets up a GPIO pin for the LED, and opens a log file. It then continuously polls the sensor, checks for impacts, and logs the data if an impact is detected. The program handles errors and ensures clean resource release on all exit paths.

