#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VAL 0x1A
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define LED_GPIO 17
#define THRESHOLD 2.0
#define G_TO_COUNTS 1024.0
#define POLL_INTERVAL_US 100000
#define LED_ON_DURATION_US 500000

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static int i2c_fd;
static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int i2c_write_reg(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_reg(int reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("I2C write reg failed");
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_reg(OUT_X_MSB, buf) == -1) {
        return -1;
    }
    *x = (buf[0] << 8) | buf[1];
    *y = (buf[2] << 8) | buf[3];
    *z = (buf[4] << 8) | buf[5];
    return 0;
}

void log_impact() {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strcspn(timestamp, "\n")] = 0; // Remove newline
    FILE *log_file = fopen("impact_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s: Impact detected\n", timestamp);
        fclose(log_file);
    } else {
        perror("Failed to open log file");
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Verify sensor identity
    uint8_t who_am_i;
    if (i2c_read_reg(WHO_AM_I_REG, &who_am_i) == -1 || who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Sensor identity verification failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize sensor
    if (i2c_write_reg(CTRL_REG1, 0x01) == -1) { // Active mode, 800 Hz
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as output
    if (gpiod_line_request_output(led_line, "accel_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int16_t x, y, z;
        if (read_acceleration(&x, &y, &z) == -1) {
            continue;
        }

        double mag = sqrt((x * x + y * y + z * z) / (G_TO_COUNTS * G_TO_COUNTS));
        if (mag > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
            log_impact();
            usleep(LED_ON_DURATION_US);
            gpiod_line_set_value(led_line, 0);
        }

        usleep(POLL_INTERVAL_US);
    }

    // Clean up
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

