#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x35
#define X_REG 0x10
#define Y_REG 0x11
#define Z_REG 0x12
#define BUFFER_SIZE 2

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("magnetic_field_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    while (1) {
        uint8_t buffer[BUFFER_SIZE];
        int16_t x, y, z;

        // Read X
        if (write(i2c_fd, &X_REG, 1) != 1) {
            perror("Failed to write X register address");
            continue;
        }
        if (read(i2c_fd, buffer, BUFFER_SIZE) != BUFFER_SIZE) {
            perror("Failed to read X register");
            continue;
        }
        x = (buffer[1] << 8) | buffer[0];

        // Read Y
        if (write(i2c_fd, &Y_REG, 1) != 1) {
            perror("Failed to write Y register address");
            continue;
        }
