#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_DEV "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define ADXL345_DEVICE_ID 0xE5
#define THRESH_FF_REG 0x0A
#define TIME_FF_REG 0x20
#define INT_ENABLE_REG 0x2E
#define INT_MAP_REG 0x2F
#define POWER_CTL_REG 0x2D
#define INT_SOURCE_REG 0x30
#define DATAX0_REG 0x32

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17

#define THRESH_FF_VALUE 0x1E // ~300 mg
#define TIME_FF_VALUE 0x0A   // ~100 ms

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        uint8_t disable_int = 0x00;
        if (write(i2c_fd, &disable_int, 1) != 1) {
            perror("Failed to disable interrupts");
        }
    }
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    // Verify device ID
    uint8_t device_id;
    if (write(i2c_fd, &device_id, 1) != 1 || read(i2c_fd, &device_id, 1) != 1) {
        perror("Failed to read device ID");
        cleanup();
        return EXIT_FAILURE;
    }
    if (device_id != ADXL345_DEVICE_ID) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        cleanup();
        return EXIT_FAILURE;
    }

    // Put sensor in standby
    uint8_t standby = 0x00;
    if (write(i2c_fd, &standby, 1) != 1) {
        perror("Failed to put sensor in standby");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure sensor
    uint8_t config[] = {
        THRESH_FF_REG, THRESH_FF_VALUE,
        TIME_FF_REG, TIME_FF_VALUE,
        INT_ENABLE_REG, 0x04, // Enable freefall interrupt
        INT_MAP_REG, 0x00,    // Map freefall interrupt to INT1
        POWER_CTL_REG, 0x08    // Enter measurement mode
    };
    if (write(i2c_fd, config, sizeof(config)) != sizeof(config)) {
        perror("Failed to configure sensor");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure GPIO line for falling-edge interrupt
    if (gpiod_line_request_falling_edge_events(gpio_line, "adxl345_int") < 0) {
        perror("Failed to request falling-edge events");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("freefall_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    // Poll for interrupts
    struct pollfd fds[1];
    fds[0].fd = gpiod_line_get_fd(gpio_line);
    fds[0].events = POLLIN;

    while (1) {
        int ret = poll(fds, 1, -1);
        if (ret < 0) {
            perror("Poll failed");
            break;
        } else if (ret == 0) {
            continue;
        }

        if (fds[0].revents & POLLIN) {
            // Read INT_SOURCE to verify freefall
            uint8_t int_source;
            if (write(i2c_fd, &int_source, 1) != 1 || read(i2c_fd, &int_source, 1) != 1) {
                perror("Failed to read INT_SOURCE");
                continue;
            }
            if (int_source & 0x04) { // Freefall detected
                // Read X, Y, Z data
                uint8_t data[6];
                if (write(i2c_fd, &data[0], 1) != 1 || read(i2c_fd, data, 6) != 6) {
                    perror("Failed to read acceleration data");
                    continue;
                }

                // Convert data to signed 16-bit values
                int16_t x = (data[1] << 8) | data[0];
                int16_t y = (data[3] << 8) | data[2];
                int16_t z = (data[5] << 8) | data[4];

                // Log timestamped data
                struct timespec ts;
                clock_gettime(CLOCK_REALTIME, &ts);
                char timestamp[30];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts));
                fprintf(log_file, "%s.%03ld,%d,%d,%d\n", timestamp, ts.tv_nsec / 1000000, x, y, z);
                fflush(log_file);
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

