#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>

#define LSM6DSR_I2C_ADDR 0x6A
#define LSM6DSR_WHO_AM_I_REG 0x0F
#define LSM6DSR_WHO_AM_I_VAL 0x6A
#define LSM6DSR_CTRL1_XL 0x10
#define LSM6DSR_CTRL2_G 0x11
#define LSM6DSR_OUTX_L_XL 0x28
#define LSM6DSR_OUTX_L_G 0x22

#define ACCEL_SCALE 0.061 // +-2g range
#define GYRO_SCALE 8.75   // +-250 dps range

#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5
#define WINDOW_DURATION 1.0

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_data(FILE *log_file, double timestamp, float ax, float ay, float az, float gx, float gy, float gz) {
    fprintf(log_file, "%.6f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", timestamp, ax, ay, az, gx, gy, gz);
}

float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetSignalFunc(SIGINT, signal_handler) < 0 ||
        gpioSetSignalFunc(SIGTERM, signal_handler) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(1, LSM6DSR_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    char who_am_i;
    if (i2cReadByteData(handle, LSM6DSR_WHO_AM_I_REG, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (who_am_i != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "Sensor not found\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(handle, LSM6DSR_CTRL1_XL, 0x60) < 0 || // 104 Hz ODR, +-2g
        i2cWriteByteData(handle, LSM6DSR_CTRL2_G, 0x60)) {  // 104 Hz ODR, +-250 dps
        fprintf(stderr, "Failed to configure sensor\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("motion_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,AccelX,AccelY,AccelZ,GyroX,GyroY,GyroZ\n");

    enum { IDLE, FREEFALL, IMPACT } state = IDLE;
    time_t start_time = time(NULL);
    float last_magnitude = 0.0;

    while (running) {
        char data[12];
        if (i2cReadI2CBlockData(handle, LSM6DSR_OUTX_L_XL, data, 12) < 0) {
            fprintf(stderr, "I2C read error\n");
            break;
        }

        float ax = (data[1] << 8 | data[0]) * ACCEL_SCALE;
        float ay = (data[3] << 8 | data[2]) * ACCEL_SCALE;
        float az = (data[5] << 8 | data[4]) * ACCEL_SCALE;
        float gx = (data[7] << 8 | data[6]) * GYRO_SCALE;
        float gy = (data[9] << 8 | data[8]) * GYRO_SCALE;
        float gz = (data[11] << 8 | data[10]) * GYRO_SCALE;

        double timestamp = time(NULL) - start_time;
        log_data(log_file, timestamp, ax, ay, az, gx, gy, gz);

        float magnitude = calculate_magnitude(ax, ay, az);

        switch (state) {
            case IDLE:
                if (magnitude < FREEFALL_THRESHOLD) {
                    state = FREEFALL;
                    start_time = time(NULL);
                }
                break;
            case FREEFALL:
                if (magnitude > IMPACT_THRESHOLD) {
                    state = IMPACT;
                    printf("Impact detected at %.6f\n", timestamp);
                } else if (time(NULL) - start_time > WINDOW_DURATION) {
                    state = IDLE;
                }
                break;
            case IMPACT:
                if (magnitude < FREEFALL_THRESHOLD) {
                    state = FREEFALL;
                    start_time = time(NULL);
                } else if (time(NULL) - start_time > WINDOW_DURATION) {
                    state = IDLE;
                }
                break;
        }

        last_magnitude = magnitude;
        gpioDelay(10000); // 10 ms delay
    }

    fclose(log_file);
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

