        i2cWriteByteData(handle, LSM6DSR_CTRL2_G, 0x60)) {  // 104 Hz ODR, +-250 dps
        fprintf(stderr, "Failed to configure sensor\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("motion_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,AccelX,AccelY,AccelZ,GyroX,GyroY,GyroZ\n");

    enum { IDLE, FREEFALL, IMPACT } state = IDLE;
    time_t start_time = time(NULL);
    float last_magnitude = 0.0;

    while (running) {
        char data[12];
        if (i2cReadI2CBlockData(handle, LSM6DSR_OUTX_L_XL, data, 12) < 0) {
            fprintf(stderr, "I2C read error\n");
            break;
        }

        float ax = (data[1] << 8 | data[0]) * ACCEL_SCALE;
        float ay = (data[3] << 8 | data[2]) * ACCEL_SCALE;
        float az = (data[5] << 8 | data[4]) * ACCEL_SCALE;
        float gx = (data[7] << 8 | data[6]) * GYRO_SCALE;
        float gy = (data[9] << 8 | data[8]) * GYRO_SCALE;
        float gz = (data[11] << 8 | data[10]) * GYRO_SCALE;

        double timestamp = time(NULL) - start_time;
        log_data(log_file, timestamp, ax, ay, az, gx, gy, gz);

        float magnitude = calculate_magnitude(ax, ay, az);

        switch (state) {
            case IDLE:
                if (magnitude < FREEFALL_THRESHOLD) {
                    state = FREEFALL;
                    start_time = time(NULL);
                }
                break;
            case FREEFALL:
                if (magnitude > IMPACT_THRESHOLD) {
                    state = IMPACT;
                    printf("Impact detected at %.6f\n", timestamp);
                } else if (time(NULL) - start_time > WINDOW_DURATION) {
                    state = IDLE;
                }
                break;
            case IMPACT:
                if (magnitude < FREEFALL_THRESHOLD) {
                    state = FREEFALL;
                    start_time = time(NULL);
                } else if (time(NULL) - start_time > WINDOW_DURATION) {
                    state = IDLE;
                }
                break;
        }

        last_magnitude = magnitude;
        gpioDelay(10000); // 10 ms delay
    }

    fclose(log_file);
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}
