#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define WHO_AM_I_REG 0x00
#define X_GYRO_OUT_REG 0x14
#define WHO_AM_I_ID 0x3F5A
#define SCALE 0.0305

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int spi_handle;
    FILE *log_file;
    struct timespec ts;
    uint16_t who_am_i, x_gyro_out;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file 'gyro_log.csv'\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Write CSV header
    fprintf(log_file, "Timestamp,Angular-Rate (deg/sec)\n");

    // Verify WHO_AM_I register
    uint8_t who_am_i_cmd = WHO_AM_I_REG;
    if (spiXfer(spi_handle, &who_am_i_cmd, NULL, 1) < 0) {
        fprintf(stderr, "Failed to send WHO_AM_I command\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (spiXfer(spi_handle, NULL, (uint8_t *)&who_am_i, 2) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I response\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    who_am_i = (who_am_i >> 8) | (who_am_i << 8); // Swap bytes
    if (who_am_i != WHO_AM_I_ID) {
        fprintf(stderr, "WHO_AM_I register mismatch: expected 0x%04X, got 0x%04X\n", WHO_AM_I_ID, who_am_i);
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        // Read X_GYRO_OUT register
        uint8_t x_gyro_out_cmd = X_GYRO_OUT_REG | 0x80;
        if (spiXfer(spi_handle, &x_gyro_out_cmd, NULL, 1) < 0) {
            fprintf(stderr, "Failed to send X_GYRO_OUT command\n");
            break;
        }
        if (spiXfer(spi_handle, NULL, (uint8_t *)&x_gyro_out, 2) < 0) {
            fprintf(stderr, "Failed to read X_GYRO_OUT response\n");
            break;
        }
        x_gyro_out = (x_gyro_out >> 8) | (x_gyro_out << 8); // Swap bytes

        // Calculate angular rate
        double angular_rate = x_gyro_out * SCALE;

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            fprintf(stderr, "Failed to get current timestamp\n");
            break;
        }

        // Log the reading
        fprintf(log_file, "%ld.%09ld,%f\n", ts.tv_sec, ts.tv_nsec, angular_rate);

        // Wait for 10 ms
        gpioDelay(10000);
    }

    // Clean up
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

