#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define GYRO_ADDR 0x69
#define WHO_AM_I_REG 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SAMPLE_RATE 10000 // 10 ms

#define WHO_AM_I_VAL 0xD3
#define CTRL_REG1_VAL 0x0F
#define CTRL_REG4_VAL 0x00
#define SENSITIVITY 114.285

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    FILE *log_file;
    struct timespec ts;
    uint8_t buffer[6];
    int retries;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Verify WHO_AM_I register
    retries = 3;
    while (retries--) {
        if (i2c_smbus_read_byte_data(i2c_fd, WHO_AM_I_REG) == WHO_AM_I_VAL) {
            break;
        }
        if (retries == 0) {
            fprintf(stderr, "Failed to verify WHO_AM_I register\n");
            close(i2c_fd);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        usleep(100000); // 100 ms delay before retry
    }

    // Configure CTRL_REG1 and CTRL_REG4
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG1, CTRL_REG1_VAL) < 0) {
        perror("Failed to write CTRL_REG1");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG4, CTRL_REG4_VAL) < 0) {
        perror("Failed to write CTRL_REG4");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Main loop
    while (running) {
        // Read 6 bytes starting at OUT_X_L
        if (i2c_smbus_read_i2c_block_data(i2c_fd, OUT_X_L, 6, buffer) != 6) {
            perror("Failed to read I2C data");
            continue;
        }

        // Convert raw values to degrees per second
        int16_t x = (buffer[1] << 8) | buffer[0];
        int16_t y = (buffer[3] << 8) | buffer[2];
        int16_t z = (buffer[5] << 8) | buffer[4];
        double x_dps = x / SENSITIVITY;
        double y_dps = y / SENSITIVITY;
        double z_dps = z / SENSITIVITY;

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get timestamp");
            continue;
        }

        // Write log entry
        fprintf(log_file, "%ld.%09ld,%f,%f,%f\n", ts.tv_sec, ts.tv_nsec, x_dps, y_dps, z_dps);

        // Sleep for 10 ms
        usleep(SAMPLE_RATE);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

