#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_MS 500

volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int sig) {
    stop_flag = 1;
}

void log_event(FILE *log_file, const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (!stop_flag) {
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);
        if (sensor_value == PI_BAD_GPIO) {
            log_event(log_file, "Error reading sensor value");
        } else {
            char *flame_status = (sensor_value == 0) ? "YES" : "NO";
            log_event(log_file, flame_status);

            if (sensor_value == 0) {
                printf("FLAME DETECTED!\n");
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

