#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x53
#define SAMPLE_INTERVAL_US 100000

static int i2c_fd = -1;
static FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void sigint_handler(int sig) {
    cleanup();
    exit(0);
