#define SENSOR1_LINE 17
#define SENSOR2_LINE 27
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor1 = NULL, *sensor2 = NULL;
    FILE *log_file = NULL;
    struct timespec ts;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        goto cleanup;
    }

    // Request lines with bias pull-up
    sensor1 = gpiod_chip_get_line(chip, SENSOR1_LINE);
    if (!sensor1) {
        perror("Failed to get GPIO line for sensor1");
        goto cleanup;
    }
    ret = gpiod_line_request_input(sensor1, "conveyor_sensor1");
    if (ret < 0) {
        perror("Failed to request input for sensor1");
        goto cleanup;
    }
    ret = gpiod_line_set_bias(sensor1, GPIOD_LINE_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Failed to set bias for sensor1");
        goto cleanup;
    }

    sensor2 = gpiod_chip_get_line(chip, SENSOR2_LINE);
    if (!sensor2) {
        perror("Failed to get GPIO line for sensor2");
        goto cleanup;
    }
    ret = gpiod_line_request_input(sensor2, "conveyor_sensor2");
    if (ret < 0) {
        perror("Failed to request input for sensor2");
        goto cleanup;
    }
    ret = gpiod_line_set_bias(sensor2, GPIOD_LINE_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Failed to set bias for sensor2");
        goto cleanup;
    }

    // Open log file
    log_file = fopen(CONVEYOR_LOG, "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Setup signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (running) {
        int sensor1_state = gpiod_line_get_value(sensor1);
        int sensor2_state = gpiod_line_get_value(sensor2);
        if (sensor1_state < 0 || sensor2_state < 0) {
            perror("Failed to read GPIO line");
            break;
        }

        // Get current time with millisecond precision
        clock_gettime(CLOCK_REALTIME, &ts);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S.%03ld", localtime(&ts.tv_sec), ts.tv_nsec / 1000000);

        // Log sensor states
        fprintf(log_file, "%s: Sensor1=%d, Sensor2=%d\n", time_str, sensor1_state, sensor2_state);
        fflush(log_file);

        // Check if both sensors are triggered
        if (sensor1_state == 1 && sensor2_state == 1) {
            printf("Conveyor halted: Both sensors triggered!\n");
        }

        // Sleep for 50 ms
        usleep(POLL_INTERVAL_US);
    }

cleanup:
    if (log_file) fclose(log_file);
    if (sensor1) gpiod_line_release(sensor1);
    if (sensor2) gpiod_line_release(sensor2);
    if (chip) gpiod_chip_close(chip);

    return 0;
}

