#include <signal.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define DATA_START_REG 0x01
#define DATA_REG_COUNT 6
#define WHO_AM_I_VALUE 0x2A
#define DATA_RATE_100HZ 0b010

static int i2c_fd = -1;
static FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int i2c_write_byte(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("i2c_write_byte");
        return -1;
    }
    return 0;
}

int i2c_read_block(int reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("i2c_read_block write");
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        perror("i2c_read_block read");
        return -1;
    }
    return 0;
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR ||
        signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        perror("ioctl");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    uint8_t who_am_i;
    if (i2c_read_block(WHO_AM_I_REG, &who_am_i, 1) < 0) {
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Unexpected WHO_AM_I value: 0x%02X\n", who_am_i);
        cleanup();
        exit(EXIT_FAILURE);
    }

    uint8_t ctrl_reg1;
    if (i2c_read_block(CTRL_REG1, &ctrl_reg1, 1) < 0) {
        cleanup();
        exit(EXIT_FAILURE);
    }

    ctrl_reg1 &= ~0x01; // Standby mode
    ctrl_reg1 |= (DATA_RATE_100HZ << 3); // Set data rate to 100 Hz
    ctrl_reg1 |= 0x01; // Active mode

    if (i2c_write_byte(CTRL_REG1, ctrl_reg1) < 0) {
        cleanup();
        exit(EXIT_FAILURE);
    }

    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        perror("fopen");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        uint8_t data[DATA_REG_COUNT];
        if (i2c_read_block(DATA_START_REG, data, DATA_REG_COUNT) < 0) {
            continue; // Skip this iteration on error
        }

        int16_t x = ((data[0] << 8) | data[1]) >> 4;
        int16_t y = ((data[2] << 8) | data[3]) >> 4;
        int16_t z = ((data[4] << 8) | data[5]) >> 4;

        double tilt_angle = atan2(x, sqrt(y * y + z * z)) * 180.0 / M_PI;

        if (fabs(tilt_angle) > 45.0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s: X=%d, Y=%d, Z=%d\n", timestamp, x, y, z);
            fflush(log_file);
        }

        usleep(10000); // 10 ms delay
    }

    cleanup();
    return 0;
}

