#define LIS3MDL_ADDR 0x1E
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VAL 0x3D
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define CTRL_REG3 0x22
#define OUT_X_L_REG 0x28
#define SENSITIVITY 0.146f
#define THRESHOLD 800.0f
#define LOG_FILE "magnetic_log.txt"
#define RETRY_LIMIT 3
#define SAMPLE_INTERVAL_US 100000

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    running = 0;
}

int i2c_write_reg(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("i2c_write_reg");
        return -1;
    }
    return 0;
}

int i2c_read_reg(int reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("i2c_read_reg write");
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        perror("i2c_read_reg read");
        return -1;
    }
    return 0;
}

int init_sensor() {
    uint8_t who_am_i;
    if (i2c_read_reg(WHO_AM_I_REG, &who_am_i, 1) == -1) {
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Unexpected WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }
