        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (reset_sensor(spi_handle) < 0) {
        fprintf(stderr, "Sensor reset failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
