#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE1 17
#define GPIO_LINE2 27
#define POLL_INTERVAL_US 100000

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk bulk;
    struct gpiod_line *lines[2];
    int ret;

    // Set up signal handler for graceful exit
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    lines[0] = gpiod_chip_get_line(chip, GPIO_LINE1);
    lines[1] = gpiod_chip_get_line(chip, GPIO_LINE2);
    if (!lines[0] || !lines[1]) {
        perror("Failed to get GPIO lines");
        ret = EXIT_FAILURE;
        goto exit;
    }

    // Configure lines for input
    ret = gpiod_line_request_input(lines[0], "ir_sensor1");
    if (ret < 0) {
        perror("Failed to request input for GPIO line 1");
        goto exit;
    }
    ret = gpiod_line_request_input(lines[1], "ir_sensor2");
    if (ret < 0) {
        perror("Failed to request input for GPIO line 2");
        goto exit;
    }

    // Add lines to bulk
    gpiod_line_bulk_init(&bulk);
    gpiod_line_bulk_add(&bulk, lines[0]);
    gpiod_line_bulk_add(&bulk, lines[1]);

    // Main loop
    while (running) {
        int values[2];
        struct timespec ts;

        // Read values from both lines
        ret = gpiod_line_request_get_values(&bulk, values);
        if (ret < 0) {
            perror("Failed to read GPIO lines");
            break;
        }

        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            break;
        }

        // Log obstacle detection status
        printf("[%ld.%09ld] Sensor 1: %s, Sensor 2: %s\n",
               ts.tv_sec, ts.tv_nsec,
               values[0] ? "Clear" : "Obstacle",
               values[1] ? "Clear" : "Obstacle");

        // Sleep for 100 ms
        usleep(POLL_INTERVAL_US);
    }

exit:
    // Release resources
    if (lines[0]) gpiod_line_release(lines[0]);
    if (lines[1]) gpiod_line_release(lines[1]);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

