#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8
#define MSC_CTRL_REG 0x24
#define DATA_READY_MODE 0x01
#define X_RATE_REG 0x04
#define Y_RATE_REG 0x06
#define Z_RATE_REG 0x08
#define SPI_MODE SPI_MODE_3
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED_HZ 1000000
#define SCALE_FACTOR 0.02
#define READ_DELAY_US 100000

static struct gpiod_chip *chip;
static struct gpiod_line *cs_line;
static int spi_fd;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct spi_ioc_transfer xfer[2];
    uint8_t tx[2], rx[2];
    int ret;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize libgpiod for CS pin
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(cs_line, "spi_cs");
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        cleanup();
        return EXIT_FAILURE;
    }

    // Write to MSC_CTRL register to enable data ready mode
    tx[0] = MSC_CTRL_REG | 0x80; // Set MSB to indicate write
    tx[1] = DATA_READY_MODE;
    xfer[0].tx_buf = (unsigned long)tx;
    xfer[0].rx_buf = 0;
    xfer[0].len = 2;
    xfer[0].speed_hz = SPI_SPEED_HZ;
    xfer[0].bits_per_word = SPI_BITS_PER_WORD;
    xfer[0].cs_change = 1;

    gpiod_line_set_value(cs_line, 0);
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), xfer);
    gpiod_line_set_value(cs_line, 1);
    if (ret < 0) {
        perror("Failed to write to MSC_CTRL register");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop to read gyroscope data
    while (running) {
        // Read X rate
        tx[0] = X_RATE_REG | 0x80; // Set MSB to indicate write
        xfer[0].tx_buf = (unsigned long)tx;
        xfer[0].rx_buf = 0;
        xfer[0].len = 1;
        xfer[0].speed_hz = SPI_SPEED_HZ;
        xfer[0].bits_per_word = SPI_BITS_PER_WORD;
        xfer[0].cs_change = 1;

        xfer[1].tx_buf = 0;
        xfer[1].rx_buf = (unsigned long)rx;
        xfer[1].len = 2;
        xfer[1].speed_hz = SPI_SPEED_HZ;
        xfer[1].bits_per_word = SPI_BITS_PER_WORD;
        xfer[1].cs_change = 0;

        gpiod_line_set_value(cs_line, 0);
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer);
        gpiod_line_set_value(cs_line, 1);
        if (ret < 0) {
            perror("Failed to read X rate");
            cleanup();
            return EXIT_FAILURE;
        }

        int16_t x_rate = (rx[0] << 8) | rx[1];

        // Read Y rate
        tx[0] = Y_RATE_REG | 0x80; // Set MSB to indicate write
        xfer[0].tx_buf = (unsigned long)tx;
        xfer[0].rx_buf = 0;
        xfer[0].len = 1;
        xfer[0].speed_hz = SPI_SPEED_HZ;
        xfer[0].bits_per_word = SPI_BITS_PER_WORD;
        xfer[0].cs_change = 1;

        xfer[1].tx_buf = 0;
        xfer[1].rx_buf = (unsigned long)rx;
        xfer[1].len = 2;
        xfer[1].speed_hz = SPI_SPEED_HZ;
        xfer[1].bits_per_word = SPI_BITS_PER_WORD;
        xfer[1].cs_change = 0;

        gpiod_line_set_value(cs_line, 0);
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer);
        gpiod_line_set_value(cs_line, 1);
        if (ret < 0) {
            perror("Failed to read Y rate");
            cleanup();
            return EXIT_FAILURE;
        }

        int16_t y_rate = (rx[0] << 8) | rx[1];

        // Read Z rate
        tx[0] = Z_RATE_REG | 0x80; // Set MSB to indicate write
        xfer[0].tx_buf = (unsigned long)tx;
        xfer[0].rx_buf = 0;
        xfer[0].len = 1;
        xfer[0].speed_hz = SPI_SPEED_HZ;
        xfer[0].bits_per_word = SPI_BITS_PER_WORD;
        xfer[0].cs_change = 1;

        xfer[1].tx_buf = 0;
        xfer[1].rx_buf = (unsigned long)rx;
        xfer[1].len = 2;
        xfer[1].speed_hz = SPI_SPEED_HZ;
        xfer[1].bits_per_word = SPI_BITS_PER_WORD;
        xfer[1].cs_change = 0;

        gpiod_line_set_value(cs_line, 0);
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer);
        gpiod_line_set_value(cs_line, 1);
        if (ret < 0) {
            perror("Failed to read Z rate");
            cleanup();
            return EXIT_FAILURE;
        }

        int16_t z_rate = (rx[0] << 8) | rx[1];

        // Convert raw values to angular rates
        double x_angular_rate = x_rate * SCALE_FACTOR;
        double y_angular_rate = y_rate * SCALE_FACTOR;
        double z_angular_rate = z_rate * SCALE_FACTOR;

        // Log the results
        printf("X Rate: %.2f deg/sec, Y Rate: %.2f deg/sec, Z Rate: %.2f deg/sec\n",
               x_angular_rate, y_angular_rate, z_angular_rate);

        // Delay for 100 ms
        usleep(READ_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

