#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define ADXL345_REG_DATA_X0 0x32
#define ADXL345_REG_DATA_Y0 0x34
#define ADXL345_REG_DATA_Z0 0x36
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int i2c_read_register(int reg, uint8_t *data, size_t len) {
    if (i2c_smbus_read_i2c_block_data(i2c_fd, reg, len, data) != len) {
        perror("Failed to read from I2C");
        return -1;
    }
    return 0;
}

int i2c_write_register(int reg, uint8_t value) {
    if (i2c_smbus_write_byte_data(i2c_fd, reg, value) < 0) {
        perror("Failed to write to I2C");
        return -1;
    }
    return 0;
}

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Power control register: 0x2D, 0x08 (measure mode)
    if (i2c_write_register(0x2D, 0x08) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t data[6];
        if (i2c_read_register(ADXL345_REG_DATA_X0, data, sizeof(data)) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        double x_g = x * 0.00390625;
        double y_g = y * 0.00390625;
        double z_g = z * 0.00390625;

        double pitch = atan2(y_g, z_g) * 180.0 / M_PI;
        double roll = atan2(-x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0 / M_PI;

        if (fabs(pitch) > TILT_THRESHOLD || fabs(roll) > TILT_THRESHOLD) {
            char message[256];
            snprintf(message, sizeof(message), "Tilt detected: Pitch = %.2f, Roll = %.2f", pitch, roll);
            log_event(message);
        }

        usleep(100000); // 100 ms
    }

    cleanup();
    return EXIT_SUCCESS;
}

