int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr;
    int threshold = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Invalid threshold: %s\n", argv[1]);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        struct timespec start, end;
        if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
            perror("clock_gettime");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        int high_count = 0;
        while (running) {
            if (gpioRead(GPIO_PIN) == PI_HIGH) {
                high_count++;
            }

            if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
                perror("clock_gettime");
                gpioTerminate();
                return EXIT_FAILURE;
            }

            long elapsed_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            if (elapsed_us >= WINDOW_DURATION_US) {
                break;
            }

            usleep(SAMPLE_INTERVAL_US);
