            time_t now = time(NULL);
            printf("%sALERT: High sound level detected\n", ctime(&now));
        } else {
            time_t now = time(NULL);
            printf("%sNormal sound level\n", ctime(&now));
        }

        usleep(PAUSE_DURATION_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}
