#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <stdbool.h>
#include <limits.h>

#define GPIO_CHIP "gpiochip0"
#define DOOR_A_LINE 17
#define DOOR_B_LINE 27
#define LOG_FILE "access_log.txt"
#define CODE_MIN 100000
#define CODE_MAX 999999
#define UNLOCK_DURATION 5

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int sig) {
    exit_flag = 1;
}

void log_access(const char *code) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log, "%s,%s\n", timestamp, code);
    fclose(log);
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *door_a_line = NULL;
    struct gpiod_line *door_b_line = NULL;
    int ret;

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Get lines
    door_a_line = gpiod_chip_get_line(chip, DOOR_A_LINE);
    door_b_line = gpiod_chip_get_line(chip, DOOR_B_LINE);
    if (!door_a_line || !door_b_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    // Request lines as outputs
    ret = gpiod_line_request_output(door_a_line, "door_access", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", DOOR_A_LINE, strerror(errno));
        goto cleanup;
    }

    ret = gpiod_line_request_output(door_b_line, "door_access", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", DOOR_B_LINE, strerror(errno));
        goto cleanup;
    }

    // Seed random number generator
    srand(time(NULL));

    // Generate initial code
    int code = CODE_MIN + rand() % (CODE_MAX - CODE_MIN + 1);
    printf("Initial security code: %06d\n", code);

    char input[7];
    while (!exit_flag) {
        printf("Enter security code: ");
        if (fgets(input, sizeof(input), stdin) == NULL) {
            fprintf(stderr, "Failed to read input: %s\n", strerror(errno));
            continue;
        }

        // Remove newline character
        input[strcspn(input, "\n")] = '\0';

        // Check if input is a valid 6-digit number
        if (strlen(input) != 6 || !strspn(input, "0123456789") == 6) {
            printf("Invalid input. Please enter a 6-digit number.\n");
            continue;
        }

        int entered_code = atoi(input);
        if (entered_code == code) {
            // Unlock Door A
            ret = gpiod_line_set_value(door_a_line, 1);
            if (ret < 0) {
                fprintf(stderr, "Failed to set GPIO line %d: %s\n", DOOR_A_LINE, strerror(errno));
                continue;
            }

            // Log access
            log_access(input);

            // Wait for unlock duration
            sleep(UNLOCK_DURATION);

            // Re-lock Door A
            ret = gpiod_line_set_value(door_a_line, 0);
            if (ret < 0) {
                fprintf(stderr, "Failed to set GPIO line %d: %s\n", DOOR_A_LINE, strerror(errno));
                continue;
            }

            // Generate new code
            code = CODE_MIN + rand() % (CODE_MAX - CODE_MIN + 1);
            printf("New security code: %06d\n", code);
        } else {
            printf("Access denied\n");
        }
    }

cleanup:
    // Ensure both doors are locked
    if (door_a_line) {
        gpiod_line_set_value(door_a_line, 0);
        gpiod_line_release(door_a_line);
    }
    if (door_b_line) {
        gpiod_line_set_value(door_b_line, 0);
        gpiod_line_release(door_b_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

