#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDRESS 0x23
#define BH1750_COMMAND 0x21
#define I2C_BUFFER_SIZE 2
#define CONVERSION_TIME_US 180000
#define LOG_FILE "light_log.txt"

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        uint8_t command = BH1750_COMMAND;
        if (write(i2c_fd, &command, 1) != 1) {
            perror("Failed to write to the BH1750 sensor");
            cleanup();
            exit(EXIT_FAILURE);
        }

        usleep(CONVERSION_TIME_US);

        uint8_t buffer[I2C_BUFFER_SIZE];
        if (read(i2c_fd, buffer, I2C_BUFFER_SIZE) != I2C_BUFFER_SIZE) {
            perror("Failed to read from the BH1750 sensor");
            cleanup();
            exit(EXIT_FAILURE);
        }

        uint16_t raw_value = (buffer[0] << 8) | buffer[1];
        float lux_value = (raw_value * 5.0) / 6.0;

        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strcspn(timestamp, "\n")] = 0; // Remove newline

        fprintf(log_file, "Timestamp: %s, Lux: %.2f\n", timestamp, lux_value);
        fflush(log_file);

        sleep(5);
    }

    cleanup();
    return 0;
}

