#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define PWM_PIN 18
#define SAMPLE_INTERVAL 20000 // 20 ms
#define PLAYBACK_DURATION 5000 // 5 seconds
#define LOG_FILE "frequency_log.txt"
#define SECRET_KEY "MySecretKey"
#define MIN_FREQ 220
#define MAX_FREQ 880

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_handle, server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    char buffer[1024] = {0};
    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        perror("pigpio initialization failed");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        perror("I2C open failed");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // MPR121 soft reset
    i2cWriteByteData(i2c_handle, 0x80, 0x63);
    usleep(10000);
    i2cWriteByteData(i2c_handle, 0x80, 0x00);

    // Configure MPR121
    i2cWriteByteData(i2c_handle, 0x5E, 0x01); // Set electrode configuration
    i2cWriteByteData(i2c_handle, 0x5F, 0x01);
    i2cWriteByteData(i2c_handle, 0x60, 0x01);
    i2cWriteByteData(i2c_handle, 0x61, 0x01);
    i2cWriteByteData(i2c_handle, 0x62, 0x01);
    i2cWriteByteData(i2c_handle, 0x63, 0x01);
    i2cWriteByteData(i2c_handle, 0x64, 0x01);
    i2cWriteByteData(i2c_handle, 0x65, 0x01);
    i2cWriteByteData(i2c_handle, 0x66, 0x01);
    i2cWriteByteData(i2c_handle, 0x67, 0x01);
    i2cWriteByteData(i2c_handle, 0x68, 0x01);
    i2cWriteByteData(i2c_handle, 0x69, 0x01);

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(12345);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        read(new_socket, buffer, 1024);
        if (strncmp(buffer, "MOTION_DETECTED:", 14) == 0 && strstr(buffer, SECRET_KEY) != NULL) {
            gpioSetPWMfrequency(PWM_PIN, MIN_FREQ);
            gpioSetPWMrange(PWM_PIN, 1000);
            gpioSetPWMdutycycle(PWM_PIN, 500);

            struct timeval start_time, current_time;
            gettimeofday(&start_time, NULL);

            while (running) {
                gettimeofday(&current_time, NULL);
                long elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_usec - start_time.tv_usec) / 1000;
                if (elapsed_time >= PLAYBACK_DURATION) {
                    break;
                }

                uint16_t touch_data = i2cReadWordData(i2c_handle, 0x04);
                uint16_t max_filtered_data = i2cReadWordData(i2c_handle, 0x06);
                if (max_filtered_data > 0) {
                    float freq = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * log10((float)touch_data / max_filtered_data);
                    gpioSetPWMfrequency(PWM_PIN, (int)freq);
                    fprintf(log_file, "Frequency: %d Hz\n", (int)freq);
                    fflush(log_file);
                }

                usleep(SAMPLE_INTERVAL);
            }

            gpioSetPWMdutycycle(PWM_PIN, 0);
        }

        close(new_socket);
    }

    gpioSetPWMdutycycle(PWM_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    close(server_fd);

    return EXIT_SUCCESS;
