#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <math.h>

#define I2C_DEV "/dev/i2c-1"
#define LSM303DLHC_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_GPIO 17
#define PWM_PERIOD 1000000 // 1 second
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 1000000 // 1 second
#define SAMPLE_INTERVAL 100000 // 100 ms

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static int i2c_fd;
static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void init_i2c() {
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303DLHC_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("Failed to set GPIO line value");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_pwm() {
    if (gpiod_line_request_pwm(led_line, "led_pwm") < 0) {
        perror("Failed to request PWM on GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_pwm_period(led_line, PWM_PERIOD) < 0) {
        perror("Failed to set PWM period");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_sensor() {
    uint8_t reg = CTRL_REG1_M;
    uint8_t value = 0x18; // 10 Hz continuous conversion

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to CTRL_REG1_M");
        return;
    }

    if (write(i2c_fd, &value, 1) != 1) {
        perror("Failed to write value to CTRL_REG1_M");
        return;
    }
}

void read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t reg = OUT_X_L_M;
    uint8_t buffer[6];

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to OUT_X_L_M");
        return;
    }

    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Failed to read from I2C");
        return;
    }

    *x = (buffer[1] << 8) | buffer[0];
    *y = (buffer[3] << 8) | buffer[2];
    *z = (buffer[5] << 8) | buffer[4];
}

void set_led_brightness(int16_t z) {
    double magnitude = fabs(z);
    double duty_cycle = (magnitude / 32768.0) * PWM_DUTY_MAX;
    duty_cycle = fmin(fmax(duty_cycle, PWM_DUTY_MIN), PWM_DUTY_MAX);

    if (gpiod_line_set_pwm_duty_cycle(led_line, (unsigned int)duty_cycle) < 0) {
        perror("Failed to set PWM duty cycle");
    }
}

void cleanup() {
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c();
    init_gpio();
    init_pwm();
    init_sensor();

    while (running) {
        int16_t x, y, z;
        read_sensor_data(&x, &y, &z);
        set_led_brightness(z);
        usleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

