#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define CONFIG_REG_A 0x00
#define CONFIG_REG_B 0x01
#define MODE_REG 0x02
#define DATA_REG 0x03

#define SAMPLE_WINDOW 100
#define SAMPLE_INTERVAL_US 500000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure the HMC5883L
    if (i2cWriteByteData(i2c_handle, CONFIG_REG_A, 0x70) < 0) {
        fprintf(stderr, "I2C write to CONFIG_REG_A failed\n");
        goto cleanup;
    }
    if (i2cWriteByteData(i2c_handle, CONFIG_REG_B, 0x20) < 0) {
        fprintf(stderr, "I2C write to CONFIG_REG_B failed\n");
        goto cleanup;
    }
    if (i2cWriteByteData(i2c_handle, MODE_REG, 0x00) < 0) {
        fprintf(stderr, "I2C write to MODE_REG failed\n");
        goto cleanup;
    }

    double offsets[3] = {0.0};
    int sample_count = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        char buffer[6];
        if (i2cReadI2CBlockData(i2c_handle, DATA_REG, buffer, 6) < 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        int16_t x = (buffer[0] << 8) | buffer[1];
        int16_t y = (buffer[4] << 8) | buffer[5];
        int16_t z = (buffer[2] << 8) | buffer[3];

        if (sample_count < SAMPLE_WINDOW) {
            offsets[0] += x;
            offsets[1] += y;
            offsets[2] += z;
            sample_count++;
        } else {
            offsets[0] = (offsets[0] + x) / 2.0;
            offsets[1] = (offsets[1] + y) / 2.0;
            offsets[2] = (offsets[2] + z) / 2.0;
        }

        if (sample_count >= SAMPLE_WINDOW) {
            printf("Offset-corrected X: %d, Y: %d, Z: %d\n", x - (int)offsets[0], y - (int)offsets[1], z - (int)offsets[2]);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

cleanup:
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

