#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define LSM303D_ADDR 0x1D
#define WHO_AM_I_REG 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define INT1_CFG 0x30
#define INT1_THS 0x32
#define INT1_DURATION 0x33
#define OUT_X_L_A 0x28

#define BUFFER_SIZE 64
#define SAMPLE_SIZE 6
#define SAMPLE_RATE_US 10000

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelerationSample;

AccelerationSample buffer[BUFFER_SIZE];
volatile sig_atomic_t running = 1;
int buffer_head = 0;

void handle_sigint(int sig) {
    running = 0;
}

void disable_accelerometer(int i2c_fd) {
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG1, 0x00) < 0) {
        perror("Failed to disable accelerometer");
    }
}

void read_acceleration(int i2c_fd) {
    uint8_t data[SAMPLE_SIZE];
    if (i2c_smbus_read_i2c_block_data(i2c_fd, OUT_X_L_A | 0x80, SAMPLE_SIZE, data) < 0) {
        fprintf(stderr, "I2C read failed, skipping sample\n");
        return;
    }

    buffer[buffer_head].x = (data[1] << 8) | data[0];
    buffer[buffer_head].y = (data[3] << 8) | data[2];
    buffer[buffer_head].z = (data[5] << 8) | data[4];

    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
}

void print_samples(int count) {
    for (int i = 0; i < count; i++) {
        int index = (buffer_head - count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("Sample %d: X=%d, Y=%d, Z=%d\n", index, buffer[index].x, buffer[index].y, buffer[index].z);
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t who_am_i = i2c_smbus_read_byte_data(i2c_fd, WHO_AM_I_REG);
    if (who_am_i != 0x49) {
        fprintf(stderr, "Unexpected WHO_AM_I value: 0x%02X\n", who_am_i);
