#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define SOL1_LINE 17
#define SOL2_LINE 27

static struct gpiod_chip *chip;
static struct gpiod_line *sol1_line;
static struct gpiod_line *sol2_line;

void cleanup_and_exit(int signum) {
    if (sol1_line) {
        gpiod_line_release(sol1_line);
    }
    if (sol2_line) {
        gpiod_line_release(sol2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    fprintf(stderr, "Exiting cleanly on signal %d\n", signum);
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    struct timespec ts = {0, 500000000}; // 500 ms

    // Setup signal handler for SIGINT and SIGTERM
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Request the gpiochip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Request lines with consumer labels
    sol1_line = gpiod_chip_get_line(chip, SOL1_LINE);
    if (!sol1_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(EXIT_FAILURE);
    }
    sol2_line = gpiod_chip_get_line(chip, SOL2_LINE);
    if (!sol2_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    // Configure lines as output
    if (gpiod_line_request_output(sol1_line, "solenoid1", 0) == -1) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(sol2_line, "solenoid2", 0) == -1) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(EXIT_FAILURE);
    }

    // Drive both lines LOW at startup
    if (gpiod_line_set_value(sol1_line, 0) == -1) {
        perror("gpiod_line_set_value");
        cleanup_and_exit(EXIT_FAILURE);
    }
    if (gpiod_line_set_value(sol2_line, 0) == -1) {
        perror("gpiod_line_set_value");
        cleanup_and_exit(EXIT_FAILURE);
    }

    // Main loop to alternate solenoids
    while (1) {
        // Energize solenoid 1 for 500 ms
        if (gpiod_line_set_value(sol1_line, 1) == -1) {
            perror("gpiod_line_set_value");
            cleanup_and_exit(EXIT_FAILURE);
        }
        nanosleep(&ts, NULL);

        // De-energize solenoid 1 and energize solenoid 2 for 500 ms
        if (gpiod_line_set_value(sol1_line, 0) == -1) {
            perror("gpiod_line_set_value");
            cleanup_and_exit(EXIT_FAILURE);
        }
        if (gpiod_line_set_value(sol2_line, 1) == -1) {
            perror("gpiod_line_set_value");
            cleanup_and_exit(EXIT_FAILURE);
        }
        nanosleep(&ts, NULL);

        // De-energize solenoid 2
        if (gpiod_line_set_value(sol2_line, 0) == -1) {
            perror("gpiod_line_set_value");
            cleanup_and_exit(EXIT_FAILURE);
        }
    }

    // Cleanup should never reach here, but just in case
    cleanup_and_exit(EXIT_SUCCESS);
}

