#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>
#include <signal.h>
#include <errno.h>

#define GPIO17 17
#define GPIO27 27
#define UART0 "/dev/serial0"
#define UART1 "/dev/serial1"
#define BAUD_RATE 9600
#define TIMEOUT_US 5000000 // 5 seconds
#define CODE_LENGTH 6
#define EXPECTED_CODE "123456"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int setup_uart(const char *device, int *fd) {
    *fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (*fd == -1) {
        perror("Failed to open UART");
        return -1;
    }

    struct termios options;
    tcgetattr(*fd, &options);
    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~CRTSCTS;
    options.c_cflag |= CREAD | CLOCAL;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;

    tcsetattr(*fd, TCSANOW, &options);
    return 0;
}

int read_code(int fd, char *code, size_t length) {
    char buffer[1024];
    size_t index = 0;
    struct timeval timeout;
    fd_set set;

    FD_ZERO(&set);
    FD_SET(fd, &set);
    timeout.tv_sec = TIMEOUT_US / 1000000;
    timeout.tv_usec = TIMEOUT_US % 1000000;

    while (index < length) {
        int ready = select(fd + 1, &set, NULL, NULL, &timeout);
        if (ready == -1) {
            perror("Select failed");
            return -1;
        } else if (ready == 0) {
            fprintf(stderr, "Timeout reading from UART\n");
            return -1;
        }

        ssize_t n = read(fd, buffer, sizeof(buffer));
        if (n == -1) {
            perror("Read failed");
            return -1;
        }

        for (size_t i = 0; i < n; i++) {
            if (buffer[i] >= '0' && buffer[i] <= '9') {
                code[index++] = buffer[i];
                if (index == length) {
                    break;
                }
            } else {
                index = 0; // Reset on non-digit character
            }
        }
    }
    code[index] = '\0';
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO17, PI_OUTPUT) < 0 || gpioSetMode(GPIO27, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(GPIO17, PI_LOW);
    gpioWrite(GPIO27, PI_LOW);

    int uart0_fd, uart1_fd;
    if (setup_uart(UART0, &uart0_fd) < 0 || setup_uart(UART1, &uart1_fd) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    char code0[CODE_LENGTH + 1], code1[CODE_LENGTH + 1];

    while (running) {
        memset(code0, 0, sizeof(code0));
        memset(code1, 0, sizeof(code1));

        if (read_code(uart0_fd, code0, CODE_LENGTH) < 0 || read_code(uart1_fd, code1, CODE_LENGTH) < 0) {
            continue;
        }

        if (strncmp(code0, code1, CODE_LENGTH) == 0 && strncmp(code0, EXPECTED_CODE, CODE_LENGTH) == 0) {
            gpioWrite(GPIO17, PI_HIGH);
            gpioWrite(GPIO27, PI_HIGH);
            usleep(2000000); // 2 seconds
            gpioWrite(GPIO17, PI_LOW);
            gpioWrite(GPIO27, PI_LOW);
        }
    }

    gpioWrite(GPIO17, PI_LOW);
    gpioWrite(GPIO27, PI_LOW);
    close(uart0_fd);
    close(uart1_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

