#define MAX_MOTION_DURATION_US 10000000
#define STRIKE_DURATION_US 1000000

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    struct sigaction sa;
    int ret;

    openlog("pir_relay", LOG_PID, LOG_DAEMON);

    // Setup signal handler for graceful shutdown
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set up signal handler: %m");
        goto cleanup;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip %s: %m", GPIO_CHIP);
        goto cleanup;
    }

