    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %m", PIR_PIN);
        goto cleanup;
    }
    ret = gpiod_line_request_input(pir_line, "pir_relay");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line %d as input: %m", PIR_PIN);
        goto cleanup;
    }

    // Request the relay line as output
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %m", RELAY_PIN);
        goto cleanup;
    }
    ret = gpiod_line_request_output(relay_line, "pir_relay", 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line %d as output: %m", RELAY_PIN);
        goto cleanup;
    }

    syslog(LOG_INFO, "System initialized. Waiting for motion...");

    while (running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to read GPIO line %d: %m", PIR_PIN);
            break;
        }

        if (pir_value) {
            static struct timespec last_motion_time;
            static int motion_detected = 0;

            if (!motion_detected) {
                motion_detected = 1;
                clock_gettime(CLOCK_MONOTONIC, &last_motion_time);
                syslog(LOG_INFO, "Motion detected. Activating relay for 1 second.");
                gpiod_line_set_value(relay_line, 1);
            } else {
                struct timespec current_time;
                clock_gettime(CLOCK_MONOTONIC, &current_time);
                if (timespec_subtract(&current_time, &last_motion_time) > MAX_MOTION_DURATION_US) {
                    syslog(LOG_WARNING, "PIR sensor remains HIGH for more than 10 seconds. De-energizing relay.");
                    gpiod_line_set_value(relay_line, 0);
                    motion_detected = 0;
                }
            }
        } else {
            gpiod_line_set_value(relay_line, 0);
            motion_detected = 0;
        }

        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down...");

cleanup:
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();

    return 0;
}

int timespec_subtract(struct timespec *result, struct timespec *x, struct timespec *y) {
    if (x->tv_sec < y->tv_sec) return -1;
    if (x->tv_sec > y->tv_sec) return 1;
    if (x->tv_nsec < y->tv_nsec) return -1;
    if (x->tv_nsec > y->tv_nsec) return 1;
    return 0;
}

