#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>

#define RELAY1 GPIO4
#define RELAY2 GPIO17
#define RELAY3 GPIO27
#define RELAY4 GPIO22

#define RELAY_COUNT 4
#define RELAY_GPIO[] { RELAY1, RELAY2, RELAY3, RELAY4 }

#define ACTIVATION_TIME 300
#define PAUSE_TIME 60

volatile sig_atomic_t running = 1;

typedef enum {
    STATE_INIT,
    STATE_ACTIVATING,
    STATE_DEACTIVATING,
    STATE_PAUSING
} State;

State currentState = STATE_INIT;
int currentRelay = 0;
time_t startTime;

void signalHandler(int signum) {
    running = 0;
}

void logStateChange(int relay, int state) {
    time_t now = time(NULL);
    char *timeStr = ctime(&now);
    timeStr[strlen(timeStr) - 1] = '\0'; // Remove newline
    syslog(LOG_INFO, "Relay %d: %s at %s", relay, state ? "OFF" : "ON", timeStr);
}

void timerCallback(void *arg) {
    switch (currentState) {
        case STATE_INIT:
            currentState = STATE_DEACTIVATING;
            break;
        case STATE_DEACTIVATING:
            gpioWrite(RELAY_GPIO[currentRelay], PI_HIGH);
            logStateChange(RELAY_GPIO[currentRelay], 1);
            currentState = STATE_PAUSING;
            startTime = time(NULL);
            break;
        case STATE_PAUSING:
            if (time(NULL) - startTime >= PAUSE_TIME) {
                currentState = STATE_ACTIVATING;
                startTime = time(NULL);
            }
            break;
        case STATE_ACTIVATING:
            gpioWrite(RELAY_GPIO[currentRelay], PI_LOW);
            logStateChange(RELAY_GPIO[currentRelay], 0);
            currentRelay = (currentRelay + 1) % RELAY_COUNT;
            currentState = STATE_DEACTIVATING;
            break;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    for (int i = 0; i < RELAY_COUNT; i++) {
        if (gpioSetMode(RELAY_GPIO[i], PI_OUTPUT) < 0) {
            syslog(LOG_ERR, "Failed to set GPIO %d as output", RELAY_GPIO[i]);
            gpioTerminate();
            closelog();
            exit(EXIT_FAILURE);
        }
        gpioWrite(RELAY_GPIO[i], PI_HIGH);
        logStateChange(RELAY_GPIO[i], 1);
    }

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    if (gpioSetTimerFuncEx(0, 60000, timerCallback, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set timer function");
        gpioTerminate();
        closelog();
        exit(EXIT_FAILURE);
    }

    while (running) {
        sleep(1);
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
        gpioWrite(RELAY_GPIO[i], PI_HIGH);
        logStateChange(RELAY_GPIO[i], 1);
    }

    gpioTerminate();
    closelog();

    return 0;
}

