#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <sys/timerfd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/mman.h>
#include <errno.h>
#include <math.h>

#define I2C_DEV "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

#define BUFFER_SIZE 100
#define TIMER_FREQ 100 // 100 Hz

typedef struct {
    float x;
    float y;
    float z;
} accel_data_t;

accel_data_t buffer[BUFFER_SIZE];
int buffer_index = 0;
int i2c_fd = -1;
int timer_fd = -1;
int sysfs_fd = -1;
char *sysfs_path = "/sys/kernel/mpu6050_accel/latest";

void cleanup() {
    if (i2c_fd != -1) close(i2c_fd);
    if (timer_fd != -1) close(timer_fd);
    if (sysfs_fd != -1) close(sysfs_fd);
    unlink(sysfs_path);
}

void handle_signal(int sig) {
    cleanup();
    exit(0);
}

void init_mpu6050() {
    uint8_t data = 0x00;
    if (write(i2c_fd, &data, 1) != 1) {
        perror("Failed to write to PWR_MGMT_1");
        exit(EXIT_FAILURE);
    }
    data = 0x00;
    if (write(i2c_fd, &data, 1) != 1) {
        perror("Failed to write to ACCEL_CONFIG");
        exit(EXIT_FAILURE);
    }
}

void read_accel_data() {
    uint8_t reg = ACCEL_XOUT_H;
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return;
    }
    uint8_t buf[6];
    if (read(i2c_fd, buf, 6) != 6) {
        perror("Failed to read accelerometer data");
        return;
    }
    int16_t x = (buf[0] << 8) | buf[1];
    int16_t y = (buf[2] << 8) | buf[3];
    int16_t z = (buf[4] << 8) | buf[5];
    buffer[buffer_index].x = x / 16384.0;
    buffer[buffer_index].y = y / 16384.0;
    buffer[buffer_index].z = z / 16384.0;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

void timer_callback() {
    read_accel_data();
    char data[100];
    snprintf(data, sizeof(data), "%.2f %.2f %.2f\n", buffer[buffer_index].x, buffer[buffer_index].y, buffer[buffer_index].z);
    if (sysfs_fd != -1) {
        lseek(sysfs_fd, 0, SEEK_SET);
        write(sysfs_fd, data, strlen(data));
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    init_mpu6050();

    timer_fd = timerfd_create(CLOCK_REALTIME, 0);
    if (timer_fd < 0) {
        perror("Failed to create timer");
        cleanup();
        exit(EXIT_FAILURE);
    }
    struct itimerspec timer_spec;
    timer_spec.it_value.tv_sec = 0;
    timer_spec.it_value.tv_nsec = 10000000; // 10 ms
    timer_spec.it_interval.tv_sec = 0;
    timer_spec.it_interval.tv_nsec = 10000000; // 10 ms
    if (timerfd_settime(timer_fd, 0, &timer_spec, NULL) < 0) {
        perror("Failed to set timer");
        cleanup();
        exit(EXIT_FAILURE);
    }

    sysfs_fd = open(sysfs_path, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (sysfs_fd < 0) {
        perror("Failed to open sysfs file");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        uint64_t exp;
        read(timer_fd, &exp, sizeof(exp));
        timer_callback();
    }

    cleanup();
    return 0;
}

