#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES 4
#define GPIO_PINS {18, 23, 24, 25}
#define PRIME_INTERVALS {2, 3, 5, 7}

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void release_resources(struct gpiod_chip *chip, struct gpiod_line *lines[], int num_lines) {
    for (int i = 0; i < num_lines; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[GPIO_LINES] = {NULL};
    int gpio_pins[] = GPIO_PINS;
    int prime_intervals[] = PRIME_INTERVALS;
    struct timespec last_toggle[GPIO_LINES];
    struct sigaction sa;

    // Set up signal handler for graceful exit
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Request GPIO lines
    for (int i = 0; i < GPIO_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            release_resources(chip, lines, i);
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(lines[i], "smart_lighting", 0) < 0) {
            perror("gpiod_line_request_output");
            release_resources(chip, lines, GPIO_LINES);
            exit(EXIT_FAILURE);
        }
        clock_gettime(CLOCK_MONOTONIC, &last_toggle[i]);
    }

    // Main loop
    while (running) {
        for (int i = 0; i < GPIO_LINES; i++) {
            struct timespec current_time;
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            if (timespec_diff(&current_time, &last_toggle[i]) >= prime_intervals[i]) {
                int current_state = gpiod_line_get_value(lines[i]);
                gpiod_line_set_value(lines[i], !current_state);
                clock_gettime(CLOCK_MONOTONIC, &last_toggle[i]);
            }
        }
        usleep(100000); // Sleep for 100ms
    }

    // Clean up
    release_resources(chip, lines, GPIO_LINES);
    return 0;
}

// Helper function to calculate the difference between two timespecs
long timespec_diff(struct timespec *a, struct timespec *b) {
    return (a->tv_sec - b->tv_sec) * 1000000000 + (a->tv_nsec - b->tv_nsec);
}

