#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define DEBOUNCE_TIME 300000 // 300 ms in microseconds
#define RELAY_DURATION 3000000 // 3 seconds in microseconds

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_activation(const char *filename) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "Alarm activated at: %s\n", timestamp);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for sound sensor pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for relay pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetSignalFunc(SIGINT, signal_handler);
    gpioSetSignalFunc(SIGTERM, signal_handler);

    struct timespec last_activation = {0};
    struct timespec current_time;
    int last_state = 0;

    while (running) {
        gpioDelay(100000); // 100 ms delay

        int current_state = gpioRead(SOUND_SENSOR_PIN);
        if (current_state == PI_HIGH && last_state == PI_LOW) {
            clock_gettime(CLOCK_REALTIME, &current_time);
            if (timespec_subtract(&current_time, &last_activation) > DEBOUNCE_TIME) {
                gpioWrite(RELAY_PIN, PI_HIGH);
                log_activation("alarm_log.txt");
                clock_gettime(CLOCK_REALTIME, &last_activation);
                gpioDelay(RELAY_DURATION);
                gpioWrite(RELAY_PIN, PI_LOW);
            }
        }
        last_state = current_state;
    }

    gpioWrite(RELAY_PIN, PI_LOW);
    gpioTerminate();
    return EXIT_SUCCESS;
}

int timespec_subtract(struct timespec *result, struct timespec *x) {
    if (x->tv_nsec < result->tv_nsec) {
        int nsec = (result->tv_nsec - x->tv_nsec) / 1000000;
        result->tv_nsec -= (nsec * 1000000);
        result->tv_sec -= (nsec + 1);
    } else {
        int nsec = (x->tv_nsec - result->tv_nsec) / 1000000;
        result->tv_nsec = x->tv_nsec - (nsec * 1000000);
        result->tv_sec = x->tv_sec - nsec;
    }
    if (result->tv_sec < 0) {
        return -1;
    }
    return 0;
}

