#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <math.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define WHO_AM_I 0x75
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0

#define BUFFER_SIZE 100

typedef struct {
    float x;
    float y;
    float z;
} GyroData;

GyroData buffer[BUFFER_SIZE];
int buffer_index = 0;

void cleanup(int sig) {
    printf("Cleaning up...\n");
    exit(0);
}

void callback(const GyroData *data) {
    printf("Threshold exceeded: X=%.2f, Y=%.2f, Z=%.2f\n", data->x, data->y, data->z);
}

float calculate_magnitude(const GyroData *data) {
    return sqrt(data->x * data->x + data->y * data->y + data->z * data->z);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("I2C ioctl failed");
        return -1;
    }
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write reg failed");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int main() {
    int fd;
    uint8_t who_am_i;
    uint8_t data[6];

    signal(SIGINT, cleanup);

    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (i2c_write(fd, PWR_MGMT_1, 0) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_read(fd, WHO_AM_I, &who_am_i, 1) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (who_am_i != MPU6050_ADDR) {
        fprintf(stderr, "Device ID mismatch: expected 0x68, got 0x%02X\n", who_am_i);
        close(fd);
        return EXIT_FAILURE;
    }

    while (1) {
        if (i2c_read(fd, GYRO_XOUT_H, data, 6) < 0) {
            close(fd);
            return EXIT_FAILURE;
        }

        GyroData gyro_data = {
            .x = (int16_t)((data[0] << 8) | data[1]) / GYRO_SENSITIVITY,
            .y = (int16_t)((data[2] << 8) | data[3]) / GYRO_SENSITIVITY,
            .z = (int16_t)((data[4] << 8) | data[5]) / GYRO_SENSITIVITY
        };

        buffer[buffer_index] = gyro_data;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        float magnitude = calculate_magnitude(&gyro_data);
        if (magnitude > 50.0) {
            callback(&gyro_data);
        }

        usleep(100000); // 100 ms delay
    }

    close(fd);
    return EXIT_SUCCESS;
}

