#define READ_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define RESPONSE_LENGTH 9
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define READ_TIMEOUT 1000000 // 1 second in microseconds

int serial_handle = -1;
FILE *log_file = NULL;
FILE *error_log_file = NULL;

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(error_log_file, "%04d-%02d-%02d %02d:%02d:%02d - %s\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, message);
    fflush(error_log_file);
}

void signal_handler(int signum) {
    if (serial_handle != -1) {
        serClose(serial_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (error_log_file) {
        fclose(error_log_file);
    }
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    serial_handle = serOpen(SERIAL_PORT, BAUD_RATE, 0);
    if (serial_handle < 0) {
        log_error("Failed to open serial port");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        serClose(serial_handle);
        gpioTerminate();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_file) {
        log_error("Failed to open error log file");
        fclose(log_file);
        serClose(serial_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t read_command[] = READ_COMMAND;
    uint8_t response[RESPONSE_LENGTH];
    struct timespec start_time, current_time;
    int timeout;

    while (1) {
        if (serWrite(serial_handle, read_command, sizeof(read_command)) != sizeof(read_command)) {
            log_error("Failed to send read command");
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &start_time);
        int bytes_read = 0;

        while (bytes_read < RESPONSE_LENGTH) {
            int available = serDataAvailable(serial_handle);
            if (available > 0) {
                int read_now = RESPONSE_LENGTH - bytes_read;
                if (available < read_now) {
                    read_now = available;
                }
                int result = serRead(serial_handle, response + bytes_read, read_now);
                if (result < 0) {
                    log_error("Failed to read from serial port");
                    break;
                }
                bytes_read += result;
            }

            clock_gettime(CLOCK_MONOTONIC, &current_time);
            timeout = (current_time.tv_sec - start_time.tv_sec) * 1000000 +
                      (current_time.tv_nsec - start_time.tv_nsec) / 1000;
            if (timeout >= READ_TIMEOUT) {
                log_error("Read timeout");
                break;
            }

            usleep(10000); // 10 ms
        }

        if (bytes_read == RESPONSE_LENGTH) {
            uint8_t checksum = 0;
            for (int i = 1; i < 8; i++) {
                checksum += response[i];
            }
            checksum = ~checksum + 1;

            if (checksum == response[8]) {
                uint16_t co2 = (response[2] << 8) | response[3];
                struct timespec ts;
                clock_gettime(CLOCK_REALTIME, &ts);
                char json[100];
                snprintf(json, sizeof(json), "{\"timestamp\":%ld,\"co2\":%u,\"error\":false}\n",
                         ts.tv_sec * 1000000 + ts.tv_nsec / 1000, co2);
                fprintf(log_file, "%s", json);
                fflush(log_file);
                printf("%s", json);
            } else {
                log_error("Checksum mismatch");
            }
        }

        usleep(5000000); // 5 seconds
    }

    return 0;
}
