#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA_REG 0x03
#define BUFFER_SIZE 100

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(17, PI_OUTPUT);
    gpioWrite(17, PI_LOW);
}

void init_i2c() {
    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        exit(EXIT_FAILURE);
    }
}

void configure_sensor() {
    char config_a = 0x70;
    char config_b = 0x20;
    char mode = 0x00;

    if (i2cWriteByteData(I2C_BUS, CONFIG_A, config_a) < 0) {
        fprintf(stderr, "Failed to write CONFIG_A\n");
    }
    if (i2cWriteByteData(I2C_BUS, CONFIG_B, config_b) < 0) {
        fprintf(stderr, "Failed to write CONFIG_B\n");
    }
    if (i2cWriteByteData(I2C_BUS, MODE, mode) < 0) {
        fprintf(stderr, "Failed to write MODE\n");
    }
}

double calculate_heading(int x, int y) {
    return atan2(y, x) * 180.0 / M_PI;
}

void compensate_heading(int *x, int *y, int x_offset, int y_offset) {
    *x -= x_offset;
    *y -= y_offset;
}

void read_data(int *x, int *z, int *y) {
    char buffer[6];
    if (i2cReadI2CBlockData(I2C_BUS, DATA_REG, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read data from sensor\n");
        return;
    }
    *x = (buffer[0] << 8) | buffer[1];
    *z = (buffer[2] << 8) | buffer[3];
    *y = (buffer[4] << 8) | buffer[5];
}

void log_heading(double heading, double *buffer, int *index) {
    buffer[*index] = heading;
    *index = (*index + 1) % BUFFER_SIZE;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();
    init_i2c();
    configure_sensor();

    double buffer[BUFFER_SIZE] = {0};
    int index = 0;
    int x_offset = 100;
    int y_offset = -50;
    double target_heading = 90.0;

    while (running) {
        int x, z, y;
        read_data(&x, &z, &y);
        compensate_heading(&x, &y, x_offset, y_offset);
        double heading = calculate_heading(x, y);
        log_heading(heading, buffer, &index);

        double deviation = fabs(heading - target_heading);
        if (deviation > 10.0) {
            gpioWrite(17, PI_HIGH);
        } else {
            gpioWrite(17, PI_LOW);
        }

        usleep(100000);
    }

    gpioTerminate();
    i2cClose(I2C_BUS);

    return 0;
}

