#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDRESS 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define RED_RELAY 17
#define GREEN_RELAY 27
#define BLUE_RELAY 22
#define LOG_FILE "lighting_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *red_line, *green_line, *blue_line;
static int i2c_fd;
static FILE *log_file;

void cleanup() {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure BH1750 for continuous high-resolution mode
    if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        perror("Failed to configure BH1750");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    red_line = gpiod_chip_get_line(chip, RED_RELAY);
    green_line = gpiod_chip_get_line(chip, GREEN_RELAY);
    blue_line = gpiod_chip_get_line(chip, BLUE_RELAY);
    if (!red_line || !green_line || !blue_line) {
        perror("Failed to get GPIO lines");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure GPIO lines as output
    if (gpiod_line_request_output(red_line, "red_relay", 0) < 0 ||
        gpiod_line_request_output(green_line, "green_relay", 0) < 0 ||
        gpiod_line_request_output(blue_line, "blue_relay", 0) < 0) {
        perror("Failed to request GPIO lines as output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t buffer[2];
        uint16_t raw_lux;
        float lux;

        // Wait for conversion to complete
        usleep(120000);

        // Read 2 bytes from BH1750
        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read from BH1750");
            cleanup();
            return EXIT_FAILURE;
        }

        // Calculate lux
        raw_lux = (buffer[0] << 8) | buffer[1];
        lux = raw_lux / 1.2;

        // Determine relay states
        int red_state = 0, green_state = 0, blue_state = 0;
        if (lux < 50) {
            red_state = 1;
        } else if (lux >= 50 && lux < 150) {
            green_state = 1;
        } else if (lux >= 150 && lux < 300) {
            blue_state = 1;
        } else {
            red_state = 1;
            green_state = 1;
            blue_state = 1;
        }

        // Set relay states
        gpiod_line_set_value(red_line, red_state);
        gpiod_line_set_value(green_line, green_state);
        gpiod_line_set_value(blue_line, blue_state);

        // Log timestamp, lux value, and relay states
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        fprintf(log_file, "%s - Lux: %.2f - Red: %d, Green: %d, Blue: %d\n",
                asctime(tm_info), lux, red_state, green_state, blue_state);
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

