#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

volatile sig_atomic_t running = 1;

void cleanup(int signum) {
    running = 0;
    gpioSetPWMfrequency(MOTOR_A_IN2, 0);
    gpioSetPWMfrequency(MOTOR_B_IN4, 0);
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
    gpioTerminate();
    exit(signum);
}

int map_distance_to_duty_cycle(int distance) {
    if (distance < 10) distance = 10;
    if (distance > 100) distance = 100;
    return 255 - (distance - 10) * 2;
}

void control_motor(int in1, int in2, int distance) {
    int duty_cycle = map_distance_to_duty_cycle(distance);
    if (distance < 50) {
        gpioWrite(in1, 1);
        gpioWrite(in2, 0);
        gpioSetPWMfrequency(in2, PWM_FREQUENCY);
        gpioSetPWMrange(in2, PWM_RANGE);
        gpioPWM(in2, duty_cycle);
    } else {
        gpioWrite(in1, 0);
        gpioWrite(in2, 1);
        gpioSetPWMfrequency(in2, PWM_FREQUENCY);
        gpioSetPWMrange(in2, PWM_RANGE);
        gpioPWM(in2, duty_cycle);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_A> <distance_B>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int distance_A = atoi(argv[1]);
    int distance_B = atoi(argv[2]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (running) {
        control_motor(MOTOR_A_IN1, MOTOR_A_IN2, distance_A);
        control_motor(MOTOR_B_IN3, MOTOR_B_IN4, distance_B);
        gpioDelay(100000); // 100 ms
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

