#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <sys/poll.h>
#include <sys/stat.h>
#include <sys/types.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define PITCH_ROLL_SCALE 16384.0
#define SERVO_GPIO 18
#define PWM_CHIP "pwmchip2"
#define PWM0 "pwm0"
#define PWM_PERIOD 20000000 // 20ms period for 50Hz PWM
#define PWM_DUTY_MIN 1000000  // 1ms pulse for 0 degrees
#define PWM_DUTY_MAX 2000000  // 2ms pulse for 180 degrees
#define RETRY_DELAY 100000 // 100ms delay between retries
#define MAX_RETRIES 5

int i2c_fd = -1;
int pwm_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (pwm_fd != -1) {
        close(pwm_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int i2c_read_register(int reg, uint8_t *data) {
    uint8_t buffer[1] = {reg};
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to write to I2C");
        return -1;
    }
    if (read(i2c_fd, data, 1) != 1) {
        perror("Failed to read from I2C");
        return -1;
    }
    return 0;
}

int i2c_read_word(int reg, int16_t *data) {
    uint8_t buffer[2];
    if (i2c_read_register(reg, buffer) == -1 || i2c_read_register(reg + 1, buffer + 1) == -1) {
        return -1;
    }
    *data = (buffer[0] << 8) | buffer[1];
    return 0;
}

int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int init_pwm() {
    char pwm_path[256];
    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/%s/export", PWM_CHIP);
    FILE *export_file = fopen(pwm_path, "w");
    if (!export_file) {
        perror("Failed to open PWM export file");
        return -1;
    }
    fprintf(export_file, "%d", SERVO_GPIO);
    fclose(export_file);

    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/%s/%s/period", PWM_CHIP, PWM0);
    pwm_fd = open(pwm_path, O_WRONLY);
    if (pwm_fd < 0) {
        perror("Failed to open PWM period file");
        return -1;
    }
    dprintf(pwm_fd, "%d", PWM_PERIOD);
    close(pwm_fd);

    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/%s/%s/duty_cycle", PWM_CHIP, PWM0);
    pwm_fd = open(pwm_path, O_WRONLY);
    if (pwm_fd < 0) {
        perror("Failed to open PWM duty cycle file");
        return -1;
    }
    dprintf(pwm_fd, "%d", PWM_DUTY_MIN);
    close(pwm_fd);

    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/%s/%s/enable", PWM_CHIP, PWM0);
    pwm_fd = open(pwm_path, O_WRONLY);
    if (pwm_fd < 0) {
        perror("Failed to open PWM enable file");
        return -1;
    }
    dprintf(pwm_fd, "1");
    close(pwm_fd);

    return 0;
}

void set_servo_position(int position) {
    if (pwm_fd < 0) {
        return;
    }
    lseek(pwm_fd, 0, SEEK_SET);
    dprintf(pwm_fd, "%d", position);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c() == -1 || init_pwm() == -1) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("solar_tracker.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    int retries = 0;
    while (retries < MAX_RETRIES) {
        int16_t accel_x, accel_y, accel_z;
        if (i2c_read_word(ACCEL_XOUT_H, &accel_x) == 0 &&
            i2c_read_word(ACCEL_YOUT_H, &accel_y) == 0 &&
            i2c_read_word(ACCEL_ZOUT_H, &accel_z) == 0) {
            double pitch = atan2(accel_y, sqrt(accel_x * accel_x + accel_z * accel_z)) * 180.0 / M_PI;
            double roll = atan2(-accel_x, accel_z) * 180.0 / M_PI;

            int duty_cycle = PWM_DUTY_MIN + (int)((pitch + 90) / 180.0 * (PWM_DUTY_MAX - PWM_DUTY_MIN));
            set_servo_position(duty_cycle);

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, duty_cycle);
            fflush(log_file);

            retries = 0; // Reset retries on successful read
        } else {
            retries++;
            usleep(RETRY_DELAY);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

