#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SCHEDULE_FILE "lighting_schedule.txt"
#define NUM_RELAYS 4
#define RELAY_PINS {4, 17, 27, 22}
#define PWM_FREQ 100
#define TRANSITION_TIME 1800

typedef struct {
    int hour;
    int minute;
    int second;
    int relay;
    int state;
} ScheduleEntry;

ScheduleEntry schedule[100];
int schedule_count = 0;
int relays[NUM_RELAYS] = RELAY_PINS;
int running = 1;

void signal_handler(int signum) {
    running = 0;
}

void parse_schedule() {
    FILE *file = fopen(SCHEDULE_FILE, "r");
    if (!file) {
        perror("Failed to open schedule file");
        exit(EXIT_FAILURE);
    }

    char line[100];
    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%d:%d:%d,%d,%d", &schedule[schedule_count].hour, &schedule[schedule_count].minute, &schedule[schedule_count].second,
                   &schedule[schedule_count].relay, &schedule[schedule_count].state) == 5) {
            if (schedule[schedule_count].relay < 1 || schedule[schedule_count].relay > NUM_RELAYS) {
                fprintf(stderr, "Invalid relay number in schedule\n");
                continue;
            }
            schedule[schedule_count].relay--; // Convert to 0-based index
            schedule_count++;
        } else {
            fprintf(stderr, "Invalid schedule entry format\n");
        }
    }

    fclose(file);
}

void fade_relay(int relay, int target_duty) {
    int current_duty = gpioGetPWMdutycycle(relays[relay]);
    int step = (target_duty > current_duty) ? 1 : -1;
    for (int i = current_duty; i != target_duty; i += step) {
        gpioPWM(relays[relay], i);
        time_sleep(0.01); // 100 Hz
    }
}

void check_schedule() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    for (int i = 0; i < schedule_count; i++) {
        if (tm_info->tm_hour == schedule[i].hour && tm_info->tm_min == schedule[i].minute && tm_info->tm_sec == schedule[i].second) {
            fade_relay(schedule[i].relay, schedule[i].state * 100);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioSetMode(relays[i], PI_OUTPUT);
        gpioSetPWMfrequency(relays[i], PWM_FREQ);
        gpioPWM(relays[i], 0);
    }

    parse_schedule();

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        check_schedule();
        time_sleep(1);
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWM(relays[i], 0);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

