#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

#define MIN_DISTANCE 2
#define MAX_DISTANCE 30
#define MIN_FREQ 200
#define MAX_FREQ 2000

#define TRIGGER_PULSE_US 10
#define MEASUREMENT_INTERVAL_US 20000

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioSetPWMfrequency(BUZZER_PIN, 0);
}

void deinit_gpio() {
    gpioSetPWMfrequency(BUZZER_PIN, 0);
    gpioTerminate();
}

int read_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);

    int start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > 30000) { // 30 ms timeout
            fprintf(stderr, "Timeout waiting for echo\n");
            return -1;
        }
    }

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > 30000) { // 30 ms timeout
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1;
        }
    }

    int echo_duration = gpioTick() - start_tick;
    int distance = (echo_duration * 340) / 2 / 10000; // cm

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Distance out of range: %d cm\n", distance);
        return -1;
    }

    return distance;
}

int map_distance_to_frequency(int distance) {
    return MIN_FREQ + ((MAX_FREQ - MIN_FREQ) * (distance - MIN_DISTANCE)) / (MAX_DISTANCE - MIN_DISTANCE);
}

int main() {
    signal(SIGINT, sigint_handler);

    init_gpio();

    while (running) {
        int distance = read_distance();
        if (distance >= 0) {
            int frequency = map_distance_to_frequency(distance);
            gpioSetPWMfrequency(BUZZER_PIN, frequency);
        }

        gpioDelay(MEASUREMENT_INTERVAL_US);
    }

    deinit_gpio();
    return 0;
}

