#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27
#define PWM_FREQUENCY 1000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    double time = 0.0;
    while (running) {
        double proximity = 0.5 * (1.0 + sin(time)); // Simulated proximity value

        // Map proximity to RGB values
        double red = 0.0, green = 0.0, blue = 0.0;
        if (proximity < 0.33) {
            red = 1.0;
            green = proximity / 0.33;
        } else if (proximity < 0.67) {
            red = 1.0 - (proximity - 0.33) / 0.33;
            green = 1.0;
        } else {
            green = 1.0 - (proximity - 0.67) / 0.33;
            blue = (proximity - 0.67) / 0.33;
        }

        // Set PWM duty cycles
        gpioPWM(RED_PIN, (uint32_t)(red * 255));
        gpioPWM(GREEN_PIN, (uint32_t)(green * 255));
        gpioPWM(BLUE_PIN, (uint32_t)(blue * 255));

        time += 0.01; // Increment time for sine wave
        gpioDelay(10000); // 10 ms delay
    }

    // Turn off the LED
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);

    gpioTerminate();
    return EXIT_SUCCESS;
}

