#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct sigaction sa;
    FILE *log_file;

    // Set up signal handler for graceful exit
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Wake up the MPU-6050
    uint8_t wake_up = 0x00;
    if (write(i2c_fd, &wake_up, 1) != 1) {
        perror("Failed to wake up MPU-6050");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t gyro_data[6];
        int16_t gyro_x, gyro_y, gyro_z;
        double gyro_x_deg, gyro_y_deg, gyro_z_deg;
        struct timespec ts;

        // Read gyroscope data
        if (lseek(i2c_fd, GYRO_XOUT_H, SEEK_SET) < 0) {
            perror("Failed to set I2C register address");
            break;
        }
        if (read(i2c_fd, gyro_data, 6) != 6) {
            perror("Failed to read gyroscope data");
            break;
        }

        // Convert raw data to degrees/second
        gyro_x = (gyro_data[0] << 8) | gyro_data[1];
        gyro_y = (gyro_data[2] << 8) | gyro_data[3];
        gyro_z = (gyro_data[4] << 8) | gyro_data[5];
        gyro_x_deg = gyro_x / GYRO_SENSITIVITY;
        gyro_y_deg = gyro_y / GYRO_SENSITIVITY;
        gyro_z_deg = gyro_z / GYRO_SENSITIVITY;

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get timestamp");
            break;
        }

        // Log the data
        fprintf(log_file, "%ld.%09ld, %f, %f, %f\n", ts.tv_sec, ts.tv_nsec, gyro_x_deg, gyro_y_deg, gyro_z_deg);
        fflush(log_file);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

