#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_TIME 50000 // 50 ms in microseconds

const int melody[] = {262, 294, 330, 349, 392, 440, 494, 523}; // C4, D4, E4, F4, G4, A4, B4, C5
const int melody_duration[] = {500000, 500000, 500000, 500000, 500000, 500000, 500000, 500000}; // 0.5 seconds each
const int melody_size = sizeof(melody) / sizeof(melody[0]);

volatile int button_pressed = 0;
volatile int playback_active = 0;
volatile int current_note = 0;

void button_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_LOW && !button_pressed) {
        button_pressed = 1;
        gpioDelay(DEBOUNCE_TIME);
    }
}

void stop_playback() {
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    playback_active = 0;
    current_note = 0;
}

void signal_handler(int signum) {
    stop_playback();
    gpioSetISRFuncEx(BUTTON_PIN, PI_EVENT_NONE, 0, NULL, NULL);
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set button pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set button pin pull-up\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, PI_FALLING_EDGE, 0, button_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set button ISR\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        if (button_pressed) {
            button_pressed = 0;
            if (playback_active) {
                stop_playback();
            } else {
                playback_active = 1;
                current_note = 0;
            }
        }

        if (playback_active) {
            gpioHardwarePWM(BUZZER_PIN, melody[current_note], 500000); // 50% duty cycle
            gpioDelay(melody_duration[current_note]);
            current_note = (current_note + 1) % melody_size;
        }
    }

    return 0;
}

