#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <poll.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <stdbool.h>
#include <atomic.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "vibration_events.log"
#define DEFAULT_TIMEOUT 1000
#define WINDOW_SIZE 5

volatile sig_atomic_t exit_flag = 0;

void sig_handler(int signum) {
    exit_flag = 1;
}

void log_event(FILE *log_file, const char *timestamp, int value) {
    if (fprintf(log_file, "%s, %d\n", timestamp, value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

const char *get_iso8601_timestamp() {
    static char timestamp[21];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    return timestamp;
}

int main(int argc, char *argv[]) {
    int timeout = DEFAULT_TIMEOUT;
    if (argc > 1) {
        timeout = atoi(argv[1]);
        if (timeout <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default %d ms.\n", DEFAULT_TIMEOUT);
            timeout = DEFAULT_TIMEOUT;
        }
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(line, "vibration_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting input on GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line_event event;
    int event_count = 0;
    int high_count = 0;
    bool events[WINDOW_SIZE] = {0};

    while (!exit_flag) {
        struct pollfd fds[1];
        fds[0].fd = gpiod_line_event_get_fd(line);
        fds[0].events = POLLIN;

        ret = poll(fds, 1, timeout);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error polling GPIO line: %s\n", strerror(errno));
            break;
        } else if (ret == 0) {
            continue;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO line event: %s\n", strerror(errno));
            break;
        }

        const char *timestamp = get_iso8601_timestamp();
        int value = event.id == GPIOD_LINE_EVENT_RISING_EDGE ? 1 : 0;
        log_event(log_file, timestamp, value);

        events[event_count % WINDOW_SIZE] = value;
        if (value == 1) {
            high_count++;
        } else {
            high_count -= events[event_count % WINDOW_SIZE];
        }
        event_count++;

        if (high_count >= 3) {
            printf("EARTHQUAKE ALERT at %s\n", timestamp);
        }
    }

    fclose(log_file);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

