#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <math.h>
#include <errno.h>

#define I2C_DEV "/dev/i2c-1"
#define MAG_ADDR 0x1E
#define CRA_REG_M 0x00
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

#define SAMPLE_INTERVAL 1

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd, csv_fd;
    char *filename = "mag_log.csv";
    FILE *csv_file;
    struct sigaction sa;
    struct i2c_msg msgs[1];
    struct i2c_rdwr_ioctl_data msgset;
    uint8_t buffer[6];
    int16_t x, y, z;
    float calibrated_x, calibrated_y, calibrated_z;
    float heading;
    const char *directions[] = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};
    int direction_index;

    // Install signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C device
    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MAG_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Configure magnetometer
    uint8_t config_data[2] = {CRA_REG_M, 0x14}; // Set ODR to 15 Hz
    msgs[0].addr = MAG_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 2;
    msgs[0].buf = config_data;
    msgset.nmsgs = 1;
    msgset.msgs = msgs;
    if (ioctl(i2c_fd, I2C_RDWR, &msgset) < 0) {
        perror("Failed to configure magnetometer");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    config_data[0] = MR_REG_M;
    config_data[1] = 0x00; // Continuous conversion mode
    msgs[0].len = 2;
    msgs[0].buf = config_data;
    if (ioctl(i2c_fd, I2C_RDWR, &msgset) < 0) {
        perror("Failed to set continuous conversion mode");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open CSV file
    csv_file = fopen(filename, "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Write header if file is empty
    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }

    while (running) {
        // Read magnetometer data
        msgs[0].addr = MAG_ADDR;
        msgs[0].flags = I2C_M_RD;
        msgs[0].len = 6;
        msgs[0].buf = buffer;
        msgset.nmsgs = 1;
        msgset.msgs = msgs;
        if (ioctl(i2c_fd, I2C_RDWR, &msgset) < 0) {
            fprintf(stderr, "Failed to read magnetometer data: %s\n", strerror(errno));
            continue;
        }

        // Assemble 16-bit values
        x = (buffer[0] << 8) | buffer[1];
        z = (buffer[2] << 8) | buffer[3];
        y = (buffer[4] << 8) | buffer[5];

        // Apply calibration offsets
        calibrated_x = x + X_OFFSET;
        calibrated_y = y + Y_OFFSET;
        calibrated_z = z + Z_OFFSET;

        // Compute heading
        heading = atan2f(calibrated_y, calibrated_x) * 180.0f / M_PI;
        if (heading < 0) {
            heading += 360.0f;
        }

        // Map heading to compass direction
        direction_index = (int)((heading + 22.5f) / 45.0f) % 8;

        // Print direction and heading
        printf("Direction: %s, Heading: %.2f\n", directions[direction_index], heading);

        // Write to CSV
        fprintf(csv_file, "%ld,%.2f,%.2f,%.2f,%.2f\n", (long)time(NULL), calibrated_x, calibrated_y, calibrated_z, heading);
        fflush(csv_file);

        // Sleep for one second
        sleep(SAMPLE_INTERVAL);
    }

    // Close resources
    fclose(csv_file);
    close(i2c_fd);

    return 0;
}

