#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_TIME 200

volatile int lastTouchTime = 0;
volatile int relayState = 0;
FILE *logFile = NULL;

void signalHandler(int signum) {
    gpioWrite(RELAY_PIN, PI_OFF);
    char timestamp[30];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
    fprintf(logFile, "{\"timestamp\":\"%s\",\"relay_state\":\"OFF\"}\n", timestamp);
    fflush(logFile);
    fclose(logFile);
    gpioTerminate();
    exit(signum);
}

void touchCallback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        int currentTime = gpioTick();
        if (currentTime - lastTouchTime > DEBOUNCE_TIME) {
            lastTouchTime = currentTime;
            relayState = !relayState;
            gpioWrite(RELAY_PIN, relayState);
            char timestamp[30];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
            fprintf(logFile, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, relayState ? "ON" : "OFF");
            fflush(logFile);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO%d\n", TOUCH_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFunc(TOUCH_PIN, EITHER_EDGE, 0, touchCallback) < 0) {
        fprintf(stderr, "Failed to set ISR function on GPIO%d\n", TOUCH_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    gpioWrite(RELAY_PIN, PI_OFF);

    logFile = fopen("relay_log.json", "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signalHandler);

    while (1) {
        gpioDelay(1000000); // Sleep for 1 second
    }

    return 0;
}

