#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES 4
#define GPIO_OFFSETS {17, 23, 24, 25}
#define LOG_FILE "irrigation_log.txt"
#define MOISTURE_THRESHOLD 30
#define RELAY_ON 0
#define RELAY_OFF 1
#define RELAY_DELAY 5
#define GAP_DELAY 1
#define READ_INTERVAL 10

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[GPIO_LINES];
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

void log_event(const char *timestamp, int relay, int moisture) {
    if (fprintf(log_file, "%s: Relay %d activated at moisture level %d\n", timestamp, relay, moisture) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

void signal_handler(int signum) {
    running = 0;
}

void deactivate_relays() {
    for (int i = 0; i < GPIO_LINES; i++) {
        if (gpiod_line_set_value(lines[i], RELAY_OFF) < 0) {
            fprintf(stderr, "Error setting line %d to OFF: %s\n", GPIO_OFFSETS[i], strerror(errno));
        }
    }
}

void cleanup() {
    if (chip) {
        for (int i = 0; i < GPIO_LINES; i++) {
            if (lines[i]) {
                gpiod_line_release(lines[i]);
            }
        }
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

