    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    for (i = 0; i < GPIO_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_OFFSETS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", GPIO_OFFSETS[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], "irrigation", RELAY_OFF) < 0) {
            fprintf(stderr, "Error requesting line %d as output: %s\n", GPIO_OFFSETS[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    // Setup signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        // Generate simulated soil-moisture value
        moisture = rand() % 101;

        // Check moisture level
        if (moisture < MOISTURE_THRESHOLD) {
            for (i = 0; i < GPIO_LINES; i++) {
                // Activate relay
                if (gpiod_line_set_value(lines[i], RELAY_ON) < 0) {
                    fprintf(stderr, "Error setting line %d to ON: %s\n", GPIO_OFFSETS[i], strerror(errno));
                    continue;
                }

                // Get current time
                if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
                    fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
                    continue;
                }
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts));

                // Log event
                log_event(timestamp, i + 1, moisture);

                // Wait for relay activation
                sleep(RELAY_DELAY);

                // Deactivate relay
                if (gpiod_line_set_value(lines[i], RELAY_OFF) < 0) {
                    fprintf(stderr, "Error setting line %d to OFF: %s\n", GPIO_OFFSETS[i], strerror(errno));
                }

                // Wait for gap
                sleep(GAP_DELAY);
            }
        }

        // Wait for next read interval
        sleep(READ_INTERVAL);
    }

    // Deactivate all relays
    deactivate_relays();

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

