#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define VALVE_GPIO 17
#define NOZZLE_GPIO 18
#define MOISTURE_READINGS {20, 40, 60, 80, 100}
#define NUM_READINGS 5
#define VALVE_OPEN 1500
#define VALVE_CLOSED 500
#define NOZZLE_ANGLES {500, 750, 1000, 1250, 1500}
#define NUM_ANGLES 5
#define WATERING_DELAY 2000
#define HOLD_DELAY 5000
#define CYCLE_DELAY 5000
#define MAX_RETRIES 3
#define BACKOFF_DELAY 100000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int set_servo_angle(int gpio, int angle, int retries) {
    int ret;
    while (retries--) {
        ret = gpioServo(gpio, angle);
        if (ret == 0) {
            return 0;
        }
        usleep(BACKOFF_DELAY);
    }
    return -1;
}

int main() {
    int moisture_readings[NUM_READINGS] = MOISTURE_READINGS;
    int nozzle_angles[NUM_ANGLES] = NOZZLE_ANGLES;
    int i, j;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetMode(NOZZLE_GPIO, PI_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        for (i = 0; i < NUM_READINGS; i++) {
            int moisture = moisture_readings[i];
            if (moisture < 50) {
                if (set_servo_angle(VALVE_GPIO, VALVE_OPEN, MAX_RETRIES) != 0) {
                    fprintf(stderr, "Critical: Failed to open valve\n");
                    break;
                }
                for (j = 0; j < NUM_ANGLES; j++) {
                    if (set_servo_angle(NOZZLE_GPIO, nozzle_angles[j], MAX_RETRIES) != 0) {
                        fprintf(stderr, "Error: Failed to set nozzle angle %d\n", j);
                        continue;
                    }
                    usleep(WATERING_DELAY);
                }
                usleep(HOLD_DELAY);
                if (set_servo_angle(VALVE_GPIO, VALVE_CLOSED, MAX_RETRIES) != 0) {
                    fprintf(stderr, "Warning: Failed to close valve\n");
                }
            }
            usleep(CYCLE_DELAY);
        }
    }

    gpioServo(VALVE_GPIO, 0);
    gpioServo(NOZZLE_GPIO, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

