#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0

static int i2c_fd = -1;
static FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Wake up the MPU-6050
    uint8_t wake_cmd = 0x00;
    if (write(i2c_fd, &wake_cmd, 1) != 1) {
        perror("Failed to wake up MPU-6050");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "timestamp,x,y,z\n");

    while (1) {
        uint8_t gyro_data[6];
        uint8_t gyro_reg = GYRO_XOUT_H;

        // Read 6 bytes of gyroscope data
        if (write(i2c_fd, &gyro_reg, 1) != 1) {
            perror("Failed to write register address");
            cleanup();
            exit(EXIT_FAILURE);
        }

        if (read(i2c_fd, gyro_data, 6) != 6) {
            perror("Failed to read gyroscope data");
            cleanup();
            exit(EXIT_FAILURE);
        }

        // Convert raw data to degrees/second
        int16_t gyro_x = (gyro_data[0] << 8) | gyro_data[1];
        int16_t gyro_y = (gyro_data[2] << 8) | gyro_data[3];
        int16_t gyro_z = (gyro_data[4] << 8) | gyro_data[5];

        double x_deg_s = gyro_x / GYRO_SENSITIVITY;
        double y_deg_s = gyro_y / GYRO_SENSITIVITY;
        double z_deg_s = gyro_z / GYRO_SENSITIVITY;

        // Get current timestamp
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        double timestamp = ts.tv_sec + ts.tv_nsec / 1e9;

        // Log the data
        fprintf(log_file, "%.9f,%.2f,%.2f,%.2f\n", timestamp, x_deg_s, y_deg_s, z_deg_s);
        fflush(log_file);

        // Sleep for 100 ms (10 Hz sampling rate)
        usleep(100000);
    }

    cleanup();
    return 0;
}

