#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000
#define MIN_GUARD_US 60000
#define DISTANCE_SCALE 0.01715

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;

void cleanup() {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_line_request_config req_config = {
        .consumer = "HC-SR04",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
    };
    struct gpiod_line_event event;
    struct timespec start_time, end_time;
    long duration_us;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request(trigger_line, &req_config);
    if (ret < 0) {
        perror("Failed to request trigger line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request the echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_input(echo_line, "HC-SR04");
    if (ret < 0) {
        perror("Failed to request echo line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        // Generate a 10 microsecond high pulse on the trigger line
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for the echo line to go high
        ret = gpiod_line_event_wait(echo_line, TIMEOUT_US);
        if (ret < 0) {
            perror("Failed to wait for echo line to go high");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            continue;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout waiting for echo line to go high\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            continue;
        }

        // Measure the echo pulse width
        ret = gpiod_line_event_read(echo_line, &event);
        if (ret < 0) {
            perror("Failed to read echo line event");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            continue;
        }
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        // Wait for the echo line to go low
        ret = gpiod_line_event_wait(echo_line, TIMEOUT_US);
        if (ret < 0) {
            perror("Failed to wait for echo line to go low");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            continue;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout waiting for echo line to go low\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            continue;
        }

        ret = gpiod_line_event_read(echo_line, &event);
        if (ret < 0) {
            perror("Failed to read echo line event");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            continue;
        }
        clock_gettime(CLOCK_MONOTONIC, &end_time);

        // Calculate the duration in microseconds
        duration_us = (end_time.tv_sec - start_time.tv_sec) * 1000000 +
                      (end_time.tv_nsec - start_time.tv_nsec) / 1000;

        // Calculate the distance in centimeters
        double distance_cm = duration_us * DISTANCE_SCALE;

        // Log the distance
        fprintf(log_file, "%.2f\n", distance_cm);
        fflush(log_file);

        // Enforce a 60 ms minimum guard between measurements
        usleep(MIN_GUARD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

