#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define VL53L1X_I2C_ADDRESS 0x29
#define RESET_REGISTER 0x0000
#define MODE_REGISTER 0x0080
#define STATUS_REGISTER 0x0044
#define DISTANCE_MSB_REGISTER 0x0096
#define DISTANCE_LSB_REGISTER 0x0097
#define RELAY_GPIO 18

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, VL53L1X_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Software reset
    if (i2cWriteWordData(i2c_handle, RESET_REGISTER, 0x00) < 0) {
        fprintf(stderr, "Failed to reset VL53L1X\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    usleep(10000); // Wait for reset to complete

    // Set ranging mode to continuous
    if (i2cWriteWordData(i2c_handle, MODE_REGISTER, 0x01) < 0) {
        fprintf(stderr, "Failed to set ranging mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, PI_LOW);

    signal(SIGINT, sigint_handler);

    while (running) {
        uint16_t status = i2cReadWordData(i2c_handle, STATUS_REGISTER);
        if (status < 0) {
            fprintf(stderr, "Failed to read status register\n");
            break;
        }

        if (status & 0x0001) { // Data ready
            uint16_t distance = i2cReadWordData(i2c_handle, DISTANCE_MSB_REGISTER);
            if (distance < 0) {
                fprintf(stderr, "Failed to read distance\n");
                break;
            }

            printf("Distance: %d mm\n", distance);

            if (distance <= 500) { // 50 cm
                gpioWrite(RELAY_GPIO, PI_HIGH);
            } else {
                gpioWrite(RELAY_GPIO, PI_LOW);
            }
        }

        usleep(100000); // Poll every 100 ms
    }

    gpioWrite(RELAY_GPIO, PI_LOW);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

