#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd;
    char buffer[14];
    int16_t gyro_x, gyro_y, gyro_z;
    float sensitivity = 131.0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Wake up the MPU6050 from sleep
    buffer[0] = PWR_MGMT_1;
    buffer[1] = 0x00;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to PWR_MGMT_1");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set the gyroscope full-scale range to ±250 dps
    buffer[0] = GYRO_CONFIG;
    buffer[1] = 0x00;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to GYRO_CONFIG");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Continuously read gyroscope data
    while (running) {
        // Read 6 bytes of data starting from GYRO_XOUT_H
        buffer[0] = GYRO_XOUT_H;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to GYRO_XOUT_H");
            break;
        }
        if (read(i2c_fd, buffer + 1, 6) != 6) {
            perror("Failed to read from I2C");
            break;
        }

        // Convert raw values to degrees/second
        gyro_x = (buffer[1] << 8) | buffer[2];
        gyro_y = (buffer[3] << 8) | buffer[4];
        gyro_z = (buffer[5] << 8) | buffer[6];

        // Log the readings
        printf("Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps\n",
               gyro_x / sensitivity, gyro_y / sensitivity, gyro_z / sensitivity);

        // Sleep for a short period
        usleep(100000); // 100 ms
    }

    // Close the I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

