#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define LOG_FILE "smart_lighting.log"
#define PWM_FREQUENCY 1000
#define DUTY_CYCLE_STEPS 256
#define SIMULATION_DURATION 1800 // 30 minutes in seconds
#define STEP_INTERVAL 1 // 1 second per step

int gpio_pins[] = {17, 18, 27, 22};
int num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

void log_event(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log, "%s: %s\n", ctime(&now), message);
    fclose(log);
}

void cleanup(int sig) {
    log_event("Cleanup initiated due to signal");
    for (int i = 0; i < num_pins; i++) {
        gpioSetPWMfrequency(gpio_pins[i], 0);
        gpioSetMode(gpio_pins[i], PI_INPUT);
    }
    gpioTerminate();
    log_event("Cleanup complete");
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }
    log_event("pigpio initialized");

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(gpio_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", gpio_pins[i]);
            cleanup(EXIT_FAILURE);
        }
        if (gpioSetPWMfrequency(gpio_pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", gpio_pins[i]);
            cleanup(EXIT_FAILURE);
        }
    }
    log_event("GPIOs initialized and PWM frequencies set");

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    for (int duty_cycle = 0; duty_cycle < DUTY_CYCLE_STEPS; duty_cycle++) {
        for (int i = 0; i < num_pins; i++) {
            gpioSetPWMrange(gpio_pins[i], DUTY_CYCLE_STEPS);
            gpioPWM(gpio_pins[i], duty_cycle);
        }
        log_event("Duty cycle set");
        sleep(STEP_INTERVAL);
    }

    cleanup(EXIT_SUCCESS);
    return EXIT_SUCCESS;
}

