#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define WHO_AM_I_REG 0x75
#define PWR_MGMT_1_REG 0x6B
#define SMPLRT_DIV_REG 0x19
#define GYRO_CONFIG_REG 0x1B
#define GYRO_XOUT_H_REG 0x43
#define LED_PIN 17
#define BUFFER_SIZE 100
#define SAMPLE_PERIOD_US 50000
#define THRESHOLD 250

typedef struct {
    uint64_t timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} GyroReading;

GyroReading buffer[BUFFER_SIZE];
volatile int buffer_index = 0;
volatile int running = 1;

void signal_handler(int signum) {
    running = 0;
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);
}

void init_i2c(int *handle) {
    *handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (*handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }
}

void write_register(int handle, uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "Failed to write to register 0x%02X\n", reg);
        exit(EXIT_FAILURE);
    }
}

uint8_t read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Failed to read from register 0x%02X\n", reg);
        exit(EXIT_FAILURE);
    }
    return (uint8_t)value;
}

void read_gyro_data(int handle, GyroReading *reading) {
    uint8_t data[6];
    if (i2cReadI2CBlockData(handle, GYRO_XOUT_H_REG, data, 6) < 0) {
        fprintf(stderr, "Failed to read gyro data\n");
        exit(EXIT_FAILURE);
    }
    reading->x = (data[0] << 8) | data[1];
    reading->y = (data[2] << 8) | data[3];
    reading->z = (data[4] << 8) | data[5];
    reading->timestamp = gpioTick();
}

void check_sensor(int handle) {
    uint8_t who_am_i = read_register(handle, WHO_AM_I_REG);
    if (who_am_i != 0x68) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        exit(EXIT_FAILURE);
    }
}

void setup_sensor(int handle) {
    write_register(handle, PWR_MGMT_1_REG, 0x00);
    write_register(handle, SMPLRT_DIV_REG, 0x07);
    write_register(handle, GYRO_CONFIG_REG, 0x00);
}

void handle_gyro_data(const GyroReading *reading) {
    int16_t x = reading->x;
    int16_t y = reading->y;
    int16_t z = reading->z;
    if (abs(x) > THRESHOLD || abs(y) > THRESHOLD || abs(z) > THRESHOLD) {
        gpioWrite(LED_PIN, PI_HIGH);
    } else {
        gpioWrite(LED_PIN, PI_LOW);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();
    int i2c_handle;
    init_i2c(&i2c_handle);

    check_sensor(i2c_handle);
    setup_sensor(i2c_handle);

    while (running) {
        GyroReading reading;
        read_gyro_data(i2c_handle, &reading);
        buffer[buffer_index] = reading;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        handle_gyro_data(&reading);
        usleep(SAMPLE_PERIOD_US);
    }

    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, PI_LOW);
    gpioTerminate();

    return 0;
}

