#define GYRO_SCALE_FACTOR 131.0

volatile sig_atomic_t running = 1;

void sig_handler(int signum) {
    running = 0;
}

int main() {
    int spi_fd = -1;
    struct gpiod_chip *gpio_chip = NULL;
    struct gpiod_line *gpio_line = NULL;
    FILE *log_file = NULL;
    struct sigaction sa;

    // Set up signal handler
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        goto cleanup;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        goto cleanup;
    }

    // Set SPI bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_path(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        goto cleanup;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        goto cleanup;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(gpio_line, "mpu9250_cs", 1) < 0) {
        perror("Failed to request GPIO line");
        goto cleanup;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Main loop
    while (running) {
        uint8_t tx[1] = {GYRO_XOUT_H | 0x80}; // Read 6 bytes starting from GYRO_XOUT_H
        uint8_t rx[6];
        struct spi_ioc_transfer tr = {
            .tx_buf = (unsigned long)tx,
            .rx_buf = (unsigned long)rx,
            .len = sizeof(rx),
            .speed_hz = SPI_SPEED,
            .bits_per_word = SPI_BITS_PER_WORD,
            .delay_usecs = 0,
            .cs_change = 0,
        };

        // Assert CS low
        gpiod_line_set_value(gpio_line, 0);

        // Perform SPI transfer
        int retries = RETRY_COUNT;
        while (retries > 0) {
            if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
                break;
            }
            retries--;
            if (retries == 0) {
                perror("SPI transfer failed");
                goto cleanup;
            }
        }

        // Deassert CS high
        gpiod_line_set_value(gpio_line, 1);

        // Convert raw values to degrees per second
        int16_t x_rate = (rx[0] << 8) | rx[1];
        int16_t y_rate = (rx[2] << 8) | rx[3];
        int16_t z_rate = (rx[4] << 8) | rx[5];
        double x_rate_dps = x_rate / GYRO_SCALE_FACTOR;
        double y_rate_dps = y_rate / GYRO_SCALE_FACTOR;
        double z_rate_dps = z_rate / GYRO_SCALE_FACTOR;

        // Get current time
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts));
        snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

        // Log data
        if (fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x_rate_dps, y_rate_dps, z_rate_dps) < 0) {
            perror("Failed to write to log file");
            goto cleanup;
        }
        fflush(log_file);

        // Sleep for 10 ms
        usleep(10000);
    }

cleanup:
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    return 0;
}
