    struct timespec timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} GyroData;

GyroData buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

struct gpiod_chip *chip;
struct gpiod_line *ce0_line;
struct gpiod_line *led_line;
int spi_fd;
volatile sig_atomic_t running = 1;

void cleanup() {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (ce0_line) {
        gpiod_line_release(ce0_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int sig) {
    running = 0;
}

int16_t read_register(uint8_t reg) {
    uint8_t tx[] = {reg};
    uint8_t rx[1];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 1,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return 0;
    }

    return (int16_t)rx[0];
}

void read_gyro_data(GyroData *data) {
    clock_gettime(CLOCK_REALTIME, &data->timestamp);
    data->x = read_register(0x43);
    data->y = read_register(0x45);
    data->z = read_register(0x47);
}

void blink_led() {
    gpiod_line_set_value(led_line, 1);
    usleep(BLINK_INTERVAL);
    gpiod_line_set_value(led_line, 0);
    usleep(BLINK_INTERVAL);
}

void print_buffer() {
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        printf("%ld.%09ld, %d, %d, %d\n",
               buffer[index].timestamp.tv_sec,
               buffer[index].timestamp.tv_nsec,
               buffer[index].x,
               buffer[index].y,
               buffer[index].z);
    }
}

