    if (!ce0_line) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_LINE);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(ce0_line, "mpu6050_ce0", 1) < 0) {
        perror("gpiod_line_request_output");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "mpu6050_led", 0) < 0) {
        perror("gpiod_line_request_output");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        return EXIT_FAILURE;
    }

    while (running) {
        GyroData data;
        read_gyro_data(&data);

        if (data.x == 0 && data.y == 0 && data.z == 0) {
            fprintf(stderr, "Invalid data read from MPU-6050\n");
            continue;
        }

        buffer[buffer_index] = data;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) {
            buffer_count++;
        }

        double x_deg = data.x / SENSITIVITY;
        double y_deg = data.y / SENSITIVITY;
        double z_deg = data.z / SENSITIVITY;

        if (fabs(x_deg) > THRESHOLD || fabs(y_deg) > THRESHOLD || fabs(z_deg) > THRESHOLD) {
            blink_led();
        }
    }

    print_buffer();
    return EXIT_SUCCESS;
}

