#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

#define LED_PIN 21

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void log_to_file(const char *timestamp, double roll, double pitch) {
    FILE *file = fopen("tilt_log.txt", "a");
    if (!file) {
        log_error("Failed to open log file");
        return;
    }
    fprintf(file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        log_error("Failed to set LED pin mode");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        log_error("Failed to write to PWR_MGMT_1");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        log_error("Failed to write to ACCEL_CONFIG");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        char buffer[6];
        if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buffer, 6) < 0) {
            log_error("Failed to read accelerometer data");
            continue;
        }

        int16_t ax = (buffer[0] << 8) | buffer[1];
        int16_t ay = (buffer[2] << 8) | buffer[3];
        int16_t az = (buffer[4] << 8) | buffer[5];

        double roll = atan2(ay, az) * 180.0 / M_PI;
        double pitch = atan2(-ax, sqrt(ay * ay + az * az)) * 180.0 / M_PI;

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        log_to_file(timestamp, roll, pitch);
        printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

        if (fabs(roll) > 45.0 || fabs(pitch) > 45.0) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }

        gpioDelay(100000); // 100 ms
    }

    gpioWrite(LED_PIN, PI_LOW);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

