#include <stdint.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define READ_BIT 0x80
#define DUMMY_BYTE 0x00
#define SAMPLE_DELAY_US 10000
#define MAX_REINIT_ATTEMPTS 3

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int spi_handle;
    FILE *file;
    struct timespec ts;
    int reinit_attempts = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open file
    file = fopen("gyro_data.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    while (running) {
        uint8_t tx_buf[2] = {READ_BIT | 0x02, DUMMY_BYTE};
        uint8_t rx_buf[2] = {0};
        int x_rate;
        int y_rate;

        // Read X axis
        if (spiXfer(spi_handle, tx_buf, rx_buf, 2) < 0) {
            fprintf(stderr, "SPI transfer failed for X axis\n");
            if (reinit_attempts < MAX_REINIT_ATTEMPTS) {
                reinit_attempts++;
                spiClose(spi_handle);
                spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
                if (spi_handle < 0) {
                    fprintf(stderr, "Failed to reinitialize SPI\n");
                    break;
                }
                continue;
            } else {
                break;
            }
        }
        x_rate = (rx_buf[0] << 8) | rx_buf[1];

        // Read Y axis
        tx_buf[0] = READ_BIT | 0x04;
        if (spiXfer(spi_handle, tx_buf, rx_buf, 2) < 0) {
            fprintf(stderr, "SPI transfer failed for Y axis\n");
            if (reinit_attempts < MAX_REINIT_ATTEMPTS) {
                reinit_attempts++;
                spiClose(spi_handle);
                spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
                if (spi_handle < 0) {
                    fprintf(stderr, "Failed to reinitialize SPI\n");
                    break;
                }
                continue;
            } else {
                break;
            }
        }
        y_rate = (rx_buf[0] << 8) | rx_buf[1];

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Failed to get timestamp\n");
            break;
        }

        // Write to file
        fprintf(file, "%ld.%06ld,%d,%d\n", ts.tv_sec, ts.tv_nsec / 1000, x_rate, y_rate);

        // Delay
        usleep(SAMPLE_DELAY_US);
    }

    // Clean up
    fclose(file);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

