#define SENSOR1_GPIO 23
#define SENSOR2_GPIO 24
#define ALERT_GPIO 17
#define DURATION_THRESHOLD 500  // milliseconds
#define LOG_FILE "seismic_events.txt"

volatile int sensor1_state = 0;
volatile int sensor2_state = 0;
volatile int alert_active = 0;
FILE *log_file = NULL;

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

void callback(int gpio, int level, uint32_t tick) {
    if (gpio == SENSOR1_GPIO) {
        sensor1_state = level;
    } else if (gpio == SENSOR2_GPIO) {
        sensor2_state = level;
    }

    if (sensor1_state && sensor2_state) {
        if (!alert_active) {
            alert_active = 1;
            gpioWrite(ALERT_GPIO, PI_HIGH);
            log_event("Seismic event detected!");
        }
    } else {
        if (alert_active) {
            alert_active = 0;
            gpioWrite(ALERT_GPIO, PI_LOW);
        }
    }
}

void signal_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    gpioWrite(ALERT_GPIO, PI_LOW);
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, PI_LOW);

    if (gpioSetISRFunc(SENSOR1_GPIO, EITHER_EDGE, 0, callback) < 0) {
        fprintf(stderr, "Failed to register callback for GPIO %d\n", SENSOR1_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFunc(SENSOR2_GPIO, EITHER_EDGE, 0, callback) < 0) {
        fprintf(stderr, "Failed to register callback for GPIO %d\n", SENSOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        gpioDelay(1000000);  // Sleep for 1 second
    }

    return 0;
}

