#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <pthread.h>

#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define LED_PIN 17
#define BUFFER_SIZE 100
#define THRESHOLD 20.0

typedef struct {
    struct timespec timestamp;
    double angular_velocity;
} GyroReading;

GyroReading buffer[BUFFER_SIZE];
volatile int head = 0;
volatile int tail = 0;
volatile int count = 0;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void *read_gyro_thread(void *arg) {
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI: %d\n", spi_handle);
        return NULL;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    while (running) {
        uint8_t tx[2] = {0x02 | 0x80, 0x00}; // Read from RATE_XL
        uint8_t rx[2] = {0};
        int result = spiXfer(spi_handle, tx, rx, 2);
        if (result < 0) {
            fprintf(stderr, "SPI transfer failed: %d\n", result);
            break;
        }

        int16_t raw_value = (rx[0] << 8) | rx[1];
        double angular_velocity = raw_value * 0.005; // 200 LSB/deg/s

        pthread_mutex_lock(&buffer_mutex);
        buffer[head].timestamp = (struct timespec){0};
        clock_gettime(CLOCK_MONOTONIC, &buffer[head].timestamp);
        buffer[head].angular_velocity = angular_velocity;
        head = (head + 1) % BUFFER_SIZE;
        if (count < BUFFER_SIZE) {
            count++;
        } else {
            tail = (tail + 1) % BUFFER_SIZE;
        }
        pthread_mutex_unlock(&buffer_mutex);

        if (angular_velocity > THRESHOLD) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }

        usleep(10000); // 10 ms delay
    }

    gpioWrite(LED_PIN, PI_LOW);
    spiClose(spi_handle);
    return NULL;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    pthread_t thread;
    if (pthread_create(&thread, NULL, read_gyro_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);
    gpioTerminate();
    return EXIT_SUCCESS;
}

