#include <signal.h>
#include <gpiod.h>

#define RED_GPIO 17
#define YELLOW_GPIO 22
#define GREEN_GPIO 23
#define RELAY_GPIO 24

#define RED_DURATION 10
#define RED_YELLOW_DURATION 2
#define GREEN_DURATION 10
#define YELLOW_DURATION 3

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *yellow_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *relay_line = NULL;

static void cleanup() {
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (yellow_line) {
        gpiod_line_release(yellow_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void signal_handler(int signum) {
    printf("Received signal %d, cleaning up and exiting...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

static void set_relay_state(int state) {
    if (gpiod_line_set_value(relay_line, state) < 0) {
        perror("Failed to set relay state");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

static void set_traffic_light_state(int red, int yellow, int green) {
    if (gpiod_line_set_value(red_line, red) < 0) {
        perror("Failed to set red light state");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_set_value(yellow_line, yellow) < 0) {
        perror("Failed to set yellow light state");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_set_value(green_line, green) < 0) {
        perror("Failed to set green light state");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    red_line = gpiod_chip_get_line(chip, RED_GPIO);
    yellow_line = gpiod_chip_get_line(chip, YELLOW_GPIO);
    green_line = gpiod_chip_get_line(chip, GREEN_GPIO);
    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);

    if (!red_line || !yellow_line || !green_line || !relay_line) {
        perror("Failed to get GPIO line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(red_line, "traffic_light", 1) < 0 ||
        gpiod_line_request_output(yellow_line, "traffic_light", 1) < 0 ||
        gpiod_line_request_output(green_line, "traffic_light", 1) < 0 ||
        gpiod_line_request_output(relay_line, "traffic_light", 1) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        exit(EXIT_FAILURE);
    }

    set_relay_state(0); // Turn relay ON (active-low)

    while (1) {
        set_traffic_light_state(0, 1, 1); // Red+Yellow
        printf("Red+Yellow\n");
        sleep(RED_YELLOW_DURATION);

        set_traffic_light_state(0, 0, 1); // Green
        printf("Green\n");
        sleep(GREEN_DURATION);

        set_traffic_light_state(0, 1, 0); // Yellow
        printf("Yellow\n");
        sleep(YELLOW_DURATION);

        set_traffic_light_state(1, 0, 0); // Red
        printf("Red\n");
        sleep(RED_DURATION);
    }

    cleanup();
    return 0;
}

