#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define RELAY_PIN 17
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE 0x21
#define CHARGE_TIME 0x0D
#define RUN_MODE 0x0D

#define LOG_FILE "touch_relay.log"

volatile sig_atomic_t running = 1;

void log_error(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        time_t now = time(NULL);
        fprintf(log, "%s: %s\n", ctime(&now), message);
        fclose(log);
    }
}

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO17 as output");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, PI_LOW) < 0) {
        log_error("Failed to set GPIO17 to LOW");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // MPR121 reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        log_error("Failed to reset MPR121");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    usleep(10000); // Wait for reset

    // Configure MPR121
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x00) < 0) {
        log_error("Failed to set stop mode");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) {
        log_error("Failed to enable electrode 0");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(i2c_handle, 0x41, TOUCH_THRESHOLD) < 0) {
        log_error("Failed to set touch threshold");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(i2c_handle, 0x42, RELEASE_THRESHOLD) < 0) {
        log_error("Failed to set release threshold");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(i2c_handle, 0x5B, DEBOUNCE) < 0) {
        log_error("Failed to set debounce");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(i2c_handle, 0x5C, CHARGE_TIME) < 0) {
        log_error("Failed to set charge time");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(i2c_handle, 0x5E, RUN_MODE) < 0) {
        log_error("Failed to set run mode");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = 0;
    time_t last_change = 0;

    while (running) {
        uint16_t touch_status = 0;
        uint8_t lsb = i2cReadByteData(i2c_handle, 0x00);
        uint8_t msb = i2cReadByteData(i2c_handle, 0x01);
        if (lsb < 0 || msb < 0) {
            log_error("Failed to read touch status");
            break;
        }
        touch_status = (msb << 8) | lsb;

        int current_state = (touch_status & 0x0001) != 0;
        if (current_state != last_state) {
            last_state = current_state;
            last_change = time(NULL);
        } else if (time(NULL) - last_change > 1) { // Debounce for 1 second
            if (gpioWrite(RELAY_PIN, current_state ? PI_HIGH : PI_LOW) < 0) {
                log_error("Failed to toggle relay");
                break;
            }
        }

        usleep(10000); // 10 ms delay
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

