volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    if (gpioSetMode(SOL1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOL1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOL2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOL2_PIN);
        gpioTerminate();
        return 1;
    }
    return 0;
}

int log_dispense_event(FILE *log_file, int sol1_pin, int sol2_pin, int duration) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    if (fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d - Solenoid 1: GPIO%d, Solenoid 2: GPIO%d, Duration: %d ms\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                sol1_pin, sol2_pin, duration) < 0) {
        fprintf(stderr, "Failed to log dispense event\n");
        return 1;
    }
    return 0;
}

int dispense_cycle(FILE *log_file) {
    gpioWrite(SOL1_PIN, PI_HIGH);
    gpioDelay(DISPENSE_DURATION / 2 * 1000);
    gpioWrite(SOL1_PIN, PI_LOW);
    gpioWrite(SOL2_PIN, PI_HIGH);
    gpioDelay(DISPENSE_DURATION / 2 * 1000);
    gpioWrite(SOL2_PIN, PI_LOW);
    return log_dispense_event(log_file, SOL1_PIN, SOL2_PIN, DISPENSE_DURATION);
}

