    signal(SIGINT, sigint_handler);

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("dispense_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (dispense_cycle(log_file) != 0) {
            fprintf(stderr, "Dispense cycle failed\n");
        }
        gpioDelay(LOOP_INTERVAL * 1000);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

