#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

#define KP 1.0
#define KI 0.01
#define KD 0.1
#define CONTROL_INTERVAL 50000 // 50 ms in microseconds

#define MIN_SPEED 0
#define MAX_SPEED 255

#define OBSTACLE_THRESHOLD 20.0

FILE *log_file;

void stop_motors() {
    gpioPWM(MOTOR_A_FORWARD, 0);
    gpioPWM(MOTOR_A_BACKWARD, 0);
    gpioPWM(MOTOR_B_FORWARD, 0);
    gpioPWM(MOTOR_B_BACKWARD, 0);
}

void handle_sigint(int sig) {
    stop_motors();
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

void init_motors() {
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    gpioWrite(MOTOR_A_ENABLE, PI_HIGH);
    gpioWrite(MOTOR_B_ENABLE, PI_HIGH);
}

float random_float(float min, float max) {
    return min + (float)rand() / ((float)RAND_MAX / (max - min));
}

void set_motor_speed(int forward_pin, int backward_pin, int speed) {
    if (speed > 0) {
        gpioPWM(forward_pin, speed);
        gpioPWM(backward_pin, 0);
    } else if (speed < 0) {
        gpioPWM(forward_pin, 0);
        gpioPWM(backward_pin, -speed);
    } else {
        gpioPWM(forward_pin, 0);
        gpioPWM(backward_pin, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen("balance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    init_motors();

    signal(SIGINT, handle_sigint);

    srand(time(NULL));

    float last_tilt_error = 0.0;
    float integral = 0.0;
    float derivative = 0.0;

    while (1) {
        float tilt_error = random_float(-10.0, 10.0);
        float distance = random_float(2.0, 400.0);

        if (distance < OBSTACLE_THRESHOLD) {
            set_motor_speed(MOTOR_A_FORWARD, MOTOR_A_BACKWARD, -MAX_SPEED / 2);
            set_motor_speed(MOTOR_B_FORWARD, MOTOR_B_BACKWARD, -MAX_SPEED / 2);
        } else {
            derivative = tilt_error - last_tilt_error;
            integral += tilt_error;
            float control_signal = KP * tilt_error + KI * integral + KD * derivative;

            int motor_a_speed = (int)control_signal;
            int motor_b_speed = (int)control_signal;

            if (motor_a_speed > MAX_SPEED) motor_a_speed = MAX_SPEED;
            if (motor_a_speed < -MAX_SPEED) motor_a_speed = -MAX_SPEED;
            if (motor_b_speed > MAX_SPEED) motor_b_speed = MAX_SPEED;
            if (motor_b_speed < -MAX_SPEED) motor_b_speed = -MAX_SPEED;

            set_motor_speed(MOTOR_A_FORWARD, MOTOR_A_BACKWARD, motor_a_speed);
            set_motor_speed(MOTOR_B_FORWARD, MOTOR_B_BACKWARD, motor_b_speed);

            last_tilt_error = tilt_error;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
        fflush(log_file);

        gpioDelay(CONTROL_INTERVAL);
    }

    return 0;
}

