#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TTP223_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY 50

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TTP223_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TTP223_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TTP223_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO%d\n", TTP223_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(RELAY_PIN, PI_LOW);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state = 0;
    while (running) {
        int current_state = gpioRead(TTP223_PIN);
        if (current_state != last_state && current_state == PI_HIGH) {
            gpioWrite(RELAY_PIN, gpioRead(RELAY_PIN) == PI_HIGH ? PI_LOW : PI_HIGH);
            gpioDelay(DEBOUNCE_DELAY * 1000);
        }
        last_state = current_state;
        gpioDelay(10); // Small delay to reduce CPU usage
    }

    gpioWrite(RELAY_PIN, PI_LOW);
    gpioTerminate();
    return EXIT_SUCCESS;
}

