    static double phase = 0.0;
    for (size_t i = 0; i < size; ++i) {
        buffer[i] = 32767 * sin(2 * M_PI * 440 * phase);
        phase += 1.0 / SAMPLE_RATE;
        if (phase >= 1.0) phase -= 1.0;
    }
}

void map_rms_to_rgb(float rms, float sensitivity, unsigned int *red, unsigned int *green, unsigned int *blue) {
    float scaled_rms = rms * sensitivity;
    if (scaled_rms < 0.2) {
        *red = 0;
        *green = 0;
        *blue = 255;
    } else if (scaled_rms < 0.4) {
        *red = 0;
        *green = 255;
        *blue = 255 - (scaled_rms - 0.2) * 255 / 0.2;
    } else if (scaled_rms < 0.6) {
        *red = 0;
        *green = 255;
        *blue = 0;
    } else if (scaled_rms < 0.8) {
        *red = (scaled_rms - 0.6) * 255 / 0.2;
        *green = 255;
        *blue = 0;
    } else {
        *red = 255;
        *green = 255 - (scaled_rms - 0.8) * 255 / 0.2;
        *blue = 0;
    }
}

