            } else if (err == -ESTRPIPE) {
                fprintf(stderr, "PCM in suspended state, resuming\n");
                snd_pcm_resume(handle);
            } else {
                fprintf(stderr, "Read error: %s\n", snd_strerror(err));
                break;
            }
        }
        if (err < 0) break;
        frames_read = err;
#else
        simulate_audio(buffer, PERIOD_SIZE);
        frames_read = PERIOD_SIZE;
#endif

        float sum = 0.0;
        for (size_t i = 0; i < frames_read; ++i) {
            sum += buffer[i] * buffer[i];
        }
        float rms = sqrt(sum / frames_read);

        unsigned int red, green, blue;
        map_rms_to_rgb(rms, sensitivity, &red, &green, &blue);

        gpioPWM(RED_PIN, red);
        gpioPWM(GREEN_PIN, green);
        gpioPWM(BLUE_PIN, blue);

        printf("RMS: %f, RGB: %u, %u, %u\n", rms, red, green, blue);
        usleep(10000);
    }

    free(buffer);
    cleanup_gpio();
#if ALSA_AVAILABLE
    cleanup_alsa(handle);
#endif

    return 0;
}

