#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define POWER_ON_AND_RGBC_ENABLE 0x03
#define INTEGRATION_TIME_154MS 0xD5
#define DATA_REG_START 0x14
#define DATA_REG_END 0x1A

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void init_sensor(int handle) {
    if (i2cWriteByteData(handle, 0x80, POWER_ON_AND_RGBC_ENABLE) < 0) {
        fprintf(stderr, "Failed to enable power and RGBC\n");
    }
    if (i2cWriteByteData(handle, 0x81, INTEGRATION_TIME_154MS) < 0) {
        fprintf(stderr, "Failed to set integration time\n");
    }
}

void read_sensor_data(int handle, uint16_t *data) {
    uint8_t buffer[6];
    if (i2cReadI2CBlockData(handle, DATA_REG_START, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        memset(data, 0, sizeof(uint16_t) * 4);
        return;
    }
    data[0] = (buffer[1] << 8) | buffer[0]; // Clear
    data[1] = (buffer[3] << 8) | buffer[2]; // Red
    data[2] = (buffer[5] << 8) | buffer[4]; // Green
    data[3] = (buffer[7] << 8) | buffer[6]; // Blue
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    init_sensor(handle);

    FILE *file = fopen("color_data.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open color_data.csv for writing\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(file, "Timestamp,Clear,Red,Green,Blue\n");

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        uint16_t data[4];
        read_sensor_data(handle, data);

        time_t now = time(NULL);
        fprintf(file, "%ld,%u,%u,%u,%u\n", (long)now, data[0], data[1], data[2], data[3]);
        fflush(file);

        gpioDelay(500000); // 500 ms
    }

    fclose(file);
    i2cClose(handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

