#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define NUM_RELAYS 4
#define GPIO_PINS {17, 27, 22, 23}
#define SUNRISE_DURATION 3600  // 1 hour
#define DAYTIME_DURATION 21600 // 6 hours
#define SUNSET_DURATION 3600   // 1 hour
#define NIGHTTIME_DURATION 52560 // 14.4 hours

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_RELAYS];
static volatile sig_atomic_t running = 1;

void cleanup() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1); // Turn off relay
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int sig) {
    running = 0;
}

void setup_gpio() {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    int pins[NUM_RELAYS] = GPIO_PINS;
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_line_get(chip, pins[i], GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
        if (!lines[i]) {
            perror("Failed to request GPIO line");
            cleanup();
            exit(EXIT_FAILURE);
        }
        gpiod_line_set_value(lines[i], 1); // Initialize relays to off
    }
}

void simulate_brightness(int duration, int start_duty, int end_duty) {
    int steps = duration / 10; // 10% increments
    int step_duty = (end_duty - start_duty) / steps;
    int current_duty = start_duty;

    for (int i = 0; i < steps && running; i++) {
        for (int j = 0; j < NUM_RELAYS; j++) {
            gpiod_line_set_value(lines[j], current_duty <= 0);
        }
        usleep(100000); // 100ms
        current_duty += step_duty;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();

    while (running) {
        // Sunrise
        simulate_brightness(SUNRISE_DURATION, 0, 100);

        // Daytime
        for (int i = 0; i < NUM_RELAYS && running; i++) {
            gpiod_line_set_value(lines[i], 0);
        }
        sleep(DAYTIME_DURATION);

        // Sunset
        simulate_brightness(SUNSET_DURATION, 100, 0);

        // Nighttime
        for (int i = 0; i < NUM_RELAYS && running; i++) {
            gpiod_line_set_value(lines[i], 1);
        }
        sleep(NIGHTTIME_DURATION);
    }

    cleanup();
    return 0;
}

