    while (running) {
        // Sunrise
        simulate_brightness(SUNRISE_DURATION, 0, 100);

        // Daytime
        for (int i = 0; i < NUM_RELAYS && running; i++) {
            gpiod_line_set_value(lines[i], 0);
        }
        sleep(DAYTIME_DURATION);

        // Sunset
        simulate_brightness(SUNSET_DURATION, 100, 0);

        // Nighttime
        for (int i = 0; i < NUM_RELAYS && running; i++) {
            gpiod_line_set_value(lines[i], 1);
        }
        sleep(NIGHTTIME_DURATION);
    }

    cleanup();
    return 0;
}
