#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48
#define GYRO_SENSITIVITY 131.0

#define SAMPLE_RATE_MS 10
#define MAX_RETRIES 3

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("gyro_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");

    while (running) {
        for (int retry = 0; retry <= MAX_RETRIES; retry++) {
            if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) == 0 &&
                i2cWriteByteData(handle, SMPLRT_DIV, 0x07) == 0 &&
                i2cWriteByteData(handle, GYRO_CONFIG, 0x00) == 0) {
                break;
            }
            if (retry == MAX_RETRIES) {
                fprintf(stderr, "Failed to initialize MPU6050 after %d retries\n", MAX_RETRIES);
                continue;
            }
        }

        uint8_t buffer[6];
        if (i2cReadI2CBlockData(handle, GYRO_XOUT_H, buffer, 6) == 6) {
            int16_t x_raw = (buffer[0] << 8) | buffer[1];
            int16_t y_raw = (buffer[2] << 8) | buffer[3];
            int16_t z_raw = (buffer[4] << 8) | buffer[5];

            double x_degps = x_raw / GYRO_SENSITIVITY;
            double y_degps = y_raw / GYRO_SENSITIVITY;
            double z_degps = z_raw / GYRO_SENSITIVITY;

            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            double timestamp = ts.tv_sec + ts.tv_nsec / 1e9;

            fprintf(log_file, "%.6f,%.2f,%.2f,%.2f\n", timestamp, x_degps, y_degps, z_degps);
            fflush(log_file);
        } else {
            fprintf(stderr, "Failed to read from MPU6050\n");
        }

        gpioDelay(SAMPLE_RATE_MS * 1000);
    }

    fclose(log_file);
    i2cClose(handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

