#define LOG_FILE "irrigation_log.txt"
#define NUM_RELAYS 4
#define GPIO_PINS {4, 17, 27, 22}
#define MOISTURE_THRESHOLD 30
#define READ_INTERVAL 5000 // 5 seconds in milliseconds

int gpio_pins[NUM_RELAYS] = GPIO_PINS;
FILE *log_file;
int pigpio_init_status;

void cleanup_and_exit(int sig) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(gpio_pins[i], PI_HIGH);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    srand(time(NULL));
    signal(SIGINT, cleanup_and_exit);

    pigpio_init_status = gpioInitialise();
    if (pigpio_init_status < 0) {
        fprintf(stderr, "pigpio initialization failed: %d\n", pigpio_init_status);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(gpio_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", gpio_pins[i]);
            cleanup_and_exit(0);
        }
        gpioWrite(gpio_pins[i], PI_HIGH); // Deactivate relay
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        for (int i = 0; i < NUM_RELAYS; i++) {
            int moisture_level = rand() % 101;
            int relay_state = (moisture_level < MOISTURE_THRESHOLD) ? PI_LOW : PI_HIGH;
            gpioWrite(gpio_pins[i], relay_state);

            fprintf(log_file, "Timestamp: %s, Zone %d: Moisture Level = %d, Relay State = %s\n",
                    timestamp, i + 1, moisture_level, (relay_state == PI_LOW) ? "ON" : "OFF");
        }

        fflush(log_file);
        gpioDelay(READ_INTERVAL);
    }

    cleanup_and_exit(0);
    return EXIT_SUCCESS;
}

