#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDR 0x53
#define DATA_FORMAT_REG 0x31
#define POWER_CTL_REG 0x2D
#define DATAX0_REG 0x32
#define GPIO_ALARM 27
#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION 500000 // 0.5 seconds in microseconds
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds
#define LOG_FILE "freefall.log"

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_ALARM, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for alarm\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(1, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, DATA_FORMAT_REG, 0x0B) < 0) {
        fprintf(stderr, "Failed to write to DATA_FORMAT register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, POWER_CTL_REG, 0x08) < 0) {
        fprintf(stderr, "Failed to write to POWER_CTL register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct timespec start_time, current_time;
    int freefall_count = 0;

    while (running) {
        uint8_t buffer[6];
        if (i2cReadI2CBlockData(i2c_handle, DATAX0_REG, buffer, 6) < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            continue;
        }

        int16_t x = (buffer[1] << 8) | buffer[0];
        int16_t y = (buffer[3] << 8) | buffer[2];
        int16_t z = (buffer[5] << 8) | buffer[4];

        double x_g = x / 256.0;
        double y_g = y / 256.0;
        double z_g = z / 256.0;

        if (fabs(x_g) < FREEFALL_THRESHOLD && fabs(y_g) < FREEFALL_THRESHOLD && fabs(z_g) < FREEFALL_THRESHOLD) {
            freefall_count++;
            if (freefall_count == 1) {
                clock_gettime(CLOCK_REALTIME, &start_time);
            } else if (freefall_count == 2) {
                clock_gettime(CLOCK_REALTIME, &current_time);
                if (current_time.tv_sec - start_time.tv_sec >= 0.5) {
                    gpioWrite(GPIO_ALARM, PI_HIGH);
                    usleep(5000000); // 5 seconds
                    gpioWrite(GPIO_ALARM, PI_LOW);

                    char timestamp[20];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&start_time));
                    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x_g, y_g, z_g);
                    fflush(log_file);
                }
                freefall_count = 0;
            }
        } else {
            freefall_count = 0;
        }

        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

