#define MAX_ECHO_US 23200
#define TIMEOUT_US 100000

volatile uint32_t echo_start;
volatile uint32_t echo_end;
volatile int echo_received;
pthread_mutex_t lock;

FILE *log_file;

void sigint_handler(int sig) {
    gpioSetAlertFunc(TRIG_PIN, NULL);
    gpioSetAlertFunc(ECHO_PIN, NULL);
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&lock);
    exit(0);
}

void trigger_pulse() {
    gpioWrite(TRIG_PIN, PI_HIGH);
    gpioDelay(TRIGGER_US);
    gpioWrite(TRIG_PIN, PI_LOW);
}

void echo_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&lock);
    if (gpio == ECHO_PIN) {
        if (level == PI_HIGH) {
            echo_start = tick;
        } else if (level == PI_LOW) {
            echo_end = tick;
            echo_received = 1;
        }
    }
    pthread_mutex_unlock(&lock);
}

void measure_distance() {
    while (1) {
        echo_received = 0;
        trigger_pulse();
        gpioDelay(MEASURE_INTERVAL_US - TRIGGER_US);

        pthread_mutex_lock(&lock);
        if (echo_received) {
            uint32_t echo_width;
            if (echo_end >= echo_start) {
                echo_width = echo_end - echo_start;
            } else {
                echo_width = (UINT32_MAX - echo_start) + echo_end;
            }

            if (echo_width <= MAX_ECHO_US) {
                double distance_cm = (echo_width * 0.0343) / 2.0;
                struct timespec ts;
                clock_gettime(CLOCK_REALTIME, &ts);
                uint64_t timestamp_ns = (uint64_t)ts.tv_sec * 1000000000 + ts.tv_nsec;
                fprintf(log_file, "%llu,%.2f\n", timestamp_ns, distance_cm);
                fflush(log_file);
            }
        }
        pthread_mutex_unlock(&lock);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (pthread_mutex_init(&lock, NULL) != 0) {
        fprintf(stderr, "mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "failed to open log file\n");
        pthread_mutex_destroy(&lock);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetAlertFunc(ECHO_PIN, echo_callback);

    measure_distance();

    return 0;
}

