#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L 0x28
#define LIS3DH_OUT_X_H 0x29
#define LIS3DH_OUT_Y_L 0x2A
#define LIS3DH_OUT_Y_H 0x2B
#define LIS3DH_OUT_Z_L 0x2C
#define LIS3DH_OUT_Z_H 0x2D
#define LIS3DH_SENSITIVITY 16384.0

#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5
#define BUZZER_GPIO 17
#define I2C_BUS 1
#define I2C_RETRIES 3

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main(int argc, char *argv[]) {
    double freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    double impact_threshold = DEFAULT_IMPACT_THRESHOLD;

