        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG1, 0x77) < 0) {
