                fprintf(stderr, "I2C read failed\n");
                break;
            }
        }

        if (retries == 0) {
            break;
        }

        x = (x >> 6) | ((x << 8) & 0xFF00);
        y = (y >> 6) | ((y << 8) & 0xFF00);
        z = (z >> 6) | ((z << 8) & 0xFF00);

        magnitude = sqrt(x * x + y * y + z * z) / LIS3DH_SENSITIVITY;

        if (magnitude < freefall_threshold) {
            printf("Freefall detected\n");
            while (running && magnitude < freefall_threshold) {
                usleep(100000);
                retries = I2C_RETRIES;
                while (retries > 0) {
                    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_OUT_X_L, (char *)&x, 6) == 6) {
                        break;
                    }
                    retries--;
                    if (retries == 0) {
                        fprintf(stderr, "I2C read failed\n");
