                y = (y >> 6) | ((y << 8) & 0xFF00);
                z = (z >> 6) | ((z << 8) & 0xFF00);
                magnitude = sqrt(x * x + y * y + z * z) / LIS3DH_SENSITIVITY;
            }
            if (magnitude > impact_threshold) {
                printf("Impact detected\n");
                gpioWrite(BUZZER_GPIO, PI_HIGH);
                usleep(1000000);
                gpioWrite(BUZZER_GPIO, PI_LOW);
            }
        }
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

