#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define X_STEP_PIN 4
#define X_DIR_PIN 17
#define X_EN_PIN 27
#define X_IN4_PIN 22

#define Y_STEP_PIN 5
#define Y_DIR_PIN 6
#define Y_EN_PIN 13
#define Y_IN4_PIN 19

#define STEPS_PER_REV 2048
#define STEP_DELAY 1000
#define STEPS_PER_MM 10
#define SQUARE_SIDE_MM 50
#define SQUARE_STEPS (SQUARE_SIDE_MM * STEPS_PER_MM)

volatile sig_atomic_t running = 1;

void cleanup(int sig) {
    running = 0;
    gpioWrite(X_STEP_PIN, 0);
    gpioWrite(Y_STEP_PIN, 0);
    gpioWrite(X_EN_PIN, 1);
    gpioWrite(Y_EN_PIN, 1);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void move_motor(int step_pin, int dir_pin, int steps, int delay) {
    gpioWrite(dir_pin, steps > 0 ? PI_HIGH : PI_LOW);
    for (int i = 0; i < abs(steps); i++) {
        gpioWrite(step_pin, PI_HIGH);
        gpioDelay(delay);
        gpioWrite(step_pin, PI_LOW);
        gpioDelay(delay);
        if (!running) {
            return;
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {X_STEP_PIN, X_DIR_PIN, X_EN_PIN, X_IN4_PIN,
                  Y_STEP_PIN, Y_DIR_PIN, Y_EN_PIN, Y_IN4_PIN};

    for (int pin : pins) {
        if (gpioSetMode(pin, PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    gpioWrite(X_EN_PIN, PI_LOW);
    gpioWrite(Y_EN_PIN, PI_LOW);

    signal(SIGINT, cleanup);

    // Draw a square
    for (int i = 0; i < 4; i++) {
        move_motor(X_STEP_PIN, X_DIR_PIN, SQUARE_STEPS, STEP_DELAY);
        move_motor(Y_STEP_PIN, Y_DIR_PIN, SQUARE_STEPS, STEP_DELAY);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

