#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define LIS3DH_I2C_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_Y_L 0x2A
#define OUT_Z_L 0x2C

#define DEFAULT_THRESHOLD 2.0f
#define DEFAULT_I2C_ADDR LIS3DH_I2C_ADDR
#define I2C_BLOCK_SIZE 6

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void log_event(float x, float y, float z) {
    FILE *log_file = fopen("/var/log/high_acceleration.log", "a");
    if (log_file) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        fprintf(log_file, "%s: X=%.3f, Y=%.3f, Z=%.3f\n", asctime(tm_info), x, y, z);
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    int i2c_addr = DEFAULT_I2C_ADDR;
    float threshold = DEFAULT_THRESHOLD;
    int i2c_handle = -1;

    // Parse command line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            i2c_addr = strtoul(argv[++i], NULL, 16);
            if (i2c_addr < 0x08 || i2c_addr > 0x77) {
                fprintf(stderr, "Invalid I2C address. Must be between 0x08 and 0x77.\n");
                return 1;
            }
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = strtof(argv[++i], NULL);
            if (threshold <= 0) {
                fprintf(stderr, "Invalid threshold. Must be greater than 0.\n");
                return 1;
            }
        } else {
            fprintf(stderr, "Usage: %s [-a hex] [-t float]\n", argv[0]);
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Open I2C
    i2c_handle = i2cOpen(1, i2c_addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X.\n", i2c_addr);
        gpioTerminate();
        return 1;
    }

    // Configure LIS3DH
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x88) < 0 ||
        i2cWriteByteData(i2c_handle, CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Failed to configure LIS3DH.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        uint8_t buffer[I2C_BLOCK_SIZE];
        if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, I2C_BLOCK_SIZE) < 0) {
            fprintf(stderr, "Failed to read from LIS3DH. Continuing...\n");
            continue;
        }

        int16_t x = (buffer[1] << 8) | buffer[0];
        int16_t y = (buffer[3] << 8) | buffer[2];
        int16_t z = (buffer[5] << 8) | buffer[4];

        x >>= 4;
        y >>= 4;
        z >>= 4;

        float ax = x * 0.0009765625f;
        float ay = y * 0.0009765625f;
        float az = z * 0.0009765625f;

        if (fabs(ax) > threshold || fabs(ay) > threshold || fabs(az) > threshold) {
            log_event(ax, ay, az);
            system("sudo shutdown -h now");
            break;
        }

        usleep(100000); // 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
