#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define LEFT_PIN 4
#define CENTER_PIN 17
#define RIGHT_PIN 27
#define ALERT_PIN 22
#define BUFFER_SIZE 5
#define POLL_INTERVAL_US 10000

volatile sig_atomic_t running = 1;

void sig_handler(int signum) {
    running = 0;
}

void setup_signals() {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

void motor_forward() {
    printf("Move forward\n");
}

void motor_left() {
    printf("Turn left\n");
}

void motor_right() {
    printf("Turn right\n");
}

void motor_stop() {
    printf("Stop\n");
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *left_line, *center_line, *right_line, *alert_line;
    int left_val, center_val, right_val;
    int buffer[BUFFER_SIZE] = {0};
    int buffer_index = 0;
    int consecutive_no_line = 0;
    struct timespec start_time, end_time;
    long elapsed_time;

    setup_signals();

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);

    if (!left_line || !center_line || !right_line || !alert_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(left_line, "line_following") < 0 ||
        gpiod_line_request_input(center_line, "line_following") < 0 ||
        gpiod_line_request_input(right_line, "line_following") < 0 ||
        gpiod_line_request_output(alert_line, "line_following") < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        left_val = gpiod_line_get_value(left_line);
        center_val = gpiod_line_get_value(center_line);
        right_val = gpiod_line_get_value(right_line);

        buffer[buffer_index] = center_val;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        consecutive_no_line = 1;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            if (buffer[i] == 0) {
                consecutive_no_line++;
            } else {
                consecutive_no_line = 0;
                break;
            }
        }

        if (consecutive_no_line >= BUFFER_SIZE) {
            gpiod_line_set_value(alert_line, 1);
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            while (running) {
                clock_gettime(CLOCK_MONOTONIC, &end_time);
                elapsed_time = (end_time.tv_sec - start_time.tv_sec) * 1000000 +
                               (end_time.tv_nsec - start_time.tv_nsec) / 1000;
                if (elapsed_time >= 2000000) {
                    break;
                }
            }
            gpiod_line_set_value(alert_line, 0);
        }

        if (center_val == 0) {
            motor_forward();
        } else if (left_val == 0) {
            motor_left();
        } else if (right_val == 0) {
            motor_right();
        } else {
            motor_stop();
        }

        usleep(POLL_INTERVAL_US);
    }

    gpiod_line_release(left_line);
    gpiod_line_release(center_line);
    gpiod_line_release(right_line);
    gpiod_line_release(alert_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

