#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x30
#define START_CONVERSION_REG 0xC1
#define FIELD_DATA_REG 0xC0
#define RELAY_PIN 17
#define THRESHOLD_MT 5.0
#define POLL_ATTEMPTS 50
#define POLL_DELAY_US 100000

volatile sig_atomic_t running = 1;

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    FILE *log_file = fopen("magnetic_events.txt", "a");
    if (log_file) {
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fclose(log_file);
    }
}

void sigint_handler(int sig) {
    running = 0;
    log_event("SIGINT received, shutting down.");
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for relay.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, SENSOR_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        if (i2cWriteByteData(i2c_handle, START_CONVERSION_REG, 0x01) < 0) {
            log_event("Failed to start conversion.");
            gpioWrite(RELAY_PIN, PI_LOW);
            continue;
        }

        int attempts = 0;
        while (attempts < POLL_ATTEMPTS) {
            if (i2cReadByteData(i2c_handle, START_CONVERSION_REG) == 0x00) {
                break;
            }
            attempts++;
            gpioDelay(POLL_DELAY_US);
        }

        if (attempts >= POLL_ATTEMPTS) {
            log_event("Conversion timeout.");
            gpioWrite(RELAY_PIN, PI_LOW);
            continue;
        }

        int lsb = i2cReadByteData(i2c_handle, FIELD_DATA_REG);
        int msb = i2cReadByteData(i2c_handle, FIELD_DATA_REG + 1);

        if (lsb < 0 || msb < 0) {
            log_event("Failed to read field data.");
            gpioWrite(RELAY_PIN, PI_LOW);
            continue;
        }

        int field_raw = (msb << 8) | lsb;
        int field_mT_x100 = field_raw * 25 / 1000;
        double field_mT = field_mT_x100 / 100.0;

        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Field strength: %.2f mT", field_mT);
        log_event(log_message);

        if (field_mT > THRESHOLD_MT) {
            gpioWrite(RELAY_PIN, PI_HIGH);
            log_event("Relay activated.");
        } else {
            gpioWrite(RELAY_PIN, PI_LOW);
            log_event("Relay deactivated.");
        }

        gpioDelay(100000); // Sample every 100 ms
    }

    i2cClose(i2c_handle);
    gpioWrite(RELAY_PIN, PI_LOW);
    gpioTerminate();
    log_event("Program terminated.");

    return EXIT_SUCCESS;
}

