#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <time.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

volatile sig_atomic_t running = 1;

void log_event(const char *event) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log, "%s: %s\n", timestamp, event);
    fclose(log);
}

void handle_signal(int sig) {
    running = 0;
}

void cleanup(int gpio_pin, int socket_fd, FILE *log) {
    if (gpio_pin >= 0) {
        gpioWrite(gpio_pin, PI_OFF);
        gpioTerminate();
    }
    if (socket_fd >= 0) {
        close(socket_fd);
    }
    if (log) {
        fclose(log);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int gpio_pin = GPIO_PIN;
    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, PI_OFF);

    int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        perror("Socket creation failed");
        cleanup(gpio_pin, socket_fd, NULL);
        return EXIT_FAILURE;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        cleanup(gpio_pin, socket_fd, NULL);
        return EXIT_FAILURE;
    }

    if (listen(socket_fd, 1) < 0) {
        perror("Listen failed");
        cleanup(gpio_pin, socket_fd, NULL);
        return EXIT_FAILURE;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        cleanup(gpio_pin, socket_fd, NULL);
        return EXIT_FAILURE;
    }

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(socket_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            perror("Accept failed");
            continue;
        }

        char buffer[BUFFER_SIZE];
        ssize_t bytes_read = read(client_fd, buffer, BUFFER_SIZE - 1);
        if (bytes_read < 0) {
            perror("Read failed");
            close(client_fd);
            continue;
        }

        buffer[bytes_read] = '\0';
        while (bytes_read > 0 && (buffer[bytes_read - 1] == ' ' || buffer[bytes_read - 1] == '\t')) {
            buffer[--bytes_read] = '\0';
        }

        if (strcasecmp(buffer, "ON") == 0) {
            gpioWrite(gpio_pin, PI_ON);
