#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/time.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define RELAY_PIN 18
#define START_MEASUREMENT_CMD 0x36
#define START_MEASUREMENT_ARG 0x08
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define SCALE_FACTOR 1.0 / 1500.0
#define MIN_FLOW_THRESHOLD 5.0
#define POLL_INTERVAL_MS 100

volatile sig_atomic_t shutdown_flag = 0;

void handle_signal(int sig) {
    shutdown_flag = 1;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c1 < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 for sensor 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c2 < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 for sensor 2\n");
        i2cClose(i2c1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        i2cClose(i2c1);
        i2cClose(i2c2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO %d low\n", RELAY_PIN);
        i2cClose(i2c1);
        i2cClose(i2c2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c1);
        i2cClose(i2c2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!shutdown_flag) {
        uint8_t cmd[2] = {START_MEASUREMENT_CMD, START_MEASUREMENT_ARG};
        if (i2cWriteDevice(i2c1, cmd, 2) < 0 || i2cWriteDevice(i2c2, cmd, 2) < 0) {
            fprintf(stderr, "Failed to send start measurement command\n");
            break;
        }

        usleep(100000); // Wait for measurement

        uint8_t data1[3], data2[3];
        if (i2cReadDevice(i2c1, data1, 3) < 0 || i2cReadDevice(i2c2, data2, 3) < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            continue;
        }

        if (crc8(data1, 2) != data1[2] || crc8(data2, 2) != data2[2]) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        int16_t flow1 = (data1[0] << 8) | data1[1];
        int16_t flow2 = (data2[0] << 8) | data2[1];
        double flow_rate1 = flow1 * SCALE_FACTOR;
        double flow_rate2 = flow2 * SCALE_FACTOR;

        struct timeval tv;
        gettimeofday(&tv, NULL);
        fprintf(log_file, "%ld.%03ld, Sensor 1: %.2f ml/min, Sensor 2: %.2f ml/min\n",
                tv.tv_sec, tv.tv_usec / 1000, flow_rate1, flow_rate2);
        fflush(log_file);

        if (flow_rate1 < MIN_FLOW_THRESHOLD || flow_rate2 < MIN_FLOW_THRESHOLD) {
            gpioWrite(RELAY_PIN, 1);
        } else {
            gpioWrite(RELAY_PIN, 0);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    gpioWrite(RELAY_PIN, 0);
    i2cClose(i2c1);
    i2cClose(i2c2);
    gpioTerminate();
    fclose(log_file);
    printf("Shutdown complete\n");

    return EXIT_SUCCESS;
}

