#define RAIN_SENSOR_GPIO 17
#define MOTOR_ENA_GPIO 22
#define MOTOR_IN1_GPIO 23
#define MOTOR_IN2_GPIO 24
#define POLL_INTERVAL_US 200000
#define MOTOR_RUN_TIME_US 5000000
#define DRY_THRESHOLD 3

volatile sig_atomic_t running = 1;

void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

void handle_signal(int sig) {
    running = 0;
}

int setup_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "Failed to initialize pigpio library");
        return -1;
    }

    if (gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT) < 0) {
        log_message(LOG_ERR, "Failed to set rain sensor GPIO mode");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP) < 0) {
        log_message(LOG_ERR, "Failed to set rain sensor pull-up");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR_ENA_GPIO, PI_OUTPUT) < 0) {
        log_message(LOG_ERR, "Failed to set motor ENA GPIO mode");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR_IN1_GPIO, PI_OUTPUT) < 0) {
        log_message(LOG_ERR, "Failed to set motor IN1 GPIO mode");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR_IN2_GPIO, PI_OUTPUT) < 0) {
        log_message(LOG_ERR, "Failed to set motor IN2 GPIO mode");
        gpioTerminate();
        return -1;
    }

    return 0;
}

void stop_motor() {
    if (gpioWrite(MOTOR_ENA_GPIO, PI_LOW) < 0) {
        log_message(LOG_WARNING, "Failed to set motor ENA LOW");
    }
    if (gpioWrite(MOTOR_IN1_GPIO, PI_LOW) < 0) {
        log_message(LOG_WARNING, "Failed to set motor IN1 LOW");
    }
    if (gpioWrite(MOTOR_IN2_GPIO, PI_LOW) < 0) {
        log_message(LOG_WARNING, "Failed to set motor IN2 LOW");
    }
}

int main() {
    openlog("rain_window", LOG_PID, LOG_USER);
    log_message(LOG_INFO, "Rain window controller started");

    if (setup_gpio() < 0) {
        closelog();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int consecutive_dry = 0;
    int last_state = gpioRead(RAIN_SENSOR_GPIO);

    while (running) {
        int current_state = gpioRead(RAIN_SENSOR_GPIO);

        if (current_state == PI_LOW && last_state == PI_HIGH) {
            log_message(LOG_INFO, "Rain detected, motor starting");
            if (gpioWrite(MOTOR_ENA_GPIO, PI_HIGH) < 0) {
                log_message(LOG_WARNING, "Failed to set motor ENA HIGH");
            }
            if (gpioWrite(MOTOR_IN1_GPIO, PI_HIGH) < 0) {
                log_message(LOG_WARNING, "Failed to set motor IN1 HIGH");
            }
            if (gpioWrite(MOTOR_IN2_GPIO, PI_LOW) < 0) {
                log_message(LOG_WARNING, "Failed to set motor IN2 LOW");
            }
            gpioDelay(MOTOR_RUN_TIME_US);
            stop_motor();
            log_message(LOG_INFO, "Motor stopped");
            consecutive_dry = 0;
        } else if (current_state == PI_HIGH) {
            consecutive_dry++;
        } else {
            consecutive_dry = 0;
        }

        last_state = current_state;

        if (consecutive_dry >= DRY_THRESHOLD) {
            log_message(LOG_INFO, "Sensor dry for 3 consecutive polls, ready for next trigger");
        }

        usleep(POLL_INTERVAL_US);
    }

    stop_motor();
    gpioTerminate();
    log_message(LOG_INFO, "Rain window controller shutting down");
    closelog();
    return EXIT_SUCCESS;
}

