#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define DEBOUNCE_DELAY 200000 // 200 ms in microseconds

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void setup_signals() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);
}

void cleanup_gpio() {
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

void lock_door() {
    if (gpioServo(SERVO_PIN, 2000) == PI_BAD_GPIO) {
        fprintf(stderr, "Failed to set servo to locked position\n");
        exit(EXIT_FAILURE);
    }
    printf("Door locked\n");
}

void unlock_door() {
    if (gpioServo(SERVO_PIN, 1000) == PI_BAD_GPIO) {
        fprintf(stderr, "Failed to set servo to unlocked position\n");
        exit(EXIT_FAILURE);
    }
    printf("Door unlocked\n");
}

int main() {
    setup_signals();
    setup_gpio();

    while (running) {
        if (gpioRead(LOCK_BUTTON_PIN) == PI_LOW) {
            lock_door();
            usleep(DEBOUNCE_DELAY);
            while (gpioRead(LOCK_BUTTON_PIN) == PI_LOW) {
                usleep(10000); // 10 ms sleep to avoid high CPU usage
            }
        }

        if (gpioRead(UNLOCK_BUTTON_PIN) == PI_LOW) {
            unlock_door();
            usleep(DEBOUNCE_DELAY);
            while (gpioRead(UNLOCK_BUTTON_PIN) == PI_LOW) {
                usleep(10000); // 10 ms sleep to avoid high CPU usage
            }
        }

        usleep(10000); // 10 ms sleep to avoid high CPU usage
    }

    cleanup_gpio();
