#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <signal.h>
#include <pthread.h>
#include <gpiod.h>
#include <time.h>
#include <stdarg.h>

#define SERVO_GPIO 17
#define PIR_GPIO 4
#define SERVO_FREQ 50
#define SERVO_MIN_US 1000
#define SERVO_MAX_US 2000
#define SERVO_RANGE_US (SERVO_MAX_US - SERVO_MIN_US)
#define SERVO_PERIOD_US (1000000 / SERVO_FREQ)
#define LOG_FILE "security.log"

static struct gpiod_chip *chip;
static struct gpiod_line *servo_line;
static struct gpiod_line *pir_line;
static int server_fd;
static FILE *log_file;
static pthread_t servo_thread;
static volatile sig_atomic_t running = 1;

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    char buffer[1024];
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    syslog(LOG_USER, "%s %s", timestamp, buffer);
    fprintf(log_file, "%s %s\n", timestamp, buffer);
    fflush(log_file);
}

void cleanup() {
    if (servo_line) {
        gpiod_line_release(servo_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    running = 0;
}

void *servo_control(void *arg) {
    while (running) {
        for (int angle = 0; angle <= 180; angle++) {
            if (!running) break;
            int pulse_width_us = SERVO_MIN_US + (angle * SERVO_RANGE_US / 180);
            gpiod_line_set_value(servo_line, 1);
            usleep(pulse_width_us);
            gpiod_line_set_value(servo_line, 0);
            usleep(SERVO_PERIOD_US - pulse_width_us);
        }
    }
    return NULL;
}

int main() {
    openlog("gpio_control", LOG_PID, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %m");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        log_message("Failed to open GPIO chip: %m");
        cleanup();
        return EXIT_FAILURE;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_GPIO);
    if (!servo_line) {
        log_message("Failed to get GPIO line %d: %m", SERVO_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(servo_line, "servo_control", 0) < 0) {
        log_message("Failed to request output on GPIO line %d: %m", SERVO_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        log_message("Failed to get GPIO line %d: %m", PIR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        log_message("Failed to request input on GPIO line %d: %m", PIR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (pthread_create(&servo_thread, NULL, servo_control, NULL) != 0) {
        log_message("Failed to create servo control thread: %m");
        cleanup();
        return EXIT_FAILURE;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message("Failed to create socket: %m");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sockaddr_in server_addr = {
        .sin_family = AF_INET,
        .sin_addr.s_addr = INADDR_ANY,
        .sin_port = htons(5000)
    };

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        log_message("Failed to bind socket: %m");
        cleanup();
        return EXIT_FAILURE;
    }

    if (listen(server_fd, 5) < 0) {
        log_message("Failed to listen on socket: %m");
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("Server started on port 5000");

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            log_message("Failed to accept connection: %m");
            break;
        }

        char buffer[1024];
        ssize_t bytes_read = read(client_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            char *command = strtok(buffer, " ");
            if (command) {
                if (strcmp(command, "SERVO") == 0) {
                    char *angle_str = strtok(NULL, " ");
                    if (angle_str) {
                        int angle = atoi(angle_str);
                        if (angle >= 0 && angle <= 180) {
                            log_message("SERVO command received: %d", angle);
                            // Implement servo control logic here
                        } else {
                            log_message("Invalid angle for SERVO command: %s", angle_str);
                        }
                    } else {
                        log_message("Missing angle for SERVO command");
                    }
                } else if (strcmp(command, "PIR") == 0) {
                    int pir_value = gpiod_line_get_value(pir_line);
                    log_message("PIR command received: PIR:%d", pir_value);
                    dprintf(client_fd, "PIR:%d\n", pir_value);
                } else {
                    log_message("Unknown command: %s", command);
                }
            }
        }

        close(client_fd);
    }

    pthread_join(servo_thread, NULL);
    cleanup();
    closelog();
    return EXIT_SUCCESS;
}

