#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define BH1750_I2C_ADDR 0x23
#define BH1750_CMD_ONE_TIME_HIGH_RES_MODE 0x20
#define RELAY_GPIO 23
#define I2C_BUS 1
#define SAMPLE_INTERVAL 2000000 // 2 seconds in microseconds
#define LUX_THRESHOLD 150.0
#define LUX_CONVERSION_FACTOR 1.2

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen("grow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%s - %s\n", asctime(tm_info), message);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for relay\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, BH1750_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (i2cWriteByte(i2c_handle, BH1750_CMD_ONE_TIME_HIGH_RES_MODE) < 0) {
            log_message("I2C write failed");
            goto next_cycle;
        }

        usleep(120000); // Wait for conversion

        unsigned char buffer[2];
        if (i2cReadDevice(i2c_handle, buffer, 2) < 0) {
            log_message("I2C read failed");
            goto next_cycle;
        }

        uint16_t raw_lux = (buffer[0] << 8) | buffer[1];
        double lux = raw_lux / LUX_CONVERSION_FACTOR;

        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Lux: %.2f", lux);
        log_message(log_message);

        if (lux < LUX_THRESHOLD) {
            gpioWrite(RELAY_GPIO, PI_HIGH);
        } else {
            gpioWrite(RELAY_GPIO, PI_LOW);
        }

next_cycle:
        usleep(SAMPLE_INTERVAL);
    }

    gpioWrite(RELAY_GPIO, PI_LOW);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

