        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%s - %s\n", asctime(tm_info), message);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for relay\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, BH1750_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (i2cWriteByte(i2c_handle, BH1750_CMD_ONE_TIME_HIGH_RES_MODE) < 0) {
            log_message("I2C write failed");
            goto next_cycle;
        }

        usleep(120000); // Wait for conversion

        unsigned char buffer[2];
        if (i2cReadDevice(i2c_handle, buffer, 2) < 0) {
            log_message("I2C read failed");
            goto next_cycle;
        }

        uint16_t raw_lux = (buffer[0] << 8) | buffer[1];
        double lux = raw_lux / LUX_CONVERSION_FACTOR;

        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Lux: %.2f", lux);
        log_message(log_message);

        if (lux < LUX_THRESHOLD) {
            gpioWrite(RELAY_GPIO, PI_HIGH);
        } else {
            gpioWrite(RELAY_GPIO, PI_LOW);
        }

next_cycle:
        usleep(SAMPLE_INTERVAL);
    }

    gpioWrite(RELAY_GPIO, PI_LOW);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}
```

This code sets up a Raspberry Pi to read from a BH1750 light sensor using the pigpio library. It triggers a relay to activate a grow light based on the lux level. The program logs the lux values and handles errors gracefully, ensuring resources are released on exit.

