#define DOUT_PIN 23
#define SCK_PIN 24
#define LOCK_PIN 25
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200
#define READINGS_PER_MEASUREMENT 5
#define TARE_READINGS 10
#define DATA_READY_TIMEOUT 1000000 // 1 second
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

void release_resources(struct gpiod_chip *chip, struct gpiod_line *dout, struct gpiod_line *sck, struct gpiod_line *lock) {
    if (lock) {
        gpiod_line_release(lock);
    }
    if (sck) {
        gpiod_line_release(sck);
    }
    if (dout) {
        gpiod_line_release(dout);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
}

int read_hx711(struct gpiod_line *dout, struct gpiod_line *sck) {
    int retries = 0;
    struct timespec timeout = {1, 0}; // 1 second

    while (retries < MAX_RETRIES) {
        if (gpiod_line_get_value(dout) == 0) {
            break;
        }
        nanosleep(&timeout, NULL);
        retries++;
    }

    if (retries == MAX_RETRIES) {
        syslog(LOG_ERR, "DOUT did not go LOW within timeout");
        return -1;
    }

    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(sck, 1);
        nanosleep(&(struct timespec){0, 1000000}, NULL); // 1 ms
        value = (value << 1) | gpiod_line_get_value(dout);
        gpiod_line_set_value(sck, 0);
        nanosleep(&(struct timespec){0, 1000000}, NULL); // 1 ms
    }

    gpiod_line_set_value(sck, 1);
    nanosleep(&(struct timespec){0, 1000000}, NULL); // 1 ms
    gpiod_line_set_value(sck, 0);

    return value;
}

int main(int argc, char *argv[]) {
    openlog("hx711_solenoid", LOG_PID | LOG_CONS, LOG_USER);

    int threshold = DEFAULT_THRESHOLD;
    double scale = DEFAULT_SCALE;
    int duration = DEFAULT_DURATION;

    static struct option long_options[] = {
        {"threshold", required_argument, 0, 't'},
        {"scale", required_argument, 0, 's'},
        {"duration", required_argument, 0, 'd'},
        {0, 0, 0, 0}
    };

    int c;
    while ((c = getopt_long(argc, argv, "t:s:d:", long_options, NULL)) != -1) {
        switch (c) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [--threshold <grams>] [--scale <factor>] [--duration <ms>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *dout = gpiod_chip_get_line(chip, DOUT_PIN);
    struct gpiod_line *sck = gpiod_chip_get_line(chip, SCK_PIN);
    struct gpiod_line *lock = gpiod_chip_get_line(chip, LOCK_PIN);

    if (!dout || !sck || !lock) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        release_resources(chip, dout, sck, lock);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(dout, "hx711_dout") < 0 ||
        gpiod_line_request_output(sck, "hx711_sck", 0) < 0 ||
        gpiod_line_request_output(lock, "solenoid_lock", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO lines");
        release_resources(chip, dout, sck, lock);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    int32_t tare_offset = 0;
    for (int i = 0; i < TARE_READINGS; i++) {
        int32_t reading = read_hx711(dout, sck);
        if (reading < 0) {
            release_resources(chip, dout, sck, lock);
            exit(EXIT_FAILURE);
        }
        tare_offset += reading;
    }
    tare_offset /= TARE_READINGS;

    while (running) {
        int32_t total = 0;
        for (int i = 0; i < READINGS_PER_MEASUREMENT; i++) {
            int32_t reading = read_hx711(dout, sck);
            if (reading < 0) {
                release_resources(chip, dout, sck, lock);
                exit(EXIT_FAILURE);
            }
            total += reading;
        }
        int32_t average_raw = total / READINGS_PER_MEASUREMENT;
        double weight = (average_raw - tare_offset) / scale;

        syslog(LOG_INFO, "Weight: %.2f grams", weight);

        if (weight > threshold) {
            gpiod_line_set_value(lock, 1);
            nanosleep(&(struct timespec){0, duration * 1000000}, NULL); // duration ms
            gpiod_line_set_value(lock, 0);
        }

        nanosleep(&(struct timespec){0, 500000000}, NULL); // 500 ms
    }

    gpiod_line_set_value(lock, 0);
    release_resources(chip, dout, sck, lock);
    closelog();

    return 0;
}

