#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_message(int priority, const char *message) {
    syslog(priority, "mqtt_relay: %s", message);
}

void on_connect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc == 0) {
        log_message(LOG_INFO, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_message(LOG_ERR, "Connection failed with code %d", rc);
    }
}

void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *msg) {
    log_message(LOG_INFO, "Received message on topic %s: %s", msg->topic, (char *)msg->payload);

    if (msg->payloadlen == 2 && strcmp((char *)msg->payload, "ON") == 0) {
        gpioWrite(GPIO_PIN, PI_HIGH);
        log_message(LOG_INFO, "Relay set to ON");
    } else if (msg->payloadlen == 3 && strcmp((char *)msg->payload, "OFF") == 0) {
        gpioWrite(GPIO_PIN, PI_LOW);
        log_message(LOG_INFO, "Relay set to OFF");
    } else {
        log_message(LOG_ERR, "Invalid payload: %s", (char *)msg->payload);
    }
}

void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc == 0) {
        log_message(LOG_INFO, "Disconnected from MQTT broker");
    } else {
        log_message(LOG_ERR, "Unexpected disconnection from MQTT broker");
    }
}

int main() {
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "Failed to initialize pigpio");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, PI_LOW);

    struct mosquitto *mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create mosquitto client");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
            log_message(LOG_ERR, "Failed to connect to MQTT broker");
            sleep(5);
            continue;
        }

        while (running) {
            int rc = mosquitto_loop(mosq, -1, 1);
            if (rc != MOSQ_ERR_SUCCESS) {
                log_message(LOG_ERR, "mosquitto_loop failed with code %d", rc);
                break;
            }
        }

        mosquitto_destroy(mosq);
        mosq = NULL;
        sleep(5);
    }

    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }

    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

