    int gpio_pins[NUM_SERVOS] = {7, 8, 9, 10, 11};
    int pulse_widths[NUM_SERVOS] = {1000, 1500, 2000, 500, 2500};

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Set PWM frequency and range for each servo
    for (int i = 0; i < NUM_SERVOS; i++) {
        gpioSetPWMfrequency(gpio_pins[i], PWM_FREQ);
        gpioSetPWMrange(gpio_pins[i], PWM_RANGE);
        gpioSetPWMwidth(gpio_pins[i], pulse_widths[i]);
    }

    // Hold the signals for 3 seconds
    gpioDelay(3000000);

    // Stop PWM and release resources
    for (int i = 0; i < NUM_SERVOS; i++) {
        gpioSetPWMwidth(gpio_pins[i], 0);
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

