    static int last_level = 0;
    if (level != last_level) {
        encoder_a_count.fetch_add(1, std::memory_order_relaxed);
        last_level = level;
    }
}

void encoder_b_callback(int gpio, int level, uint32_t tick) {
    static int last_level = 0;
    if (level != last_level) {
