        last_level = level;
    }
}

void control_loop() {
    double integral_a = 0;
    double integral_b = 0;
    auto last_time = std::chrono::high_resolution_clock::now();
    auto stall_start_a = std::chrono::high_resolution_clock::now();
    auto stall_start_b = std::chrono::high_resolution_clock::now();

    while (running) {
        auto now = std::chrono::high_resolution_clock::now();
        std::chrono::duration<double> elapsed = now - last_time;
        if (elapsed.count() * 1000 >= CONTROL_PERIOD_MS) {
            last_time = now;

            int count_a = encoder_a_count.exchange(0, std::memory_order_relaxed);
            int count_b = encoder_b_count.exchange(0, std::memory_order_relaxed);

            if (count_a == 0) {
                auto stall_elapsed = now - stall_start_a;
                if (stall_elapsed.count() * 1000 > STALL_TIMEOUT_MS) {
                    printf("Warning: Motor A stall detected!\n");
