#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/time.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define BH1750_CMD 0x21
#define RELAY_PIN 17
#define LUX_THRESHOLD_LOW 50
#define LUX_THRESHOLD_HIGH 200
#define POLL_INTERVAL 5000 // 5 seconds in milliseconds
#define BH1750_DELAY 180000 // 180 ms in microseconds

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen("chicken_coop_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fclose(log_file);
}

int read_lux(int i2c_handle) {
    if (i2cWriteByte(i2c_handle, BH1750_CMD) < 0) {
        log_message("Failed to send command to BH1750");
        return -1;
    }

    usleep(BH1750_DELAY);

    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, 0, buffer, 2) < 0) {
        log_message("Failed to read data from BH1750");
        return -1;
    }

    uint16_t raw_lux = (buffer[0] << 8) | buffer[1];
    return raw_lux / 1.2;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, PI_LOW);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int current_relay_state = PI_LOW;
    while (running) {
        int lux = read_lux(i2c_handle);
        if (lux < 0) {
            gpioWrite(RELAY_PIN, PI_LOW);
            continue;
        }

        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Lux = %d", lux);
        log_message(log_message);

        if (lux < LUX_THRESHOLD_LOW && current_relay_state == PI_LOW) {
            gpioWrite(RELAY_PIN, PI_HIGH);
            current_relay_state = PI_HIGH;
            log_message("Relay = ON");
        } else if (lux > LUX_THRESHOLD_HIGH && current_relay_state == PI_HIGH) {
            gpioWrite(RELAY_PIN, PI_LOW);
            current_relay_state = PI_LOW;
            log_message("Relay = OFF");
        }

        usleep(POLL_INTERVAL * 1000);
    }

    gpioWrite(RELAY_PIN, PI_LOW);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

