#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY 50
#define MAIN_LOOP_DELAY 10

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(RELAY_GPIO, PI_LOW);

    signal(SIGINT, handle_sigint);

    while (running) {
        if (gpioRead(TOUCH_SENSOR_GPIO) == PI_HIGH) {
            gpioDelay(DEBOUNCE_DELAY * 1000);
            if (gpioRead(TOUCH_SENSOR_GPIO) == PI_HIGH) {
                int current_state = gpioRead(RELAY_GPIO);
                gpioWrite(RELAY_GPIO, !current_state);

                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

                printf("%s Relay %s\n", timestamp, gpioRead(RELAY_GPIO) ? "ON" : "OFF");

                while (gpioRead(TOUCH_SENSOR_GPIO) == PI_HIGH) {
                    gpioDelay(MAIN_LOOP_DELAY * 1000);
                }
            }
        }
        gpioDelay(MAIN_LOOP_DELAY * 1000);
    }

    gpioWrite(RELAY_GPIO, PI_LOW);
    gpioTerminate();
    printf("Exiting gracefully\n");

    return EXIT_SUCCESS;
}

