#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define DEBOUNCE_TIMEOUT 1000

volatile unsigned int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file;

void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%s: %s\n", asctime(tm_info), message);
    fflush(log_file);
}

void gpio_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_TIMEOUT) return;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

void *flow_monitor_thread(void *arg) {
    while (1) {
        sleep(1);
        pthread_mutex_lock(&pulse_mutex);
        unsigned int current_pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = (current_pulses / PULSES_PER_LITER) * 60.0;
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "LPM: %.2f", lpm);
        log_message(log_message);

        if (lpm > LPM_THRESHOLD_HIGH) {
            gpioWrite(SOLENOID_PIN, PI_LOW);
            log_message("Solenoid closed");
