#include <arpa/inet.h>
#include <sys/socket.h>
#include <ini.h>

#define DATA_PIN 23
#define SCK_PIN 24
#define SERVO_PIN 18
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define HX711_TIMEOUT 1000
#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_hx711(int data_pin, int sck_pin) {
    int count = 0;
    int value = 0;
    gpioWrite(sck_pin, PI_LOW);
    gpioDelay(1);
    while (gpioRead(data_pin) == PI_HIGH && count < HX711_TIMEOUT) {
        count++;
    }
    if (count >= HX711_TIMEOUT) {
        fprintf(stderr, "HX711 timeout\n");
        return -1;
    }
    for (int i = 0; i < 24; i++) {
        gpioWrite(sck_pin, PI_HIGH);
        gpioDelay(1);
        value = (value << 1) | gpioRead(data_pin);
        gpioWrite(sck_pin, PI_LOW);
        gpioDelay(1);
    }
    gpioWrite(sck_pin, PI_HIGH);
    gpioDelay(1);
    gpioWrite(sck_pin, PI_LOW);
    gpioDelay(1);
    return value;
}

void log_event(const char *target_weight, const char *actual_weight, const char *error) {
    FILE *log_file = fopen("dispensing_log.json", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "{\n");
    fprintf(log_file, "  \"timestamp\": \"%s\",\n", timestamp);
    fprintf(log_file, "  \"target_weight\": \"%s\",\n", target_weight);
    fprintf(log_file, "  \"actual_weight\": \"%s\",\n", actual_weight);
    if (error) {
        fprintf(log_file, "  \"error\": \"%s\"\n", error);
    } else {
        fprintf(log_file, "  \"error\": null\n");
    }
    fprintf(log_file, "},\n");
    fclose(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    char server_ip[16] = DEFAULT_SERVER_IP;
    int server_port = DEFAULT_SERVER_PORT;
    double calibration_factor = DEFAULT_CALIBRATION_FACTOR;

    if (ini_parse("config.ini", NULL, NULL) > 0) {
        ini_gets("server", "ip", DEFAULT_SERVER_IP, server_ip, sizeof(server_ip), "config.ini");
        ini_getint("server", "port", DEFAULT_SERVER_PORT, &server_port, "config.ini");
        ini_getdouble("hx711", "calibration_factor", DEFAULT_CALIBRATION_FACTOR, &calibration_factor, "config.ini");
    }

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Socket creation failed");
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = inet_addr(server_ip);
    address.sin_port = htons(server_port);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            perror("Accept failed");
            continue;
        }

        char buffer[1024] = {0};
        int valread = read(client_fd, buffer, 1024);
        if (valread <= 0) {
            perror("Read failed");
            close(client_fd);
            continue;
        }

        double target_weight = atof(buffer);
        double target_pulse = SERVO_MIN_PULSE + (SERVO_MAX_PULSE - SERVO_MIN_PULSE) * target_weight / 1000.0;
        gpioServo(SERVO_PIN, target_pulse);
        gpioDelay(1000000);

        int actual_weight = read_hx711(DATA_PIN, SCK_PIN);
        if (actual_weight < 0) {
            log_event(buffer, "null", "HX711 read failed");
            send(client_fd, "Error: HX711 read failed", 24, 0);
        } else {
            actual_weight = (int)(actual_weight * calibration_factor);
            char response[1024];
            snprintf(response, sizeof(response), "Actual weight: %d grams", actual_weight);
            send(client_fd, response, strlen(response), 0);
            log_event(buffer, response, NULL);
        }

        gpioServo(SERVO_PIN, 0);
        close(client_fd);
    }

    gpioTerminate();
    close(server_fd);
    return 0;
}

