#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_relay_state(int state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("%s Relay: %s\n", time_str, state ? "ON" : "OFF");
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEFAULT_DEBOUNCE_MS;
    if (argc > 2 && strcmp(argv[1], "-d") == 0) {
        debounce_ms = atoi(argv[2]);
        if (debounce_ms <= 0) {
            fprintf(stderr, "Invalid debounce time: %s\n", argv[2]);
            return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, PI_LOW) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to low\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = PI_LOW;
    int current_state = PI_LOW;
    struct timespec last_change_time = {0, 0};

    while (running) {
        current_state = gpioRead(TOUCH_PIN);
        if (current_state != last_state) {
            clock_gettime(CLOCK_MONOTONIC, &last_change_time);
            last_state = current_state;
        } else {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long elapsed_ms = (now.tv_sec - last_change_time.tv_sec) * 1000 +
                             (now.tv_nsec - last_change_time.tv_nsec) / 1000000;
            if (elapsed_ms >= debounce_ms) {
                if (current_state == PI_HIGH) {
                    gpioWrite(RELAY_PIN, gpioRead(RELAY_PIN) == PI_LOW ? PI_HIGH : PI_LOW);
                    log_relay_state(gpioRead(RELAY_PIN));
                }
                last_state = PI_LOW; // Reset state after processing
            }
        }
        gpioDelay(1000); // 1 ms delay
    }

    gpioWrite(RELAY_PIN, PI_LOW);
    gpioTerminate();
    return EXIT_SUCCESS;
}

