#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define DEBOUNCE_US 2000
#define RPM_INTERVAL_US 5000000

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_event event;
    FILE *log_file = NULL;
    unsigned int pulse_count = 0;
    struct timespec last_event_time = {0};
    struct timespec current_time = {0};
    struct sigaction sa;

    // Set up signal handlers
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line as input with pull-up
    int ret = gpiod_line_request_input_flags(line, "motor_monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Failed to request GPIO line as input with pull-up");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("motor_rpm.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Wait for an event
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            perror("Failed to wait for GPIO line event");
            break;
        }

        // Read the event
        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("Failed to read GPIO line event");
            break;
        }

        // Check for rising edge
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Get current time
            clock_gettime(CLOCK_MONOTONIC, &current_time);

            // Check debounce
            if (current_time.tv_sec > last_event_time.tv_sec ||
                (current_time.tv_sec == last_event_time.tv_sec && current_time.tv_nsec - last_event_time.tv_nsec > DEBOUNCE_US * 1000)) {
                pulse_count++;
                last_event_time = current_time;
            }
        }

        // Check if it's time to compute RPM
        if (current_time.tv_sec > last_event_time.tv_sec ||
            (current_time.tv_sec == last_event_time.tv_sec && current_time.tv_nsec - last_event_time.tv_nsec > RPM_INTERVAL_US)) {
            double rpm = (pulse_count / 5.0) * 60.0;
            char timestamp[30];
            struct tm *tm_info;

            // Get current time for timestamp
            clock_gettime(CLOCK_REALTIME, &current_time);
            tm_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

            // Log RPM
            fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
            fflush(log_file);

            // Print RPM to stdout
            printf("Current RPM: %.2f\n", rpm);

            // Reset pulse count
            pulse_count = 0;
        }
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

