#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17
#define POLL_INTERVAL_US 50000
#define FAILSAFE_TIMEOUT_US 10000000

volatile sig_atomic_t exit_flag = 0;

void signal_handler(int signum) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, PI_LOW) < 0) {
        fprintf(stderr, "Failed to set initial state for GPIO %d\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int relay_state = PI_LOW;
    struct timespec last_touch_time;
    clock_gettime(CLOCK_MONOTONIC, &last_touch_time);

    while (!exit_flag) {
        int touch_state = gpioRead(TOUCH_SENSOR_GPIO);
        if (touch_state == PI_BAD_GPIO) {
            fprintf(stderr, "Failed to read GPIO %d\n", TOUCH_SENSOR_GPIO);
            break;
        }

        if (touch_state == PI_HIGH) {
            struct timespec current_time;
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            long elapsed_time = (current_time.tv_sec - last_touch_time.tv_sec) * 1000000 +
                               (current_time.tv_nsec - last_touch_time.tv_nsec) / 1000;

            if (elapsed_time > FAILSAFE_TIMEOUT_US) {
                if (gpioWrite(RELAY_GPIO, PI_LOW) < 0) {
                    fprintf(stderr, "Failed to set GPIO %d to LOW\n", RELAY_GPIO);
                    break;
                }
                relay_state = PI_LOW;
            } else if (elapsed_time > POLL_INTERVAL_US) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
                    fprintf(stderr, "Failed to toggle GPIO %d\n", RELAY_GPIO);
                    break;
                }
                clock_gettime(CLOCK_MONOTONIC, &last_touch_time);
            }
        } else {
            clock_gettime(CLOCK_MONOTONIC, &last_touch_time);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    if (gpioWrite(RELAY_GPIO, PI_LOW) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to LOW\n", RELAY_GPIO);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

