#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>

#define PWM_PIN 18
#define ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24
#define PULSE_PER_LITER 450
#define SAMPLE_INTERVAL_MS 100
#define Kp 1.0

volatile int pulse_count = 0;
int target_flow_rate = 0;
FILE *log_file = NULL;
int running = 1;

void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

void signal_handler(int signum) {
    running = 0;
}

void log_data(uint32_t timestamp_ms, double flow_rate, int valve_position) {
    fprintf(log_file, "%u,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
    fflush(log_file);
}

int main(int argc, char *argv[]) {
    if (argc != 3 || strcmp(argv[1], "-t") != 0) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
        return EXIT_FAILURE;
    }

    target_flow_rate = atoi(argv[2]);
    if (target_flow_rate <= 0) {
        fprintf(stderr, "Invalid target flow rate: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ENABLE_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "GPIO mode setup failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISR(FLOW_SENSOR_PIN, RISING_EDGE, pulse_callback) < 0) {
        fprintf(stderr, "ISR registration failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(ENABLE_PIN, PI_HIGH);

    log_file = fopen("flow_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp_ms,flow_rate,valve_position\n");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint32_t start_time = gpioTick();
        while (gpioTick() - start_time < SAMPLE_INTERVAL_MS) {
            time_usleep(1000);
        }

        int current_pulses = pulse_count;
        pulse_count = 0;

        double flow_rate = (current_pulses / PULSE_PER_LITER) * (1000.0 / SAMPLE_INTERVAL_MS) * 60.0;
        int valve_position = (int)(Kp * (target_flow_rate - flow_rate));
        if (valve_position < 0) valve_position = 0;
        if (valve_position > 255) valve_position = 255;

        gpioPWM(PWM_PIN, valve_position);

        uint32_t timestamp_ms = gpioTick() / 1000;
        log_data(timestamp_ms, flow_rate, valve_position);
    }

    gpioPWM(PWM_PIN, 0);
    gpioWrite(ENABLE_PIN, PI_LOW);
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

