#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>
#include <math.h>

#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SAMPLE_TIME 0.1
#define TARGET_RPM 60
#define PWM_FREQ 100
#define PWM_PERIOD (1.0 / PWM_FREQ)
#define ENCODER_PULSES_PER_REV 600

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    pthread_mutex_t mutex;
    int count;
} Encoder;

typedef struct {
    Encoder *encoder;
    struct gpiod_line *ena;
    struct gpiod_line *in1;
    struct gpiod_line *in2;
    double setpoint;
    double integral;
    double prev_error;
    double prev_time;
} Motor;

Encoder encoder1, encoder2;
Motor motor1, motor2;
FILE *log_file;
volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void *encoder_thread(void *arg) {
    Encoder *encoder = (Encoder *)arg;
    struct gpiod_line_event event;
    int b_pin_value;

    while (running) {
        if (gpiod_line_event_wait(encoder->line, NULL) < 0) {
            perror("gpiod_line_event_wait");
            continue;
        }

        if (gpiod_line_event_read(encoder->line, &event) < 0) {
            perror("gpiod_line_event_read");
            continue;
        }

        pthread_mutex_lock(&encoder->mutex);
        b_pin_value = gpiod_line_get_value(encoder->line->chip, encoder->line->offset + 1);
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            encoder->count += b_pin_value ? -1 : 1;
        } else {
            encoder->count += b_pin_value ? 1 : -1;
        }
        pthread_mutex_unlock(&encoder->mutex);
    }

    return NULL;
}

double calculate_rpm(Encoder *encoder, double elapsed_time) {
    pthread_mutex_lock(&encoder->mutex);
    int pulses = encoder->count;
    encoder->count = 0;
    pthread_mutex_unlock(&encoder->mutex);

    return (pulses / ENCODER_PULSES_PER_REV) * (60 / elapsed_time);
}

void control_loop() {
    struct timespec start_time, current_time;
    double elapsed_time;
    double error, p_term, i_term, d_term, pid_output;
    double motor1_rpm, motor2_rpm;

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;
        if (elapsed_time < SAMPLE_TIME) {
            continue;
        }

        motor1_rpm = calculate_rpm(&encoder1, elapsed_time);
        motor2_rpm = calculate_rpm(&encoder2, elapsed_time);

        error = TARGET_RPM - motor1_rpm;
        p_term = KP * error;
        motor1.integral += error * elapsed_time;
        i_term = KI * motor1.integral;
        d_term = KD * (error - motor1.prev_error) / elapsed_time;
        pid_output = p_term + i_term + d_term;
        motor1.prev_error = error;
        motor1.prev_time = current_time.tv_sec + current_time.tv_nsec / 1e9;

        error = TARGET_RPM - motor2_rpm;
        p_term = KP * error;
        motor2.integral += error * elapsed_time;
        i_term = KI * motor2.integral;
        d_term = KD * (error - motor2.prev_error) / elapsed_time;
        pid_output = p_term + i_term + d_term;
        motor2.prev_error = error;
        motor2.prev_time = current_time.tv_sec + current_time.tv_nsec / 1e9;

        // Apply PID output to motor duty cycle
        // This is a placeholder for actual PWM implementation
        // You need to implement software PWM using libgpiod line toggling

        fprintf(log_file, "%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                motor1_rpm, motor1.prev_error, motor1.integral, motor1.prev_error * elapsed_time, pid_output,
                motor2_rpm, motor2.prev_error, motor2.integral, motor2.prev_error * elapsed_time, pid_output);
        fflush(log_file);

        start_time = current_time;
    }
}

int main() {
    struct sigaction sa;
    pthread_t encoder1_thread, encoder2_thread;

    // Initialize signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open GPIO chips
    encoder1.chip = gpiod_chip_open("/dev/gpiochip0");
    encoder2.chip = gpiod_chip_open("/dev/gpiochip0");
    motor1.chip = gpiod_chip_open("/dev/gpiochip0");
    motor2.chip = gpiod_chip_open("/dev/gpiochip0");
    if (!encoder1.chip || !encoder2.chip || !motor1.chip || !motor2.chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    encoder1.line = gpiod_chip_get_line(encoder1.chip, ENCODER1_A);
    encoder2.line = gpiod_chip_get_line(encoder2.chip, ENCODER2_A);
    motor1.ena = gpiod_chip_get_line(motor1.chip, MOTOR1_ENA);
    motor1.in1 = gpiod_chip_get_line(motor1.chip, MOTOR1_IN1);
    motor1.in2 = gpiod_chip_get_line(motor1.chip, MOTOR1_IN2);
    motor2.ena = gpiod_chip_get_line(motor2.chip, MOTOR2_ENB);
    motor2.in3 = gpiod_chip_get_line(motor2.chip, MOTOR2_IN3);
    motor2.in4 = gpiod_chip_get_line(motor2.chip, MOTOR2_IN4);
    if (!encoder1.line || !encoder2.line || !motor1.ena || !motor1.in1 || !motor1.in2 || !motor2.ena || !motor2.in3 || !motor2.in4) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    // Configure GPIO lines
    if (gpiod_line_request_input(encoder1.line, "encoder1") < 0 ||
        gpiod_line_request_input(encoder2.line, "encoder2") < 0 ||
        gpiod_line_request_output(motor1.ena, "motor1_ena") < 0 ||
        gpiod_line_request_output(motor1.in1, "motor1_in1") < 0 ||
        gpiod_line_request_output(motor1.in2, "motor1_in2") < 0 ||
        gpiod_line_request_output(motor2.ena, "motor2_enb") < 0 ||
        gpiod_line_request_output(motor2.in3, "motor2_in3") < 0 ||
        gpiod_line_request_output(motor2.in4, "motor2_in4") < 0) {
        perror("gpiod_line_request");
        return EXIT_FAILURE;
    }

    // Set up edge events
    if (gpiod_line_event_request_both_edges(encoder1.line) < 0 ||
        gpiod_line_event_request_both_edges(encoder2.line) < 0) {
        perror("gpiod_line_event_request");
        return EXIT_FAILURE;
    }

    // Initialize encoder counts and mutexes
    encoder1.count = 0;
    encoder2.count = 0;
    pthread_mutex_init(&encoder1.mutex, NULL);
    pthread_mutex_init(&encoder2.mutex, NULL);

    // Open log file
    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Motor1_RPM,Motor1_Error,Motor1_Integral,Motor1_Derivative,Motor1_PID_Output,"
            "Motor2_RPM,Motor2_Error,Motor2_Integral,Motor2_Derivative,Motor2_PID_Output\n");
    fflush(log_file);

    // Start encoder threads
    if (pthread_create(&encoder1_thread, NULL, encoder_thread, &encoder1) < 0 ||
        pthread_create(&encoder2_thread, NULL, encoder_thread, &encoder2) < 0) {
        perror("pthread_create");
        return EXIT_FAILURE;
    }

    // Start control loop
    control_loop();

    // Clean up
    pthread_join(encoder1_thread, NULL);
    pthread_join(encoder2_thread, NULL);
    pthread_mutex_destroy(&encoder1.mutex);
    pthread_mutex_destroy(&encoder2.mutex);
    fclose(log_file);
    gpiod_line_release(encoder1.line);
    gpiod_line_release(encoder2.line);
    gpiod_line_release(motor1.ena);
    gpiod_line_release(motor1.in1);
    gpiod_line_release(motor1.in2);
    gpiod_line_release(motor2.ena);
    gpiod_line_release(motor2.in3);
    gpiod_line_release(motor2.in4);
    gpiod_chip_close(encoder1.chip);
    gpiod_chip_close(encoder2.chip);
    gpiod_chip_close(motor1.chip);
    gpiod_chip_close(motor2.chip);

    return EXIT_SUCCESS;
}

