        gpiod_line_request_input(encoder2.line, "encoder2") < 0 ||
        gpiod_line_request_output(motor1.ena, "motor1_ena") < 0 ||
        gpiod_line_request_output(motor1.in1, "motor1_in1") < 0 ||
        gpiod_line_request_output(motor1.in2, "motor1_in2") < 0 ||
        gpiod_line_request_output(motor2.ena, "motor2_enb") < 0 ||
        gpiod_line_request_output(motor2.in3, "motor2_in3") < 0 ||
        gpiod_line_request_output(motor2.in4, "motor2_in4") < 0) {
        perror("gpiod_line_request");
        return EXIT_FAILURE;
    }

    // Set up edge events
    if (gpiod_line_event_request_both_edges(encoder1.line) < 0 ||
        gpiod_line_event_request_both_edges(encoder2.line) < 0) {
        perror("gpiod_line_event_request");
        return EXIT_FAILURE;
    }

    // Initialize encoder counts and mutexes
    encoder1.count = 0;
    encoder2.count = 0;
    pthread_mutex_init(&encoder1.mutex, NULL);
    pthread_mutex_init(&encoder2.mutex, NULL);

    // Open log file
    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Motor1_RPM,Motor1_Error,Motor1_Integral,Motor1_Derivative,Motor1_PID_Output,"
            "Motor2_RPM,Motor2_Error,Motor2_Integral,Motor2_Derivative,Motor2_PID_Output\n");
    fflush(log_file);

    // Start encoder threads
    if (pthread_create(&encoder1_thread, NULL, encoder_thread, &encoder1) < 0 ||
        pthread_create(&encoder2_thread, NULL, encoder_thread, &encoder2) < 0) {
        perror("pthread_create");
        return EXIT_FAILURE;
    }

    // Start control loop
    control_loop();

    // Clean up
    pthread_join(encoder1_thread, NULL);
    pthread_join(encoder2_thread, NULL);
    pthread_mutex_destroy(&encoder1.mutex);
    pthread_mutex_destroy(&encoder2.mutex);
    fclose(log_file);
    gpiod_line_release(encoder1.line);
    gpiod_line_release(encoder2.line);
    gpiod_line_release(motor1.ena);
    gpiod_line_release(motor1.in1);
    gpiod_line_release(motor1.in2);
    gpiod_line_release(motor2.ena);
    gpiod_line_release(motor2.in3);
    gpiod_line_release(motor2.in4);
    gpiod_chip_close(encoder1.chip);
    gpiod_chip_close(encoder2.chip);
    gpiod_chip_close(motor1.chip);
    gpiod_chip_close(motor2.chip);

    return EXIT_SUCCESS;
}
