#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define RELAY_PIN 17

#define MPR121_SOFT_RESET 0x80
#define MPR121_ECR 0x5E
#define MPR121_TOUCH_STATUS_0 0x00
#define MPR121_TOUCH_STATUS_1 0x01
#define MPR121_FILTER_CFG 0x5D
#define MPR121_TOUCH_THRESHOLD 0x41
#define MPR121_RELEASE_THRESHOLD 0x4B

#define NUM_ELECTRODES 12

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_relay_state(int state) {
    FILE *log_file = fopen("relay_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s - Relay state: %s\n", timestamp, state ? "ON" : "OFF");
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for relay\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // MPR121 initialization sequence
    if (i2cWriteByteData(i2c_handle, MPR121_SOFT_RESET, 0x63) < 0) {
        fprintf(stderr, "Failed to soft reset MPR121\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    usleep(10000); // Wait for reset to complete

    if (i2cWriteByteData(i2c_handle, MPR121_FILTER_CFG, 0x0F) < 0) {
        fprintf(stderr, "Failed to configure filtering\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCH_THRESHOLD + i, 0x40) < 0 ||
            i2cWriteByteData(i2c_handle, MPR121_RELEASE_THRESHOLD + i, 0x20) < 0) {
            fprintf(stderr, "Failed to set touch/release thresholds for electrode %d\n", i);
            i2cClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x8F) < 0) {
        fprintf(stderr, "Failed to enable run mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    int last_relay_state = 0;

    while (running) {
        uint8_t status[2];
        if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCH_STATUS_0, status, 2) < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            continue;
        }

        int current_relay_state = 0;
        for (int i = 0; i < NUM_ELECTRODES; i++) {
            if (status[i / 8] & (1 << (i % 8))) {
                current_relay_state = 1;
                break;
            }
        }

        if (current_relay_state != last_relay_state) {
            gpioWrite(RELAY_PIN, current_relay_state);
            log_relay_state(current_relay_state);
            last_relay_state = current_relay_state;
        }

        usleep(50000); // 50 ms delay
    }

    gpioWrite(RELAY_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

