#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define VALVE1_PIN 17
#define VALVE2_PIN 18
#define LOG_FILE "valve_log.txt"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;
static FILE *log_file = NULL;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "[%s] %s\n", timestamp, event);
    fflush(log_file);
}

void cleanup() {
    if (valve1_line) {
        gpiod_line_release(valve1_line);
        valve1_line = NULL;
    }
    if (valve2_line) {
        gpiod_line_release(valve2_line);
        valve2_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_PIN);
    if (!valve1_line) {
        perror("Failed to get GPIO line for Valve 1");
        cleanup();
        return EXIT_FAILURE;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE2_PIN);
    if (!valve2_line) {
        perror("Failed to get GPIO line for Valve 2");
        cleanup();
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_output(valve1_line, "valve1", 0);
    if (ret < 0) {
        perror("Failed to request output for Valve 1");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(valve2_line, "valve2", 0);
    if (ret < 0) {
        perror("Failed to request output for Valve 2");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        gpiod_line_set_value(valve1_line, 1);
        log_event("Valve 1 activated");
        usleep(500000); // 500 ms
        gpiod_line_set_value(valve1_line, 0);
        log_event("Valve 1 deactivated");
        sleep(5); // 5 seconds

        gpiod_line_set_value(valve2_line, 1);
        log_event("Valve 2 activated");
        usleep(1000000); // 1000 ms
        gpiod_line_set_value(valve2_line, 0);
        log_event("Valve 2 deactivated");
        sleep(10); // 10 seconds
    }

    cleanup();
    return EXIT_SUCCESS;
}

