#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define RELAY_PIN 17

#define TOUCH_THRESHOLD 0x10
#define RELEASE_THRESHOLD 0x0A
#define FILTER_CHARGE_TIME 0x20
#define ELE_CURRENT 0x01

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin mode\n");
        gpioTerminate();
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    gpioWrite(RELAY_PIN, PI_LOW);

    uint8_t data[2];
    data[0] = 0x80 | 0x5E; // Stop mode
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to write to MPR121");
        gpioTerminate();
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    data[0] = 0x80 | 0x5D; // Run mode with ELE_EN=1
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to write to MPR121");
        gpioTerminate();
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    data[0] = 0x00; // Touch threshold
    data[1] = TOUCH_THRESHOLD;
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to write to MPR121");
        gpioTerminate();
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    data[0] = 0x01; // Release threshold
    data[1] = RELEASE_THRESHOLD;
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to write to MPR121");
        gpioTerminate();
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    data[0] = 0x20; // Filter/charge time
    data[1] = FILTER_CHARGE_TIME;
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to write to MPR121");
        gpioTerminate();
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    data[0] = 0x01; // Electrode current
    data[1] = ELE_CURRENT;
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to write to MPR121");
        gpioTerminate();
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    usleep(100000); // Wait for stabilization

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        data[0] = 0x00; // Touch status registers
        if (write(i2c_fd, data, 1) != 1) {
            perror("Failed to write to MPR121");
            break;
        }

        if (read(i2c_fd, data, 2) != 2) {
            perror("Failed to read from MPR121");
            break;
        }

        uint16_t touch_status = (data[0] << 8) | data[1];
        if (touch_status > 0) {
            gpioWrite(RELAY_PIN, gpioRead(RELAY_PIN) == PI_LOW ? PI_HIGH : PI_LOW);
            printf("Touch detected, relay toggled\n");
        }

        usleep(100000); // 100 ms delay
    }

    gpioTerminate();
    close(i2c_fd);
    return EXIT_SUCCESS;
}

