#define RATE_LIMIT 2000

volatile sig_atomic_t running = 1;
FILE *log_file = NULL;
time_t last_event_time = 0;

void log_event(const char *event) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%.3f - %s\n", ts.tv_sec + ts.tv_nsec / 1e9, event);
    fflush(log_file);
}

void handle_sigint(int sig) {
    running = 0;
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    gpioWrite(RELAY_GPIO, PI_LOW);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    atexit(cleanup);
    signal(SIGINT, handle_sigint);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, PI_LOW);

    while (running) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long current_time = ts.tv_sec * 1000 + ts.tv_nsec / 1e6;

        if (gpioRead(PIR_GPIO) == PI_HIGH) {
            long time_since_last_event = current_time - last_event_time;
            if (time_since_last_event > RATE_LIMIT) {
                log_event("Motion detected");
                gpioWrite(RELAY_GPIO, PI_HIGH);
                log_event("Door unlocked");
                gpioDelay(RELAY_DURATION);
                gpioWrite(RELAY_GPIO, PI_LOW);
                last_event_time = current_time;
            } else {
                log_event("Rate-limited: Motion detected");
            }
        }

        gpioDelay(50000); // 50 ms delay
    }

    return 0;
}

