#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define DATA_PIN 4
#define CLOCK_PIN 17
#define LOCK_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define DEFAULT_SCALE 1.0
#define DEFAULT_OFFSET 0.0
#define STARTUP_READINGS 100
#define READ_INTERVAL 500
#define TIMEOUT 500000
#define THRESHOLD 10.0

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

double read_hx711() {
    uint32_t count = 0;
    gpioWrite(CLOCK_PIN, PI_LOW);
    gpioDelay(1);
    while (gpioRead(DATA_PIN) == PI_HIGH) {
        if (count++ > TIMEOUT) {
            return -1.0; // Timeout
        }
    }
    for (int i = 0; i < 24; i++) {
        gpioDelay(1);
        gpioWrite(CLOCK_PIN, PI_HIGH);
        gpioDelay(1);
        count = (count << 1) | gpioRead(DATA_PIN);
        gpioWrite(CLOCK_PIN, PI_LOW);
    }
    gpioDelay(1);
    gpioWrite(CLOCK_PIN, PI_HIGH);
    gpioDelay(1);
    gpioWrite(CLOCK_PIN, PI_LOW);
    return (count & 0x7FFFFF) - (count & 0x800000);
}

void load_calibration(double *scale, double *offset) {
    FILE *file = fopen(CALIBRATION_FILE, "r");
    if (file) {
        if (fscanf(file, "%lf %lf", scale, offset) != 2) {
            *scale = DEFAULT_SCALE;
            *offset = DEFAULT_OFFSET;
        }
        fclose(file);
    } else {
        *scale = DEFAULT_SCALE;
        *offset = DEFAULT_OFFSET;
    }
}

void save_calibration(double scale, double offset) {
    FILE *file = fopen(CALIBRATION_FILE, "w");
    if (file) {
        fprintf(file, "%lf %lf\n", scale, offset);
        fclose(file);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_PIN, PI_OUTPUT);

    double scale = DEFAULT_SCALE;
    double offset = DEFAULT_OFFSET;
    load_calibration(&scale, &offset);

    double total_offset = 0.0;
    for (int i = 0; i < STARTUP_READINGS; i++) {
        double reading = read_hx711();
        if (reading != -1.0) {
            total_offset += reading;
        }
        gpioDelay(READ_INTERVAL);
    }
    offset = total_offset / STARTUP_READINGS;
    save_calibration(scale, offset);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        double reading = read_hx711();
        if (reading != -1.0) {
            double weight = (reading - offset) * scale;
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log_file, "%s: Raw=%lf, Weight=%lf\n", timestamp, reading, weight);
            fflush(log_file);

            if (weight > THRESHOLD) {
                gpioWrite(LOCK_PIN, PI_HIGH);
            } else {
                gpioWrite(LOCK_PIN, PI_LOW);
            }
        }
        gpioDelay(READ_INTERVAL);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

