#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_GPIO 4
#define MOTOR_IN1_GPIO 17
#define MOTOR_IN2_GPIO 18
#define MOTOR_PWM_GPIO 27
#define DEBOUNCE_DELAY 50
#define DEBOUNCE_COUNT 5
#define RAIN_THRESHOLD 3
#define MOTOR_FREQ 1000
#define MOTOR_DUTY 150
#define MOTOR_RUN_TIME 5000
#define CHECK_INTERVAL 60000
#define LOG_FILE "/var/log/window_control.log"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_event(const char *message) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "%s", message);
    closelog();
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RAIN_SENSOR_GPIO);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(MOTOR_IN1_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_IN1_GPIO);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(MOTOR_IN2_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_IN2_GPIO);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(MOTOR_PWM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_PWM_GPIO);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioSetPWMfrequency(MOTOR_PWM_GPIO, MOTOR_FREQ);
}

void close_window() {
    gpioWrite(MOTOR_IN1_GPIO, 1);
    gpioWrite(MOTOR_IN2_GPIO, 0);
    gpioPWM(MOTOR_PWM_GPIO, MOTOR_DUTY);
    usleep(MOTOR_RUN_TIME);
    gpioWrite(MOTOR_IN1_GPIO, 0);
    gpioWrite(MOTOR_IN2_GPIO, 0);
    gpioPWM(MOTOR_PWM_GPIO, 0);
    log_event("Window closed");
}

int detect_rain() {
    int rain_count = 0;
    for (int i = 0; i < DEBOUNCE_COUNT; i++) {
        if (gpioRead(RAIN_SENSOR_GPIO) == PI_LOW) {
            rain_count++;
        }
        usleep(DEBOUNCE_DELAY * 1000);
    }
    return rain_count >= RAIN_THRESHOLD;
}

void cleanup() {
    gpioWrite(MOTOR_IN1_GPIO, 0);
    gpioWrite(MOTOR_IN2_GPIO, 0);
    gpioPWM(MOTOR_PWM_GPIO, 0);
    gpioTerminate();
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();

    while (running) {
        if (detect_rain()) {
            close_window();
            log_event("Rain detected and window closed");
            usleep(CHECK_INTERVAL * 1000);
        } else {
            usleep(CHECK_INTERVAL * 1000);
        }
    }

    cleanup();
    return 0;
}

