    gpioWrite(MOTOR_IN2_GPIO, 0);
    gpioPWM(MOTOR_PWM_GPIO, MOTOR_DUTY);
    usleep(MOTOR_RUN_TIME);
    gpioWrite(MOTOR_IN1_GPIO, 0);
    gpioWrite(MOTOR_IN2_GPIO, 0);
    gpioPWM(MOTOR_PWM_GPIO, 0);
    log_event("Window closed");
}

int detect_rain() {
    int rain_count = 0;
    for (int i = 0; i < DEBOUNCE_COUNT; i++) {
        if (gpioRead(RAIN_SENSOR_GPIO) == PI_LOW) {
            rain_count++;
        }
        usleep(DEBOUNCE_DELAY * 1000);
    }
    return rain_count >= RAIN_THRESHOLD;
}

void cleanup() {
    gpioWrite(MOTOR_IN1_GPIO, 0);
    gpioWrite(MOTOR_IN2_GPIO, 0);
    gpioPWM(MOTOR_PWM_GPIO, 0);
    gpioTerminate();
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();

    while (running) {
        if (detect_rain()) {
            close_window();
            log_event("Rain detected and window closed");
            usleep(CHECK_INTERVAL * 1000);
        } else {
            usleep(CHECK_INTERVAL * 1000);
        }
    }

    cleanup();
    return 0;
}
```

