#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define DATA_PIN 4
#define CLOCK_PIN 17
#define LOCK_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define TIMEOUT_US 100000
#define LOCK_DURATION_US 5000000

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void unlock_solenoid() {
    gpioWrite(LOCK_PIN, PI_LOW);
}

void cleanup() {
    gpioTerminate();
    unlock_solenoid();
}

int read_hx711() {
    int data = 0;
    gpioWrite(CLOCK_PIN, PI_LOW);
    usleep(1);
    while (gpioRead(DATA_PIN) == PI_HIGH) {
        if (gpioTick() - gpioTick() > TIMEOUT_US) {
            fprintf(stderr, "HX711 communication timeout\n");
            return -1;
        }
    }
    for (int i = 0; i < 24; i++) {
        gpioWrite(CLOCK_PIN, PI_HIGH);
        usleep(1);
        data = (data << 1) | gpioRead(DATA_PIN);
        gpioWrite(CLOCK_PIN, PI_LOW);
        usleep(1);
    }
    gpioWrite(CLOCK_PIN, PI_HIGH);
    usleep(1);
    gpioWrite(CLOCK_PIN, PI_LOW);
    return data;
}

double read_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        perror("Failed to open calibration file");
        return -1;
    }
    double calibration_factor;
    if (fscanf(fp, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Failed to read calibration factor\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return calibration_factor;
}

void write_calibration(double calibration_factor) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        perror("Failed to open calibration file for writing");
        return;
    }
    if (fprintf(fp, "%.10f\n", calibration_factor) < 0) {
        perror("Failed to write calibration factor");
    }
    fclose(fp);
}

void log_event(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    if (fprintf(fp, "%s: Weight exceeded 5.0 kg: %.2f kg\n", timestamp, weight) < 0) {
        perror("Failed to write to log file");
    }
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }
    atexit(cleanup);
    signal(SIGINT, sigint_handler);

    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_PIN, PI_OUTPUT);
    gpioWrite(LOCK_PIN, PI_LOW);

    double calibration_factor = read_calibration();
    if (calibration_factor < 0) {
        printf("Enter known weight in kilograms: ");
        double known_weight;
        if (scanf("%lf", &known_weight) != 1) {
            fprintf(stderr, "Invalid input for known weight\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }
        int raw_value = read_hx711();
        if (raw_value < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
        calibration_factor = (double)raw_value / known_weight;
        write_calibration(calibration_factor);
    }

    while (running) {
        int raw_value = read_hx711();
        if (raw_value < 0) {
            continue;
        }
        double weight = (double)raw_value * calibration_factor;
        if (weight > 5.0) {
            log_event(weight);
            gpioWrite(LOCK_PIN, PI_HIGH);
            usleep(LOCK_DURATION_US);
            gpioWrite(LOCK_PIN, PI_LOW);
        }
    }

    return EXIT_SUCCESS;
}

