#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_LINE 16
#define RELAY_LINE 20
#define CHIP_NAME "gpiochip0"
#define LOG_FILE "relay_events.log"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_event(const char *state) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log, "%s - Relay state: %s\n", timestamp, state);
    fclose(log);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line, *relay_line;
    struct gpiod_line_bulk sensor_bulk, relay_bulk;
    int sensor_value, relay_value = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get sensor and relay lines
    sensor_line = gpiod_chip_get_line(chip, SENSOR_LINE);
    relay_line = gpiod_chip_get_line(chip, RELAY_LINE);
    if (!sensor_line || !relay_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request sensor line as input
    if (gpiod_line_request_input(sensor_line, "ir_sensor") < 0) {
        perror("Failed to request sensor line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request relay line as output
    if (gpiod_line_request_output(relay_line, "relay", relay_value) < 0) {
        perror("Failed to request relay line as output");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Add lines to bulk
    gpiod_line_bulk_add(&sensor_bulk, 1, sensor_line);
    gpiod_line_bulk_add(&relay_bulk, 1, relay_line);

    while (running) {
        // Read sensor value
        if (gpiod_line_get_value_bulk(&sensor_bulk, &sensor_value) < 0) {
            perror("Failed to read sensor value");
            break;
        }

        // Check for obstacle
        if (sensor_value == 0) { // Active-low sensor
            // Toggle relay state
            relay_value = !relay_value;
            if (gpiod_line_set_value_bulk(&relay_bulk, relay_value) < 0) {
                perror("Failed to set relay value");
                break;
            }

            // Log event
            log_event(relay_value ? "ON" : "OFF");
        }

        // Sleep for a short period
        usleep(100000); // 100 ms
    }

    // Release resources
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

