#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define CONFIG_FILE "watering.conf"

volatile sig_atomic_t sigint_received = 0;

void signal_handler(int signum) {
    sigint_received = 1;
}

int parse_duration(const char *line, int *duration) {
    if (sscanf(line, "duration=%d", duration) != 1 || *duration < 1 || *duration > 3600) {
        return -1;
    }
    return 0;
}

void release_resources(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int duration = 0;
    FILE *config_file = NULL;
    char line_buffer[256];
    struct sigaction sa;

    // Set up signal handlers
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        release_resources(chip, NULL);
        return EXIT_FAILURE;
    }

    // Request the line as an output
    if (gpiod_line_request_output(line, "watering_system", 0) < 0) {
        perror("gpiod_line_request_output");
        release_resources(chip, line);
        return EXIT_FAILURE;
    }

    // Read the duration from the configuration file
    config_file = fopen(CONFIG_FILE, "r");
    if (!config_file) {
        perror("fopen");
        release_resources(chip, line);
        return EXIT_FAILURE;
    }

    if (fgets(line_buffer, sizeof(line_buffer), config_file) == NULL) {
        fprintf(stderr, "Error: Empty configuration file or read error.\n");
        fclose(config_file);
        release_resources(chip, line);
        return EXIT_FAILURE;
    }

    fclose(config_file);

    if (parse_duration(line_buffer, &duration) < 0) {
        fprintf(stderr, "Error: Malformed or out-of-range duration in configuration file.\n");
        release_resources(chip, line);
        return EXIT_FAILURE;
    }

    printf("Configured duration: %d seconds\n", duration);

    // Activate the valve
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value");
        release_resources(chip, line);
        return EXIT_FAILURE;
    }

    printf("Valve turned on\n");

    // Wait for the configured duration
    struct timespec ts;
    ts.tv_sec = duration;
    ts.tv_nsec = 0;

    while (ts.tv_sec > 0 || ts.tv_nsec > 0) {
        if (nanosleep(&ts, &ts) == -1 && errno != EINTR) {
            perror("nanosleep");
            break;
        }
        if (sigint_received) {
            break;
        }
    }

    // Turn off the valve
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value");
    } else {
        printf("Valve turned off\n");
    }

    // Release resources
    release_resources(chip, line);

    if (sigint_received) {
        printf("Interrupted by signal\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

