#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27
#define LEFT_MOTOR_FORWARD 22
#define LEFT_MOTOR_BACKWARD 23
#define RIGHT_MOTOR_FORWARD 24
#define RIGHT_MOTOR_BACKWARD 25
#define BASE_SPEED 150
#define PWM_FREQUENCY 1000
#define LOG_FILE "trace_log.txt"
#define SAMPLE_INTERVAL 10000 // 10 ms

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_cycle(FILE *log, int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts));
    fprintf(log, "%s,%d,%d,%d,%d,%d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
    fflush(log);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_SENSOR, PI_INPUT) < 0 ||
        gpioSetMode(MIDDLE_SENSOR, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_SENSOR, PI_INPUT) < 0 ||
        gpioSetMode(LEFT_MOTOR_FORWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(LEFT_MOTOR_BACKWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(RIGHT_MOTOR_FORWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(RIGHT_MOTOR_BACKWARD, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO mode setting failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(LEFT_MOTOR_FORWARD, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(LEFT_MOTOR_BACKWARD, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RIGHT_MOTOR_FORWARD, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RIGHT_MOTOR_BACKWARD, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "PWM frequency setting failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int left_sensor = gpioRead(LEFT_SENSOR);
        int middle_sensor = gpioRead(MIDDLE_SENSOR);
        int right_sensor = gpioRead(RIGHT_SENSOR);

        int left_speed = 0;
        int right_speed = 0;

        if (middle_sensor == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left_sensor == 0) {
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (right_sensor == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        }

        gpioPWM(LEFT_MOTOR_FORWARD, left_speed);
        gpioPWM(LEFT_MOTOR_BACKWARD, 0);
        gpioPWM(RIGHT_MOTOR_FORWARD, right_speed);
        gpioPWM(RIGHT_MOTOR_BACKWARD, 0);

        log_cycle(log, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        gpioDelay(SAMPLE_INTERVAL);
    }

    gpioPWM(LEFT_MOTOR_FORWARD, 0);
    gpioPWM(LEFT_MOTOR_BACKWARD, 0);
    gpioPWM(RIGHT_MOTOR_FORWARD, 0);
    gpioPWM(RIGHT_MOTOR_BACKWARD, 0);

    fclose(log);
    gpioTerminate();

    return EXIT_SUCCESS;
}

