#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define BH1750_I2C_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define RELAY_GPIO 23
#define I2C_BUS 1
#define LUX_THRESHOLD 150
#define LOG_FILE "grow_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%.3f: %s\n", ts.tv_sec + ts.tv_nsec / 1e9, message);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for relay\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, BH1750_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByte(i2c_handle, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Failed to set BH1750 mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        usleep(180000); // 180 ms measurement delay

        uint16_t lux = 0;
        if (i2cReadWordData(i2c_handle, 0) < 0) {
            log_message("I2C read failed");
            continue;
        } else {
            lux = i2cReadWordData(i2c_handle, 0);
            lux = (lux >> 8) | (lux << 8); // Swap bytes
            lux /= 1.2; // Convert to lux
        }

        char log_buffer[100];
        snprintf(log_buffer, sizeof(log_buffer), "Lux: %.2f", lux);
        log_message(log_buffer);

        if (lux < LUX_THRESHOLD) {
            gpioWrite(RELAY_GPIO, PI_HIGH);
            log_message("Relay activated");
        } else {
            gpioWrite(RELAY_GPIO, PI_LOW);
            log_message("Relay deactivated");
        }
    }

    gpioWrite(RELAY_GPIO, PI_LOW);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

