        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        usleep(180000); // 180 ms measurement delay

        uint16_t lux = 0;
        if (i2cReadWordData(i2c_handle, 0) < 0) {
            log_message("I2C read failed");
            continue;
        } else {
            lux = i2cReadWordData(i2c_handle, 0);
            lux = (lux >> 8) | (lux << 8); // Swap bytes
            lux /= 1.2; // Convert to lux
        }

        char log_buffer[100];
        snprintf(log_buffer, sizeof(log_buffer), "Lux: %.2f", lux);
        log_message(log_buffer);

        if (lux < LUX_THRESHOLD) {
            gpioWrite(RELAY_GPIO, PI_HIGH);
            log_message("Relay activated");
        } else {
            gpioWrite(RELAY_GPIO, PI_LOW);
            log_message("Relay deactivated");
        }
    }

    gpioWrite(RELAY_GPIO, PI_LOW);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}
```

This code initializes the pigpio library, sets up the relay GPIO, opens the I2C bus, and configures the BH1750 sensor. It reads the lux value every 180 ms, logs the reading, and activates the relay if the lux is below the threshold. It handles signals to terminate gracefully, ensuring all resources are released.

