#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LOCK_BUTTON_GPIO 21
#define UNLOCK_BUTTON_GPIO 22
#define SERVO_GPIO 18
#define LOCK_PULSE_WIDTH 1000
#define UNLOCK_PULSE_WIDTH 2000
#define DEBOUNCE_DELAY 100

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(LOCK_BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDnControl(LOCK_BUTTON_GPIO, PI_PUD_UP);

    gpioSetMode(UNLOCK_BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDnControl(UNLOCK_BUTTON_GPIO, PI_PUD_UP);

    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_GPIO, 50); // 50 Hz frequency
    gpioSetPWMrange(SERVO_GPIO, 20000); // 20000 us range
}

void cleanup_gpio() {
    gpioTerminate();
}

void move_servo(int pulse_width) {
    if (pulse_width < 500 || pulse_width > 2500) {
        fprintf(stderr, "Pulse width out of safe range\n");
        return;
    }
    gpioPWM(SERVO_GPIO, pulse_width);
}

void handle_button_press(int button_gpio, int target_pulse_width) {
    if (gpioRead(button_gpio) == 0) {
        printf("Button pressed, moving servo to %d us\n", target_pulse_width);
        move_servo(target_pulse_width);
        gpioDelay(DEBOUNCE_DELAY * 1000);
    }
}

int main() {
    signal(SIGINT, signal_handler);

    init_gpio();

    while (running) {
        handle_button_press(LOCK_BUTTON_GPIO, LOCK_PULSE_WIDTH);
        handle_button_press(UNLOCK_BUTTON_GPIO, UNLOCK_PULSE_WIDTH);
        gpioDelay(10 * 1000); // 10 ms loop delay
    }

    cleanup_gpio();
    printf("Program terminated\n");
    return 0;
}

