#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define MOTOR1_PULSE_MS 200
#define MOTOR2_PULSE_MS 300

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *motor1_line, *motor2_line;
    int ret;

    // Register signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Request GPIO lines
    motor1_line = gpiod_chip_get_line(chip, MOTOR1_GPIO);
    if (!motor1_line) {
        perror("gpiod_chip_get_line(MOTOR1_GPIO)");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    motor2_line = gpiod_chip_get_line(chip, MOTOR2_GPIO);
    if (!motor2_line) {
        perror("gpiod_chip_get_line(MOTOR2_GPIO)");
        gpiod_line_release(motor1_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(motor1_line, "haptic_motor1", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(MOTOR1_GPIO)");
        gpiod_line_release(motor2_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_output(motor2_line, "haptic_motor2", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(MOTOR2_GPIO)");
        gpiod_line_release(motor1_line);
        gpiod_line_release(motor2_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (running) {
        // Pulse motor 1
        ret = gpiod_line_set_value(motor1_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(MOTOR1_GPIO, 1)");
            break;
        }
        usleep(MOTOR1_PULSE_MS * 1000);
        ret = gpiod_line_set_value(motor1_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(MOTOR1_GPIO, 0)");
            break;
        }

        // Pulse motor 2
        ret = gpiod_line_set_value(motor2_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(MOTOR2_GPIO, 1)");
            break;
        }
        usleep(MOTOR2_PULSE_MS * 1000);
        ret = gpiod_line_set_value(motor2_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(MOTOR2_GPIO, 0)");
            break;
        }
    }

    // Cleanup
    gpiod_line_release(motor1_line);
    gpiod_line_release(motor2_line);
    gpiod_chip_close(chip);

    return 0;
}

