#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <czmq.h>

#define GPIO_CHIP "gpiochip0"
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define ZMQ_PUBLISHER_ENDPOINT "tcp://*:5555"
#define ZMQ_SUBSCRIBER_ENDPOINT "tcp://localhost:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"
#define POLL_INTERVAL_US 10000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void setup_signals() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_sensor_line = NULL;
    struct gpiod_line *alarm_led_line = NULL;
    zctx_t *zctx = NULL;
    void *zsock = NULL;

    if (strcmp(mode, "sound_sensor") == 0) {
        // Initialize GPIO
        chip = gpiod_chip_open_by_name(GPIO_CHIP);
        if (!chip) {
            perror("Failed to open GPIO chip");
            return EXIT_FAILURE;
        }

        sound_sensor_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
        if (!sound_sensor_line) {
            perror("Failed to get sound sensor line");
            goto cleanup;
        }

        if (gpiod_line_request_input(sound_sensor_line, "sound_sensor") < 0) {
            perror("Failed to request input on sound sensor line");
            goto cleanup;
        }

        // Initialize ZeroMQ
        zctx = zctx_new();
        if (!zctx) {
            fprintf(stderr, "Failed to create ZeroMQ context\n");
            goto cleanup;
        }

        zsock = zsocket_new(zctx, ZMQ_PUB);
        if (!zsock) {
            fprintf(stderr, "Failed to create ZeroMQ publisher socket\n");
            goto cleanup;
        }

        if (zsocket_bind(zsock, ZMQ_PUBLISHER_ENDPOINT) < 0) {
            fprintf(stderr, "Failed to bind ZeroMQ publisher socket\n");
            goto cleanup;
        }

        setup_signals();

        while (running) {
            int value = gpiod_line_get_value(sound_sensor_line);
            if (value < 0) {
                perror("Failed to read sound sensor line");
                break;
            }

            if (value == 0) {
                zstr_sendm(zsock, ZMQ_TOPIC);
                zstr_send(zsock, "Sound detected");
            }

            usleep(POLL_INTERVAL_US);
        }
    } else if (strcmp(mode, "alarm_node") == 0) {
        // Initialize GPIO
        chip = gpiod_chip_open_by_name(GPIO_CHIP);
        if (!chip) {
            perror("Failed to open GPIO chip");
            return EXIT_FAILURE;
        }

        alarm_led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
        if (!alarm_led_line) {
            perror("Failed to get alarm LED line");
            goto cleanup;
        }

        if (gpiod_line_request_output(alarm_led_line, "alarm_node", 0) < 0) {
            perror("Failed to request output on alarm LED line");
            goto cleanup;
        }

        // Initialize ZeroMQ
        zctx = zctx_new();
        if (!zctx) {
            fprintf(stderr, "Failed to create ZeroMQ context\n");
            goto cleanup;
        }

        zsock = zsocket_new(zctx, ZMQ_SUB);
        if (!zsock) {
            fprintf(stderr, "Failed to create ZeroMQ subscriber socket\n");
            goto cleanup;
        }

        if (zsocket_connect(zsock, ZMQ_SUBSCRIBER_ENDPOINT) < 0) {
            fprintf(stderr, "Failed to connect ZeroMQ subscriber socket\n");
            goto cleanup;
        }

        zsocket_set_subscribe(zsock, ZMQ_TOPIC);

        setup_signals();

        while (running) {
            char *topic, *message;
            zmsg_t *msg = zmsg_recv(zsock);
            if (!msg) {
                if (zctx_interrupted(zctx)) {
                    break;
                }
                perror("Failed to receive ZeroMQ message");
                continue;
            }

            topic = zmsg_popstr(msg);
            message = zmsg_popstr(msg);

            if (strcmp(topic, ZMQ_TOPIC) == 0) {
                printf("Received alert: %s\n", message);
                gpiod_line_set_value(alarm_led_line, 1);
                usleep(1000000);
                gpiod_line_set_value(alarm_led_line, 0);
            }

            zstr_free(&topic);
            zstr_free(&message);
            zmsg_destroy(&msg);
        }
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return EXIT_FAILURE;
    }

cleanup:
    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (alarm_led_line) {
        gpiod_line_release(alarm_led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (zsock) {
        zsocket_destroy(zctx, zsock);
    }
    if (zctx) {
        zctx_destroy(zctx);
    }

    return EXIT_SUCCESS;
}

