volatile int pulse_count = 0;
volatile uint32_t pulse_buffer[PULSE_BUFFER_SIZE];

void signal_handler(int signum) {
    running = 0;
}

void gpio_callback(int gpio, int level, uint32_t tick) {
    if (pulse_count < PULSE_BUFFER_SIZE) {
        pulse_buffer[pulse_count++] = tick;
    }
}

int decode_nec(uint32_t *pulses, int count, uint32_t *address, uint32_t *command) {
    if (count < 33) return -1;

    uint32_t header_mark = pulses[1] - pulses[0];
    uint32_t header_space = pulses[2] - pulses[1];

    if (header_mark < HEADER_MARK_US - 1000 || header_mark > HEADER_MARK_US + 1000 ||
        header_space < HEADER_SPACE_US - 1000 || header_space > HEADER_SPACE_US + 1000) {
        return -1;
    }

    uint32_t addr = 0, cmd = 0;
    for (int i = 3; i < 33; i += 2) {
        uint32_t bit_mark = pulses[i] - pulses[i - 1];
        uint32_t bit_space = pulses[i + 1] - pulses[i];

        if (bit_mark < BIT_MARK_US - 100 || bit_mark > BIT_MARK_US + 100) return -1;

        if (bit_space > BIT_1_SPACE_US - 100 && bit_space < BIT_1_SPACE_US + 100) {
            if (i < 33) addr = (addr << 1) | 1;
            else cmd = (cmd << 1) | 1;
        } else if (bit_space > BIT_0_SPACE_US - 100 && bit_space < BIT_0_SPACE_US + 100) {
            if (i < 33) addr = (addr << 1);
            else cmd = (cmd << 1);
        } else {
