        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(GPIO_PIN, gpio_callback) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO alert function");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    MQTTClient client;
    MQTTClient_create(&client, "tcp://localhost:1883", "ir_decoder", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (pulse_count >= 33) {
            uint32_t address, command;
            if (decode_nec(pulse_buffer, pulse_count, &address, &command) == 0) {
                syslog(LOG_INFO, "Decoded address: %u, command: %u", address, command);
                publish_mqtt(client, address, command);
            }
            pulse_count = 0;
        }
        MQTTClient_yield(client);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

