#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRS {0x23, 0x24, 0x25, 0x26}
#define UDP_MULTICAST_GROUP "239.255.255.250"
#define UDP_PORT 5005
#define BH1750_COMMAND 0x20
#define CONVERSION_TIME_US 180000

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int sig) {
    exit_flag = 1;
}

int main() {
    int i2c_fd[4] = {-1, -1, -1, -1};
    int udp_sock = -1;
    struct sockaddr_in udp_addr;
    char buffer[1024];
    const int i2c_addrs[] = I2C_ADDRS;
    const int num_sensors = sizeof(i2c_addrs) / sizeof(i2c_addrs[0]);

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C devices
    for (int i = 0; i < num_sensors; i++) {
        i2c_fd[i] = open(I2C_DEVICE, O_RDWR);
        if (i2c_fd[i] < 0) {
            perror("Failed to open I2C device");
            goto cleanup;
        }
    }

    // Set up UDP socket
    udp_sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_sock < 0) {
        perror("Failed to create UDP socket");
        goto cleanup;
    }

    memset(&udp_addr, 0, sizeof(udp_addr));
    udp_addr.sin_family = AF_INET;
    udp_addr.sin_addr.s_addr = inet_addr(UDP_MULTICAST_GROUP);
    udp_addr.sin_port = htons(UDP_PORT);

    // Main loop
    while (!exit_flag) {
        char result[1024];
        result[0] = '\0';

        for (int i = 0; i < num_sensors; i++) {
            uint8_t data[2];
            float lux = NAN;

            // Set I2C slave address
            if (ioctl(i2c_fd[i], I2C_SLAVE, i2c_addrs[i]) < 0) {
                perror("Failed to set I2C slave address");
                snprintf(result + strlen(result), sizeof(result) - strlen(result), "%d,NAN;", i + 1);
                continue;
            }

            // Write command to start conversion
            if (write(i2c_fd[i], &BH1750_COMMAND, 1) != 1) {
                perror("Failed to write to I2C device");
                snprintf(result + strlen(result), sizeof(result) - strlen(result), "%d,NAN;", i + 1);
                continue;
            }

            // Wait for conversion
            usleep(CONVERSION_TIME_US);

            // Read conversion result
            if (read(i2c_fd[i], data, 2) != 2) {
                perror("Failed to read from I2C device");
                snprintf(result + strlen(result), sizeof(result) - strlen(result), "%d,NAN;", i + 1);
                continue;
            }

            // Convert to lux
            lux = ((data[0] << 8) | data[1]) / 1.2;
            snprintf(result + strlen(result), sizeof(result) - strlen(result), "%d,%.1f;", i + 1, lux);
        }

        // Remove trailing semicolon
        if (result[0] != '\0') {
            result[strlen(result) - 1] = '\0';
        }

        // Send UDP multicast packet
        if (sendto(udp_sock, result, strlen(result), 0, (struct sockaddr *)&udp_addr, sizeof(udp_addr)) < 0) {
            perror("Failed to send UDP packet");
        }

        // Sleep for 1 second
        sleep(1);
    }

cleanup:
    // Close I2C devices
    for (int i = 0; i < num_sensors; i++) {
        if (i2c_fd[i] >= 0) {
            close(i2c_fd[i]);
        }
    }

    // Close UDP socket
    if (udp_sock >= 0) {
        close(udp_sock);
    }

    return 0;
}

