#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x28
#define RETRY_COUNT 3
#define RETRY_DELAY 100000 // 100 ms in microseconds

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    char filename[] = "airflow_log.txt";
    FILE *log_file = fopen(filename, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t buffer[2];
        int retries = 0;
        int result;

        while (retries < RETRY_COUNT) {
            result = read(i2c_fd, buffer, sizeof(buffer));
            if (result == sizeof(buffer)) {
                break;
            } else if (errno == EIO || errno == ENXIO) {
                perror("I2C read error");
                retries++;
                usleep(RETRY_DELAY);
            } else {
                perror("I2C read failed");
                close(i2c_fd);
                fclose(log_file);
                return EXIT_FAILURE;
            }
        }

        if (retries == RETRY_COUNT) {
            fprintf(stderr, "Max retries reached, exiting\n");
            close(i2c_fd);
            fclose(log_file);
            return EXIT_FAILURE;
        }

        uint16_t raw_value = (buffer[0] << 8) | buffer[1];
        raw_value &= 0x3FFF;
        double flow_rate = (raw_value - 3277) * 0.1;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s: %.1f SLPM\n", timestamp, flow_rate);
        fflush(log_file);

        sleep(1);
    }

    close(i2c_fd);
    fclose(log_file);
    return EXIT_SUCCESS;
}

