#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define AS7341_I2C_ADDRESS 0x39
#define WHO_AM_I_REG 0x24
#define ENABLE_REG 0x80
#define CFG6_REG 0xAF
#define F1_REG 0x60
#define F8_REG 0x67
#define CLEAR_REG 0x68
#define NIR_REG 0x69
#define NUM_CHANNELS 10

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int i2c_write_byte(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int reg, uint8_t *buf, int len) {
    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_I2C_ADDRESS) < 0) {
        perror("I2C ioctl failed");
        return -1;
    }
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("I2C write reg failed");
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
