#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define DEFAULT_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define REGISTER_START 0x28
#define NUM_BYTES 6
#define RETRY_COUNT 3
#define RETRY_DELAY 10000 // 10 ms

static int i2c_fd = -1;
static FILE *data_file = NULL;
static FILE *error_file = NULL;
static int address = DEFAULT_ADDRESS;
static int interval = DEFAULT_INTERVAL;
static char *filename = DEFAULT_FILENAME;

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(error_file, "%s: %s\n", asctime(tm_info), message);
    fflush(error_file);
}

void close_files() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (data_file) {
        fclose(data_file);
        data_file = NULL;
    }
    if (error_file) {
        fclose(error_file);
        error_file = NULL;
    }
}

void signal_handler(int signum) {
    close_files();
    exit(signum);
}

int i2c_write_register(int reg) {
    unsigned char buf[1] = {reg};
    int retries = RETRY_COUNT;
    while (retries--) {
        if (write(i2c_fd, buf, 1) == 1) {
            return 0;
        }
        if (errno != EIO) {
            log_error("I2C write error");
            return -1;
        }
        usleep(RETRY_DELAY);
    }
    log_error("I2C write failed after retries");
    return -1;
}

int i2c_read_bytes(unsigned char *buf, int count) {
    int retries = RETRY_COUNT;
    while (retries--) {
        if (read(i2c_fd, buf, count) == count) {
            return 0;
        }
        if (errno != EIO) {
            log_error("I2C read error");
            return -1;
        }
        usleep(RETRY_DELAY);
    }
    log_error("I2C read failed after retries");
    return -1;
}

void read_and_log_data() {
    unsigned char buf[NUM_BYTES];
    if (i2c_write_register(REGISTER_START) < 0) {
        return;
    }
    if (i2c_read_bytes(buf, NUM_BYTES) < 0) {
        return;
    }

    int16_t x = (buf[1] << 8) | buf[0];
    int16_t y = (buf[3] << 8) | buf[2];
    int16_t z = (buf[5] << 8) | buf[4];

    double x_g = x * 0.000244;
    double y_g = y * 0.000244;
    double z_g = z * 0.000244;

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(data_file, "%s,%f,%f,%f\n", asctime(tm_info), x_g, y_g, z_g);
    fflush(data_file);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                address = strtoul(optarg, NULL, 0);
                break;
            case 'i':
                interval = atoi(optarg);
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a address] [-i interval] [-f filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close_files();
        exit(EXIT_FAILURE);
    }

    data_file = fopen(filename, "a");
    if (!data_file) {
        perror("Failed to open data file");
        close_files();
        exit(EXIT_FAILURE);
    }

    error_file = fopen("seismic_error.log", "a");
    if (!error_file) {
        perror("Failed to open error file");
        close_files();
        exit(EXIT_FAILURE);
    }

    while (1) {
        read_and_log_data();
        sleep(interval);
    }

    close_files();
    return 0;
}

