code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDRESS 0x23
#define POWER_ON_COMMAND 0x01
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define I2C_BUFFER_SIZE 2
#define UDP_MULTICAST_GROUP "239.255.255.250"
#define UDP_PORT 5000
#define UDP_TTL 1
#define READ_INTERVAL 1

int i2c_fd = -1;
int udp_socket = -1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (udp_socket != -1) {
        close(udp_socket);
        udp_socket = -1;
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    uint8_t power_on_command = POWER_ON_COMMAND;
    if (write(i2c_fd, &power_on_command, 1) != 1) {
        perror("Failed to send power-on command");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    uint8_t continuous_high_res_mode = CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &continuous_high_res_mode, 1) != 1) {
        perror("Failed to send continuous high-resolution mode command");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int init_udp() {
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Failed to create UDP socket");
        return -1;
    }

    struct ip_mreq mreq;
    mreq.imr_multiaddr.s_addr = inet_addr(UDP_MULTICAST_GROUP);
    mreq.imr_interface.s_addr = htonl(INADDR_ANY);
    if (setsockopt(udp_socket, IPPROTO_IP, IP_ADD_MEMBERSHIP, &mreq, sizeof(mreq)) < 0) {
        perror("Failed to join multicast group");
        close(udp_socket);
        udp_socket = -1;
        return -1;
    }

    int ttl = UDP_TTL;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Failed to set multicast TTL");
        close(udp_socket);
        udp_socket = -1;
        return -1;
    }

    return 0;
}

int read_light_level(uint16_t *raw_value) {
    uint8_t buffer[I2C_BUFFER_SIZE];
    if (read(i2c_fd, buffer, I2C_BUFFER_SIZE) != I2C_BUFFER_SIZE) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

void broadcast_light_level(float lux) {
    char message[20];
    snprintf(message, sizeof(message), "%.2f", lux);

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(UDP_MULTICAST_GROUP);
    addr.sin_port = htons(UDP_PORT);

    if (sendto(udp_socket, message, strlen(message), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Failed to send UDP message");
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return EXIT_FAILURE;
    }

    if (init_udp() < 0) {
        fprintf(stderr, "Failed to initialize UDP\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t raw_value;
        if (read_light_level(&raw_value) < 0) {
            fprintf(stderr, "Failed to read light level, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        float lux = raw_value / 1.2;
        broadcast_light_level(lux);

        sleep(READ_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

