    if (setsockopt(udp_socket, IPPROTO_IP, IP_ADD_MEMBERSHIP, &mreq, sizeof(mreq)) < 0) {
        perror("Failed to join multicast group");
        close(udp_socket);
        udp_socket = -1;
        return -1;
    }

    int ttl = UDP_TTL;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Failed to set multicast TTL");
        close(udp_socket);
        udp_socket = -1;
        return -1;
    }

    return 0;
}

int read_light_level(uint16_t *raw_value) {
    uint8_t buffer[I2C_BUFFER_SIZE];
    if (read(i2c_fd, buffer, I2C_BUFFER_SIZE) != I2C_BUFFER_SIZE) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

void broadcast_light_level(float lux) {
    char message[20];
    snprintf(message, sizeof(message), "%.2f", lux);

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(UDP_MULTICAST_GROUP);
    addr.sin_port = htons(UDP_PORT);

    if (sendto(udp_socket, message, strlen(message), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Failed to send UDP message");
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return EXIT_FAILURE;
    }

    if (init_udp() < 0) {
        fprintf(stderr, "Failed to initialize UDP\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t raw_value;
        if (read_light_level(&raw_value) < 0) {
            fprintf(stderr, "Failed to read light level, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        float lux = raw_value / 1.2;
        broadcast_light_level(lux);

        sleep(READ_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}
