#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define MAGIC_WORD_SIZE 8
#define MAGIC_WORD {0x02, 0x04, 0x03, 0x06, 0x08, 0x05, 0x07, 0x09}
#define CSV_FILE "radar_data.csv"

typedef struct {
    uint16_t range;
    int16_t velocity;
} DetectedObject;

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void write_csv_header(FILE *csv_file) {
    fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
}

void write_csv_row(FILE *csv_file, uint32_t timestamp, uint8_t object_index, float range_m, float velocity_mps) {
    fprintf(csv_file, "%u,%u,%.2f,%.2f\n", timestamp, object_index, range_m, velocity_mps);
}

int main() {
    int uart_handle;
    FILE *csv_file;
    uint8_t buffer[1024];
    uint8_t magic_word[MAGIC_WORD_SIZE] = MAGIC_WORD;
    size_t buffer_size = 0;
    size_t buffer_pos = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "Failed to open UART device %s\n", UART_DEVICE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file %s\n", CSV_FILE);
        serClose(uart_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    write_csv_header(csv_file);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int bytes_read = serRead(uart_handle, buffer + buffer_pos, sizeof(buffer) - buffer_pos);
        if (bytes_read < 0) {
            fprintf(stderr, "UART read error\n");
            continue;
        }
        buffer_size += bytes_read;

        while (buffer_size >= MAGIC_WORD_SIZE) {
            if (memcmp(buffer, magic_word, MAGIC_WORD_SIZE) == 0) {
                // Synchronized on magic word, process TLV payload
                size_t payload_size = buffer_size - MAGIC_WORD_SIZE;
                uint8_t *payload = buffer + MAGIC_WORD_SIZE;

                // Example TLV parsing (simplified)
                for (size_t i = 0; i < payload_size; i += 4) {
                    uint8_t object_index = payload[i];
                    uint16_t range = (payload[i + 1] << 8) | payload[i + 2];
                    int16_t velocity = (payload[i + 3] << 8) | payload[i + 4];

                    // Convert to meters and m/s
                    float range_m = range * 0.001f;
                    float velocity_mps = velocity * 0.01f;

                    // Get current timestamp
                    struct timespec ts;
                    clock_gettime(CLOCK_REALTIME, &ts);
                    uint32_t timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

                    // Write to CSV
                    write_csv_row(csv_file, timestamp, object_index, range_m, velocity_mps);
                }

                // Move remaining data to the start of the buffer
                memmove(buffer, buffer + payload_size, buffer_size - payload_size);
                buffer_size -= payload_size;
            } else {
                // Not synchronized, skip one byte
                memmove(buffer, buffer + 1, buffer_size - 1);
                buffer_size -= 1;
            }
        }
    }

    fclose(csv_file);
    serClose(uart_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

