#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/serial0"
#define BUFFER_SIZE 256
#define TIMEOUT_SECONDS 2
#define INTER_BYTE_TIMEOUT 500000 // 0.5 seconds in microseconds

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_error(const char *msg) {
    perror(msg);
}

void log_detection(const char *timestamp, float range) {
    struct tm *tm_info;
    time_t t = (time_t)atol(timestamp);
    char time_str[20];

    tm_info = localtime(&t);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    printf("Timestamp: %s, Range: %.2f meters\n", time_str, range);
}

int main() {
    int uart_fd;
    struct termios options;
    fd_set read_fds;
    struct timeval timeout;
    char buffer[BUFFER_SIZE];
    char *line = NULL;
    size_t line_len = 0;
    ssize_t bytes_read;
    char *token;
    float range;

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open UART device
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        log_error("Failed to open UART device");
        return EXIT_FAILURE;
    }

    // Configure UART
    if (tcgetattr(uart_fd, &options) != 0) {
        log_error("Failed to get UART attributes");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    cfsetispeed(&options, B115200);
    cfsetospeed(&options, B115200);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~CRTSCTS;
    options.c_cflag |= CREAD | CLOCAL;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;

    // Set inter-byte timeout
    options.c_cc[VTIME] = INTER_BYTE_TIMEOUT / 100000; // tenths of a second
    options.c_cc[VMIN] = 0;

    if (tcsetattr(uart_fd, TCSANOW, &options) != 0) {
        log_error("Failed to set UART attributes");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        FD_ZERO(&read_fds);
        FD_SET(uart_fd, &read_fds);

        timeout.tv_sec = TIMEOUT_SECONDS;
        timeout.tv_usec = 0;

        if (select(uart_fd + 1, &read_fds, NULL, NULL, &timeout) == -1) {
            if (errno == EINTR) {
                continue;
            }
            log_error("Select failed");
            break;
        }

        if (FD_ISSET(uart_fd, &read_fds)) {
            bytes_read = read(uart_fd, buffer, BUFFER_SIZE - 1);
            if (bytes_read == -1) {
                log_error("Read failed");
                break;
            }

            buffer[bytes_read] = '\0';

            if (line == NULL) {
                line = strdup(buffer);
                line_len = bytes_read;
            } else {
                line = realloc(line, line_len + bytes_read + 1);
                if (line == NULL) {
                    fprintf(stderr, "Memory allocation failed\n");
                    break;
                }
                memcpy(line + line_len, buffer, bytes_read);
                line_len += bytes_read;
                line[line_len] = '\0';
            }

            char *newline = strchr(line, '\n');
            while (newline != NULL) {
                *newline = '\0';
                token = strtok(line, ",");
                if (token != NULL) {
                    char *timestamp = strdup(token);
                    token = strtok(NULL, ",");
                    if (token != NULL) {
                        range = strtof(token, NULL);
                        log_detection(timestamp, range);
                        free(timestamp);
                    }
                }
                line_len -= (newline - line + 1);
                memmove(line, newline + 1, line_len + 1);
                newline = strchr(line, '\n');
            }
        }
    }

    free(line);
    close(uart_fd);
    return EXIT_SUCCESS;
}

