#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200

int serial_handle = -1;
int running = 1;

void cleanup() {
    if (serial_handle >= 0) {
        serClose(serial_handle);
    }
    gpioTerminate();
}

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    atexit(cleanup);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetPullUpDnControl(LEFT_SENSOR, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetPullUpDnControl(MIDDLE_SENSOR, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetPullUpDnControl(RIGHT_SENSOR, PI_PUD_UP);

    serial_handle = serOpen(SERIAL_PORT, BAUD_RATE, 0);
    if (serial_handle < 0) {
        fprintf(stderr, "Failed to open serial port %s\n", SERIAL_PORT);
        return 1;
    }

    while (running) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        int left = gpioRead(LEFT_SENSOR);
        int middle = gpioRead(MIDDLE_SENSOR);
        int right = gpioRead(RIGHT_SENSOR);

        if (left == PI_BAD_GPIO || middle == PI_BAD_GPIO || right == PI_BAD_GPIO) {
            fprintf(stderr, "gpioRead failed\n");
            continue;
        }

        printf("%s: Left=%d, Middle=%d, Right=%d\n", timestamp, left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            const char *emergency_message = "EMERGENCY STOP!\n";
            int bytes_written = serWrite(serial_handle, emergency_message, strlen(emergency_message));
            if (bytes_written < 0) {
                fprintf(stderr, "Failed to write to serial port\n");
            }
        }

        gpioDelay(100000); // 100 ms delay
    }

    return 0;
}

